/* =========================================================
   FAEZA ERP V2
   SCRIPT.JS — BAGIAN 1/3
   FONDASI + MASTER DATA
========================================================= */

"use strict";


/* =========================================================
   DATABASE
========================================================= */

const DB_KEY = "faeza_erp_v2_database";

const defaultDB = {

  products: [],

  suppliers: [],

  sales: [],

  purchases: [],

  debts: [],

  receivables: [],

  stockMovements: [],

  settings: {

    storeName: "Faeza Store",

    storePhone: ""

  }

};


let db = loadDatabase();


/* =========================================================
   STATE
========================================================= */

let saleCart = [];

let purchaseCart = [];

let modalAction = null;

let editingProductId = null;

let editingSupplierId = null;


/* =========================================================
   DATABASE FUNCTIONS
========================================================= */

function loadDatabase() {

  try {

    const saved =
      localStorage.getItem(DB_KEY);

    if (!saved) {

      return structuredClone(
        defaultDB
      );

    }

    const parsed =
      JSON.parse(saved);

    return {

      ...structuredClone(
        defaultDB
      ),

      ...parsed,

      settings: {

        ...defaultDB.settings,

        ...(parsed.settings || {})

      }

    };

  } catch (error) {

    console.error(
      "Database error:",
      error
    );

    return structuredClone(
      defaultDB
    );

  }

}


function saveDatabase() {

  localStorage.setItem(
    DB_KEY,
    JSON.stringify(db)
  );

}


/* =========================================================
   ID GENERATOR
========================================================= */

function generateId(
  prefix = "ID"
) {

  return (

    prefix +

    "-" +

    Date.now()
      .toString(36) +

    "-" +

    Math.random()
      .toString(36)
      .substring(2, 7)

  ).toUpperCase();

}


/* =========================================================
   FORMAT
========================================================= */

function formatRupiah(
  value
) {

  const number =
    Number(value) || 0;

  return new Intl.NumberFormat(
    "id-ID",
    {

      style: "currency",

      currency: "IDR",

      maximumFractionDigits: 0

    }
  ).format(number);

}


function formatNumber(
  value
) {

  return new Intl.NumberFormat(
    "id-ID"
  ).format(
    Number(value) || 0
  );

}


function today() {

  return new Date()
    .toISOString()
    .split("T")[0];

}


function escapeHTML(
  value
) {

  return String(
    value ?? ""
  )

    .replaceAll(
      "&",
      "&amp;"
    )

    .replaceAll(
      "<",
      "&lt;"
    )

    .replaceAll(
      ">",
      "&gt;"
    )

    .replaceAll(
      '"',
      "&quot;"
    )

    .replaceAll(
      "'",
      "&#039;"
    );

}


/* =========================================================
   TOAST
========================================================= */

let toastTimer = null;


function showToast(
  message,
  type = "success"
) {

  const toast =
    document.getElementById(
      "toast"
    );

  if (!toast) return;


  toast.textContent =
    message;

  toast.dataset.type =
    type;

  toast.classList.add(
    "show"
  );


  clearTimeout(
    toastTimer
  );


  toastTimer =
    setTimeout(
      () => {

        toast.classList.remove(
          "show"
        );

      },
      2500
    );

}


/* =========================================================
   NAVIGATION
========================================================= */

function initNavigation() {

  const navItems =
    document.querySelectorAll(
      ".nav-item"
    );


  navItems.forEach(
    item => {

      item.addEventListener(
        "click",
        () => {

          const page =
            item.dataset.page;

          openPage(page);

        }
      );

    }
  );


  const menuToggle =
    document.getElementById(
      "menuToggle"
    );


  if (menuToggle) {

    menuToggle.addEventListener(
      "click",
      toggleSidebar
    );

  }

}


function openPage(
  pageName
) {

  document
    .querySelectorAll(
      ".page"
    )
    .forEach(
      page => {

        page.classList.remove(
          "active"
        );

      }
    );


  const target =
    document.getElementById(
      `page-${pageName}`
    );


  if (!target) {

    console.warn(
      `Halaman ${pageName} tidak ditemukan.`
    );

    return;

  }


  target.classList.add(
    "active"
  );


  document
    .querySelectorAll(
      ".nav-item"
    )
    .forEach(
      item => {

        item.classList.toggle(
          "active",
          item.dataset.page ===
          pageName
        );

      }
    );


  closeSidebar();

  refreshPage(
    pageName
  );

}


/* =========================================================
   REFRESH PAGE
========================================================= */

function refreshPage(
  page
) {

  switch (page) {

    case "dashboard":

      if (
        typeof renderDashboard ===
        "function"
      ) {

        renderDashboard();

      }

      break;


    case "produk":

      renderProducts();

      break;


    case "supplier":

      renderSuppliers();

      break;


    case "kasir":

      if (
        typeof renderSaleProducts ===
        "function"
      ) {

        renderSaleProducts();

      }

      if (
        typeof renderSaleCart ===
        "function"
      ) {

        renderSaleCart();

      }

      break;


    case "pembelian":

      if (
        typeof renderPurchaseSuppliers ===
        "function"
      ) {

        renderPurchaseSuppliers();

      }

      if (
        typeof renderPurchaseCart ===
        "function"
      ) {

        renderPurchaseCart();

      }

      if (
        typeof renderPurchaseHistory ===
        "function"
      ) {

        renderPurchaseHistory();

      }

      break;


    case "hutang":

      if (
        typeof renderDebts ===
        "function"
      ) {

        renderDebts();

      }

      break;


    case "piutang":

      if (
        typeof renderReceivables ===
        "function"
      ) {

        renderReceivables();

      }

      break;


    case "stok":

      if (
        typeof renderStockMovements ===
        "function"
      ) {

        renderStockMovements();

      }

      break;


    case "laporan":

      if (
        typeof renderReports ===
        "function"
      ) {

        renderReports();

      }

      break;


    case "pengaturan":

      if (
        typeof loadSettingsForm ===
        "function"
      ) {

        loadSettingsForm();

      }

      break;

  }

}


/* =========================================================
   SIDEBAR
========================================================= */

function toggleSidebar() {

  const sidebar =
    document.getElementById(
      "sidebar"
    );


  if (!sidebar) return;


  sidebar.classList.toggle(
    "open"
  );

}


function closeSidebar() {

  const sidebar =
    document.getElementById(
      "sidebar"
    );


  if (!sidebar) return;


  sidebar.classList.remove(
    "open"
  );

}


/* =========================================================
   MODAL
========================================================= */

function openModal(
  title,
  bodyHTML,
  action
) {

  const overlay =
    document.getElementById(
      "modalOverlay"
    );


  const titleEl =
    document.getElementById(
      "modalTitle"
    );


  const bodyEl =
    document.getElementById(
      "modalBody"
    );


  if (!overlay) {

    console.warn(
      "modalOverlay tidak ditemukan."
    );

    return;

  }


  if (titleEl) {

    titleEl.textContent =
      title;

  }


  if (bodyEl) {

    bodyEl.innerHTML =
      bodyHTML;

  }


  modalAction =
    action;


  overlay.classList.add(
    "show"
  );

}


function closeModal() {

  const overlay =
    document.getElementById(
      "modalOverlay"
    );


  if (!overlay) return;


  overlay.classList.remove(
    "show"
  );


  modalAction =
    null;

}


function initModal() {

  document
    .getElementById(
      "modalClose"
    )
    ?.addEventListener(
      "click",
      closeModal
    );


  document
    .getElementById(
      "modalCancel"
    )
    ?.addEventListener(
      "click",
      closeModal
    );


  document
    .getElementById(
      "modalSave"
    )
    ?.addEventListener(
      "click",
      () => {

        if (
          typeof modalAction ===
          "function"
        ) {

          modalAction();

        }

      }
    );


  document
    .getElementById(
      "modalOverlay"
    )
    ?.addEventListener(
      "click",
      event => {

        if (
          event.target.id ===
          "modalOverlay"
        ) {

          closeModal();

        }

      }
    );

}


/* =========================================================
   PRODUK
========================================================= */

function openProductForm(
  product = null
) {

  const isEdit =
    Boolean(product);


  editingProductId =
    product?.id || null;


  const body = `

    <div class="form-grid">

      <div class="form-group">

        <label>
          Kode Produk
        </label>

        <input
          id="modalProductCode"
          type="text"
          value="${escapeHTML(
            product?.code || ""
          )}"
          placeholder="Contoh: BRG001"
        >

      </div>


      <div class="form-group">

        <label>
          Nama Produk
        </label>

        <input
          id="modalProductName"
          type="text"
          value="${escapeHTML(
            product?.name || ""
          )}"
          placeholder="Nama produk"
        >

      </div>


      <div class="form-group">

        <label>
          Satuan
        </label>

        <input
          id="modalProductUnit"
          type="text"
          value="${escapeHTML(
            product?.unit || "pcs"
          )}"
          placeholder="pcs / kg / box"
        >

      </div>


      <div class="form-group">

        <label>
          Harga Beli
        </label>

        <input
          id="modalProductBuy"
          type="number"
          min="0"
          value="${
            product?.buyPrice || 0
          }"
        >

      </div>


      <div class="form-group">

        <label>
          Harga Jual
        </label>

        <input
          id="modalProductSell"
          type="number"
          min="0"
          value="${
            product?.sellPrice || 0
          }"
        >

      </div>


      <div class="form-group">

        <label>
          Stok Awal
        </label>

        <input
          id="modalProductStock"
          type="number"
          min="0"
          value="${
            product?.stock || 0
          }"
          ${
            isEdit
              ? "disabled"
              : ""
          }
        >

      </div>


      <div class="form-group">

        <label>
          Minimum Stok
        </label>

        <input
          id="modalProductMin"
          type="number"
          min="0"
          value="${
            product?.minStock || 0
          }"
        >

      </div>

    </div>

  `;


  openModal(

    isEdit
      ? "Edit Produk"
      : "Tambah Produk",

    body,

    saveProduct

  );

}


/* =========================================================
   SAVE PRODUCT
========================================================= */

function saveProduct() {

  const code =
    document
      .getElementById(
        "modalProductCode"
      )
      ?.value
      .trim();


  const name =
    document
      .getElementById(
        "modalProductName"
      )
      ?.value
      .trim();


  const unit =
    document
      .getElementById(
        "modalProductUnit"
      )
      ?.value
      .trim();


  const buyPrice =
    Number(
      document
        .getElementById(
          "modalProductBuy"
        )
        ?.value
    );


  const sellPrice =
    Number(
      document
        .getElementById(
          "modalProductSell"
        )
        ?.value
    );


  const minStock =
    Number(
      document
        .getElementById(
          "modalProductMin"
        )
        ?.value
    );


  if (!code || !name) {

    showToast(
      "Kode dan nama produk wajib diisi.",
      "error"
    );

    return;

  }


  if (

    !Number.isFinite(
      buyPrice
    )

    ||

    buyPrice < 0

    ||

    !Number.isFinite(
      sellPrice
    )

    ||

    sellPrice < 0

  ) {

    showToast(
      "Harga produk tidak valid.",
      "error"
    );

    return;

  }


  const duplicate =
    db.products.find(
      product =>

        product.code
          .toLowerCase() ===
        code.toLowerCase()

        &&

        product.id !==
        editingProductId

    );


  if (duplicate) {

    showToast(
      "Kode produk sudah digunakan.",
      "error"
    );

    return;

  }


  /* EDIT */

  if (editingProductId) {

    const product =
      db.products.find(
        p =>
          p.id ===
          editingProductId
      );


    if (!product) {

      showToast(
        "Produk tidak ditemukan.",
        "error"
      );

      return;

    }


    product.code =
      code;

    product.name =
      name;

    product.unit =
      unit || "pcs";

    product.buyPrice =
      buyPrice;

    product.sellPrice =
      sellPrice;

    product.minStock =
      Math.max(
        0,
        minStock || 0
      );


    showToast(
      "Produk berhasil diperbarui."
    );

  }


  /* PRODUK BARU */

  else {

    const stock =
      Number(
        document
          .getElementById(
            "modalProductStock"
          )
          ?.value
      ) || 0;


    const product = {

      id:
        generateId(
          "PROD"
        ),

      code,

      name,

      unit:
        unit || "pcs",

      buyPrice,

      sellPrice,

      stock:
        Math.max(
          0,
          stock
        ),

      minStock:
        Math.max(
          0,
          minStock || 0
        ),

      createdAt:
        new Date()
          .toISOString()

    };


    db.products.push(
      product
    );


    /* CATAT STOK AWAL */

    if (stock > 0) {

      db.stockMovements.push({

        id:
          generateId(
            "STK"
          ),

        date:
          today(),

        productId:
          product.id,

        type:
          "IN",

        reference:
          "STOK-AWAL",

        qty:
          stock,

        balance:
          stock

      });

    }


    showToast(
      "Produk berhasil ditambahkan."
    );

  }


  saveDatabase();

  closeModal();

  renderProducts();


  if (
    typeof renderSaleProducts ===
    "function"
  ) {

    renderSaleProducts();

  }


  if (
    typeof renderPurchaseCart ===
    "function"
  ) {

    renderPurchaseCart();

  }


  if (
    typeof updateDashboard ===
    "function"
  ) {

    updateDashboard();

  }

}


/* =========================================================
   RENDER PRODUCTS
========================================================= */

function renderProducts(
  keyword = ""
) {

  const table =
    document.getElementById(
      "productTable"
    );


  if (!table) return;


  const search =
    keyword
      .toLowerCase()
      .trim();


  const products =
    db.products.filter(
      product => {

        if (!search)
          return true;


        return (

          product.code
            .toLowerCase()
            .includes(search)

          ||

          product.name
            .toLowerCase()
            .includes(search)

        );

      }
    );


  if (!products.length) {

    table.innerHTML = `

      <tr>

        <td
          colspan="8"
          class="empty-state"
        >

          Belum ada produk

        </td>

      </tr>

    `;

    return;

  }


  table.innerHTML =

    products

      .map(
        product => {

          const low =
            Number(
              product.stock
            ) <=
            Number(
              product.minStock
            );


          return `

            <tr>

              <td>

                ${escapeHTML(
                  product.code
                )}

              </td>


              <td>

                <strong>

                  ${escapeHTML(
                    product.name
                  )}

                </strong>

              </td>


              <td>

                ${escapeHTML(
                  product.unit
                )}

              </td>


              <td>

                ${formatRupiah(
                  product.buyPrice
                )}

              </td>


              <td>

                ${formatRupiah(
                  product.sellPrice
                )}

              </td>


              <td
                class="${
                  low
                    ? "text-danger fw-bold"
                    : ""
                }"
              >

                ${formatNumber(
                  product.stock
                )}

              </td>


              <td>

                ${formatNumber(
                  product.minStock
                )}

              </td>


              <td>

                <div
                  class="action-group"
                >

                  <button
                    class="action-btn"
                    type="button"
                    title="Edit"
                    onclick="editProduct('${product.id}')"
                  >
                    ✎
                  </button>


                  <button
                    class="action-btn danger"
                    type="button"
                    title="Hapus"
                    onclick="deleteProduct('${product.id}')"
                  >
                    ×
                  </button>

                </div>

              </td>

            </tr>

          `;

        }
      )

      .join("");

}


/* =========================================================
   EDIT PRODUCT
========================================================= */

function editProduct(
  id
) {

  const product =
    db.products.find(
      p =>
        p.id ===
        id
    );


  if (!product) {

    showToast(
      "Produk tidak ditemukan.",
      "error"
    );

    return;

  }


  openProductForm(
    product
  );

}


/* =========================================================
   DELETE PRODUCT
========================================================= */

function deleteProduct(
  id
) {

  const product =
    db.products.find(
      p =>
        p.id ===
        id
    );


  if (!product)
    return;


  const used =
    db.sales.some(
      sale =>
        sale.items.some(
          item =>
            item.productId ===
            id
        )
    )

    ||

    db.purchases.some(
      purchase =>
        purchase.items.some(
          item =>
            item.productId ===
            id
        )
    );


  if (used) {

    showToast(
      "Produk sudah memiliki transaksi dan tidak dapat dihapus.",
      "error"
    );

    return;

  }


  if (
    !confirm(
      `Hapus produk "${product.name}"?`
    )
  ) {

    return;

  }


  db.products =
    db.products.filter(
      p =>
        p.id !==
        id
    );


  db.stockMovements =
    db.stockMovements.filter(
      movement =>
        movement.productId !==
        id
    );


  saveDatabase();

  renderProducts();


  if (
    typeof renderSaleProducts ===
    "function"
  ) {

    renderSaleProducts();

  }


  if (
    typeof updateDashboard ===
    "function"
  ) {

    updateDashboard();

  }


  showToast(
    "Produk berhasil dihapus."
  );

}


