/* =========================================================
   SAVE SUPPLIER
========================================================= */

function saveSupplier() {

  const code =
    document
      .getElementById(
        "modalSupplierCode"
      )
      ?.value
      .trim();


  const name =
    document
      .getElementById(
        "modalSupplierName"
      )
      ?.value
      .trim();


  const contact =
    document
      .getElementById(
        "modalSupplierContact"
      )
      ?.value
      .trim();


  const phone =
    document
      .getElementById(
        "modalSupplierPhone"
      )
      ?.value
      .trim();


  const address =
    document
      .getElementById(
        "modalSupplierAddress"
      )
      ?.value
      .trim();


  const note =
    document
      .getElementById(
        "modalSupplierNote"
      )
      ?.value
      .trim();


  /* VALIDASI */

  if (!code) {

    showToast(
      "Kode supplier wajib diisi.",
      "error"
    );

    return;

  }


  if (!name) {

    showToast(
      "Nama supplier wajib diisi.",
      "error"
    );

    return;

  }


  /* CEK KODE DUPLIKAT */

  const duplicate =
    db.suppliers.find(
      supplier =>

        String(
          supplier.code || ""
        )
          .toLowerCase() ===
        code.toLowerCase()

        &&

        supplier.id !==
        editingSupplierId

    );


  if (duplicate) {

    showToast(
      "Kode supplier sudah digunakan.",
      "error"
    );

    return;

  }


  /* =====================================================
     EDIT SUPPLIER
  ===================================================== */

  if (editingSupplierId) {

    const supplier =
      db.suppliers.find(
        item =>
          item.id ===
          editingSupplierId
      );


    if (!supplier) {

      showToast(
        "Supplier tidak ditemukan.",
        "error"
      );

      return;

    }


    supplier.code =
      code;

    supplier.name =
      name;

    supplier.contact =
      contact;

    supplier.phone =
      phone;

    supplier.address =
      address;

    supplier.note =
      note;

    supplier.updatedAt =
      new Date().toISOString();


    saveDatabase();

    closeModal();

    renderSuppliers();

    showToast(
      "Supplier berhasil diperbarui."
    );

    return;

  }


  /* =====================================================
     SUPPLIER BARU
  ===================================================== */

  const newSupplier = {

    id:
      generateId(
        "SUP"
      ),

    code,

    name,

    contact,

    phone,

    address,

    note,

    createdAt:
      new Date().toISOString(),

    updatedAt:
      new Date().toISOString()

  };


  db.suppliers.push(
    newSupplier
  );


  saveDatabase();

  closeModal();

  renderSuppliers();


  /* REFRESH MODUL PEMBELIAN
     JIKA SUDAH TERSEDIA */

  if (
    typeof renderPurchaseSuppliers ===
    "function"
  ) {

    renderPurchaseSuppliers();

  }


  if (
    typeof updateDashboard ===
    "function"
  ) {

    updateDashboard();

  }


  showToast(
    "Supplier berhasil ditambahkan."
  );

}


/* =========================================================
   END SUPPLIER POTONGAN 1
========================================================= */

/* =========================================================
   FAEZA ERP V2
   SUPPLIER MODULE
   BAGIAN 1/3 — POTONGAN SUPPLIER 2
========================================================= */


/* =========================================================
   RENDER SUPPLIER TABLE
========================================================= */

function renderSuppliers(keyword = "") {

  const table =
    document.getElementById(
      "supplierTable"
    );

  if (!table) return;


  const search =
    String(keyword || "")
      .toLowerCase()
      .trim();


  const suppliers =
    db.suppliers.filter(
      supplier => {

        if (!search) {
          return true;
        }


        const code =
          String(
            supplier.code || ""
          )
            .toLowerCase();


        const name =
          String(
            supplier.name || ""
          )
            .toLowerCase();


        const contact =
          String(
            supplier.contact || ""
          )
            .toLowerCase();


        const phone =
          String(
            supplier.phone || ""
          )
            .toLowerCase();


        return (

          code.includes(search)

          ||

          name.includes(search)

          ||

          contact.includes(search)

          ||

          phone.includes(search)

        );

      }
    );


  /* TIDAK ADA DATA */

  if (!suppliers.length) {

    table.innerHTML = `

      <tr>

        <td
          colspan="7"
          class="empty-state"
        >

          <div>
            📦
          </div>

          <strong>
            Belum ada supplier
          </strong>

          <small>
            Tambahkan supplier pertama
            untuk mulai menggunakan
            modul pembelian.
          </small>

        </td>

      </tr>

    `;

    return;

  }


  /* TABEL */

  table.innerHTML =

    suppliers
      .map(
        supplier => {

          const outstanding =
            getSupplierOutstanding(
              supplier.id
            );


          return `

            <tr>

              <td>
                ${escapeHTML(
                  supplier.code
                )}
              </td>


              <td>

                <strong>
                  ${escapeHTML(
                    supplier.name
                  )}
                </strong>

              </td>


              <td>
                ${escapeHTML(
                  supplier.contact ||
                  "-"
                )}
              </td>


              <td>
                ${escapeHTML(
                  supplier.phone ||
                  "-"
                )}
              </td>


              <td>

                <span
                  class="supplier-address"
                  title="${escapeHTML(
                    supplier.address ||
                    ""
                  )}"
                >

                  ${escapeHTML(
                    supplier.address ||
                    "-"
                  )}

                </span>

              </td>


              <td>

                <span
                  class="${
                    outstanding > 0
                      ? "text-danger fw-bold"
                      : "text-success"
                  }"
                >

                  ${formatRupiah(
                    outstanding
                  )}

                </span>

              </td>


              <td>

                <div
                  class="action-group"
                >

                  <button
                    type="button"
                    class="action-btn"
                    title="Edit Supplier"
                    onclick="editSupplier('${supplier.id}')"
                  >

                    ✎

                  </button>


                  <button
                    type="button"
                    class="action-btn danger"
                    title="Hapus Supplier"
                    onclick="deleteSupplier('${supplier.id}')"
                  >

                    ×

                  </button>

                </div>

              </td>

            </tr>

          `;

        }
      )
      .join("");

}


/* =========================================================
   EDIT SUPPLIER
========================================================= */

function editSupplier(id) {

  const supplier =
    db.suppliers.find(
      item =>
        item.id === id
    );


  if (!supplier) {

    showToast(
      "Supplier tidak ditemukan.",
      "error"
    );

    return;

  }


  openSupplierForm(
    supplier
  );

}


/* =========================================================
   CHECK SUPPLIER TRANSACTION
========================================================= */

function supplierHasTransactions(
  supplierId
) {

  return db.purchases.some(
    purchase =>
      purchase.supplierId ===
      supplierId
  );

}


/* =========================================================
   DELETE SUPPLIER
========================================================= */

function deleteSupplier(id) {

  const supplier =
    db.suppliers.find(
      item =>
        item.id === id
    );


  if (!supplier) {

    showToast(
      "Supplier tidak ditemukan.",
      "error"
    );

    return;

  }


  /* JANGAN HAPUS JIKA SUDAH
     DIPAKAI TRANSAKSI */

  if (
    supplierHasTransactions(
      id
    )
  ) {

    showToast(
      "Supplier sudah memiliki transaksi pembelian dan tidak dapat dihapus.",
      "error"
    );

    return;

  }


  const outstanding =
    getSupplierOutstanding(
      id
    );


  /* JANGAN HAPUS JIKA MASIH
     MEMILIKI HUTANG */

  if (
    outstanding > 0
  ) {

    showToast(
      "Supplier masih memiliki hutang yang belum lunas.",
      "error"
    );

    return;

  }


  const confirmed =
    confirm(
      `Hapus supplier "${supplier.name}"?`
    );


  if (!confirmed) {
    return;
  }


  db.suppliers =
    db.suppliers.filter(
      item =>
        item.id !== id
    );


  saveDatabase();

  renderSuppliers();


  if (
    typeof renderPurchaseSuppliers ===
    "function"
  ) {

    renderPurchaseSuppliers();

  }


  if (
    typeof updateDashboard ===
    "function"
  ) {

    updateDashboard();

  }


  showToast(
    "Supplier berhasil dihapus."
  );

}


/* =========================================================
   GET SUPPLIER OUTSTANDING DEBT
========================================================= */

function getSupplierOutstanding(
  supplierId
) {

  if (!supplierId) {
    return 0;
  }


  return db.debts

    .filter(
      debt =>

        debt.supplierId ===
        supplierId

    )

    .reduce(
      (
        total,
        debt
      ) => {

        const totalDebt =
          Number(
            debt.total
          ) || 0;


        const paid =
          Number(
            debt.paid
          ) || 0;


        const remaining =
          Math.max(
            0,
            totalDebt - paid
          );


        return (
          total +
          remaining
        );

      },

      0

    );

}


/* =========================================================
   SUPPLIER SEARCH
========================================================= */

function initSupplierSearch() {

  const searchInput =
    document.getElementById(
      "supplierSearch"
    );


  if (!searchInput) {
    return;
  }


  searchInput.addEventListener(
    "input",
    event => {

      renderSuppliers(
        event.target.value
      );

    }
  );

}


/* =========================================================
   SUPPLIER TOTAL
========================================================= */

function getSupplierCount() {

  return db.suppliers.length;

}


/* =========================================================
   FIND SUPPLIER
========================================================= */

function findSupplier(
  supplierId
) {

  return db.suppliers.find(
    supplier =>
      supplier.id ===
      supplierId
  ) || null;

}


/* =========================================================
   FIND SUPPLIER BY CODE
========================================================= */

function findSupplierByCode(
  code
) {

  if (!code) {
    return null;
  }


  const normalized =
    String(code)
      .trim()
      .toLowerCase();


  return db.suppliers.find(
    supplier =>

      String(
        supplier.code || ""
      )
        .trim()
        .toLowerCase() ===
      normalized

  ) || null;

}


/* =========================================================
   SUPPLIER NAME
========================================================= */

function getSupplierName(
  supplierId
) {

  const supplier =
    findSupplier(
      supplierId
    );


  return supplier
    ? supplier.name
    : "-";

}


