/* =========================================================
   SUPPLIER SUMMARY
========================================================= */

function getSupplierSummary() {

  const totalSupplier =
    db.suppliers.length;


  const totalDebt =
    db.suppliers.reduce(
      (total, supplier) => {

        return (
          total +
          getSupplierOutstanding(
            supplier.id
          )
        );

      },
      0
    );


  return {

    totalSupplier,

    totalDebt

  };

}


/* =========================================================
   SUPPLIER OPTION HTML
   Digunakan oleh modul PEMBELIAN
========================================================= */

function getSupplierOptions(
  selectedId = ""
) {

  let html = `

    <option value="">
      -- Pilih Supplier --
    </option>

  `;


  db.suppliers.forEach(
    supplier => {

      html += `

        <option
          value="${escapeHTML(
            supplier.id
          )}"
          ${
            supplier.id ===
            selectedId
              ? "selected"
              : ""
          }
        >

          ${escapeHTML(
            supplier.code
          )}
          -
          ${escapeHTML(
            supplier.name
          )}

        </option>

      `;

    }
  );


  return html;

}


/* =========================================================
   SUPPLIER VALIDATION
========================================================= */

function validateSupplier(
  supplierId
) {

  if (!supplierId) {

    showToast(
      "Supplier belum dipilih.",
      "error"
    );

    return false;

  }


  const supplier =
    findSupplier(
      supplierId
    );


  if (!supplier) {

    showToast(
      "Data supplier tidak ditemukan.",
      "error"
    );

    return false;

  }


  return true;

}


/* =========================================================
   SUPPLIER DELETE CHECK
   Dipakai oleh modul lain
========================================================= */

function canDeleteSupplier(
  supplierId
) {

  if (
    supplierHasTransactions(
      supplierId
    )
  ) {

    return {

      allowed: false,

      reason:
        "Supplier sudah memiliki transaksi."

    };

  }


  if (
    getSupplierOutstanding(
      supplierId
    ) > 0
  ) {

    return {

      allowed: false,

      reason:
        "Supplier masih memiliki hutang."

    };

  }


  return {

    allowed: true,

    reason: ""

  };

}


/* =========================================================
   SUPPLIER BALANCE
========================================================= */

function getSupplierBalance(
  supplierId
) {

  const debt =
    getSupplierOutstanding(
      supplierId
    );


  return {

    debt,

    status:
      debt > 0
        ? "BELUM LUNAS"
        : "LUNAS"

  };

}


/* =========================================================
   SUPPLIER TRANSACTION COUNT
========================================================= */

function getSupplierTransactionCount(
  supplierId
) {

  return db.purchases.filter(
    purchase =>
      purchase.supplierId ===
      supplierId
  ).length;

}


/* =========================================================
   SUPPLIER CARD
========================================================= */

function renderSupplierSummary() {

  const totalEl =
    document.getElementById(
      "totalSupplier"
    );


  const debtEl =
    document.getElementById(
      "totalSupplierDebt"
    );


  if (
    totalEl
  ) {

    totalEl.textContent =
      formatNumber(
        db.suppliers.length
      );

  }


  if (
    debtEl
  ) {

    const totalDebt =
      db.suppliers.reduce(
        (
          total,
          supplier
        ) => {

          return (

            total +

            getSupplierOutstanding(
              supplier.id
            )

          );

        },

        0

      );


    debtEl.textContent =
      formatRupiah(
        totalDebt
      );

  }

}


/* =========================================================
   REFRESH SUPPLIER MODULE
========================================================= */

function refreshSupplierModule() {

  renderSuppliers();

  renderSupplierSummary();

}


