/* =========================================================
   PURCHASE STATE
========================================================= */

let purchaseCart = [];

let selectedPurchaseSupplierId = "";

let selectedPurchasePayment =
  "CASH";


/* =========================================================
   RESET PURCHASE CART
========================================================= */

function resetPurchaseCart() {

  purchaseCart = [];

  selectedPurchaseSupplierId =
    "";

  selectedPurchasePayment =
    "CASH";


  const supplierSelect =
    document.getElementById(
      "purchaseSupplier"
    );


  if (supplierSelect) {

    supplierSelect.value =
      "";

  }


  const paymentSelect =
    document.getElementById(
      "purchasePayment"
    );


  if (paymentSelect) {

    paymentSelect.value =
      "CASH";

  }


  renderPurchaseCart();

}


/* =========================================================
   FIND PRODUCT
========================================================= */

function findProduct(
  productId
) {

  return db.products.find(
    product =>
      product.id ===
      productId
  ) || null;

}


/* =========================================================
   FIND PRODUCT BY CODE
========================================================= */

function findProductByCode(
  code
) {

  if (!code) {

    return null;

  }


  const normalized =
    String(code)
      .trim()
      .toLowerCase();


  return db.products.find(
    product =>

      String(
        product.code || ""
      )
        .trim()
        .toLowerCase() ===
      normalized

  ) || null;

}


/* =========================================================
   GET PRODUCT NAME
========================================================= */

function getProductName(
  productId
) {

  const product =
    findProduct(
      productId
    );


  return product
    ? product.name
    : "-";

}


/* =========================================================
   GET PRODUCT OPTIONS
========================================================= */

function getProductOptions(
  selectedId = ""
) {

  let html = `

    <option value="">
      -- Pilih Produk --
    </option>

  `;


  db.products.forEach(
    product => {

      html += `

        <option
          value="${escapeHTML(
            product.id
          )}"
          ${
            product.id ===
            selectedId
              ? "selected"
              : ""
          }
        >

          ${escapeHTML(
            product.code
          )}
          -
          ${escapeHTML(
            product.name
          )}

        </option>

      `;

    }
  );


  return html;

}


/* =========================================================
   ADD PRODUCT TO PURCHASE CART
========================================================= */

function addPurchaseItem(
  productId,
  qty,
  price
) {

  const product =
    findProduct(
      productId
    );


  if (!product) {

    showToast(
      "Produk tidak ditemukan.",
      "error"
    );

    return false;

  }


  const quantity =
    Number(qty);


  const buyPrice =
    Number(price);


  if (
    !Number.isFinite(
      quantity
    )
    ||
    quantity <= 0
  ) {

    showToast(
      "Jumlah pembelian harus lebih dari 0.",
      "error"
    );

    return false;

  }


  if (
    !Number.isFinite(
      buyPrice
    )
    ||
    buyPrice < 0
  ) {

    showToast(
      "Harga beli tidak valid.",
      "error"
    );

    return false;

  }


  /* CEK PRODUK SUDAH ADA
     DI KERANJANG */

  const existing =
    purchaseCart.find(
      item =>
        item.productId ===
        productId
    );


  if (existing) {

    existing.qty +=
      quantity;

    existing.price =
      buyPrice;

    existing.subtotal =
      existing.qty *
      existing.price;

  }


  else {

    purchaseCart.push({

      productId,

      code:
        product.code,

      name:
        product.name,

      unit:
        product.unit,

      qty:
        quantity,

      price:
        buyPrice,

      subtotal:
        quantity *
        buyPrice

    });

  }


  renderPurchaseCart();

  return true;

}


/* =========================================================
   REMOVE PURCHASE ITEM
========================================================= */

function removePurchaseItem(
  productId
) {

  purchaseCart =
    purchaseCart.filter(
      item =>
        item.productId !==
        productId
    );


  renderPurchaseCart();

}


/* =========================================================
   UPDATE PURCHASE ITEM QTY
========================================================= */

function updatePurchaseQty(
  productId,
  qty
) {

  const item =
    purchaseCart.find(
      purchase =>
        purchase.productId ===
        productId
    );


  if (!item) {
    return;
  }


  const quantity =
    Number(qty);


  if (
    !Number.isFinite(
      quantity
    )
    ||
    quantity <= 0
  ) {

    removePurchaseItem(
      productId
    );

    return;

  }


  item.qty =
    quantity;


  item.subtotal =
    item.qty *
    item.price;


  renderPurchaseCart();

}


/* =========================================================
   UPDATE PURCHASE PRICE
========================================================= */

function updatePurchasePrice(
  productId,
  price
) {

  const item =
    purchaseCart.find(
      purchase =>
        purchase.productId ===
        productId
    );


  if (!item) {
    return;
  }


  const buyPrice =
    Number(price);


  if (
    !Number.isFinite(
      buyPrice
    )
    ||
    buyPrice < 0
  ) {

    return;

  }


  item.price =
    buyPrice;


  item.subtotal =
    item.qty *
    item.price;


  renderPurchaseCart();

}


/* =========================================================
   PURCHASE SUBTOTAL
========================================================= */

function getPurchaseSubtotal() {

  return purchaseCart.reduce(
    (
      total,
      item
    ) => {

      return (

        total +

        (
          Number(
            item.subtotal
          ) || 0
        )

      );

    },

    0

  );

}


/* =========================================================
   PURCHASE TOTAL
========================================================= */

function getPurchaseTotal() {

  return getPurchaseSubtotal();

}


/* =========================================================
   SET PURCHASE SUPPLIER
========================================================= */

function setPurchaseSupplier(
  supplierId
) {

  if (
    supplierId &&
    !validateSupplier(
      supplierId
    )
  ) {

    return;

  }


  selectedPurchaseSupplierId =
    supplierId || "";


  const select =
    document.getElementById(
      "purchaseSupplier"
    );


  if (
    select &&
    select.value !==
    selectedPurchaseSupplierId
  ) {

    select.value =
      selectedPurchaseSupplierId;

  }

}


/* =========================================================
   SET PURCHASE PAYMENT
========================================================= */

function setPurchasePayment(
  paymentType
) {

  const normalized =
    String(
      paymentType || ""
    )
      .toUpperCase();


  if (
    normalized !==
      "CASH"
    &&
    normalized !==
      "CREDIT"
  ) {

    selectedPurchasePayment =
      "CASH";

  }

  else {

    selectedPurchasePayment =
      normalized;

  }


  const select =
    document.getElementById(
      "purchasePayment"
    );


  if (select) {

    select.value =
      selectedPurchasePayment;

  }


  updatePurchasePaymentUI();

}


/* =========================================================
   PURCHASE PAYMENT UI
========================================================= */

function updatePurchasePaymentUI() {

  const payment =
    selectedPurchasePayment;


  const debtInfo =
    document.getElementById(
      "purchaseDebtInfo"
    );


  if (!debtInfo) {
    return;
  }


  if (
    payment ===
    "CREDIT"
  ) {

    debtInfo.style.display =
      "";

    debtInfo.innerHTML = `

      <div class="info-box warning">

        <strong>
          Pembelian Kredit
        </strong>

        <div>
          Total akan otomatis
          masuk ke Hutang Supplier.
        </div>

      </div>

    `;

  }


  else {

    debtInfo.style.display =
      "none";

    debtInfo.innerHTML =
      "";

  }

}


/* =========================================================
   PURCHASE CART TOTAL UI
========================================================= */

function updatePurchaseTotals() {

  const subtotal =
    getPurchaseSubtotal();


  const total =
    getPurchaseTotal();


  const subtotalEl =
    document.getElementById(
      "purchaseSubtotal"
    );


  const totalEl =
    document.getElementById(
      "purchaseTotal"
    );


  if (subtotalEl) {

    subtotalEl.textContent =
      formatRupiah(
        subtotal
      );

  }


  if (totalEl) {

    totalEl.textContent =
      formatRupiah(
        total
      );

  }


  const countEl =
    document.getElementById(
      "purchaseItemCount"
    );


  if (countEl) {

    countEl.textContent =
      formatNumber(
        purchaseCart.length
      );

  }

}


/* =========================================================
   END PEMBELIAN POTONGAN 1
========================================================= */

/* =========================================================
   FAEZA ERP V2
   PEMBELIAN + STOK MASUK
   BAGIAN 1/3 — POTONGAN 2
========================================================= */


/* =========================================================
   RENDER PURCHASE SUPPLIERS
========================================================= */

function renderPurchaseSuppliers() {

  const select =
    document.getElementById(
      "purchaseSupplier"
    );


  if (!select) {
    return;
  }


  const current =
    selectedPurchaseSupplierId ||
    select.value ||
    "";


  select.innerHTML =
    getSupplierOptions(
      current
    );


  if (
    current &&
    db.suppliers.some(
      supplier =>
        supplier.id ===
        current
    )
  ) {

    select.value =
      current;

    selectedPurchaseSupplierId =
      current;

  }

}


/* =========================================================
   RENDER PURCHASE PRODUCTS
========================================================= */

function renderPurchaseProducts(
  keyword = ""
) {

  const container =
    document.getElementById(
      "purchaseProductList"
    );


  if (!container) {
    return;
  }


  const search =
    String(
      keyword || ""
    )
      .toLowerCase()
      .trim();


  const products =
    db.products.filter(
      product => {

        if (!search) {
          return true;
        }


        return (

          String(
            product.code || ""
          )
            .toLowerCase()
            .includes(search)

          ||

          String(
            product.name || ""
          )
            .toLowerCase()
            .includes(search)

        );

      }
    );


  if (!products.length) {

    container.innerHTML = `

      <div class="empty-state">

        <div>
          📦
        </div>

        <strong>
          Produk tidak ditemukan
        </strong>

      </div>

    `;

    return;

  }


  container.innerHTML =

    products
      .map(
        product => `

          <button
            type="button"
            class="purchase-product-item"
            onclick="openPurchaseProduct('${product.id}')"
          >

            <span
              class="product-code"
            >

              ${escapeHTML(
                product.code
              )}

            </span>


            <strong>

              ${escapeHTML(
                product.name
              )}

            </strong>


            <span>

              Harga terakhir:
              ${formatRupiah(
                product.buyPrice
              )}

            </span>


            <small>

              Stok saat ini:
              ${formatNumber(
                product.stock
              )}
              ${escapeHTML(
                product.unit
              )}

            </small>

          </button>

        `
      )
      .join("");

}


