/* =========================================================
   CLEAR PURCHASE CART
========================================================= */

function clearPurchaseCart() {

  if (
    !purchaseCart.length
  ) {

    showToast(
      "Keranjang pembelian sudah kosong.",
      "info"
    );

    return;

  }


  const confirmed =
    confirm(
      "Kosongkan seluruh keranjang pembelian?"
    );


  if (!confirmed) {
    return;
  }


  purchaseCart = [];


  renderPurchaseCart();


  showToast(
    "Keranjang pembelian dikosongkan."
  );

}


/* =========================================================
   CANCEL PURCHASE
========================================================= */

function cancelPurchase() {

  const hasData =
    purchaseCart.length > 0
    ||
    selectedPurchaseSupplierId;


  if (!hasData) {

    resetPurchaseCart();

    return;

  }


  const confirmed =
    confirm(
      "Batalkan transaksi pembelian saat ini?"
    );


  if (!confirmed) {
    return;
  }


  resetPurchaseCart();


  showToast(
    "Transaksi pembelian dibatalkan.",
    "info"
  );

}


/* =========================================================
   PURCHASE CART VALIDATION
========================================================= */

function validatePurchaseCart() {

  if (
    !purchaseCart.length
  ) {

    showToast(
      "Keranjang pembelian masih kosong.",
      "error"
    );

    return false;

  }


  if (
    !selectedPurchaseSupplierId
  ) {

    const select =
      document.getElementById(
        "purchaseSupplier"
      );


    if (
      select &&
      select.value
    ) {

      selectedPurchaseSupplierId =
        select.value;

    }

  }


  if (
    !selectedPurchaseSupplierId
  ) {

    showToast(
      "Supplier wajib dipilih.",
      "error"
    );

    return false;

  }


  if (
    !validateSupplier(
      selectedPurchaseSupplierId
    )
  ) {

    return false;

  }


  for (
    const item
    of purchaseCart
  ) {

    const product =
      findProduct(
        item.productId
      );


    if (!product) {

      showToast(
        `Produk ${item.code} tidak ditemukan.`,
        "error"
      );

      return false;

    }


    if (
      Number(item.qty) <= 0
    ) {

      showToast(
        `Jumlah ${item.name} tidak valid.`,
        "error"
      );

      return false;

    }


    if (
      Number(item.price) < 0
    ) {

      showToast(
        `Harga ${item.name} tidak valid.`,
        "error"
      );

      return false;

    }

  }


  return true;

}


