/* =========================================================
   FAEZA ERP V2
   HUTANG SUPPLIER
   BAGIAN 1/3 — POTONGAN 1
========================================================= */


/* =========================================================
   DEBT STATE
========================================================= */

let selectedDebtId = null;

let debtFilterStatus = "ALL";


/* =========================================================
   NORMALIZE DEBT
========================================================= */

function normalizeDebt(debt) {

  const total =
    Number(debt.total) || 0;

  const paid =
    Number(debt.paid) || 0;

  const remaining =
    Math.max(
      0,
      total - paid
    );


  debt.total =
    total;

  debt.paid =
    Math.min(
      paid,
      total
    );

  debt.remaining =
    remaining;


  if (
    remaining <= 0
  ) {

    debt.status =
      "PAID";

  }

  else if (
    paid > 0
  ) {

    debt.status =
      "PARTIAL";

  }

  else {

    debt.status =
      "UNPAID";

  }


  return debt;

}


/* =========================================================
   GET DEBT
========================================================= */

function findDebt(
  debtId
) {

  return db.debts.find(
    debt =>
      debt.id ===
      debtId
  ) || null;

}


/* =========================================================
   GET SUPPLIER DEBTS
========================================================= */

function getSupplierDebts(
  supplierId
) {

  return db.debts.filter(
    debt =>
      debt.supplierId ===
      supplierId
  );

}


/* =========================================================
   GET TOTAL DEBT
========================================================= */

function getTotalDebt() {

  return db.debts.reduce(
    (
      total,
      debt
    ) => {

      normalizeDebt(
        debt
      );

      return (

        total +
        Number(
          debt.remaining
        )

      );

    },

    0
  );

}


/* =========================================================
   GET TOTAL ORIGINAL DEBT
========================================================= */

function getTotalOriginalDebt() {

  return db.debts.reduce(
    (
      total,
      debt
    ) => {

      return (

        total +
        (
          Number(
            debt.total
          ) || 0
        )

      );

    },

    0
  );

}


/* =========================================================
   GET TOTAL DEBT PAID
========================================================= */

function getTotalDebtPaid() {

  return db.debts.reduce(
    (
      total,
      debt
    ) => {

      return (

        total +
        (
          Number(
            debt.paid
          ) || 0
        )

      );

    },

    0
  );

}


/* =========================================================
   DEBT STATUS LABEL
========================================================= */

function getDebtStatusLabel(
  status
) {

  switch (
    String(
      status || ""
    )
      .toUpperCase()
  ) {

    case "PAID":

      return "LUNAS";


    case "PARTIAL":

      return "SEBAGIAN";


    case "UNPAID":

      return "BELUM LUNAS";


    default:

      return "-";

  }

}


/* =========================================================
   DEBT STATUS CLASS
========================================================= */

function getDebtStatusClass(
  status
) {

  switch (
    String(
      status || ""
    )
      .toUpperCase()
  ) {

    case "PAID":

      return "badge-success";


    case "PARTIAL":

      return "badge-warning";


    case "UNPAID":

      return "badge-danger";


    default:

      return "badge";

  }

}


/* =========================================================
   RENDER DEBT SUMMARY
========================================================= */

function renderDebtSummary() {

  const totalDebtEl =
    document.getElementById(
      "totalDebt"
    );


  const originalEl =
    document.getElementById(
      "totalOriginalDebt"
    );


  const paidEl =
    document.getElementById(
      "totalDebtPaid"
    );


  const unpaidCountEl =
    document.getElementById(
      "unpaidDebtCount"
    );


  const partialCountEl =
    document.getElementById(
      "partialDebtCount"
    );


  const paidCountEl =
    document.getElementById(
      "paidDebtCount"
    );


  const totalDebt =
    getTotalDebt();


  const originalDebt =
    getTotalOriginalDebt();


  const paidDebt =
    getTotalDebtPaid();


  const unpaidCount =
    db.debts.filter(
      debt => {

        normalizeDebt(
          debt
        );

        return (
          debt.status ===
          "UNPAID"
        );

      }
    ).length;


  const partialCount =
    db.debts.filter(
      debt => {

        normalizeDebt(
          debt
        );

        return (
          debt.status ===
          "PARTIAL"
        );

      }
    ).length;


  const paidCount =
    db.debts.filter(
      debt => {

        normalizeDebt(
          debt
        );

        return (
          debt.status ===
          "PAID"
        );

      }
    ).length;


  if (totalDebtEl) {

    totalDebtEl.textContent =
      formatRupiah(
        totalDebt
      );

  }


  if (originalEl) {

    originalEl.textContent =
      formatRupiah(
        originalDebt
      );

  }


  if (paidEl) {

    paidEl.textContent =
      formatRupiah(
        paidDebt
      );

  }


  if (unpaidCountEl) {

    unpaidCountEl.textContent =
      formatNumber(
        unpaidCount
      );

  }


  if (partialCountEl) {

    partialCountEl.textContent =
      formatNumber(
        partialCount
      );

  }


  if (paidCountEl) {

    paidCountEl.textContent =
      formatNumber(
        paidCount
      );

  }

}


/* =========================================================
   RENDER DEBT TABLE
========================================================= */

function renderDebts(
  keyword = ""
) {

  const table =
    document.getElementById(
      "debtTable"
    );


  if (!table) {
    return;
  }


  const search =
    String(
      keyword || ""
    )
      .toLowerCase()
      .trim();


  const debts =
    [...db.debts]
      .reverse()
      .filter(
        debt => {

          normalizeDebt(
            debt
          );


          /* FILTER STATUS */

          if (
            debtFilterStatus !==
            "ALL"
          ) {

            if (
              debt.status !==
              debtFilterStatus
            ) {

              return false;

            }

          }


          /* SEARCH */

          if (!search) {

            return true;

          }


          return (

            String(
              debt.purchaseNumber ||
              ""
            )
              .toLowerCase()
              .includes(search)

            ||

            String(
              debt.supplierName ||
              ""
            )
              .toLowerCase()
              .includes(search)

            ||

            String(
              debt.description ||
              ""
            )
              .toLowerCase()
              .includes(search)

          );

        }
      );


  if (!debts.length) {

    table.innerHTML = `

      <tr>

        <td
          colspan="8"
          class="empty-state"
        >

          <div>
            💰
          </div>

          <strong>
            Belum ada data hutang
          </strong>

          <small>
            Hutang dari pembelian kredit
            akan muncul otomatis di sini.
          </small>

        </td>

      </tr>

    `;

    renderDebtSummary();

    return;

  }


  table.innerHTML =

    debts
      .map(
        debt => `

          <tr>

            <td>

              ${escapeHTML(
                debt.purchaseNumber ||
                "-"
              )}

            </td>


            <td>

              ${escapeHTML(
                debt.date ||
                "-"
              )}

            </td>


            <td>

              <strong>

                ${escapeHTML(
                  debt.supplierName ||
                  "-"
                )}

              </strong>

            </td>


            <td>

              ${formatRupiah(
                debt.total
              )}

            </td>


            <td>

              ${formatRupiah(
                debt.paid
              )}

            </td>


            <td>

              <strong>

                ${formatRupiah(
                  debt.remaining
                )}

              </strong>

            </td>


            <td>

              <span
                class="badge ${getDebtStatusClass(
                  debt.status
                )}"
              >

                ${getDebtStatusLabel(
                  debt.status
                )}

              </span>

            </td>


            <td>

              <div
                class="action-group"
              >

                <button
                  type="button"
                  class="action-btn"
                  title="Detail"
                  onclick="viewDebtDetail('${debt.id}')"
                >

                  👁

                </button>


                ${
                  debt.remaining > 0
                    ? `

                      <button
                        type="button"
                        class="action-btn"
                        title="Bayar Hutang"
                        onclick="openDebtPayment('${debt.id}')"
                      >

                        💳

                      </button>

                    `
                    : ""
                }

              </div>

            </td>

          </tr>

        `
      )
      .join("");


  renderDebtSummary();

}


/* =========================================================
   DEBT SEARCH
========================================================= */

function initDebtSearch() {

  const input =
    document.getElementById(
      "debtSearch"
    );


  if (!input) {
    return;
  }


  input.addEventListener(
    "input",
    event => {

      renderDebts(
        event.target.value
      );

    }
  );

}


/* =========================================================
   DEBT STATUS FILTER
========================================================= */

function setDebtFilter(
  status
) {

  const normalized =
    String(
      status || "ALL"
    )
      .toUpperCase();


  const allowed = [
    "ALL",
    "UNPAID",
    "PARTIAL",
    "PAID"
  ];


  debtFilterStatus =
    allowed.includes(
      normalized
    )
      ? normalized
      : "ALL";


  const searchInput =
    document.getElementById(
      "debtSearch"
    );


  renderDebts(
    searchInput
      ? searchInput.value
      : ""
  );

}


