/* =========================================================
   OPEN DEBT PAYMENT
========================================================= */

function openDebtPayment(debtId) {

  const debt = findDebt(debtId);

  if (!debt) {
    showToast(
      "Data hutang tidak ditemukan.",
      "error"
    );
    return;
  }


  normalizeDebt(debt);


  if (debt.remaining <= 0) {

    showToast(
      "Hutang ini sudah lunas.",
      "info"
    );

    return;
  }


  selectedDebtId = debt.id;


  const supplierName =
    debt.supplierName ||
    getSupplierName(
      debt.supplierId
    );


  const body = `

    <div class="form-grid">

      <div
        class="form-group"
        style="grid-column:1/-1"
      >

        <label>
          Supplier
        </label>

        <input
          type="text"
          value="${escapeHTML(
            supplierName
          )}"
          disabled
        >

      </div>


      <div class="form-group">

        <label>
          No. Pembelian
        </label>

        <input
          type="text"
          value="${escapeHTML(
            debt.purchaseNumber ||
            "-"
          )}"
          disabled
        >

      </div>


      <div class="form-group">

        <label>
          Sisa Hutang
        </label>

        <input
          type="text"
          value="${formatRupiah(
            debt.remaining
          )}"
          disabled
        >

      </div>


      <div
        class="form-group"
        style="grid-column:1/-1"
      >

        <label for="debtPaymentAmount">
          Nominal Pembayaran
        </label>

        <input
          id="debtPaymentAmount"
          type="number"
          min="1"
          max="${debt.remaining}"
          step="1"
          value="${debt.remaining}"
          inputmode="numeric"
        >

        <small>
          Maksimal:
          ${formatRupiah(
            debt.remaining
          )}
        </small>

      </div>


      <div
        class="form-group"
        style="grid-column:1/-1"
      >

        <label for="debtPaymentDate">
          Tanggal Pembayaran
        </label>

        <input
          id="debtPaymentDate"
          type="date"
          value="${today()}"
        >

      </div>


      <div
        class="form-group"
        style="grid-column:1/-1"
      >

        <label for="debtPaymentNote">
          Catatan
        </label>

        <textarea
          id="debtPaymentNote"
          rows="2"
          placeholder="Catatan pembayaran..."
        ></textarea>

      </div>

    </div>

  `;


  openModal(
    "Bayar Hutang Supplier",
    body,
    saveDebtPayment
  );

}


/* =========================================================
   VALIDATE DEBT PAYMENT
========================================================= */

function validateDebtPayment(
  debt,
  amount
) {

  if (!debt) {

    showToast(
      "Data hutang tidak ditemukan.",
      "error"
    );

    return false;
  }


  normalizeDebt(debt);


  if (
    debt.remaining <= 0
  ) {

    showToast(
      "Hutang sudah lunas.",
      "info"
    );

    return false;
  }


  if (
    !Number.isFinite(amount)
    ||
    amount <= 0
  ) {

    showToast(
      "Nominal pembayaran harus lebih dari 0.",
      "error"
    );

    return false;
  }


  if (
    amount >
    debt.remaining
  ) {

    showToast(
      "Pembayaran melebihi sisa hutang.",
      "error"
    );

    return false;
  }


  return true;

}


/* =========================================================
   SAVE DEBT PAYMENT
========================================================= */

function saveDebtPayment() {

  if (!selectedDebtId) {

    showToast(
      "Hutang belum dipilih.",
      "error"
    );

    return;
  }


  const debt =
    findDebt(
      selectedDebtId
    );


  if (!debt) {

    showToast(
      "Data hutang tidak ditemukan.",
      "error"
    );

    return;
  }


  const amount =
    Number(
      document
        .getElementById(
          "debtPaymentAmount"
        )
        ?.value
    );


  const paymentDate =
    document
      .getElementById(
        "debtPaymentDate"
      )
      ?.value
      ||
      today();


  const note =
    document
      .getElementById(
        "debtPaymentNote"
      )
      ?.value
      .trim()
      ||
      "";


  if (
    !validateDebtPayment(
      debt,
      amount
    )
  ) {

    return;
  }


  normalizeDebt(debt);


  const previousPaid =
    Number(
      debt.paid
    ) || 0;


  const previousRemaining =
    Number(
      debt.remaining
    ) || 0;


  const newPaid =
    previousPaid +
    amount;


  const newRemaining =
    Math.max(
      0,
      Number(
        debt.total
      ) -
      newPaid
    );


  /* =====================================================
     UPDATE HUTANG
  ===================================================== */

  debt.paid =
    newPaid;


  debt.remaining =
    newRemaining;


  debt.status =
    newRemaining <= 0
      ? "PAID"
      : "PARTIAL";


  debt.updatedAt =
    new Date()
      .toISOString();


  /* =====================================================
     PAYMENT HISTORY
  ===================================================== */

  if (
    !Array.isArray(
      db.debtPayments
    )
  ) {

    db.debtPayments = [];

  }


  const payment = {

    id:
      generateId(
        "BYH"
      ),

    debtId:
      debt.id,

    supplierId:
      debt.supplierId,

    supplierName:
      debt.supplierName,

    purchaseId:
      debt.purchaseId,

    purchaseNumber:
      debt.purchaseNumber,

    date:
      paymentDate,

    amount:
      amount,

    balanceBefore:
      previousRemaining,

    balanceAfter:
      newRemaining,

    note:
      note,

    createdAt:
      new Date()
        .toISOString()

  };


  db.debtPayments.push(
    payment
  );


  /* =====================================================
     SAVE
  ===================================================== */

  saveDatabase();


  /* =====================================================
     RESET
  ===================================================== */

  selectedDebtId =
    null;


  closeModal();


  /* =====================================================
     REFRESH
  ===================================================== */

  renderDebts();


  renderDebtSummary();


  renderSuppliers();


  if (
    typeof updateDashboard ===
    "function"
  ) {

    updateDashboard();

  }


  showToast(

    newRemaining <= 0

      ? "Hutang berhasil dilunasi."

      : `Pembayaran ${formatRupiah(
          amount
        )} berhasil dicatat.`

  );

}


/* =========================================================
   GET DEBT PAYMENTS
========================================================= */

function getDebtPayments(
  debtId
) {

  if (
    !Array.isArray(
      db.debtPayments
    )
  ) {

    return [];

  }


  return db.debtPayments
    .filter(
      payment =>
        payment.debtId ===
        debtId
    )
    .sort(
      (
        a,
        b
      ) => {

        return String(
          b.date || ""
        ).localeCompare(
          String(
            a.date || ""
          )
        );

      }
    );

}


/* =========================================================
   GET SUPPLIER PAYMENTS
========================================================= */

function getSupplierPayments(
  supplierId
) {

  if (
    !Array.isArray(
      db.debtPayments
    )
  ) {

    return [];

  }


  return db.debtPayments
    .filter(
      payment =>
        payment.supplierId ===
        supplierId
    );

}


/* =========================================================
   GET TOTAL PAYMENT FOR DEBT
========================================================= */

function getDebtPaymentTotal(
  debtId
) {

  return getDebtPayments(
    debtId
  ).reduce(
    (
      total,
      payment
    ) => {

      return (

        total +
        (
          Number(
            payment.amount
          ) || 0
        )

      );

    },
    0
  );

}


/* =========================================================
   RENDER DEBT PAYMENT HISTORY
========================================================= */

function renderDebtPaymentHistory(
  debtId
) {

  const container =
    document.getElementById(
      "debtPaymentHistory"
    );


  if (!container) {
    return;
  }


  const payments =
    getDebtPayments(
      debtId
    );


  if (!payments.length) {

    container.innerHTML = `

      <div class="empty-state">

        Belum ada pembayaran.

      </div>

    `;

    return;
  }


  container.innerHTML = `

    <div class="table-wrapper">

      <table>

        <thead>

          <tr>

            <th>
              Tanggal
            </th>

            <th>
              Nominal
            </th>

            <th>
              Saldo Sebelum
            </th>

            <th>
              Saldo Sesudah
            </th>

            <th>
              Catatan
            </th>

          </tr>

        </thead>

        <tbody>

          ${payments
            .map(
              payment => `

                <tr>

                  <td>
                    ${escapeHTML(
                      payment.date ||
                      "-"
                    )}
                  </td>

                  <td>
                    <strong>
                      ${formatRupiah(
                        payment.amount
                      )}
                    </strong>
                  </td>

                  <td>
                    ${formatRupiah(
                      payment.balanceBefore
                    )}
                  </td>

                  <td>
                    ${formatRupiah(
                      payment.balanceAfter
                    )}
                  </td>

                  <td>
                    ${escapeHTML(
                      payment.note ||
                      "-"
                    )}
                  </td>

                </tr>

              `
            )
            .join("")}

        </tbody>

      </table>

    </div>

  `;

}


/* =========================================================
   QUICK FULL PAYMENT
========================================================= */

function payDebtInFull(
  debtId
) {

  const debt =
    findDebt(
      debtId
    );


  if (!debt) {

    showToast(
      "Data hutang tidak ditemukan.",
      "error"
    );

    return;
  }


  normalizeDebt(debt);


  if (
    debt.remaining <= 0
  ) {

    showToast(
      "Hutang sudah lunas.",
      "info"
    );

    return;
  }


  selectedDebtId =
    debt.id;


  const confirmed =
    confirm(
      `Lunasi hutang sebesar ${formatRupiah(
        debt.remaining
      )}?`
    );


  if (!confirmed) {

    selectedDebtId =
      null;

    return;
  }


  const amount =
    debt.remaining;


  const previousRemaining =
    debt.remaining;


  debt.paid =
    Number(
      debt.paid
    ) +
    amount;


  debt.remaining =
    0;


  debt.status =
    "PAID";


  debt.updatedAt =
    new Date()
      .toISOString();


  if (
    !Array.isArray(
      db.debtPayments
    )
  ) {

    db.debtPayments = [];

  }


  db.debtPayments.push({

    id:
      generateId(
        "BYH"
      ),

    debtId:
      debt.id,

    supplierId:
      debt.supplierId,

    supplierName:
      debt.supplierName,

    purchaseId:
      debt.purchaseId,

    purchaseNumber:
      debt.purchaseNumber,

    date:
      today(),

    amount:
      amount,

    balanceBefore:
      previousRemaining,

    balanceAfter:
      0,

    note:
      "Pelunasan hutang",

    createdAt:
      new Date()
        .toISOString()

  });


  saveDatabase();


  selectedDebtId =
    null;


  renderDebts();

  renderDebtSummary();

  renderSuppliers();


  if (
    typeof updateDashboard ===
    "function"
  ) {

    updateDashboard();

  }


  showToast(
    "Hutang berhasil dilunasi."
  );

}


