/* =========================================================
   END MODUL PIUTANG PELANGGAN
========================================================= */


/* =========================================================
   FAEZA ERP V2
   INTEGRASI PENJUALAN → PIUTANG
   BAGIAN 1 — CREATE RECEIVABLE FROM SALE
========================================================= */


/* =========================================================
   PASTIKAN ARRAY PIUTANG
========================================================= */

function ensureReceivableStorage() {

  if (
    !Array.isArray(
      db.receivables
    )
  ) {

    db.receivables = [];

  }


  if (
    !Array.isArray(
      db.receivablePayments
    )
  ) {

    db.receivablePayments = [];

  }

}


/* =========================================================
   CARI PIUTANG BERDASARKAN PENJUALAN
========================================================= */

function findReceivableBySale(
  saleId
) {

  ensureReceivableStorage();


  return (
    db.receivables.find(
      receivable =>
        receivable.saleId ===
        saleId
    ) ||
    null
  );

}


/* =========================================================
   BUAT PIUTANG DARI PENJUALAN KREDIT
========================================================= */

function createReceivableFromSale(
  sale
) {

  ensureReceivableStorage();


  if (!sale) {

    throw new Error(
      "Data penjualan tidak ditemukan."
    );

  }


  const saleId =
    sale.id ||
    sale.saleId ||
    "";


  if (!saleId) {

    throw new Error(
      "ID penjualan tidak ditemukan."
    );

  }


  /* -------------------------------------------------------
     CEGAH DUPLIKASI
  ------------------------------------------------------- */

  const existing =
    findReceivableBySale(
      saleId
    );


  if (existing) {

    normalizeReceivable(
      existing
    );

    return existing;

  }


  /* -------------------------------------------------------
     AMBIL TOTAL PENJUALAN
  ------------------------------------------------------- */

  const total =
    Number(
      sale.total ??
      sale.grandTotal ??
      sale.amount ??
      0
    );


  if (
    !Number.isFinite(
      total
    ) ||
    total <= 0
  ) {

    throw new Error(
      "Total penjualan tidak valid."
    );

  }


  /* -------------------------------------------------------
     IDENTITAS PELANGGAN
  ------------------------------------------------------- */

  const customerId =
    sale.customerId ||
    sale.customer?.id ||
    "";


  const customer =
    customerId
      ? findCustomer(
          customerId
        )
      : null;


  const customerName =
    sale.customerName ||
    sale.customer?.name ||
    customer?.name ||
    "Pelanggan";


  /* -------------------------------------------------------
     TANGGAL
  ------------------------------------------------------- */

  const saleDate =
    sale.date ||
    sale.createdAt?.slice(
      0,
      10
    ) ||
    today();


  /* -------------------------------------------------------
     JATUH TEMPO
  ------------------------------------------------------- */

  let dueDate =
    sale.dueDate ||
    "";


  /*
    Jika penjualan membawa creditDays,
    hitung otomatis tanggal jatuh tempo.
  */

  if (
    !dueDate &&
    Number(
      sale.creditDays
    ) > 0
  ) {

    dueDate =
      addDays(
        saleDate,
        Number(
          sale.creditDays
        )
      );

  }


  /* -------------------------------------------------------
     BUAT DATA PIUTANG
  ------------------------------------------------------- */

  const receivable = {

    id:
      generateId(
        "PIUT"
      ),

    saleId:
      saleId,

    saleNumber:
      sale.saleNumber ||
      sale.invoiceNumber ||
      sale.invoice ||
      sale.number ||
      saleId,

    customerId:
      customerId,

    customerName:
      customerName,

    date:
      saleDate,

    dueDate:
      dueDate,

    total:
      total,

    paid:
      0,

    remaining:
      total,

    status:
      "UNPAID",

    description:
      sale.description ||
      "Piutang penjualan kredit",

    createdAt:
      new Date()
        .toISOString(),

    updatedAt:
      new Date()
        .toISOString()

  };


  /* -------------------------------------------------------
     SIMPAN
  ------------------------------------------------------- */

  db.receivables.push(
    receivable
  );


  saveDatabase();


  /* -------------------------------------------------------
     REFRESH
  ------------------------------------------------------- */

  if (
    typeof refreshAllReceivableData ===
    "function"
  ) {

    refreshAllReceivableData();

  }


  return receivable;

}


/* =========================================================
   TAMBAHKAN PEMBAYARAN AWAL KE PENJUALAN
========================================================= */

function createReceivableFromSaleWithPayment(
  sale,
  initialPayment = 0
) {

  const receivable =
    createReceivableFromSale(
      sale
    );


  const payment =
    Number(
      initialPayment
    ) || 0;


  if (
    payment <= 0
  ) {

    return receivable;

  }


  normalizeReceivable(
    receivable
  );


  if (
    payment >
    receivable.remaining
  ) {

    throw new Error(
      "Pembayaran awal melebihi total penjualan."
    );

  }


  receivable.paid =
    payment;


  receivable.remaining =
    Math.max(
      0,
      receivable.total -
      payment
    );


  receivable.status =
    receivable.remaining <= 0
      ? "PAID"
      : "PARTIAL";


  db.receivablePayments.push({

    id:
      generateId(
        "BYPI"
      ),

    receivableId:
      receivable.id,

    customerId:
      receivable.customerId,

    customerName:
      receivable.customerName,

    saleId:
      receivable.saleId,

    saleNumber:
      receivable.saleNumber,

    date:
      sale.date ||
      today(),

    amount:
      payment,

    balanceBefore:
      receivable.total,

    balanceAfter:
      receivable.remaining,

    note:
      "Pembayaran awal penjualan",

    createdAt:
      new Date()
        .toISOString()

  });


  saveDatabase();


  return receivable;

}


/* =========================================================
   TENTUKAN APAKAH PENJUALAN KREDIT
========================================================= */

function isCreditSale(
  sale
) {

  if (!sale) {
    return false;
  }


  const paymentMethod =
    String(
      sale.paymentMethod ||
      sale.paymentType ||
      sale.payment ||
      ""
    )
      .toUpperCase()
      .trim();


  const creditMethods = [

    "KREDIT",
    "HUTANG",
    "PIUTANG",
    "CREDIT",
    "TEMPO"

  ];


  if (
    creditMethods.includes(
      paymentMethod
    )
  ) {

    return true;

  }


  if (
    sale.isCredit === true
  ) {

    return true;

  }


  if (
    sale.credit === true
  ) {

    return true;

  }


  return false;

}


/* =========================================================
   HITUNG PEMBAYARAN AWAL PENJUALAN
========================================================= */

function getSaleInitialPayment(
  sale
) {

  if (!sale) {
    return 0;
  }


  return Number(

    sale.paid ??
    sale.paymentAmount ??
    sale.cashReceived ??
    sale.downPayment ??
    0

  ) || 0;

}


/* =========================================================
   PROSES PENJUALAN → PIUTANG
========================================================= */

function processSaleReceivable(
  sale
) {

  if (!sale) {

    return null;

  }


  /*
    Penjualan tunai tidak membuat piutang.
  */

  if (
    !isCreditSale(
      sale
    )
  ) {

    return null;

  }


  const initialPayment =
    getSaleInitialPayment(
      sale
    );


  /*
    Jika pembayaran awal sama dengan
    total transaksi, tidak ada saldo piutang.
  */

  const total =
    Number(
      sale.total ??
      sale.grandTotal ??
      sale.amount ??
      0
    ) || 0;


  if (
    initialPayment >=
    total
  ) {

    return null;

  }


  return createReceivableFromSaleWithPayment(
    sale,
    initialPayment
  );

}


/* =========================================================
   SINKRONISASI SEMUA PENJUALAN → PIUTANG
========================================================= */

function syncSalesToReceivables() {

  ensureReceivableStorage();


  if (
    !Array.isArray(
      db.sales
    )
  ) {

    return;

  }


  db.sales.forEach(
    sale => {

      if (
        !isCreditSale(
          sale
        )
      ) {

        return;

      }


      const existing =
        findReceivableBySale(
          sale.id
        );


      if (!existing) {

        try {

          processSaleReceivable(
            sale
          );

        } catch (
          error
        ) {

          console.warn(
            "Gagal membuat piutang:",
            error
          );

        }

      }

    }
  );


  saveDatabase();


  if (
    typeof refreshAllReceivableData ===
    "function"
  ) {

    refreshAllReceivableData();

  }

}


/* =========================================================
   END INTEGRASI PENJUALAN → PIUTANG
========================================================= */

/* =========================================================
   ADD DAYS
========================================================= */

function addDays(
  dateString,
  days
) {

  const date =
    new Date(
      `${dateString}T00:00:00`
    );


  if (
    Number.isNaN(
      date.getTime()
    )
  ) {

    return "";

  }


  date.setDate(
    date.getDate() +
    Number(days)
  );


  const year =
    date.getFullYear();


  const month =
    String(
      date.getMonth() + 1
    ).padStart(
      2,
      "0"
    );


  const day =
    String(
      date.getDate()
    ).padStart(
      2,
      "0"
    );


  return `${year}-${month}-${day}`;

}


/* =========================================================
   END ADD DAYS
========================================================= */

/* =========================================================
   FAEZA ERP V2
   INTEGRASI PEMBELIAN
   BAGIAN 1 — PEMBELIAN → STOK MASUK → HUTANG
========================================================= */


/* =========================================================
   PASTIKAN STORAGE PEMBELIAN
========================================================= */

function ensurePurchaseStorage() {

  if (
    !Array.isArray(
      db.purchases
    )
  ) {

    db.purchases = [];

  }


  if (
    !Array.isArray(
      db.purchaseItems
    )
  ) {

    db.purchaseItems = [];

  }


  if (
    !Array.isArray(
      db.stockMovements
    )
  ) {

    db.stockMovements = [];

  }


  if (
    !Array.isArray(
      db.debts
    )
  ) {

    db.debts = [];

  }


  if (
    !Array.isArray(
      db.debtPayments
    )
  ) {

    db.debtPayments = [];

  }

}


/* =========================================================
   FIND PURCHASE
========================================================= */

function findPurchase(
  purchaseId
) {

  ensurePurchaseStorage();


  return (
    db.purchases.find(
      purchase =>
        purchase.id ===
        purchaseId
    ) ||
    null
  );

}


/* =========================================================
   FIND DEBT BY PURCHASE
========================================================= */

function findDebtByPurchase(
  purchaseId
) {

  ensurePurchaseStorage();


  return (
    db.debts.find(
      debt =>
        debt.purchaseId ===
        purchaseId
    ) ||
    null
  );

}


/* =========================================================
   NORMALIZE PURCHASE
========================================================= */

function normalizePurchase(
  purchase
) {

  if (!purchase) {
    return null;
  }


  purchase.total =
    Number(
      purchase.total ??
      purchase.grandTotal ??
      0
    ) || 0;


  purchase.paid =
    Number(
      purchase.paid ??
      purchase.paymentAmount ??
      0
    ) || 0;


  purchase.paid =
    Math.min(
      Math.max(
        0,
        purchase.paid
      ),
      purchase.total
    );


  purchase.remaining =
    Math.max(
      0,
      purchase.total -
      purchase.paid
    );


  if (
    purchase.remaining <= 0
  ) {

    purchase.paymentStatus =
      "PAID";

  } else if (
    purchase.paid > 0
  ) {

    purchase.paymentStatus =
      "PARTIAL";

  } else {

    purchase.paymentStatus =
      "UNPAID";

  }


  return purchase;

}


/* =========================================================
   GET PURCHASE SUPPLIER
========================================================= */

function getPurchaseSupplier(
  purchase
) {

  if (!purchase) {
    return null;
  }


  const supplierId =
    purchase.supplierId ||
    purchase.supplier?.id ||
    "";


  if (!supplierId) {
    return null;
  }


  return findSupplier(
    supplierId
  );

}


/* =========================================================
   GET PURCHASE ITEMS
========================================================= */

function getPurchaseItems(
  purchase
) {

  if (!purchase) {
    return [];

  }


  /* Jika items sudah berada
     di dalam transaksi */

  if (
    Array.isArray(
      purchase.items
    )
  ) {

    return purchase.items;

  }


  /* Jika menggunakan purchaseItems */

  if (
    Array.isArray(
      db.purchaseItems
    )
  ) {

    return db.purchaseItems.filter(
      item =>
        item.purchaseId ===
        purchase.id
    );

  }


  return [];

}


/* =========================================================
   NORMALIZE PURCHASE ITEM
========================================================= */

function normalizePurchaseItem(
  item
) {

  if (!item) {
    return null;
  }


  const qty =
    Number(
      item.qty ??
      item.quantity ??
      0
    ) || 0;


  const price =
    Number(
      item.price ??
      item.purchasePrice ??
      item.costPrice ??
      0
    ) || 0;


  const subtotal =
    Number(
      item.subtotal ??
      item.total ??
      (
        qty *
        price
      )
    ) || 0;


  return {

    ...item,

    qty:
      qty,

    quantity:
      qty,

    price:
      price,

    purchasePrice:
      price,

    subtotal:
      subtotal

  };

}


/* =========================================================
   CHECK CREDIT PURCHASE
========================================================= */

function isCreditPurchase(
  purchase
) {

  if (!purchase) {
    return false;
  }


  const paymentMethod =
    String(
      purchase.paymentMethod ||
      purchase.paymentType ||
      purchase.payment ||
      ""
    )
      .toUpperCase()
      .trim();


  const creditMethods = [

    "KREDIT",
    "HUTANG",
    "TEMPO",
    "CREDIT"

  ];


  if (
    creditMethods.includes(
      paymentMethod
    )
  ) {

    return true;

  }


  if (
    purchase.isCredit ===
    true
  ) {

    return true;

  }


  if (
    purchase.credit ===
    true
  ) {

    return true;

  }


  return false;

}


/* =========================================================
   GET PURCHASE INITIAL PAYMENT
========================================================= */

function getPurchaseInitialPayment(
  purchase
) {

  if (!purchase) {
    return 0;
  }


  return Number(

    purchase.paid ??
    purchase.paymentAmount ??
    purchase.downPayment ??
    0

  ) || 0;

}


/* =========================================================
   CREATE STOCK MOVEMENT
========================================================= */

function createPurchaseStockMovement(
  purchase,
  item
) {

  ensurePurchaseStorage();


  const normalized =
    normalizePurchaseItem(
      item
    );


  if (!normalized) {

    return null;

  }


  if (
    normalized.qty <= 0
  ) {

    return null;

  }


  const movement = {

    id:
      generateId(
        "STIN"
      ),

    type:
      "IN",

    source:
      "PURCHASE",

    purchaseId:
      purchase.id,

    purchaseNumber:
      purchase.purchaseNumber ||
      purchase.invoiceNumber ||
      purchase.id,

    productId:
      normalized.productId ||
      normalized.product?.id ||
      "",

    productName:
      normalized.productName ||
      normalized.product?.name ||
      "",

    qty:
      normalized.qty,

    quantity:
      normalized.qty,

    unit:
      normalized.unit ||
      "pcs",

    price:
      normalized.price,

    subtotal:
      normalized.subtotal,

    supplierId:
      purchase.supplierId ||
      "",

    supplierName:
      purchase.supplierName ||
      getPurchaseSupplier(
        purchase
      )?.name ||
      "",

    date:
      purchase.date ||
      today(),

    note:
      "Stok masuk dari pembelian",

    createdAt:
      new Date()
        .toISOString()

  };


  db.stockMovements.push(
    movement
  );


  return movement;

}


/* =========================================================
   APPLY STOCK IN
========================================================= */

function applyPurchaseStockIn(
  purchase
) {

  ensurePurchaseStorage();


  const items =
    getPurchaseItems(
      purchase
    );


  if (!items.length) {

    return [];

  }


  const movements = [];


  items.forEach(
    item => {

      const normalized =
        normalizePurchaseItem(
          item
        );


      if (!normalized) {
        return;
      }


      /*
        Cegah stok masuk ganda
        untuk item yang sama.
      */

      const alreadyExists =
        db.stockMovements.some(
          movement =>
            movement.source ===
              "PURCHASE"
            &&
            movement.purchaseId ===
              purchase.id
            &&
            movement.productId ===
              normalized.productId
        );


      if (
        alreadyExists
      ) {

        return;

      }


      const movement =
        createPurchaseStockMovement(
          purchase,
          normalized
        );


      if (
        movement
      ) {

        movements.push(
          movement
        );

      }

    }
  );


  return movements;

}


/* =========================================================
   UPDATE PRODUCT STOCK
========================================================= */

function applyStockMovementToProduct(
  movement
) {

  if (!movement) {
    return;
  }


  if (
    !Array.isArray(
      db.products
    )
  ) {

    return;

  }


  const product =
    db.products.find(
      item =>
        item.id ===
        movement.productId
    );


  if (!product) {

    console.warn(
      "Produk tidak ditemukan:",
      movement.productId
    );

    return;

  }


  const currentStock =
    Number(
      product.stock
    ) || 0;


  const quantity =
    Number(
      movement.quantity ??
      movement.qty ??
      0
    ) || 0;


  if (
    movement.type ===
    "IN"
  ) {

    product.stock =
      currentStock +
      quantity;

  }


  if (
    movement.type ===
    "OUT"
  ) {

    product.stock =
      currentStock -
      quantity;

  }


  product.updatedAt =
    new Date()
      .toISOString();

}


/* =========================================================
   APPLY ALL NEW PURCHASE STOCK
========================================================= */

function applyPurchaseStock(
  purchase
) {

  const movements =
    applyPurchaseStockIn(
      purchase
    );


  movements.forEach(
    movement => {

      applyStockMovementToProduct(
        movement
      );

    }
  );


  return movements;

}


/* =========================================================
   END BAGIAN 1
========================================================= */


/* =========================================================
   FAEZA ERP V2
   INTEGRASI PEMBELIAN
   BAGIAN 2 — PEMBELIAN → HUTANG SUPPLIER
========================================================= */


/* =========================================================
   NORMALIZE DEBT
========================================================= */

function normalizeDebt(debt) {

  if (!debt) {
    return null;
  }


  debt.total =
    Number(
      debt.total ??
      debt.amount ??
      0
    ) || 0;


  debt.paid =
    Number(
      debt.paid ??
      debt.paidAmount ??
      0
    ) || 0;


  debt.paid =
    Math.min(
      Math.max(
        0,
        debt.paid
      ),
      debt.total
    );


  debt.remaining =
    Math.max(
      0,
      debt.total -
      debt.paid
    );


  if (
    debt.remaining <= 0
  ) {

    debt.status =
      "PAID";

  }
  else if (
    debt.paid > 0
  ) {

    debt.status =
      "PARTIAL";

  }
  else {

    debt.status =
      "UNPAID";

  }


  return debt;

}


/* =========================================================
   FIND DEBT
========================================================= */

function findDebt(
  debtId
) {

  ensurePurchaseStorage();


  return (
    db.debts.find(
      debt =>
        debt.id ===
        debtId
    ) ||
    null
  );

}


/* =========================================================
   GET SUPPLIER NAME
========================================================= */

function getDebtSupplierName(
  debt
) {

  if (!debt) {
    return "Supplier";
  }


  if (
    debt.supplierName
  ) {

    return debt.supplierName;

  }


  const supplier =
    debt.supplierId
      ? findSupplier(
          debt.supplierId
        )
      : null;


  return (
    supplier?.name ||
    "Supplier"
  );

}


/* =========================================================
   CREATE DEBT FROM PURCHASE
========================================================= */

function createDebtFromPurchase(
  purchase
) {

  ensurePurchaseStorage();


  if (!purchase) {

    throw new Error(
      "Data pembelian tidak ditemukan."
    );

  }


  if (!purchase.id) {

    throw new Error(
      "ID pembelian tidak ditemukan."
    );

  }


  /*
     Cegah hutang ganda.
  */

  const existing =
    findDebtByPurchase(
      purchase.id
    );


  if (existing) {

    normalizeDebt(
      existing
    );


    return existing;

  }


  normalizePurchase(
    purchase
  );


  const total =
    Number(
      purchase.total
    ) || 0;


  if (
    total <= 0
  ) {

    throw new Error(
      "Total pembelian tidak valid."
    );

  }


  const supplierId =
    purchase.supplierId ||
    purchase.supplier?.id ||
    "";


  if (!supplierId) {

    throw new Error(
      "Supplier belum dipilih."
    );

  }


  const supplier =
    findSupplier(
      supplierId
    );


  const supplierName =
    purchase.supplierName ||
    purchase.supplier?.name ||
    supplier?.name ||
    "Supplier";


  /*
     Tanggal pembelian.
  */

  const purchaseDate =
    purchase.date ||
    purchase.createdAt?.slice(
      0,
      10
    ) ||
    today();


  /*
     Jatuh tempo.
  */

  let dueDate =
    purchase.dueDate ||
    "";


  if (
    !dueDate &&
    Number(
      purchase.creditDays
    ) > 0
  ) {

    dueDate =
      addDays(
        purchaseDate,
        Number(
          purchase.creditDays
        )
      );

  }


  const initialPayment =
    Math.min(
      total,
      getPurchaseInitialPayment(
        purchase
      )
    );


  const remaining =
    Math.max(
      0,
      total -
      initialPayment
    );


  /*
     Jika sebenarnya sudah lunas,
     tidak perlu membuat hutang.
  */

  if (
    remaining <= 0
  ) {

    return null;

  }


  const debt = {

    id:
      generateId(
        "HUT"
      ),

    purchaseId:
      purchase.id,

    purchaseNumber:
      purchase.purchaseNumber ||
      purchase.invoiceNumber ||
      purchase.number ||
      purchase.id,

    supplierId:
      supplierId,

    supplierName:
      supplierName,

    date:
      purchaseDate,

    dueDate:
      dueDate,

    total:
      total,

    paid:
      initialPayment,

    remaining:
      remaining,

    status:
      initialPayment > 0
        ? "PARTIAL"
        : "UNPAID",

    description:
      purchase.description ||
      "Hutang pembelian supplier",

    createdAt:
      new Date()
        .toISOString(),

    updatedAt:
      new Date()
        .toISOString()

  };


  db.debts.push(
    debt
  );


  /*
     Simpan pembayaran awal
     jika ada.
  */

  if (
    initialPayment > 0
  ) {

    db.debtPayments.push({

      id:
        generateId(
          "BYHUT"
        ),

      debtId:
        debt.id,

      purchaseId:
        purchase.id,

      supplierId:
        supplierId,

      supplierName:
        supplierName,

      purchaseNumber:
        debt.purchaseNumber,

      date:
        purchaseDate,

      amount:
        initialPayment,

      balanceBefore:
        total,

      balanceAfter:
        remaining,

      note:
        "Pembayaran awal pembelian",

      createdAt:
        new Date()
          .toISOString()

    });

  }


  debt.updatedAt =
    new Date()
      .toISOString();


  saveDatabase();


  return debt;

}


/* =========================================================
   PROCESS PURCHASE DEBT
========================================================= */

function processPurchaseDebt(
  purchase
) {

  if (!purchase) {
    return null;
  }


  /*
     Pembelian tunai tidak membuat hutang.
  */

  if (
    !isCreditPurchase(
      purchase
    )
  ) {

    return null;

  }


  normalizePurchase(
    purchase
  );


  const initialPayment =
    getPurchaseInitialPayment(
      purchase
    );


  const total =
    Number(
      purchase.total
    ) || 0;


  /*
     Sudah lunas → tidak ada saldo hutang.
  */

  if (
    initialPayment >=
    total
  ) {

    return null;

  }


  return createDebtFromPurchase(
    purchase
  );

}


/* =========================================================
   SYNC PURCHASES → DEBTS
========================================================= */

function syncPurchasesToDebts() {

  ensurePurchaseStorage();


  if (
    !Array.isArray(
      db.purchases
    )
  ) {

    return;

  }


  db.purchases.forEach(
    purchase => {

      if (
        !isCreditPurchase(
          purchase
        )
      ) {

        return;

      }


      const existing =
        findDebtByPurchase(
          purchase.id
        );


      if (existing) {

        normalizeDebt(
          existing
        );

        return;

      }


      try {

        processPurchaseDebt(
          purchase
        );

      }
      catch (
        error
      ) {

        console.warn(
          "Gagal membuat hutang:",
          error
        );

      }

    }
  );


  saveDatabase();

}


/* =========================================================
   CREATE PURCHASE TRANSACTION
   HELPER TERPADU
========================================================= */

function finalizePurchaseTransaction(
  purchase
) {

  if (!purchase) {

    throw new Error(
      "Data pembelian tidak ditemukan."
    );

  }


  ensurePurchaseStorage();


  /*
     Pastikan ID tersedia.
  */

  if (!purchase.id) {

    purchase.id =
      generateId(
        "BEL"
      );

  }


  /*
     Normalisasi transaksi.
  */

  normalizePurchase(
    purchase
  );


  /*
     Simpan pembelian
     jika belum ada.
  */

  const existingIndex =
    db.purchases.findIndex(
      item =>
        item.id ===
        purchase.id
    );


  if (
    existingIndex >= 0
  ) {

    db.purchases[
      existingIndex
    ] = {

      ...db.purchases[
        existingIndex
      ],

      ...purchase

    };

  }
  else {

    db.purchases.push(
      purchase
    );

  }


  /*
     STOK MASUK
  */

  applyPurchaseStock(
    purchase
  );


  /*
     HUTANG SUPPLIER
  */

  if (
    isCreditPurchase(
      purchase
    )
  ) {

    processPurchaseDebt(
      purchase
    );

  }


  /*
     Simpan seluruh transaksi.
  */

  saveDatabase();


  /*
     Refresh modul.
  */

  if (
    typeof refreshAllPurchaseData ===
    "function"
  ) {

    refreshAllPurchaseData();

  }


  if (
    typeof refreshAllDebtData ===
    "function"
  ) {

    refreshAllDebtData();

  }


  if (
    typeof updateDashboard ===
    "function"
  ) {

    updateDashboard();

  }


  return purchase;

}


/* =========================================================
   END BAGIAN 2
========================================================= */

/* =========================================================
   FAEZA ERP V2
   HUTANG SUPPLIER
   BAGIAN 3 — PEMBAYARAN HUTANG
========================================================= */


/* =========================================================
   OPEN DEBT PAYMENT
========================================================= */

function openDebtPayment(debtId) {

  const debt =
    findDebt(debtId);


  if (!debt) {

    showToast(
      "Data hutang tidak ditemukan.",
      "error"
    );

    return;

  }


  normalizeDebt(debt);


  if (
    debt.remaining <= 0
  ) {

    showToast(
      "Hutang ini sudah lunas.",
      "info"
    );

    return;

  }


  selectedDebtId =
    debt.id;


  const supplierName =
    getDebtSupplierName(
      debt
    );


  const body = `

    <div class="form-grid">

      <div
        class="form-group"
        style="grid-column:1/-1"
      >

        <label>
          Supplier
        </label>

        <input
          type="text"
          value="${escapeHTML(
            supplierName
          )}"
          disabled
        >

      </div>


      <div class="form-group">

        <label>
          No. Pembelian
        </label>

        <input
          type="text"
          value="${escapeHTML(
            debt.purchaseNumber ||
            "-"
          )}"
          disabled
        >

      </div>


      <div class="form-group">

        <label>
          Sisa Hutang
        </label>

        <input
          type="text"
          value="${formatRupiah(
            debt.remaining
          )}"
          disabled
        >

      </div>


      <div
        class="form-group"
        style="grid-column:1/-1"
      >

        <label
          for="debtPaymentAmount"
        >
          Nominal Pembayaran
        </label>

        <input
          id="debtPaymentAmount"
          type="number"
          min="1"
          max="${debt.remaining}"
          step="1"
          value="${debt.remaining}"
          inputmode="numeric"
        >

        <small>
          Maksimal:
          ${formatRupiah(
            debt.remaining
          )}
        </small>

      </div>


      <div
        class="form-group"
        style="grid-column:1/-1"
      >

        <label
          for="debtPaymentDate"
        >
          Tanggal Pembayaran
        </label>

        <input
          id="debtPaymentDate"
          type="date"
          value="${today()}"
        >

      </div>


      <div
        class="form-group"
        style="grid-column:1/-1"
      >

        <label
          for="debtPaymentNote"
        >
          Catatan
        </label>

        <textarea
          id="debtPaymentNote"
          rows="2"
          placeholder="Catatan pembayaran hutang..."
        ></textarea>

      </div>

    </div>

  `;


  openModal(
    "Bayar Hutang Supplier",
    body,
    saveDebtPayment
  );

}


/* =========================================================
   VALIDATE DEBT PAYMENT
========================================================= */

function validateDebtPayment(
  debt,
  amount
) {

  if (!debt) {

    showToast(
      "Data hutang tidak ditemukan.",
      "error"
    );

    return false;

  }


  normalizeDebt(
    debt
  );


  if (
    debt.remaining <= 0
  ) {

    showToast(
      "Hutang sudah lunas.",
      "info"
    );

    return false;

  }


  if (
    !Number.isFinite(
      amount
    ) ||
    amount <= 0
  ) {

    showToast(
      "Nominal pembayaran harus lebih dari 0.",
      "error"
    );

    return false;

  }


  if (
    amount >
    debt.remaining
  ) {

    showToast(
      "Pembayaran melebihi sisa hutang.",
      "error"
    );

    return false;

  }


  return true;

}


/* =========================================================
   SAVE DEBT PAYMENT
========================================================= */

function saveDebtPayment() {

  if (
    !selectedDebtId
  ) {

    showToast(
      "Hutang belum dipilih.",
      "error"
    );

    return;

  }


  const debt =
    findDebt(
      selectedDebtId
    );


  if (!debt) {

    showToast(
      "Data hutang tidak ditemukan.",
      "error"
    );

    return;

  }


  const amount =
    Number(
      document
        .getElementById(
          "debtPaymentAmount"
        )
        ?.value
    );


  const paymentDate =
    document
      .getElementById(
        "debtPaymentDate"
      )
      ?.value
      ||
      today();


  const note =
    document
      .getElementById(
        "debtPaymentNote"
      )
      ?.value
      ?.trim()
      ||
      "";


  if (
    !validateDebtPayment(
      debt,
      amount
    )
  ) {

    return;

  }


  normalizeDebt(
    debt
  );


  const previousPaid =
    Number(
      debt.paid
    ) || 0;


  const previousRemaining =
    Number(
      debt.remaining
    ) || 0;


  const newPaid =
    previousPaid +
    amount;


  const newRemaining =
    Math.max(
      0,
      debt.total -
      newPaid
    );


  /* -------------------------------------------------------
     UPDATE HUTANG
  ------------------------------------------------------- */

  debt.paid =
    newPaid;


  debt.remaining =
    newRemaining;


  debt.status =
    newRemaining <= 0
      ? "PAID"
      : "PARTIAL";


  debt.updatedAt =
    new Date()
      .toISOString();


  /* -------------------------------------------------------
     PASTIKAN STORAGE
  ------------------------------------------------------- */

  ensurePurchaseStorage();


  /* -------------------------------------------------------
     SIMPAN RIWAYAT PEMBAYARAN
  ------------------------------------------------------- */

  db.debtPayments.push({

    id:
      generateId(
        "BYHUT"
      ),

    debtId:
      debt.id,

    purchaseId:
      debt.purchaseId,

    supplierId:
      debt.supplierId,

    supplierName:
      debt.supplierName,

    purchaseNumber:
      debt.purchaseNumber,

    date:
      paymentDate,

    amount:
      amount,

    balanceBefore:
      previousRemaining,

    balanceAfter:
      newRemaining,

    note:
      note,

    createdAt:
      new Date()
        .toISOString()

  });


  /* -------------------------------------------------------
     SIMPAN DATABASE
  ------------------------------------------------------- */

  saveDatabase();


  selectedDebtId =
    null;


  closeModal();


  /* -------------------------------------------------------
     REFRESH
  ------------------------------------------------------- */

  refreshAllDebtData();


  if (
    typeof updateDashboard ===
    "function"
  ) {

    updateDashboard();

  }


  showToast(

    newRemaining <= 0

      ? "Hutang berhasil dilunasi."

      : `Pembayaran ${formatRupiah(
          amount
        )} berhasil disimpan.`

  );

}


/* =========================================================
   FULL DEBT PAYMENT
========================================================= */

function payDebtInFull(
  debtId
) {

  const debt =
    findDebt(
      debtId
    );


  if (!debt) {

    showToast(
      "Data hutang tidak ditemukan.",
      "error"
    );

    return;

  }


  normalizeDebt(
    debt
  );


  if (
    debt.remaining <= 0
  ) {

    showToast(
      "Hutang sudah lunas.",
      "info"
    );

    return;

  }


  const amount =
    debt.remaining;


  const confirmed =
    confirm(
      `Bayar hutang sebesar ${formatRupiah(
        amount
      )}?`
    );


  if (!confirmed) {

    return;

  }


  const previousRemaining =
    debt.remaining;


  debt.paid =
    Number(
      debt.paid
    ) +
    amount;


  debt.remaining =
    0;


  debt.status =
    "PAID";


  debt.updatedAt =
    new Date()
      .toISOString();


  ensurePurchaseStorage();


  db.debtPayments.push({

    id:
      generateId(
        "BYHUT"
      ),

    debtId:
      debt.id,

    purchaseId:
      debt.purchaseId,

    supplierId:
      debt.supplierId,

    supplierName:
      debt.supplierName,

    purchaseNumber:
      debt.purchaseNumber,

    date:
      today(),

    amount:
      amount,

    balanceBefore:
      previousRemaining,

    balanceAfter:
      0,

    note:
      "Pelunasan hutang",

    createdAt:
      new Date()
        .toISOString()

  });


  saveDatabase();


  refreshAllDebtData();


  if (
    typeof updateDashboard ===
    "function"
  ) {

    updateDashboard();

  }


  showToast(
    "Hutang berhasil dilunasi."
  );

}


/* =========================================================
   GET DEBT PAYMENTS
========================================================= */

function getDebtPayments(
  debtId
) {

  ensurePurchaseStorage();


  return db.debtPayments
    .filter(
      payment =>
        payment.debtId ===
        debtId
    )
    .sort(
      (
        a,
        b
      ) =>
        String(
          b.date || ""
        ).localeCompare(
          String(
            a.date || ""
          )
        )
    );

}


/* =========================================================
   TOTAL DEBT PAYMENT
========================================================= */

function getDebtPaymentTotal(
  debtId
) {

  return getDebtPayments(
    debtId
  )
  .reduce(
    (
      total,
      payment
    ) => {

      return (

        total +
        (
          Number(
            payment.amount
          ) || 0
        )

      );

    },
    0
  );

}


/* =========================================================
   DEBT LEDGER
========================================================= */

function getDebtLedger(
  debtId
) {

  const debt =
    findDebt(
      debtId
    );


  if (!debt) {

    return [];

  }


  normalizeDebt(
    debt
  );


  const ledger = [];


  /* Hutang dari pembelian */

  ledger.push({

    date:
      debt.date ||
      "",

    type:
      "HUTANG",

    reference:
      debt.purchaseNumber ||
      "",

    description:
      debt.description ||
      "Pembelian kredit",

    debit:
      Number(
        debt.total
      ) || 0,

    credit:
      0

  });


  /* Pembayaran */

  getDebtPayments(
    debtId
  ).forEach(
    payment => {

      ledger.push({

        date:
          payment.date ||
          "",

        type:
          "PEMBAYARAN",

        reference:
          payment.purchaseNumber ||
          "",

        description:
          payment.note ||
          "Pembayaran hutang",

        debit:
          0,

        credit:
          Number(
            payment.amount
          ) || 0

      });

    }
  );


  ledger.sort(
    (
      a,
      b
    ) =>
      String(
        a.date || ""
      ).localeCompare(
        String(
          b.date || ""
        )
      )
  );


  let balance = 0;


  return ledger.map(
    entry => {

      balance +=
        Number(
          entry.debit
        ) || 0;


      balance -=
        Number(
          entry.credit
        ) || 0;


      return {

        ...entry,

        balance

      };

    }
  );

}


/* =========================================================
   END BAGIAN 3
========================================================= */

/* =========================================================
   FAEZA ERP V2
   HUTANG SUPPLIER
   BAGIAN 4 — DAFTAR + REKAP + JATUH TEMPO
========================================================= */


/* =========================================================
   GET TOTAL DEBT
========================================================= */

function getTotalDebt() {

  ensurePurchaseStorage();

  return db.debts.reduce(
    (total, debt) => {

      normalizeDebt(debt);

      return (
        total +
        (
          Number(debt.remaining) ||
          0
        )
      );

    },
    0
  );

}


/* =========================================================
   GET TOTAL DEBT ORIGINAL
========================================================= */

function getTotalDebtOriginal() {

  ensurePurchaseStorage();

  return db.debts.reduce(
    (total, debt) => {

      return (
        total +
        (
          Number(debt.total) ||
          0
        )
      );

    },
    0
  );

}


/* =========================================================
   GET TOTAL DEBT PAID
========================================================= */

function getTotalDebtPaid() {

  ensurePurchaseStorage();

  return db.debts.reduce(
    (total, debt) => {

      normalizeDebt(debt);

      return (
        total +
        (
          Number(debt.paid) ||
          0
        )
      );

    },
    0
  );

}


/* =========================================================
   GET UNPAID DEBT
========================================================= */

function getUnpaidDebts() {

  ensurePurchaseStorage();

  return db.debts.filter(
    debt => {

      normalizeDebt(debt);

      return (
        debt.remaining > 0
      );

    }
  );

}


/* =========================================================
   GET OVERDUE DEBTS
========================================================= */

function getOverdueDebts() {

  return getUnpaidDebts()
    .filter(
      debt => {

        if (!debt.dueDate) {
          return false;
        }

        return (
          debt.dueDate <
          today()
        );

      }
    );

}


/* =========================================================
   GET OVERDUE DEBT TOTAL
========================================================= */

function getOverdueDebtTotal() {

  return getOverdueDebts()
    .reduce(
      (total, debt) => {

        return (
          total +
          (
            Number(
              debt.remaining
            ) || 0
          )
        );

      },
      0
    );

}


/* =========================================================
   GET DEBT AGE
========================================================= */

function getDebtAge(
  dueDate
) {

  if (!dueDate) {
    return 0;
  }

  const due =
    new Date(
      `${dueDate}T00:00:00`
    );

  const now =
    new Date();

  due.setHours(
    0,
    0,
    0,
    0
  );

  now.setHours(
    0,
    0,
    0,
    0
  );

  const difference =
    now.getTime() -
    due.getTime();

  return Math.max(
    0,
    Math.floor(
      difference /
      (
        1000 *
        60 *
        60 *
        24
      )
    )
  );

}


/* =========================================================
   DEBT DUE STATUS
========================================================= */

function getDebtDueStatus(
  debt
) {

  normalizeDebt(debt);

  if (
    debt.remaining <= 0
  ) {

    return "PAID";

  }

  if (
    !debt.dueDate
  ) {

    return "NO_DUE_DATE";

  }

  const currentDate =
    today();

  if (
    debt.dueDate <
    currentDate
  ) {

    return "OVERDUE";

  }

  if (
    debt.dueDate ===
    currentDate
  ) {

    return "TODAY";

  }

  return "UPCOMING";

}


/* =========================================================
   DEBT DUE LABEL
========================================================= */

function getDebtDueStatusLabel(
  status
) {

  switch (status) {

    case "PAID":
      return "LUNAS";

    case "OVERDUE":
      return "JATUH TEMPO";

    case "TODAY":
      return "JATUH TEMPO HARI INI";

    case "UPCOMING":
      return "BELUM JATUH TEMPO";

    case "NO_DUE_DATE":
      return "TANPA JATUH TEMPO";

    default:
      return "-";

  }

}


/* =========================================================
   DEBT DUE CLASS
========================================================= */

function getDebtDueStatusClass(
  status
) {

  switch (status) {

    case "PAID":
      return "badge-success";

    case "OVERDUE":
      return "badge-danger";

    case "TODAY":
      return "badge-warning";

    case "UPCOMING":
      return "badge-success";

    case "NO_DUE_DATE":
      return "badge";

    default:
      return "badge";

  }

}


