/* =========================================================
   FAEZA ERP V2
   SUPPLIER + PEMBELIAN
   BAGIAN 5 — CRUD SUPPLIER + FORM PEMBELIAN
========================================================= */


/* =========================================================
   SUPPLIER STORAGE
========================================================= */

function ensureSupplierStorage() {

  if (
    !Array.isArray(
      db.suppliers
    )
  ) {

    db.suppliers = [];

  }

}


/* =========================================================
   FIND SUPPLIER
========================================================= */

function findSupplier(
  supplierId
) {

  ensureSupplierStorage();


  return (
    db.suppliers.find(
      supplier =>
        supplier.id ===
        supplierId
    ) ||
    null
  );

}


/* =========================================================
   GET SUPPLIER LIST
========================================================= */

function getSuppliers() {

  ensureSupplierStorage();


  return [
    ...db.suppliers
  ].sort(
    (
      a,
      b
    ) =>
      String(
        a.name || ""
      ).localeCompare(
        String(
          b.name || ""
        )
      )
  );

}


/* =========================================================
   CREATE SUPPLIER
========================================================= */

function createSupplier(
  data
) {

  ensureSupplierStorage();


  const name =
    String(
      data?.name ||
      ""
    ).trim();


  if (!name) {

    throw new Error(
      "Nama supplier wajib diisi."
    );

  }


  const duplicate =
    db.suppliers.some(
      supplier =>
        String(
          supplier.name
        )
        .trim()
        .toLowerCase() ===
        name.toLowerCase()
    );


  if (duplicate) {

    throw new Error(
      "Supplier dengan nama tersebut sudah ada."
    );

  }


  const supplier = {

    id:
      generateId(
        "SUP"
      ),

    code:
      data.code ||
      generateId(
        "SUP"
      ),

    name:
      name,

    phone:
      String(
        data.phone ||
        ""
      ).trim(),

    address:
      String(
        data.address ||
        ""
      ).trim(),

    email:
      String(
        data.email ||
        ""
      ).trim(),

    contactPerson:
      String(
        data.contactPerson ||
        ""
      ).trim(),

    notes:
      String(
        data.notes ||
        ""
      ).trim(),

    createdAt:
      new Date()
        .toISOString(),

    updatedAt:
      new Date()
        .toISOString()

  };


  db.suppliers.push(
    supplier
  );


  saveDatabase();


  renderSuppliers();


  showToast(
    "Supplier berhasil ditambahkan."
  );


  return supplier;

}


/* =========================================================
   UPDATE SUPPLIER
========================================================= */

function updateSupplier(
  supplierId,
  data
) {

  const supplier =
    findSupplier(
      supplierId
    );


  if (!supplier) {

    throw new Error(
      "Supplier tidak ditemukan."
    );

  }


  const name =
    String(
      data?.name ||
      ""
    ).trim();


  if (!name) {

    throw new Error(
      "Nama supplier wajib diisi."
    );

  }


  const duplicate =
    db.suppliers.some(
      item =>
        item.id !==
          supplierId
        &&
        String(
          item.name
        )
        .trim()
        .toLowerCase() ===
        name.toLowerCase()
    );


  if (duplicate) {

    throw new Error(
      "Nama supplier sudah digunakan."
    );

  }


  Object.assign(
    supplier,
    {

      name,

      code:
        data.code ||
        supplier.code ||
        "",

      phone:
        String(
          data.phone ||
          ""
        ).trim(),

      address:
        String(
          data.address ||
          ""
        ).trim(),

      email:
        String(
          data.email ||
          ""
        ).trim(),

      contactPerson:
        String(
          data.contactPerson ||
          ""
        ).trim(),

      notes:
        String(
          data.notes ||
          ""
        ).trim(),

      updatedAt:
        new Date()
          .toISOString()

    }
  );


  saveDatabase();


  renderSuppliers();


  showToast(
    "Supplier berhasil diperbarui."
  );


  return supplier;

}


/* =========================================================
   DELETE SUPPLIER
========================================================= */

function deleteSupplier(
  supplierId
) {

  const supplier =
    findSupplier(
      supplierId
    );


  if (!supplier) {

    return;

  }


  const hasPurchase =
    Array.isArray(
      db.purchases
    )
    &&
    db.purchases.some(
      purchase =>
        purchase.supplierId ===
        supplierId
    );


  if (hasPurchase) {

    showToast(
      "Supplier tidak dapat dihapus karena sudah memiliki transaksi.",
      "error"
    );

    return;

  }


  if (
    !confirm(
      `Hapus supplier "${supplier.name}"?`
    )
  ) {

    return;

  }


  db.suppliers =
    db.suppliers.filter(
      item =>
        item.id !==
        supplierId
    );


  saveDatabase();


  renderSuppliers();


  showToast(
    "Supplier berhasil dihapus."
  );

}


