/* =========================================================
   PURCHASE FORM STATE
========================================================= */

let purchaseDraft = {

  supplierId:
    "",

  date:
    today(),

  paymentMethod:
    "CASH",

  creditDays:
    0,

  dueDate:
    "",

  notes:
    "",

  items:
    []

};


/* =========================================================
   RESET PURCHASE DRAFT
========================================================= */

function resetPurchaseDraft() {

  purchaseDraft = {

    supplierId:
      "",

    date:
      today(),

    paymentMethod:
      "CASH",

    creditDays:
      0,

    dueDate:
      "",

    notes:
      "",

    items:
      []

  };

}


/* =========================================================
   PURCHASE TOTAL
========================================================= */

function calculatePurchaseTotal() {

  return purchaseDraft.items
    .reduce(
      (
        total,
        item
      ) => {

        const qty =
          Number(
            item.qty
          ) || 0;

        const price =
          Number(
            item.price
          ) || 0;

        return (
          total +
          (
            qty *
            price
          )
        );

      },
      0
    );

}


/* =========================================================
   ADD PURCHASE ITEM
========================================================= */

function addPurchaseItem(
  productId,
  qty,
  price
) {

  if (!productId) {

    showToast(
      "Produk belum dipilih.",
      "error"
    );

    return false;

  }


  const product =
    Array.isArray(
      db.products
    )
      ? db.products.find(
          item =>
            item.id ===
            productId
        )
      : null;


  if (!product) {

    showToast(
      "Produk tidak ditemukan.",
      "error"
    );

    return false;

  }


  qty =
    Number(qty) || 0;


  price =
    Number(price) || 0;


  if (
    qty <= 0
  ) {

    showToast(
      "Jumlah harus lebih dari 0.",
      "error"
    );

    return false;

  }


  if (
    price < 0
  ) {

    showToast(
      "Harga beli tidak valid.",
      "error"
    );

    return false;

  }


  const existingIndex =
    purchaseDraft.items.findIndex(
      item =>
        item.productId ===
        productId
    );


  if (
    existingIndex >= 0
  ) {

    purchaseDraft.items[
      existingIndex
    ].qty +=
      qty;

    purchaseDraft.items[
      existingIndex
    ].price =
      price;

  }
  else {

    purchaseDraft.items.push({

      productId:

        product.id,

      productName:

        product.name ||
        "",

      qty:
        qty,

      quantity:
        qty,

      price:
        price,

      purchasePrice:
        price,

      unit:
        product.unit ||
        "pcs"

    });

  }


  renderPurchaseItems();


  return true;

}


/* =========================================================
   REMOVE PURCHASE ITEM
========================================================= */

function removePurchaseItem(
  index
) {

  if (
    index < 0 ||
    index >=
      purchaseDraft.items.length
  ) {

    return;

  }


  purchaseDraft.items.splice(
    index,
    1
  );


  renderPurchaseItems();

}


/* =========================================================
   RENDER PURCHASE ITEMS
========================================================= */

function renderPurchaseItems() {

  const tbody =
    document.getElementById(
      "purchaseItemsBody"
    );


  const totalEl =
    document.getElementById(
      "purchaseGrandTotal"
    );


  if (tbody) {

    if (
      !purchaseDraft.items.length
    ) {

      tbody.innerHTML = `

        <tr>

          <td
            colspan="7"
            class="empty-state"
          >

            Belum ada barang.

          </td>

        </tr>

      `;

    }
    else {

      tbody.innerHTML =
        purchaseDraft.items
          .map(
            (
              item,
              index
            ) => `

              <tr>

                <td>
                  ${index + 1}
                </td>

                <td>
                  ${escapeHTML(
                    item.productName
                  )}
                </td>

                <td>

                  <input
                    type="number"
                    min="1"
                    value="${item.qty}"
                    class="table-input"
                    onchange="
                      updatePurchaseItemQty(
                        ${index},
                        this.value
                      )
                    "
                  >

                </td>

                <td>

                  <input
                    type="number"
                    min="0"
                    value="${item.price}"
                    class="table-input"
                    onchange="
                      updatePurchaseItemPrice(
                        ${index},
                        this.value
                      )
                    "
                  >

                </td>

                <td>

                  ${formatRupiah(
                    item.qty *
                    item.price
                  )}

                </td>

                <td>

                  ${escapeHTML(
                    item.unit ||
                    "pcs"
                  )}

                </td>

                <td>

                  <button
                    type="button"
                    class="action-btn danger"
                    onclick="
                      removePurchaseItem(
                        ${index}
                      )
                    "
                  >
                    🗑️
                  </button>

                </td>

              </tr>

            `
          )
          .join("");

    }

  }


  if (totalEl) {

    totalEl.textContent =
      formatRupiah(
        calculatePurchaseTotal()
      );

  }

}


/* =========================================================
   UPDATE ITEM QTY
========================================================= */

function updatePurchaseItemQty(
  index,
  value
) {

  const qty =
    Number(value) || 0;


  if (
    qty <= 0
  ) {

    showToast(
      "Jumlah tidak valid.",
      "error"
    );

    renderPurchaseItems();

    return;

  }


  if (
    purchaseDraft.items[
      index
    ]
  ) {

    purchaseDraft.items[
      index
    ].qty =
      qty;

    purchaseDraft.items[
      index
    ].quantity =
      qty;

  }


  renderPurchaseItems();

}


/* =========================================================
   UPDATE ITEM PRICE
========================================================= */

function updatePurchaseItemPrice(
  index,
  value
) {

  const price =
    Number(value) || 0;


  if (
    price < 0
  ) {

    showToast(
      "Harga tidak valid.",
      "error"
    );

    renderPurchaseItems();

    return;

  }


  if (
    purchaseDraft.items[
      index
    ]
  ) {

    purchaseDraft.items[
      index
    ].price =
      price;

    purchaseDraft.items[
      index
    ].purchasePrice =
      price;

  }


  renderPurchaseItems();

}


