/* =========================================================
   GENERATE PURCHASE NUMBER
========================================================= */

function generatePurchaseNumber() {

  ensurePurchaseStorage();

  const prefix =
    "PO-" +
    today().replace(
      /-/g,
      ""
    ) +
    "-";


  const count =
    db.purchases.filter(
      purchase =>
        String(
          purchase.purchaseNumber ||
          ""
        ).startsWith(
          prefix
        )
    ).length + 1;


  return (
    prefix +
    String(
      count
    ).padStart(
      4,
      "0"
    )
  );

}


/* =========================================================
   UPDATE PURCHASE DUE DATE
========================================================= */

function updatePurchaseDueDate() {

  const date =
    document
      .getElementById(
        "purchaseDate"
      )
      ?.value ||
    today();


  const creditDays =
    Number(
      document
        .getElementById(
          "purchaseCreditDays"
        )
        ?.value
    ) || 0;


  const dueDate =
    document.getElementById(
      "purchaseDueDate"
    );


  if (!dueDate) {
    return;
  }


  if (
    creditDays <= 0
  ) {

    dueDate.value =
      "";

    return;

  }


  dueDate.value =
    addDays(
      date,
      creditDays
    );

}


/* =========================================================
   PURCHASE PAYMENT CHANGE
========================================================= */

function handlePurchasePaymentMethod() {

  const method =
    document
      .getElementById(
        "purchasePaymentMethod"
      )
      ?.value ||
    "CASH";


  const creditBox =
    document.getElementById(
      "purchaseCreditBox"
    );


  if (!creditBox) {
    return;
  }


  if (
    method ===
    "CREDIT"
  ) {

    creditBox.style.display =
      "";

    updatePurchaseDueDate();

  }
  else {

    creditBox.style.display =
      "none";

  }

}


