/* =========================================================
   GET SUPPLIER NAME
========================================================= */

function getSupplierName(
  supplierId
) {

  if (!supplierId) {
    return "";
  }


  const supplier =
    findSupplier(
      supplierId
    );


  return (
    supplier?.name ||
    ""
  );

}


/* =========================================================
   FIND PURCHASE
========================================================= */

function findPurchase(
  purchaseId
) {

  ensurePurchaseStorage();


  return (
    db.purchases.find(
      purchase =>
        purchase.id ===
        purchaseId
    ) ||
    null
  );

}


/* =========================================================
   GET PURCHASE ITEMS
========================================================= */

function getPurchaseItems(
  purchase
) {

  if (!purchase) {
    return [];
  }


  if (
    Array.isArray(
      purchase.items
    )
  ) {

    return purchase.items;

  }


  if (
    Array.isArray(
      purchase.details
    )
  ) {

    return purchase.details;

  }


  return [];

}


/* =========================================================
   NORMALIZE PURCHASE ITEM
========================================================= */

function normalizePurchaseItem(
  item
) {

  const qty =
    Number(
      item.qty ??
      item.quantity ??
      0
    ) || 0;


  const price =
    Number(
      item.price ??
      item.purchasePrice ??
      item.buyPrice ??
      0
    ) || 0;


  const subtotal =
    Number(
      item.subtotal
    );


  return {

    ...item,

    productId:
      item.productId ||
      "",

    productName:
      item.productName ||
      getProductName(
        item.productId
      ) ||
      "",

    qty,

    quantity:
      qty,

    price,

    purchasePrice:
      price,

    subtotal:
      Number.isFinite(
        subtotal
      )
        ? subtotal
        : qty * price,

    unit:
      item.unit ||
      "pcs"

  };

}


/* =========================================================
   NORMALIZE PURCHASE
========================================================= */

function normalizePurchase(
  purchase
) {

  if (!purchase) {
    return purchase;
  }


  const items =
    getPurchaseItems(
      purchase
    )
    .map(
      item =>
        normalizePurchaseItem(
          item
        )
    );


  purchase.items =
    items;


  purchase.total =
    Number(
      purchase.total
    );


  if (
    !Number.isFinite(
      purchase.total
    )
  ) {

    purchase.total =
      items.reduce(
        (
          total,
          item
        ) =>
          total +
          item.subtotal,
        0
      );

  }


  purchase.paid =
    Number(
      purchase.paid
    ) || 0;


  purchase.remaining =
    Math.max(
      0,
      purchase.total -
      purchase.paid
    );


  purchase.paymentMethod =
    String(
      purchase.paymentMethod ||
      purchase.paymentType ||
      "CASH"
    )
    .toUpperCase();


  purchase.supplierName =
    purchase.supplierName ||
    getSupplierName(
      purchase.supplierId
    );


  return purchase;

}


