/* =========================================================
   FILTER PURCHASES
========================================================= */

function filterPurchases() {

  const search =
    (
      document
        .getElementById(
          "purchaseSearch"
        )
        ?.value ||
      ""
    )
    .trim()
    .toLowerCase();


  const startDate =
    document
      .getElementById(
        "purchaseStartDate"
      )
      ?.value ||
    "";


  const endDate =
    document
      .getElementById(
        "purchaseEndDate"
      )
      ?.value ||
    "";


  const payment =
    document
      .getElementById(
        "purchasePaymentFilter"
      )
      ?.value ||
    "";


  const tbody =
    document.getElementById(
      "purchaseTableBody"
    );


  if (!tbody) {
    return;
  }


  ensurePurchaseStorage();


  const purchases =
    db.purchases
      .map(
        purchase =>
          normalizePurchase(
            purchase
          )
      )
      .filter(
        purchase => {

          if (
            search
          ) {

            const text =
              [

                purchase.purchaseNumber,

                purchase.invoiceNumber,

                purchase.supplierName,

                purchase.notes

              ]
              .join(" ")
              .toLowerCase();


            if (
              !text.includes(
                search
              )
            ) {

              return false;

            }

          }


          if (
            startDate &&
            purchase.date <
              startDate
          ) {

            return false;

          }


          if (
            endDate &&
            purchase.date >
              endDate
          ) {

            return false;

          }


          if (
            payment &&
            purchase.paymentMethod !==
              payment
          ) {

            return false;

          }


          return true;

        }
      )
      .sort(
        (
          a,
          b
        ) =>
          String(
            b.date ||
            ""
          )
          .localeCompare(
            String(
              a.date ||
              ""
            )
          )
      );


  if (!purchases.length) {

    tbody.innerHTML = `

      <tr>

        <td
          colspan="9"
          class="empty-state"
        >

          🔎 Tidak ada data yang sesuai.

        </td>

      </tr>

    `;

    return;

  }


  tbody.innerHTML =
    purchases
      .map(
        purchase => {

          const isCredit =
            purchase.paymentMethod ===
            "CREDIT";


          const status =
            purchase.remaining <=
            0

              ? "LUNAS"

              : isCredit
                ? "HUTANG"
                : "BELUM LUNAS";


          return `

            <tr>

              <td>

                ${escapeHTML(
                  purchase.date ||
                  "-"
                )}

              </td>


              <td>

                <strong>

                  ${escapeHTML(
                    purchase.purchaseNumber ||
                    purchase.id
                  )}

                </strong>

              </td>


              <td>

                ${escapeHTML(
                  purchase.supplierName ||
                  "-"
                )}

              </td>


              <td>

                ${
                  isCredit
                    ? "KREDIT"
                    : "TUNAI"
                }

              </td>


              <td>

                ${formatRupiah(
                  purchase.total
                )}

              </td>


              <td>

                ${formatRupiah(
                  purchase.paid
                )}

              </td>


              <td>

                ${formatRupiah(
                  purchase.remaining
                )}

              </td>


              <td>

                <span
                  class="badge"
                >

                  ${status}

                </span>

              </td>


              <td>

                <button
                  type="button"
                  class="action-btn"
                  onclick="
                    viewPurchase(
                      '${purchase.id}'
                    )
                  "
                >

                  👁️

                </button>

              </td>

            </tr>

          `;

        }
      )
      .join("");

}


