/* =========================================================
   SNAPSHOT DATABASE
========================================================= */

function createPurchaseSnapshot() {

  return JSON.stringify({
    purchases:
      Array.isArray(db.purchases)
        ? db.purchases
        : [],

    stockMovements:
      Array.isArray(db.stockMovements)
        ? db.stockMovements
        : [],

    debts:
      Array.isArray(db.debts)
        ? db.debts
        : [],

    products:
      Array.isArray(db.products)
        ? db.products
        : [],

    suppliers:
      Array.isArray(db.suppliers)
        ? db.suppliers
        : []

  });

}


/* =========================================================
   RESTORE DATABASE SNAPSHOT
========================================================= */

function restorePurchaseSnapshot(
  snapshot
) {

  if (!snapshot) {
    return;
  }


  const data =
    JSON.parse(
      snapshot
    );


  db.purchases =
    data.purchases || [];


  db.stockMovements =
    data.stockMovements || [];


  db.debts =
    data.debts || [];


  db.products =
    data.products || [];


  db.suppliers =
    data.suppliers || [];


  saveDatabase();

}


/* =========================================================
   CHECK DUPLICATE PURCHASE
========================================================= */

function purchaseAlreadyExists(
  purchase
) {

  ensurePurchaseStorage();


  const purchaseNumber =
    String(
      purchase.purchaseNumber ||
      purchase.invoiceNumber ||
      ""
    )
    .trim();


  if (!purchaseNumber) {
    return false;
  }


  return db.purchases.some(
    existing => {

      const existingNumber =
        String(
          existing.purchaseNumber ||
          existing.invoiceNumber ||
          ""
        )
        .trim();


      return (
        existingNumber ===
        purchaseNumber
      );

    }
  );

}


/* =========================================================
   CHECK DUPLICATE STOCK MOVEMENT
========================================================= */

function stockMovementAlreadyExists(
  referenceId,
  productId
) {

  ensureStockStorage();


  return db.stockMovements.some(
    movement => {

      return (

        movement.referenceId ===
        referenceId

        &&

        movement.productId ===
        productId

        &&

        movement.referenceType ===
        "PURCHASE"

      );

    }
  );

}


/* =========================================================
   GET PURCHASE OUTSTANDING
========================================================= */

function getPurchaseOutstanding(
  purchase
) {

  normalizePurchase(
    purchase
  );


  return Math.max(
    0,
    Number(
      purchase.total
    ) -
    Number(
      purchase.paid
    )
  );

}


/* =========================================================
   CREATE PURCHASE DEBT
========================================================= */

function createPurchaseDebt(
  purchase
) {

  /*
     Pastikan storage hutang tersedia.
  */

  if (
    typeof ensureDebtStorage ===
    "function"
  ) {

    ensureDebtStorage();

  }
  else {

    if (
      !Array.isArray(
        db.debts
      )
    ) {

      db.debts = [];

    }

  }


  const outstanding =
    getPurchaseOutstanding(
      purchase
    );


  /*
     Kalau sudah lunas,
     tidak perlu membuat hutang.
  */

  if (
    outstanding <=
    0
  ) {

    return null;

  }


  /*
     Jangan buat hutang
     dua kali.
  */

  const existing =
    db.debts.find(
      debt => {

        return (

          debt.referenceId ===
          purchase.id

          &&

          (
            debt.type ===
            "PAYABLE"

            ||

            debt.debtType ===
            "PAYABLE"

            ||

            debt.category ===
            "SUPPLIER"

          )

        );

      }
    );


  if (existing) {

    return existing;

  }


  const debt = {

    id:
      generateId(
        "HUT"
      ),

    type:
      "PAYABLE",

    debtType:
      "PAYABLE",

    category:
      "SUPPLIER",

    partyType:
      "SUPPLIER",

    partyId:
      purchase.supplierId ||
      "",

    supplierId:
      purchase.supplierId ||
      "",

    supplierName:
      purchase.supplierName ||
      "",

    referenceId:
      purchase.id,

    referenceNumber:
      purchase.purchaseNumber ||
      purchase.invoiceNumber ||
      "",

    invoiceNumber:
      purchase.purchaseNumber ||
      purchase.invoiceNumber ||
      "",

    date:
      purchase.date ||
      today(),

    dueDate:
      purchase.dueDate ||
      "",

    originalAmount:
      Number(
        purchase.total
      ) || 0,

    amount:
      outstanding,

    paid:
      0,

    remaining:
      outstanding,

    status:
      "OPEN",

    notes:
      purchase.notes ||
      "",

    createdAt:
      new Date()
        .toISOString(),

    updatedAt:
      new Date()
        .toISOString()

  };


  db.debts.push(
    debt
  );


  return debt;

}


/* =========================================================
   UPDATE SUPPLIER PURCHASE BALANCE
========================================================= */

function updateSupplierPurchaseBalance(
  purchase
) {

  if (
    !Array.isArray(
      db.suppliers
    )
  ) {

    return;

  }


  const supplier =
    db.suppliers.find(
      item =>
        item.id ===
        purchase.supplierId
    );


  if (!supplier) {
    return;
  }


  /*
     Jangan mengganti nilai saldo
     secara membabi buta.

     Kita hitung ulang dari hutang
     supplier agar lebih aman.
  */

  if (
    !Array.isArray(
      db.debts
    )
  ) {

    return;

  }


  const balance =
    db.debts
      .filter(
        debt => {

          return (

            (
              debt.type ===
              "PAYABLE"

              ||

              debt.debtType ===
              "PAYABLE"

              ||

              debt.category ===
              "SUPPLIER"

            )

            &&

            (
              debt.supplierId ===
              supplier.id

              ||

              debt.partyId ===
              supplier.id

            )

          );

        }
      )
      .reduce(
        (
          total,
          debt
        ) => {

          return (
            total +
            (
              Number(
                debt.remaining
              ) || 0
            )
          );

        },
        0
      );


  supplier.outstandingDebt =
    balance;


  supplier.payable =
    balance;


  supplier.hutang =
    balance;


  supplier.updatedAt =
    new Date()
      .toISOString();

}


/* =========================================================
   FINALIZE PURCHASE TRANSACTION
========================================================= */

function finalizePurchaseTransaction(
  purchase
) {

  if (!purchase) {

    throw new Error(
      "Data pembelian tidak tersedia."
    );

  }


  ensurePurchaseStorage();

  ensureStockStorage();


  if (
    !Array.isArray(
      db.debts
    )
  ) {

    db.debts = [];

  }


  /*
     ======================================================
     VALIDASI DATA DASAR
     ======================================================
  */

  if (
    !purchase.supplierId
  ) {

    throw new Error(
      "Supplier wajib dipilih."
    );

  }


  if (
    !purchase.items ||
    !Array.isArray(
      purchase.items
    ) ||
    !purchase.items.length
  ) {

    throw new Error(
      "Barang pembelian belum tersedia."
    );

  }


  /*
     ======================================================
     NORMALISASI TRANSAKSI
     ======================================================
  */

  normalizePurchase(
    purchase
  );


  /*
     ======================================================
     CEK TRANSAKSI GANDA
     ======================================================
  */

  if (
    purchaseAlreadyExists(
      purchase
    )
  ) {

    throw new Error(
      "Nomor pembelian sudah tersimpan. Transaksi dibatalkan agar tidak terjadi duplikasi."
    );

  }


  /*
     ======================================================
     SNAPSHOT
     ======================================================

     Jika proses di tengah jalan gagal,
     seluruh perubahan dikembalikan.
  */

  const snapshot =
    createPurchaseSnapshot();


  try {

    /*
       ====================================================
       1. SIMPAN PEMBELIAN
       ====================================================
    */

    db.purchases.push(
      purchase
    );


    /*
       ====================================================
       2. TAMBAH STOK + KARTU STOK
       ====================================================
    */

    purchase.items.forEach(
      item => {

        const normalized =
          normalizePurchaseItem(
            item
          );


        if (
          !normalized.productId
        ) {

          throw new Error(
            "Ada barang pembelian tanpa productId."
          );

        }


        if (
          normalized.qty <=
          0
        ) {

          throw new Error(
            `Qty ${normalized.productName || "barang"} tidak valid.`
          );

        }


        /*
           Cegah stok masuk ganda.
        */

        if (
          stockMovementAlreadyExists(
            purchase.id,
            normalized.productId
          )
        ) {

          throw new Error(
            `Pergerakan stok untuk ${normalized.productName} sudah tercatat.`
          );

        }


        /*
           recordStockIn:

           - mengambil stok lama
           - menambah qty
           - menyimpan stockBefore
           - menyimpan stockAfter
           - mencatat kartu stok
        */

        recordStockIn({

          date:
            purchase.date,

          productId:
            normalized.productId,

          qty:
            normalized.qty,

          price:
            normalized.price,

          unit:
            normalized.unit,

          referenceType:
            "PURCHASE",

          referenceId:
            purchase.id,

          referenceNumber:
            purchase.purchaseNumber ||
            purchase.invoiceNumber ||
            "",

          supplierId:
            purchase.supplierId,

          supplierName:
            purchase.supplierName,

          notes:
            `Stok masuk dari pembelian ${
              purchase.purchaseNumber ||
              purchase.id
            }`

        });

      }
    );


    /*
       ====================================================
       3. BUAT HUTANG SUPPLIER
       ====================================================
    */

    if (
      purchase.paymentMethod ===
      "CREDIT"
    ) {

      createPurchaseDebt(
        purchase
      );

    }


    /*
       ====================================================
       4. UPDATE SALDO SUPPLIER
       ====================================================
    */

    updateSupplierPurchaseBalance(
      purchase
    );


    /*
       ====================================================
       5. SIMPAN DATABASE
       ====================================================
    */

    saveDatabase();


    /*
       ====================================================
       6. REFRESH DATA
       ====================================================
    */

    if (
      typeof refreshStockData ===
      "function"
    ) {

      refreshStockData();

    }


    if (
      typeof renderPurchases ===
      "function"
    ) {

      renderPurchases();

    }


    if (
      typeof renderPurchaseSummary ===
      "function"
    ) {

      renderPurchaseSummary();

    }


    if (
      typeof renderPurchaseCreditSummary ===
      "function"
    ) {

      renderPurchaseCreditSummary();

    }


    if (
      typeof renderPurchaseStatusSummary ===
      "function"
    ) {

      renderPurchaseStatusSummary();

    }


    if (
      typeof renderDebtSummary ===
      "function"
    ) {

      renderDebtSummary();

    }


    /*
       ====================================================
       7. RETURN TRANSAKSI
       ====================================================
    */

    return purchase;

  }
  catch (
    error
  ) {

    /*
       ====================================================
       ROLLBACK
       ====================================================
    */

    console.error(
      "PURCHASE TRANSACTION FAILED:",
      error
    );


    restorePurchaseSnapshot(
      snapshot
    );


    throw new Error(
      error.message ||
      "Transaksi pembelian gagal dan perubahan dibatalkan."
    );

  }

}


/* =========================================================
   VERIFY PURCHASE TRANSACTION
========================================================= */

function verifyPurchaseTransaction(
  purchaseId
) {

  const purchase =
    findPurchase(
      purchaseId
    );


  if (!purchase) {

    return {

      valid:
        false,

      reason:
        "Pembelian tidak ditemukan."

    };

  }


  normalizePurchase(
    purchase
  );


  const stockMovements =
    getStockMovements({

      referenceType:
        "PURCHASE"

    })
    .filter(
      movement =>
        movement.referenceId ===
        purchase.id
    );


  const stockQty =
    stockMovements.reduce(
      (
        total,
        movement
      ) =>
        total +
        (
          Number(
            movement.qty
          ) || 0
        ),
      0
    );


  const purchaseQty =
    purchase.items.reduce(
      (
        total,
        item
      ) =>
        total +
        (
          Number(
            item.qty ??
            item.quantity ??
            0
          ) || 0
        ),
      0
    );


  const debt =
    Array.isArray(
      db.debts
    )

      ? db.debts.find(
          item =>
            item.referenceId ===
            purchase.id
        )

      : null;


  const stockCorrect =
    stockQty ===
    purchaseQty;


  const debtCorrect =
    purchase.paymentMethod !==
      "CREDIT"

      ? !debt

      : (
          !!debt &&
          Number(
            debt.remaining
          ) ===
          Number(
            purchase.remaining
          )
        );


  return {

    valid:
      stockCorrect &&
      debtCorrect,

    purchaseId:
      purchase.id,

    purchaseNumber:
      purchase.purchaseNumber,

    purchaseQty:
      purchaseQty,

    stockQty:
      stockQty,

    stockCorrect:
      stockCorrect,

    debtCorrect:
      debtCorrect,

    debtId:
      debt?.id ||
      null

  };

}


