/* =========================================================
   DEBT STORAGE
========================================================= */

function ensureDebtStorage() {

  if (
    !Array.isArray(
      db.debts
    )
  ) {

    db.debts = [];

  }

}


/* =========================================================
   DEBT PAYMENT STORAGE
========================================================= */

function ensureDebtPaymentStorage() {

  if (
    !Array.isArray(
      db.debtPayments
    )
  ) {

    db.debtPayments = [];

  }

}


/* =========================================================
   FIND DEBT
========================================================= */

function findDebt(
  debtId
) {

  ensureDebtStorage();


  return (
    db.debts.find(
      debt =>
        debt.id ===
        debtId
    ) ||
    null
  );

}


/* =========================================================
   FIND DEBT BY PURCHASE
========================================================= */

function findDebtByPurchase(
  purchaseId
) {

  ensureDebtStorage();


  return (
    db.debts.find(
      debt =>
        debt.referenceId ===
        purchaseId
    ) ||
    null
  );

}


/* =========================================================
   GET DEBT REMAINING
========================================================= */

function getDebtRemaining(
  debt
) {

  if (!debt) {
    return 0;
  }


  const amount =
    Number(
      debt.amount ??
      debt.originalAmount ??
      0
    ) || 0;


  const paid =
    Number(
      debt.paid
    ) || 0;


  const explicitRemaining =
    Number(
      debt.remaining
    );


  if (
    Number.isFinite(
      explicitRemaining
    )
  ) {

    return Math.max(
      0,
      explicitRemaining
    );

  }


  return Math.max(
    0,
    amount -
    paid
  );

}


/* =========================================================
   NORMALIZE DEBT
========================================================= */

function normalizeDebt(
  debt
) {

  if (!debt) {
    return null;
  }


  debt.amount =
    Number(
      debt.amount ??
      debt.originalAmount ??
      0
    ) || 0;


  debt.originalAmount =
    Number(
      debt.originalAmount ??
      debt.amount
    ) || 0;


  debt.paid =
    Number(
      debt.paid
    ) || 0;


  debt.remaining =
    Math.max(
      0,
      Number(
        debt.amount
      ) -
      Number(
        debt.paid
      )
    );


  if (
    debt.remaining <=
    0
  ) {

    debt.status =
      "PAID";

  }
  else {

    debt.status =
      "OPEN";

  }


  debt.updatedAt =
    new Date()
      .toISOString();


  return debt;

}


/* =========================================================
   GENERATE DEBT PAYMENT NUMBER
========================================================= */

function generateDebtPaymentNumber() {

  ensureDebtPaymentStorage();


  const date =
    new Date();


  const year =
    date.getFullYear();


  const month =
    String(
      date.getMonth() + 1
    )
    .padStart(
      2,
      "0"
    );


  const prefix =
    `BYR-${year}${month}-`;


  let max =
    0;


  db.debtPayments.forEach(
    payment => {

      const number =
        String(
          payment.paymentNumber ||
          ""
        );


      if (
        !number.startsWith(
          prefix
        )
      ) {

        return;

      }


      const value =
        Number(
          number
            .replace(
              prefix,
              ""
            )
        );


      if (
        Number.isFinite(
          value
        )
      ) {

        max =
          Math.max(
            max,
            value
          );

      }

    }
  );


  return (
    prefix +
    String(
      max + 1
    )
    .padStart(
      4,
      "0"
    )
  );

}


/* =========================================================
   FIND PAYMENT
========================================================= */

function findDebtPayment(
  paymentId
) {

  ensureDebtPaymentStorage();


  return (
    db.debtPayments.find(
      payment =>
        payment.id ===
        paymentId
    ) ||
    null
  );

}


/* =========================================================
   GET DEBT PAYMENTS
========================================================= */

function getDebtPayments(
  debtId
) {

  ensureDebtPaymentStorage();


  return db.debtPayments
    .filter(
      payment =>
        payment.debtId ===
        debtId
    )
    .sort(
      (
        a,
        b
      ) =>
        String(
          b.date ||
          ""
        )
        .localeCompare(
          String(
            a.date ||
            ""
          )
        )
    );

}


/* =========================================================
   CREATE DEBT PAYMENT
========================================================= */

function createDebtPayment(
  data
) {

  ensureDebtStorage();

  ensureDebtPaymentStorage();


  const debt =
    findDebt(
      data.debtId
    );


  if (!debt) {

    throw new Error(
      "Hutang supplier tidak ditemukan."
    );

  }


  normalizeDebt(
    debt
  );


  const amount =
    Number(
      data.amount
    ) || 0;


  if (
    amount <=
    0
  ) {

    throw new Error(
      "Nominal pembayaran harus lebih dari 0."
    );

  }


  const remainingBefore =
    getDebtRemaining(
      debt
    );


  if (
    remainingBefore <=
    0
  ) {

    throw new Error(
      "Hutang ini sudah lunas."
    );

  }


  if (
    amount >
    remainingBefore
  ) {

    throw new Error(
      `Pembayaran melebihi sisa hutang. Sisa hutang: ${formatRupiah(
        remainingBefore
      )}.`
    );

  }


  const paymentNumber =
    data.paymentNumber ||
    generateDebtPaymentNumber();


  const payment = {

    id:
      generateId(
        "BAYAR"
      ),

    paymentNumber,

    debtId:
      debt.id,

    purchaseId:
      debt.referenceId ||
      "",

    supplierId:
      debt.supplierId ||
      debt.partyId ||
      "",

    supplierName:
      debt.supplierName ||
      "",

    date:
      data.date ||
      today(),

    amount:
      amount,

    paymentMethod:
      String(
        data.paymentMethod ||
        "CASH"
      )
      .toUpperCase(),

    referenceNumber:
      data.referenceNumber ||
      "",

    notes:
      data.notes ||
      "",

    createdAt:
      new Date()
        .toISOString()

  };


  /*
     Update hutang.
  */

  debt.paid =
    Number(
      debt.paid
    ) +
    amount;


  debt.remaining =
    Math.max(
      0,
      Number(
        debt.amount
      ) -
      Number(
        debt.paid
      )
    );


  debt.status =
    debt.remaining <=
    0

      ? "PAID"

      : "OPEN";


  debt.updatedAt =
    new Date()
      .toISOString();


  db.debtPayments.push(
    payment
  );


  /*
     Update transaksi pembelian
     jika pembayaran berasal dari
     hutang pembelian.
  */

  if (
    debt.referenceId
  ) {

    const purchase =
      findPurchase(
        debt.referenceId
      );


    if (purchase) {

      normalizePurchase(
        purchase
      );


      purchase.paid =
        Number(
          purchase.paid
        ) +
        amount;


      purchase.remaining =
        Math.max(
          0,
          Number(
            purchase.total
          ) -
          Number(
            purchase.paid
          )
        );


      if (
        purchase.remaining <=
        0
      ) {

        purchase.paymentStatus =
          "PAID";

      }
      else {

        purchase.paymentStatus =
          "PARTIAL";

      }


      purchase.updatedAt =
        new Date()
          .toISOString();

    }

  }


  /*
     Update saldo supplier.
  */

  if (
    typeof updateSupplierPurchaseBalance ===
    "function"
  ) {

    const purchase =
      debt.referenceId
        ? findPurchase(
            debt.referenceId
          )
        : null;


    if (purchase) {

      updateSupplierPurchaseBalance(
        purchase
      );

    }

  }


  saveDatabase();


  /*
     Refresh tampilan.
  */

  if (
    typeof renderDebtSummary ===
    "function"
  ) {

    renderDebtSummary();

  }


  if (
    typeof renderOverdueDebts ===
    "function"
  ) {

    renderOverdueDebts();

  }


  if (
    typeof renderPurchases ===
    "function"
  ) {

    renderPurchases();

  }


  if (
    typeof renderPurchaseSummary ===
    "function"
  ) {

    renderPurchaseSummary();

  }


  return payment;

}


/* =========================================================
   OPEN PURCHASE PAYMENT
========================================================= */

function openPurchasePayment(
  purchaseId
) {

  const purchase =
    findPurchase(
      purchaseId
    );


  if (!purchase) {

    showToast(
      "Pembelian tidak ditemukan.",
      "error"
    );

    return;

  }


  normalizePurchase(
    purchase
  );


  if (
    purchase.remaining <=
    0
  ) {

    showToast(
      "Pembelian ini sudah lunas.",
      "info"
    );

    return;

  }


  let debt =
    findDebtByPurchase(
      purchase.id
    );


  /*
     Jika transaksi kredit ada,
     tetapi hutangnya belum tercatat,
     buat otomatis.
  */

  if (
    !debt &&
    purchase.paymentMethod ===
      "CREDIT"
  ) {

    debt =
      createPurchaseDebt(
        purchase
      );


    saveDatabase();

  }


  if (!debt) {

    showToast(
      "Hutang supplier tidak ditemukan.",
      "error"
    );

    return;

  }


  normalizeDebt(
    debt
  );


  const body = `

    <form
      id="debtPaymentForm"
      onsubmit="
        event.preventDefault();
        submitDebtPayment(
          '${debt.id}'
        );
      "
    >

      <div
        class="form-grid"
      >

        <div
          class="preview-row"
        >

          <span>
            No. Pembelian
          </span>

          <strong>

            ${escapeHTML(
              purchase.purchaseNumber ||
              purchase.id
            )}

          </strong>

        </div>


        <div
          class="preview-row"
        >

          <span>
            Supplier
          </span>

          <strong>

            ${escapeHTML(
              debt.supplierName ||
              "-"
            )}

          </strong>

        </div>


        <div
          class="preview-row"
        >

          <span>
            Total Hutang
          </span>

          <strong>

            ${formatRupiah(
              debt.amount
            )}

          </strong>

        </div>


        <div
          class="preview-total"
        >

          <span>
            SISA HUTANG
          </span>

          <strong>

            ${formatRupiah(
              debt.remaining
            )}

          </strong>

        </div>


        <div
          class="form-group"
        >

          <label>
            Tanggal Pembayaran
          </label>

          <input
            type="date"
            id="debtPaymentDate"
            value="${today()}"
            required
          >

        </div>


        <div
          class="form-group"
        >

          <label>
            Nominal Pembayaran
          </label>

          <input
            type="number"
            id="debtPaymentAmount"
            min="1"
            max="${debt.remaining}"
            step="1"
            value="${debt.remaining}"
            required
          >

        </div>


        <div
          class="form-group"
        >

          <label>
            Metode Pembayaran
          </label>

          <select
            id="debtPaymentMethod"
            required
          >

            <option
              value="CASH"
            >
              Tunai
            </option>

            <option
              value="BANK"
            >
              Transfer Bank
            </option>

            <option
              value="EWALLET"
            >
              E-Wallet
            </option>

          </select>

        </div>


        <div
          class="form-group"
        >

          <label>
            No. Referensi
          </label>

          <input
            type="text"
            id="debtPaymentReference"
            placeholder="Opsional"
          >

        </div>


        <div
          class="form-group"
        >

          <label>
            Catatan
          </label>

          <textarea
            id="debtPaymentNotes"
            rows="3"
            placeholder="Catatan pembayaran..."
          ></textarea>

        </div>

      </div>

    </form>

  `;


  openModal(
    "Pembayaran Hutang Supplier",
    body,
    () => {

      submitDebtPayment(
        debt.id
      );

    }
  );

}


/* =========================================================
   SUBMIT DEBT PAYMENT
========================================================= */

function submitDebtPayment(
  debtId
) {

  const date =
    document.getElementById(
      "debtPaymentDate"
    )?.value ||
    today();


  const amount =
    Number(
      document.getElementById(
        "debtPaymentAmount"
      )?.value
    ) || 0;


  const paymentMethod =
    document.getElementById(
      "debtPaymentMethod"
    )?.value ||
    "CASH";


  const referenceNumber =
    document.getElementById(
      "debtPaymentReference"
    )?.value ||
    "";


  const notes =
    document.getElementById(
      "debtPaymentNotes"
    )?.value ||
    "";


  try {

    const payment =
      createDebtPayment({

        debtId,

        date,

        amount,

        paymentMethod,

        referenceNumber,

        notes

      });


    closeModal();


    showToast(
      `Pembayaran ${
        payment.paymentNumber
      } berhasil disimpan.`,
      "success"
    );


  }
  catch (
    error
  ) {

    console.error(
      "DEBT PAYMENT ERROR:",
      error
    );


    showToast(
      error.message ||
      "Pembayaran hutang gagal.",
      "error"
    );

  }

}


/* =========================================================
   PAY FULL DEBT
========================================================= */

function payDebtInFull(
  debtId
) {

  const debt =
    findDebt(
      debtId
    );


  if (!debt) {

    showToast(
      "Hutang tidak ditemukan.",
      "error"
    );

    return;

  }


  normalizeDebt(
    debt
  );


  if (
    debt.remaining <=
    0
  ) {

    showToast(
      "Hutang sudah lunas.",
      "info"
    );

    return;

  }


  const confirmed =
    confirm(
      `Bayar lunas hutang sebesar ${formatRupiah(
        debt.remaining
      )}?`
    );


  if (!confirmed) {
    return;
  }


  try {

    createDebtPayment({

      debtId:
        debt.id,

      date:
        today(),

      amount:
        debt.remaining,

      paymentMethod:
        "CASH",

      notes:
        "Pelunasan hutang supplier."

    });


    showToast(
      "Hutang berhasil dilunasi.",
      "success"
    );

  }
  catch (
    error
  ) {

    showToast(
      error.message ||
      "Pelunasan gagal.",
      "error"
    );

  }

}


/* =========================================================
   GET SUPPLIER DEBT BALANCE
========================================================= */

function getSupplierDebtBalance(
  supplierId
) {

  ensureDebtStorage();


  return db.debts
    .filter(
      debt => {

        return (

          (
            debt.supplierId ===
            supplierId

            ||

            debt.partyId ===
            supplierId
          )

          &&

          (
            debt.type ===
            "PAYABLE"

            ||

            debt.debtType ===
            "PAYABLE"

            ||

            debt.category ===
            "SUPPLIER"

          )

        );

      }
    )
    .reduce(
      (
        total,
        debt
      ) => {

        return (
          total +
          getDebtRemaining(
            debt
          )
        );

      },
      0
    );

}


/* =========================================================
   GET TOTAL PAYABLE
========================================================= */

function getTotalSupplierPayable() {

  ensureDebtStorage();


  return db.debts
    .filter(
      debt => {

        return (

          debt.type ===
          "PAYABLE"

          ||

          debt.debtType ===
          "PAYABLE"

          ||

          debt.category ===
          "SUPPLIER"

        );

      }
    )
    .reduce(
      (
        total,
        debt
      ) => {

        return (
          total +
          getDebtRemaining(
            debt
          )
        );

      },
      0
    );

}


