/* =========================================================
   GET PAYABLE SUMMARY
========================================================= */

function getPayableSummary() {

  ensureDebtStorage();


  let totalDebt = 0;

  let totalPaid = 0;

  let totalRemaining = 0;

  let totalOpen = 0;

  let totalPartial = 0;

  let totalOverdue = 0;

  let totalPaidInvoices = 0;


  db.debts.forEach(
    debt => {

      const isPayable =

        debt.type ===
        "PAYABLE"

        ||

        debt.debtType ===
        "PAYABLE"

        ||

        debt.category ===
        "SUPPLIER";


      if (!isPayable) {
        return;
      }


      normalizeDebt(
        debt
      );


      const status =
        getDebtStatus(
          debt
        );


      totalDebt +=
        Number(
          debt.amount
        ) || 0;


      totalPaid +=
        Number(
          debt.paid
        ) || 0;


      totalRemaining +=
        Number(
          debt.remaining
        ) || 0;


      if (
        status ===
        "OPEN"
      ) {

        totalOpen +=
          1;

      }


      if (
        status ===
        "PARTIAL"
      ) {

        totalPartial +=
          1;

      }


      if (
        status ===
        "OVERDUE"
      ) {

        totalOverdue +=
          1;

      }


      if (
        status ===
        "PAID"
      ) {

        totalPaidInvoices +=
          1;

      }

    }
  );


  return {

    totalDebt,

    totalPaid,

    totalRemaining,

    totalOpen,

    totalPartial,

    totalOverdue,

    totalPaidInvoices

  };

}


/* =========================================================
   RENDER DEBT SUMMARY
========================================================= */

