/* =========================================================
   GET OVERDUE DEBTS
========================================================= */

function getOverdueDebts() {

  ensureDebtStorage();


  return db.debts
    .filter(
      debt => {

        const isPayable =

          debt.type ===
          "PAYABLE"

          ||

          debt.debtType ===
          "PAYABLE"

          ||

          debt.category ===
          "SUPPLIER";


        if (!isPayable) {

          return false;

        }


        normalizeDebt(
          debt
        );


        return (
          getDebtStatus(
            debt
          ) ===
          "OVERDUE"
        );

      }
    )
    .sort(
      (
        a,
        b
      ) => {

        return String(
          a.dueDate ||
          ""
        )
        .localeCompare(
          String(
            b.dueDate ||
            ""
          )
        );

      }
    );

}


/* =========================================================
   GET UPCOMING DEBTS
========================================================= */

function getUpcomingDebts(
  days = 7
) {

  ensureDebtStorage();


  const now =
    new Date();


  const limit =
    new Date();


  limit.setDate(
    limit.getDate() +
    Number(
      days
    )
  );


  return db.debts
    .filter(
      debt => {

        const isPayable =

          debt.type ===
          "PAYABLE"

          ||

          debt.debtType ===
          "PAYABLE"

          ||

          debt.category ===
          "SUPPLIER";


        if (!isPayable) {

          return false;

        }


        normalizeDebt(
          debt
        );


        if (
          debt.remaining <=
          0
        ) {

          return false;

        }


        if (
          !debt.dueDate
        ) {

          return false;

        }


        const due =
          new Date(
            debt.dueDate +
            "T00:00:00"
          );


        return (

          due >=
          now

          &&

          due <=
          limit

        );

      }
    )
    .sort(
      (
        a,
        b
      ) =>
        String(
          a.dueDate
        )
        .localeCompare(
          String(
            b.dueDate
          )
        )
    );

}


