/* =========================================================
   RECEIVABLE STORAGE
========================================================= */

function ensureReceivableStorage() {

  if (
    !Array.isArray(
      db.receivables
    )
  ) {

    db.receivables = [];

  }

}


/* =========================================================
   RECEIVABLE PAYMENT STORAGE
========================================================= */

function ensureReceivablePaymentStorage() {

  if (
    !Array.isArray(
      db.receivablePayments
    )
  ) {

    db.receivablePayments = [];

  }

}


/* =========================================================
   FIND RECEIVABLE
========================================================= */

function findReceivable(
  receivableId
) {

  ensureReceivableStorage();


  return (
    db.receivables.find(
      item =>
        item.id ===
        receivableId
    ) ||
    null
  );

}


/* =========================================================
   FIND RECEIVABLE BY SALE
========================================================= */

function findReceivableBySale(
  saleId
) {

  ensureReceivableStorage();


  return (
    db.receivables.find(
      item =>
        item.referenceId ===
        saleId
    ) ||
    null
  );

}


/* =========================================================
   GET RECEIVABLE REMAINING
========================================================= */

function getReceivableRemaining(
  receivable
) {

  if (!receivable) {
    return 0;
  }


  const amount =
    Number(
      receivable.amount ??
      receivable.originalAmount ??
      0
    ) || 0;


  const paid =
    Number(
      receivable.paid
    ) || 0;


  const explicitRemaining =
    Number(
      receivable.remaining
    );


  if (
    Number.isFinite(
      explicitRemaining
    )
  ) {

    return Math.max(
      0,
      explicitRemaining
    );

  }


  return Math.max(
    0,
    amount -
    paid
  );

}


/* =========================================================
   NORMALIZE RECEIVABLE
========================================================= */

function normalizeReceivable(
  receivable
) {

  if (!receivable) {
    return null;
  }


  receivable.amount =
    Number(
      receivable.amount ??
      receivable.originalAmount ??
      0
    ) || 0;


  receivable.originalAmount =
    Number(
      receivable.originalAmount ??
      receivable.amount
    ) || 0;


  receivable.paid =
    Number(
      receivable.paid
    ) || 0;


  receivable.remaining =
    Math.max(
      0,
      Number(
        receivable.amount
      ) -
      Number(
        receivable.paid
      )
    );


  if (
    receivable.remaining <=
    0
  ) {

    receivable.status =
      "PAID";

  }
  else {

    receivable.status =
      "OPEN";

  }


  receivable.updatedAt =
    new Date()
      .toISOString();


  return receivable;

}


/* =========================================================
   GET RECEIVABLE STATUS
========================================================= */

function getReceivableStatus(
  receivable
) {

  if (!receivable) {

    return "UNKNOWN";

  }


  normalizeReceivable(
    receivable
  );


  const remaining =
    getReceivableRemaining(
      receivable
    );


  /*
     LUNAS
  */

  if (
    remaining <=
    0
  ) {

    return "PAID";

  }


  /*
     JATUH TEMPO
  */

  if (
    receivable.dueDate
    &&
    receivable.dueDate <
      today()
  ) {

    return "OVERDUE";

  }


  /*
     SEBAGIAN
  */

  if (
    Number(
      receivable.paid
    ) > 0
  ) {

    return "PARTIAL";

  }


  return "OPEN";

}


/* =========================================================
   RECEIVABLE STATUS LABEL
========================================================= */

function getReceivableStatusLabel(
  status
) {

  switch (
    status
  ) {

    case "PAID":

      return "LUNAS";


    case "PARTIAL":

      return "SEBAGIAN";


    case "OVERDUE":

      return "JATUH TEMPO";


    case "OPEN":

      return "BELUM DIBAYAR";


    default:

      return status ||
        "-";

  }

}


/* =========================================================
   RECEIVABLE STATUS CLASS
========================================================= */

function getReceivableStatusClass(
  status
) {

  switch (
    status
  ) {

    case "PAID":

      return "badge-success";


    case "PARTIAL":

      return "badge-warning";


    case "OVERDUE":

      return "badge-danger";


    case "OPEN":

      return "badge-warning";


    default:

      return "";

  }

}


/* =========================================================
   GET CUSTOMER RECEIVABLES
========================================================= */

function getCustomerReceivables(
  filters = {}
) {

  ensureReceivableStorage();


  let receivables =
    db.receivables.filter(
      receivable => {

        const isReceivable =

          receivable.type ===
          "RECEIVABLE"

          ||

          receivable.receivableType ===
          "RECEIVABLE"

          ||

          receivable.category ===
          "CUSTOMER";


        if (
          !isReceivable
        ) {

          return false;

        }


        /*
           Filter customer.
        */

        if (
          filters.customerId
        ) {

          const customerId =
            receivable.customerId ||
            receivable.partyId ||
            "";


          if (
            customerId !==
            filters.customerId
          ) {

            return false;

          }

        }


        /*
           Filter status.
        */

        if (
          filters.status
        ) {

          const status =
            getReceivableStatus(
              receivable
            );


          if (
            status !==
            filters.status
          ) {

            return false;

          }

        }


        /*
           Search.
        */

        if (
          filters.search
        ) {

          const search =
            String(
              filters.search
            )
            .toLowerCase()
            .trim();


          const text =
            [

              receivable.customerName,

              receivable.referenceNumber,

              receivable.invoiceNumber,

              receivable.notes

            ]
            .join(" ")
            .toLowerCase();


          if (
            !text.includes(
              search
            )
          ) {

            return false;

          }

        }


        return true;

      }
    );


  /*
     Overdue ditampilkan dahulu.
  */

  return receivables
    .sort(
      (
        a,
        b
      ) => {

        const statusA =
          getReceivableStatus(
            a
          );


        const statusB =
          getReceivableStatus(
            b
          );


        if (
          statusA ===
            "OVERDUE"
          &&
          statusB !==
            "OVERDUE"
        ) {

          return -1;

        }


        if (
          statusA !==
            "OVERDUE"
          &&
          statusB ===
            "OVERDUE"
        ) {

          return 1;

        }


        return String(
          a.dueDate ||
          a.date ||
          ""
        )
        .localeCompare(
          String(
            b.dueDate ||
            b.date ||
            ""
          )
        );

      }
    );

}


/* =========================================================
   GENERATE RECEIVABLE PAYMENT NUMBER
========================================================= */

function generateReceivablePaymentNumber() {

  ensureReceivablePaymentStorage();


  const date =
    new Date();


  const year =
    date.getFullYear();


  const month =
    String(
      date.getMonth() + 1
    )
    .padStart(
      2,
      "0"
    );


  const prefix =
    `TER-${year}${month}-`;


  let max =
    0;


  db.receivablePayments.forEach(
    payment => {

      const number =
        String(
          payment.paymentNumber ||
          ""
        );


      if (
        !number.startsWith(
          prefix
        )
      ) {

        return;

      }


      const value =
        Number(
          number.replace(
            prefix,
            ""
          )
        );


      if (
        Number.isFinite(
          value
        )
      ) {

        max =
          Math.max(
            max,
            value
          );

      }

    }
  );


  return (
    prefix +
    String(
      max + 1
    )
    .padStart(
      4,
      "0"
    )
  );

}


/* =========================================================
   GET RECEIVABLE PAYMENTS
========================================================= */

function getReceivablePayments(
  receivableId
) {

  ensureReceivablePaymentStorage();


  return db.receivablePayments
    .filter(
      payment =>
        payment.receivableId ===
        receivableId
    )
    .sort(
      (
        a,
        b
      ) =>
        String(
          b.date ||
          ""
        )
        .localeCompare(
          String(
            a.date ||
            ""
          )
        )
    );

}


/* =========================================================
   CREATE RECEIVABLE
========================================================= */

function createCustomerReceivable(
  sale
) {

  ensureReceivableStorage();


  if (!sale) {

    throw new Error(
      "Data penjualan tidak tersedia."
    );

  }


  const outstanding =
    Math.max(
      0,
      Number(
        sale.total
      ) -
      Number(
        sale.paid
      )
    );


  if (
    outstanding <=
    0
  ) {

    return null;

  }


  /*
     Jangan duplikasi.
  */

  const existing =
    findReceivableBySale(
      sale.id
    );


  if (existing) {

    return existing;

  }


  const receivable = {

    id:
      generateId(
        "PIU"
      ),

    type:
      "RECEIVABLE",

    receivableType:
      "RECEIVABLE",

    category:
      "CUSTOMER",

    partyType:
      "CUSTOMER",

    customerId:
      sale.customerId ||
      "",

    customerName:
      sale.customerName ||
      "",

    referenceId:
      sale.id,

    referenceNumber:
      sale.invoiceNumber ||
      sale.saleNumber ||
      sale.id,

    invoiceNumber:
      sale.invoiceNumber ||
      sale.saleNumber ||
      sale.id,

    date:
      sale.date ||
      today(),

    dueDate:
      sale.dueDate ||
      "",

    originalAmount:
      Number(
        sale.total
      ) || 0,

    amount:
      outstanding,

    paid:
      0,

    remaining:
      outstanding,

    status:
      "OPEN",

    notes:
      sale.notes ||
      "",

    createdAt:
      new Date()
        .toISOString(),

    updatedAt:
      new Date()
        .toISOString()

  };


  db.receivables.push(
    receivable
  );


  return receivable;

}


/* =========================================================
   CREATE RECEIVABLE PAYMENT
========================================================= */

function createReceivablePayment(
  data
) {

  ensureReceivableStorage();

  ensureReceivablePaymentStorage();


  const receivable =
    findReceivable(
      data.receivableId
    );


  if (!receivable) {

    throw new Error(
      "Piutang customer tidak ditemukan."
    );

  }


  normalizeReceivable(
    receivable
  );


  const amount =
    Number(
      data.amount
    ) || 0;


  if (
    amount <=
    0
  ) {

    throw new Error(
      "Nominal pembayaran harus lebih dari 0."
    );

  }


  const remainingBefore =
    getReceivableRemaining(
      receivable
    );


  if (
    remainingBefore <=
    0
  ) {

    throw new Error(
      "Piutang ini sudah lunas."
    );

  }


  if (
    amount >
    remainingBefore
  ) {

    throw new Error(
      `Pembayaran melebihi sisa piutang. Sisa piutang: ${formatRupiah(
        remainingBefore
      )}.`
    );

  }


  const payment = {

    id:
      generateId(
        "TERIMA"
      ),

    paymentNumber:
      data.paymentNumber ||
      generateReceivablePaymentNumber(),

    receivableId:
      receivable.id,

    saleId:
      receivable.referenceId ||
      "",

    customerId:
      receivable.customerId ||
      receivable.partyId ||
      "",

    customerName:
      receivable.customerName ||
      "",

    date:
      data.date ||
      today(),

    amount:
      amount,

    paymentMethod:
      String(
        data.paymentMethod ||
        "CASH"
      )
      .toUpperCase(),

    referenceNumber:
      data.referenceNumber ||
      "",

    notes:
      data.notes ||
      "",

    createdAt:
      new Date()
        .toISOString()

  };


  /*
     Update piutang.
  */

  receivable.paid =
    Number(
      receivable.paid
    ) +
    amount;


  receivable.remaining =
    Math.max(
      0,
      Number(
        receivable.amount
      ) -
      Number(
        receivable.paid
      )
    );


  receivable.status =
    receivable.remaining <=
    0

      ? "PAID"

      : "OPEN";


  if (
    receivable.remaining >
      0
    &&
    receivable.paid >
      0
  ) {

    receivable.status =
      "PARTIAL";

  }


  receivable.updatedAt =
    new Date()
      .toISOString();


  db.receivablePayments.push(
    payment
  );


  /*
     Update transaksi penjualan.
  */

  if (
    receivable.referenceId
  ) {

    const sale =
      findSale(
        receivable.referenceId
      );


    if (sale) {

      if (
        typeof normalizeSale ===
        "function"
      ) {

        normalizeSale(
          sale
        );

      }


      sale.paid =
        Number(
          sale.paid
        ) +
        amount;


      sale.remaining =
        Math.max(
          0,
          Number(
            sale.total
          ) -
          Number(
            sale.paid
          )
        );


      if (
        sale.remaining <=
        0
      ) {

        sale.paymentStatus =
          "PAID";

      }
      else {

        sale.paymentStatus =
          "PARTIAL";

      }


      sale.updatedAt =
        new Date()
          .toISOString();

    }

  }


  saveDatabase();


  /*
     Refresh tampilan.
  */

  if (
    typeof renderCustomerReceivableSummary ===
    "function"
  ) {

    renderCustomerReceivableSummary();

  }


  if (
    typeof renderCustomerReceivables ===
    "function"
  ) {

    renderCustomerReceivables();

  }


  if (
    typeof renderSales ===
    "function"
  ) {

    renderSales();

  }


  return payment;

}


/* =========================================================
   RENDER CUSTOMER RECEIVABLES
========================================================= */

function renderCustomerReceivables(
  filters = {}
) {

  const tbody =
    document.getElementById(
      "customerReceivableTableBody"
    );


  if (!tbody) {

    return;

  }


  const receivables =
    getCustomerReceivables(
      filters
    );


  if (!receivables.length) {

    tbody.innerHTML = `

      <tr>

        <td
          colspan="10"
          class="empty-state"
        >

          <div>
            💰
          </div>

          <strong>
            Tidak ada piutang customer
          </strong>

          <small>
            Piutang dari penjualan kredit akan tampil di sini.
          </small>

        </td>

      </tr>

    `;

    return;

  }


  tbody.innerHTML =
    receivables
      .map(
        (
          receivable,
          index
        ) => {

          normalizeReceivable(
            receivable
          );


          const status =
            getReceivableStatus(
              receivable
            );


          return `

            <tr>

              <td>
                ${index + 1}
              </td>

              <td>

                ${escapeHTML(
                  receivable.date ||
                  "-"
                )}

              </td>

              <td>

                <strong>

                  ${escapeHTML(
                    receivable.customerName ||
                    "-"
                  )}

                </strong>

              </td>

              <td>

                ${escapeHTML(
                  receivable.referenceNumber ||
                  receivable.invoiceNumber ||
                  "-"
                )}

              </td>

              <td>

                ${escapeHTML(
                  receivable.dueDate ||
                  "-"
                )}

              </td>

              <td>

                ${formatRupiah(
                  receivable.amount
                )}

              </td>

              <td>

                ${formatRupiah(
                  receivable.paid
                )}

              </td>

              <td>

                <strong>

                  ${formatRupiah(
                    receivable.remaining
                  )}

                </strong>

              </td>

              <td>

                <span
                  class="badge ${
                    getReceivableStatusClass(
                      status
                    )
                  }"
                >

                  ${getReceivableStatusLabel(
                    status
                  )}

                </span>

              </td>

              <td>

                <div
                  class="action-group"
                >

                  <button
                    type="button"
                    class="action-btn"
                    onclick="
                      viewCustomerReceivable(
                        '${receivable.id}'
                      )
                    "
                    title="Detail"
                  >

                    👁️

                  </button>


                  ${
                    receivable.remaining > 0

                      ? `

                        <button
                          type="button"
                          class="action-btn"
                          onclick="
                            openReceivablePayment(
                              '${receivable.id}'
                            )
                          "
                          title="Terima Pembayaran"
                        >

                          💳

                        </button>

                      `

                      : ""

                  }

                </div>

              </td>

            </tr>

          `;

        }
      )
      .join("");

}


