/* =========================================================
   FAEZA ERP V2
   BAGIAN 6H-2
   SUBMIT RECEIVABLE PAYMENT
   - Validasi pembayaran
   - Ambil data form
   - Simpan pembayaran
   - Refresh piutang
========================================================= */


/* =========================================================
   SUBMIT RECEIVABLE PAYMENT
========================================================= */

function submitReceivablePayment(
  receivableId
) {

  /* -------------------------------------------------------
     Ambil nominal pembayaran
  ------------------------------------------------------- */

  const amount =
    Number(
      document.getElementById(
        "receivablePaymentAmount"
      )?.value
    ) || 0;


  /* -------------------------------------------------------
     Ambil tanggal
  ------------------------------------------------------- */

  const date =
    document.getElementById(
      "receivablePaymentDate"
    )?.value ||
    today();


  /* -------------------------------------------------------
     Ambil metode pembayaran
  ------------------------------------------------------- */

  const paymentMethod =
    document.getElementById(
      "receivablePaymentMethod"
    )?.value ||
    "CASH";


  /* -------------------------------------------------------
     Ambil nomor referensi
  ------------------------------------------------------- */

  const referenceNumber =
    document.getElementById(
      "receivablePaymentReference"
    )?.value
    ?.trim() ||
    "";


  /* -------------------------------------------------------
     Ambil catatan
  ------------------------------------------------------- */

  const notes =
    document.getElementById(
      "receivablePaymentNotes"
    )?.value
    ?.trim() ||
    "";


  /* -------------------------------------------------------
     Validasi nominal
  ------------------------------------------------------- */

  if (
    amount <=
    0
  ) {

    showToast(
      "Nominal pembayaran harus lebih dari 0.",
      "error"
    );

    return;

  }


  /* -------------------------------------------------------
     Cari piutang
  ------------------------------------------------------- */

  const receivable =
    findReceivable(
      receivableId
    );


  if (!receivable) {

    showToast(
      "Data piutang tidak ditemukan.",
      "error"
    );

    return;

  }


  /* -------------------------------------------------------
     Normalisasi
  ------------------------------------------------------- */

  normalizeReceivable(
    receivable
  );


  /* -------------------------------------------------------
     Validasi sisa piutang
  ------------------------------------------------------- */

  if (
    receivable.remaining <=
    0
  ) {

    showToast(
      "Piutang ini sudah lunas.",
      "info"
    );

    return;

  }


  /* -------------------------------------------------------
     Tidak boleh melebihi sisa piutang
  ------------------------------------------------------- */

  if (
    amount >
    receivable.remaining
  ) {

    showToast(
      `Nominal pembayaran melebihi sisa piutang. Sisa piutang ${formatRupiah(
        receivable.remaining
      )}.`,
      "error"
    );

    return;

  }


  /* -------------------------------------------------------
     Konfirmasi pembayaran
  ------------------------------------------------------- */

  const confirmed =
    window.confirm(
      `Terima pembayaran ${formatRupiah(
        amount
      )} dari ${
        receivable.customerName ||
        "customer"
      }?`
    );


  if (!confirmed) {

    return;

  }


  /* -------------------------------------------------------
     Proses pembayaran
  ------------------------------------------------------- */

  try {

    const payment =
      createReceivablePayment({

        receivableId:

          receivableId,

        amount:

          amount,

        date:

          date,

        paymentMethod:

          paymentMethod,

        referenceNumber:

          referenceNumber,

        notes:

          notes

      });


    /* -----------------------------------------------------
       Tutup modal
    ----------------------------------------------------- */

    closeModal();


    /* -----------------------------------------------------
       Notifikasi berhasil
    ----------------------------------------------------- */

    showToast(
      `Pembayaran ${payment.paymentNumber} berhasil disimpan.`,
      "success"
    );


    /* -----------------------------------------------------
       Refresh daftar piutang
    ----------------------------------------------------- */

    if (
      typeof renderCustomerReceivables ===
      "function"
    ) {

      renderCustomerReceivables();

    }


    /* -----------------------------------------------------
       Refresh ringkasan piutang
    ----------------------------------------------------- */

    if (
      typeof renderCustomerReceivableSummary ===
      "function"
    ) {

      renderCustomerReceivableSummary();

    }


    /* -----------------------------------------------------
       Refresh daftar penjualan
    ----------------------------------------------------- */

    if (
      typeof renderSales ===
      "function"
    ) {

      renderSales();

    }


    /* -----------------------------------------------------
       Refresh dashboard
    ----------------------------------------------------- */

    if (
      typeof renderDashboard ===
      "function"
    ) {

      renderDashboard();

    }


  }
  catch (
    error
  ) {

    console.error(
      "SUBMIT RECEIVABLE PAYMENT ERROR:",
      error
    );


    showToast(
      error.message ||
      "Pembayaran piutang gagal disimpan.",
      "error"
    );

  }

}


