/* =========================================================
   GET TOP CUSTOMER RECEIVABLE
========================================================= */

function getTopCustomerReceivables(
  limit = 10
) {

  return getCustomerReceivableBalanceSummary()
    .filter(
      customer =>
        customer.remaining > 0
    )
    .slice(
      0,
      Number(
        limit
      ) || 10
    );

}


