/* =========================================================
   FAEZA ERP V2
   BAGIAN 6I-7
   CUSTOMER RECEIVABLE STATEMENT
   - Kartu piutang customer
   - Invoice
   - Pembayaran
   - Saldo berjalan
   - Filter periode
========================================================= */


/* =========================================================
   GET CUSTOMER RECEIVABLE STATEMENT
========================================================= */

function getCustomerReceivableStatement(
  customerId,
  options = {}
) {

  ensureReceivableStorage();
  ensureReceivablePaymentStorage();


  if (!customerId) {

    return [];

  }


  const startDate =
    options.startDate ||
    "";


  const endDate =
    options.endDate ||
    "";


  const movements = [];


  /* =======================================================
     1. TRANSAKSI PIUTANG / INVOICE
  ======================================================= */

  db.receivables.forEach(
    receivable => {

      const isReceivable =

        receivable.type ===
        "RECEIVABLE"

        ||

        receivable.receivableType ===
        "RECEIVABLE"

        ||

        receivable.category ===
        "CUSTOMER";


      if (
        !isReceivable
      ) {

        return;

      }


      const id =
        receivable.customerId ||
        receivable.partyId ||
        "";


      if (
        id !== customerId
      ) {

        return;

      }


      normalizeReceivable(
        receivable
      );


      const date =
        receivable.date ||
        receivable.createdAt?.slice(
          0,
          10
        ) ||
        today();


      /*
         Filter tanggal.
      */

      if (
        startDate &&
        date <
        startDate
      ) {

        return;

      }


      if (
        endDate &&
        date >
        endDate
      ) {

        return;

      }


      movements.push({

        id:
          `INV-${receivable.id}`,

        date,

        type:
          "INVOICE",

        reference:
          receivable.referenceNumber ||
          receivable.invoiceNumber ||
          "-",

        description:
          "Penjualan Kredit",

        debit:
          Number(
            receivable.amount
          ) || 0,

        credit:
          0,

        receivableId:
          receivable.id,

        createdAt:
          receivable.createdAt ||
          date

      });

    }
  );


  /* =======================================================
     2. PEMBAYARAN CUSTOMER
  ======================================================= */

  db.receivablePayments.forEach(
    payment => {

      const id =
        payment.customerId ||
        "";


      if (
        id !== customerId
      ) {

        return;

      }


      const date =
        payment.date ||
        payment.createdAt?.slice(
          0,
          10
        ) ||
        today();


      /*
         Filter tanggal.
      */

      if (
        startDate &&
        date <
        startDate
      ) {

        return;

      }


      if (
        endDate &&
        date >
        endDate
      ) {

        return;

      }


      movements.push({

        id:
          `PAY-${payment.id}`,

        date,

        type:
          "PAYMENT",

        reference:
          payment.paymentNumber ||
          "-",

        description:
          "Pembayaran Customer",

        debit:
          0,

        credit:
          Number(
            payment.amount
          ) || 0,

        receivableId:
          payment.receivableId ||
          "",

        createdAt:
          payment.createdAt ||
          date

      });

    }
  );


  /* =======================================================
     SORT MUTASI
  ======================================================= */

  movements.sort(
    (
      a,
      b
    ) => {

      const dateCompare =
        String(
          a.date
        )
        .localeCompare(
          String(
            b.date
          )
        );


      if (
        dateCompare !==
        0
      ) {

        return dateCompare;

      }


      return String(
        a.createdAt ||
        ""
      )
      .localeCompare(
        String(
          b.createdAt ||
          ""
        )
      );

    }
  );


  /* =======================================================
     SALDO BERJALAN
  ======================================================= */

  let runningBalance =
    0;


  return movements.map(
    movement => {

      runningBalance +=
        Number(
          movement.debit
        ) || 0;


      runningBalance -=
        Number(
          movement.credit
        ) || 0;


      return {

        ...movement,

        balance:
          Math.max(
            0,
            runningBalance
          )

      };

    }
  );

}


/* =========================================================
   RENDER CUSTOMER RECEIVABLE STATEMENT
========================================================= */

function renderCustomerReceivableStatement(
  customerId,
  options = {}
) {

  const tbody =
    document.getElementById(
      "customerReceivableStatementBody"
    );


  if (!tbody) {

    return;

  }


  const movements =
    getCustomerReceivableStatement(
      customerId,
      options
    );


  if (
    !movements.length
  ) {

    tbody.innerHTML = `

      <tr>

        <td
          colspan="7"
          class="empty-state"
        >

          <div>
            📒
          </div>

          <strong>
            Belum ada mutasi piutang
          </strong>

          <small>
            Invoice dan pembayaran customer akan tampil di sini.
          </small>

        </td>

      </tr>

    `;

    return;

  }


  tbody.innerHTML =
    movements
      .map(
        (
          movement,
          index
        ) => {

          const isInvoice =
            movement.type ===
            "INVOICE";


          return `

            <tr>

              <td>

                ${index + 1}

              </td>


              <td>

                ${escapeHTML(
                  movement.date
                )}

              </td>


              <td>

                <span
                  class="badge ${
                    isInvoice
                      ? "badge-warning"
                      : "badge-success"
                  }"
                >

                  ${
                    isInvoice
                      ? "INVOICE"
                      : "PEMBAYARAN"
                  }

                </span>

              </td>


              <td>

                ${escapeHTML(
                  movement.reference
                )}

              </td>


              <td>

                ${escapeHTML(
                  movement.description
                )}

              </td>


              <td>

                ${
                  movement.debit > 0

                    ? `

                      <strong>

                        ${formatRupiah(
                          movement.debit
                        )}

                      </strong>

                    `

                    : "-"

                }

              </td>


              <td>

                ${
                  movement.credit > 0

                    ? `

                      <strong>

                        ${formatRupiah(
                          movement.credit
                        )}

                      </strong>

                    `

                    : "-"

                }

              </td>


              <td>

                <strong>

                  ${formatRupiah(
                    movement.balance
                  )}

                </strong>

              </td>


            </tr>

          `;

        }
      )
      .join("");

}


