/* =========================================================
   FILTER CUSTOMER RECEIVABLE STATEMENT
========================================================= */

function filterCustomerReceivableStatement() {

  const customerId =
    document.getElementById(
      "statementCustomerFilter"
    )?.value || "";


  const startDate =
    document.getElementById(
      "statementStartDate"
    )?.value || "";


  const endDate =
    document.getElementById(
      "statementEndDate"
    )?.value || "";


  if (!customerId) {

    showToast(
      "Pilih customer terlebih dahulu.",
      "warning"
    );

    return;

  }


  if (
    startDate &&
    endDate &&
    startDate > endDate
  ) {

    showToast(
      "Tanggal mulai tidak boleh melebihi tanggal akhir.",
      "error"
    );

    return;

  }


  renderCustomerReceivableStatement(
    customerId,
    {
      startDate,
      endDate
    }
  );


  updateCustomerReceivableStatementSummary(
    customerId,
    {
      startDate,
      endDate
    }
  );

}


/* =========================================================
   UPDATE STATEMENT SUMMARY
========================================================= */

function updateCustomerReceivableStatementSummary(
  customerId,
  options = {}
) {

  const movements =
    getCustomerReceivableStatement(
      customerId,
      options
    );


  let totalDebit =
    0;


  let totalCredit =
    0;


  movements.forEach(
    movement => {

      totalDebit +=
        Number(
          movement.debit
        ) || 0;


      totalCredit +=
        Number(
          movement.credit
        ) || 0;

    }
  );


  const balance =
    movements.length
      ? movements[
          movements.length - 1
        ].balance
      : 0;


  const debitEl =
    document.getElementById(
      "statementTotalDebit"
    );


  if (
    debitEl
  ) {

    debitEl.textContent =
      formatRupiah(
        totalDebit
      );

  }


  const creditEl =
    document.getElementById(
      "statementTotalCredit"
    );


  if (
    creditEl
  ) {

    creditEl.textContent =
      formatRupiah(
        totalCredit
      );

  }


  const balanceEl =
    document.getElementById(
      "statementEndingBalance"
    );


  if (
    balanceEl
  ) {

    balanceEl.textContent =
      formatRupiah(
        balance
      );

  }

}


