/* =========================================================
   GET CUSTOMER NAME
========================================================= */

function getCustomerNameById(
  customerId
) {

  const customers =
    Array.isArray(
      db.customers
    )
      ? db.customers
      : [];


  const customer =
    customers.find(
      item =>
        item.id ===
        customerId
    );


  return (
    customer?.name ||
    customer?.customerName ||
    "Customer"
  );

}


/* =========================================================
   FORMAT PRINT DATE
========================================================= */

function formatPrintDate(
  date
) {

  if (!date) {

    return "-";

  }


  const parts =
    String(
      date
    ).split("-");


  if (
    parts.length !==
    3
  ) {

    return date;

  }


  return (
    parts[2] +
    "/" +
    parts[1] +
    "/" +
    parts[0]
  );

}


