/* =========================================================
   FAEZA ERP V2
   BAGIAN 6I-11
   VALIDASI PEMBAYARAN PIUTANG CUSTOMER

   Proteksi:
   - Nominal pembayaran > 0
   - Tidak boleh melebihi sisa piutang
   - Receivable harus ada
   - Customer harus sesuai
   - Receivable yang lunas tidak bisa dibayar lagi
========================================================= */


/* =========================================================
   GET RECEIVABLE BY ID
========================================================= */

function getCustomerReceivableById(
  receivableId
) {

  ensureReceivableStorage();


  return db.receivables.find(
    receivable =>
      String(
        receivable.id
      ) ===
      String(
        receivableId
      )
  ) || null;

}


/* =========================================================
   GET RECEIVABLE PAYMENT TOTAL
========================================================= */

function getReceivablePaymentTotal(
  receivableId
) {

  ensureReceivablePaymentStorage();


  return db.receivablePayments
    .filter(
      payment =>
        String(
          payment.receivableId
        ) ===
        String(
          receivableId
        )
    )
    .reduce(
      (
        total,
        payment
      ) => {

        return (
          total +
          (
            Number(
              payment.amount
            ) || 0
          )
        );

      },
      0
    );

}


/* =========================================================
   GET RECEIVABLE REMAINING REAL-TIME
========================================================= */

function getCustomerReceivableRemaining(
  receivableId
) {

  const receivable =
    getCustomerReceivableById(
      receivableId
    );


  if (!receivable) {

    return 0;

  }


  const amount =
    Number(
      receivable.amount
    ) || 0;


  const paidFromPayments =
    getReceivablePaymentTotal(
      receivableId
    );


  /*
     Gunakan nilai terbesar
     dari data pembayaran aktual
     dan field paid jika tersedia.
  */

  const storedPaid =
    Number(
      receivable.paid
    ) || 0;


  const paid =
    Math.max(
      storedPaid,
      paidFromPayments
    );


  return Math.max(
    0,
    amount - paid
  );

}


/* =========================================================
   VALIDATE CUSTOMER RECEIVABLE PAYMENT
========================================================= */

function validateCustomerReceivablePayment(
  data
) {

  const errors = [];


  if (!data) {

    errors.push(
      "Data pembayaran tidak ditemukan."
    );


    return {

      valid: false,

      errors

    };

  }


  const receivableId =
    data.receivableId ||
    "";


  if (!receivableId) {

    errors.push(
      "Piutang belum dipilih."
    );

  }


  const receivable =
    getCustomerReceivableById(
      receivableId
    );


  if (
    receivableId &&
    !receivable
  ) {

    errors.push(
      "Data piutang tidak ditemukan."
    );

  }


  const amount =
    Number(
      data.amount
    );


  if (
    !Number.isFinite(
      amount
    ) ||
    amount <= 0
  ) {

    errors.push(
      "Nominal pembayaran harus lebih besar dari Rp0."
    );

  }


  if (receivable) {

    const receivableCustomerId =
      receivable.customerId ||
      receivable.partyId ||
      "";


    const paymentCustomerId =
      data.customerId ||
      "";


    /*
       Customer pembayaran harus
       sama dengan customer piutang.
    */

    if (
      paymentCustomerId &&
      receivableCustomerId &&
      String(
        paymentCustomerId
      ) !==
      String(
        receivableCustomerId
      )
    ) {

      errors.push(
        "Customer pembayaran tidak sesuai dengan piutang."
      );

    }


    const remaining =
      getCustomerReceivableRemaining(
        receivableId
      );


    if (
      amount >
      remaining
    ) {

      errors.push(

        `Pembayaran ${formatRupiah(
          amount
        )} melebihi sisa piutang ${formatRupiah(
          remaining
        )}.`

      );

    }


    if (
      remaining <= 0
    ) {

      errors.push(
        "Piutang ini sudah lunas."
      );

    }

  }


  return {

    valid:
      errors.length === 0,

    errors,

    receivable:
      receivable || null

  };

}


/* =========================================================
   SHOW PAYMENT VALIDATION ERROR
========================================================= */

function showReceivablePaymentValidationErrors(
  errors
) {

  if (
    !Array.isArray(
      errors
    ) ||
    !errors.length
  ) {

    return;

  }


  const message =
    errors
      .map(
        error =>
          `• ${error}`
      )
      .join(
        "\n"
      );


  showToast(
    message,
    "error"
  );

}


/* =========================================================
   CHECK PAYMENT BEFORE SAVE
========================================================= */

function canSaveCustomerReceivablePayment(
  data
) {

  const result =
    validateCustomerReceivablePayment(
      data
    );


  if (
    !result.valid
  ) {

    showReceivablePaymentValidationErrors(
      result.errors
    );


    return false;

  }


  return true;

}


/* =========================================================
   GET PAYMENT LIMIT
========================================================= */

function getCustomerReceivablePaymentLimit(
  receivableId
) {

  return getCustomerReceivableRemaining(
    receivableId
  );

}


/* =========================================================
   UPDATE PAYMENT INPUT LIMIT
========================================================= */

function updateCustomerReceivablePaymentLimit() {

  const receivableSelect =
    document.getElementById(
      "receivablePaymentReceivable"
    );


  const amountInput =
    document.getElementById(
      "receivablePaymentAmount"
    );


  if (
    !receivableSelect ||
    !amountInput
  ) {

    return;

  }


  const receivableId =
    receivableSelect.value;


  if (!receivableId) {

    amountInput.removeAttribute(
      "max"
    );


    amountInput.placeholder =
      "Nominal pembayaran";


    return;

  }


  const remaining =
    getCustomerReceivablePaymentLimit(
      receivableId
    );


  amountInput.max =
    String(
      remaining
    );


  amountInput.placeholder =
    `Maksimal ${formatRupiah(
      remaining
    )}`;


  /*
     Jika nilai lama lebih besar
     dari sisa, otomatis dikosongkan.
  */

  const current =
    Number(
      amountInput.value
    ) || 0;


  if (
    current >
    remaining
  ) {

    amountInput.value =
      remaining > 0
        ? remaining
        : "";

  }

}


/* =========================================================
   LIVE PAYMENT VALIDATION
========================================================= */

function validateCustomerReceivablePaymentInput() {

  const receivableId =
    document.getElementById(
      "receivablePaymentReceivable"
    )?.value || "";


  const customerId =
    document.getElementById(
      "receivablePaymentCustomer"
    )?.value || "";


  const amount =
    Number(
      document.getElementById(
        "receivablePaymentAmount"
      )?.value
    ) || 0;


  if (!receivableId) {

    return {

      valid: false,

      message:
        "Pilih piutang terlebih dahulu."

    };

  }


  const remaining =
    getCustomerReceivableRemaining(
      receivableId
    );


  if (
    amount <= 0
  ) {

    return {

      valid: false,

      message:
        "Nominal pembayaran harus lebih besar dari Rp0."

    };

  }


  if (
    amount >
    remaining
  ) {

    return {

      valid: false,

      message:
        `Maksimal pembayaran ${formatRupiah(
          remaining
        )}.`

    };

  }


  const receivable =
    getCustomerReceivableById(
      receivableId
    );


  if (
    receivable
  ) {

    const receivableCustomerId =
      receivable.customerId ||
      receivable.partyId ||
      "";


    if (
      customerId &&
      receivableCustomerId &&
      String(
        customerId
      ) !==
      String(
        receivableCustomerId
      )
    ) {

      return {

        valid: false,

        message:
          "Customer tidak sesuai dengan piutang."

      };

    }

  }


  return {

    valid: true,

    message: "Pembayaran valid."

  };

}


/* =========================================================
   BLOCK INVALID PAYMENT SUBMISSION
========================================================= */

function guardCustomerReceivablePaymentSubmit(
  data
) {

  const result =
    validateCustomerReceivablePayment(
      data
    );


  if (
    !result.valid
  ) {

    showReceivablePaymentValidationErrors(
      result.errors
    );


    return {

      allowed: false,

      result

    };

  }


  return {

    allowed: true,

    result

  };

}


