/* =========================================================
   FAEZA ERP V2
   BAGIAN 6I-12
   POSTING CUSTOMER RECEIVABLE PAYMENT

   Alur:
   Validasi
      ↓
   Simpan pembayaran
      ↓
   Update paid
      ↓
   Update remaining
      ↓
   Update status
      ↓
   Save database
      ↓
   Refresh dashboard
========================================================= */


/* =========================================================
   GENERATE RECEIVABLE PAYMENT NUMBER
========================================================= */

function generateReceivablePaymentNumber() {

  ensureReceivablePaymentStorage();


  const todayDate =
    today()
    .replace(
      /-/g,
      ""
    );


  const prefix =
    `RCP-${todayDate}-`;


  const numbers =
    db.receivablePayments
      .map(
        payment => {

          const number =
            String(
              payment.paymentNumber ||
              ""
            );


          if (
            !number.startsWith(
              prefix
            )
          ) {

            return 0;

          }


          const match =
            number.match(
              /-(\d+)$/
            );


          return match
            ? Number(
                match[1]
              )
            : 0;

        }
      );


  const next =
    Math.max(
      0,
      ...numbers
    ) + 1;


  return (

    prefix +

    String(
      next
    )
    .padStart(
      4,
      "0"
    )

  );

}


/* =========================================================
   UPDATE RECEIVABLE AFTER PAYMENT
========================================================= */

function updateCustomerReceivableAfterPayment(
  receivableId
) {

  const receivable =
    getCustomerReceivableById(
      receivableId
    );


  if (!receivable) {

    return null;

  }


  const totalPaid =
    getReceivablePaymentTotal(
      receivableId
    );


  const originalAmount =
    Number(
      receivable.amount
    ) || 0;


  const paid =
    Math.min(
      originalAmount,
      totalPaid
    );


  const remaining =
    Math.max(
      0,
      originalAmount -
      paid
    );


  /*
     Update field utama.
  */

  receivable.paid =
    paid;


  receivable.remaining =
    remaining;


  /*
     Status otomatis.
  */

  if (
    remaining <= 0
  ) {

    receivable.status =
      "PAID";

  }

  else if (
    paid > 0
  ) {

    /*
       Cek jatuh tempo.
    */

    const dueDate =
      receivable.dueDate ||
      "";


    if (
      dueDate &&
      dueDate <
      today()
    ) {

      receivable.status =
        "OVERDUE";

    }
    else {

      receivable.status =
        "PARTIAL";

    }

  }

  else {

    const dueDate =
      receivable.dueDate ||
      "";


    if (
      dueDate &&
      dueDate <
      today()
    ) {

      receivable.status =
        "OVERDUE";

    }
    else {

      receivable.status =
        "OPEN";

    }

  }


  /*
     Timestamp.
  */

  receivable.updatedAt =
    new Date().toISOString();


  return receivable;

}


/* =========================================================
   POST CUSTOMER RECEIVABLE PAYMENT
========================================================= */

function postCustomerReceivablePayment(
  data
) {

  /*
     Pastikan storage.
  */

  ensureReceivableStorage();

  ensureReceivablePaymentStorage();


  /*
     -------------------------------------------------------
     VALIDASI
     -------------------------------------------------------
  */

  const validation =
    validateCustomerReceivablePayment(
      data
    );


  if (
    !validation.valid
  ) {

    showReceivablePaymentValidationErrors(
      validation.errors
    );


    return {

      success: false,

      errors:
        validation.errors

    };

  }


  const receivable =
    validation.receivable;


  const amount =
    Number(
      data.amount
    );


  /*
     -------------------------------------------------------
     CEK ULANG SISA PIUTANG
     Tepat sebelum posting.
     -------------------------------------------------------
  */

  const remainingBefore =
    getCustomerReceivableRemaining(
      receivable.id
    );


  if (
    amount >
    remainingBefore
  ) {

    const error =

      `Pembayaran melebihi sisa piutang. ` +

      `Sisa saat ini ${formatRupiah(
        remainingBefore
      )}.`;


    showToast(
      error,
      "error"
    );


    return {

      success: false,

      errors: [
        error
      ]

    };

  }


  /*
     -------------------------------------------------------
     PAYMENT NUMBER
     -------------------------------------------------------
  */

  const paymentNumber =
    data.paymentNumber ||
    generateReceivablePaymentNumber();


  /*
     -------------------------------------------------------
     CREATE PAYMENT
     -------------------------------------------------------
  */

  const payment = {

    id:
      generateId(
        "RCP"
      ),

    paymentNumber,

    receivableId:
      receivable.id,

    customerId:
      receivable.customerId ||
      data.customerId ||
      "",

    customerName:
      receivable.customerName ||
      data.customerName ||
      "",

    date:
      data.date ||
      today(),

    amount,

    method:
      data.method ||
      data.paymentMethod ||
      "CASH",

    reference:
      data.reference ||
      "",

    notes:
      data.notes ||
      "",

    createdAt:
      new Date().toISOString(),

    updatedAt:
      new Date().toISOString()

  };


  /*
     -------------------------------------------------------
     SIMPAN PAYMENT
     -------------------------------------------------------
  */

  db.receivablePayments.push(
    payment
  );


  /*
     -------------------------------------------------------
     UPDATE PIUTANG
     -------------------------------------------------------
  */

  const updatedReceivable =
    updateCustomerReceivableAfterPayment(
      receivable.id
    );


  /*
     -------------------------------------------------------
     AUDIT
     -------------------------------------------------------
  */

  addAuditLog({

    action:
      "CUSTOMER_RECEIVABLE_PAYMENT",

    reference:
      paymentNumber,

    module:
      "RECEIVABLE",

    description:
      `Pembayaran piutang customer ${payment.customerName}`,

    amount:

      payment.amount

  });


  /*
     -------------------------------------------------------
     SAVE DATABASE
     -------------------------------------------------------
  */

  saveDB();


  /*
     -------------------------------------------------------
     REFRESH
     -------------------------------------------------------
  */

  refreshReceivableAfterTransaction();


  refreshCustomerReceivableDashboardSafe();


  /*
     -------------------------------------------------------
     HASIL
     -------------------------------------------------------
  */

  showToast(

    `Pembayaran ${paymentNumber} berhasil disimpan.`,

    "success"

  );


  return {

    success: true,

    payment,

    receivable:
      updatedReceivable

  };

}


/* =========================================================
   HANDLE RECEIVABLE PAYMENT FORM
========================================================= */

function handleCustomerReceivablePaymentSubmit(
  event
) {

  if (
    event
  ) {

    event.preventDefault();

  }


  const receivableId =
    document.getElementById(
      "receivablePaymentReceivable"
    )?.value || "";


  const customerId =
    document.getElementById(
      "receivablePaymentCustomer"
    )?.value || "";


  const date =
    document.getElementById(
      "receivablePaymentDate"
    )?.value ||
    today();


  const amount =
    Number(
      document.getElementById(
        "receivablePaymentAmount"
      )?.value
    ) || 0;


  const method =
    document.getElementById(
      "receivablePaymentMethod"
    )?.value ||
    "CASH";


  const reference =
    document.getElementById(
      "receivablePaymentReference"
    )?.value ||
    "";


  const notes =
    document.getElementById(
      "receivablePaymentNotes"
    )?.value ||
    "";


  const result =
    postCustomerReceivablePayment({

      receivableId,

      customerId,

      date,

      amount,

      method,

      reference,

      notes

    });


  if (
    result.success
  ) {

    closeModal();


    /*
       Reset form jika masih ada.
    */

    resetCustomerReceivablePaymentForm();

  }


  return result;

}


/* =========================================================
   RESET PAYMENT FORM
========================================================= */

function resetCustomerReceivablePaymentForm() {

  const form =
    document.getElementById(
      "customerReceivablePaymentForm"
    );


  if (
    form
  ) {

    form.reset();

  }


  const dateInput =
    document.getElementById(
      "receivablePaymentDate"
    );


  if (
    dateInput
  ) {

    dateInput.value =
      today();

  }


  const amountInput =
    document.getElementById(
      "receivablePaymentAmount"
    );


  if (
    amountInput
  ) {

    amountInput.removeAttribute(
      "max"
    );

    amountInput.value =
      "";

  }

}


/* =========================================================
   PAYMENT RECEIVABLE SELECT CHANGE
========================================================= */

function handleReceivablePaymentReceivableChange() {

  const receivableSelect =
    document.getElementById(
      "receivablePaymentReceivable"
    );


  const customerSelect =
    document.getElementById(
      "receivablePaymentCustomer"
    );


  if (!receivableSelect) {

    return;

  }


  const receivableId =
    receivableSelect.value;


  if (!receivableId) {

    updateCustomerReceivablePaymentLimit();

    return;

  }


  const receivable =
    getCustomerReceivableById(
      receivableId
    );


  if (
    !receivable
  ) {

    return;

  }


  /*
     Otomatis pilih customer.
  */

  if (
    customerSelect
  ) {

    customerSelect.value =
      receivable.customerId ||
      receivable.partyId ||
      "";

  }


  updateCustomerReceivablePaymentLimit();

}


