/* =========================================================
   END BAGIAN 6I-14
========================================================= */
/* =========================================================
   FAEZA ERP V2
   BAGIAN 6I-15
   CUSTOMER RECEIVABLE RECONCILIATION

   Rumus:
   Total Piutang
   - Pembayaran Aktif
   = Saldo Seharusnya

   Sistem membandingkan:
   calculatedRemaining
   dengan
   stored remaining

   Status:
   MATCH
   WARNING
   ERROR
========================================================= */


/* =========================================================
   RECONCILE ONE CUSTOMER RECEIVABLE
========================================================= */

function reconcileCustomerReceivable(
  receivableId
) {

  const receivable =
    getCustomerReceivableById(
      receivableId
    );


  if (!receivable) {

    return {

      status:
        "ERROR",

      message:
        "Piutang tidak ditemukan.",

      receivableId

    };

  }


  /*
     -------------------------------------------------------
     NILAI PIUTANG
     -------------------------------------------------------
  */

  const invoiceAmount =
    Number(
      receivable.amount
    ) || 0;


  /*
     -------------------------------------------------------
     PEMBAYARAN AKTIF
     -------------------------------------------------------
  */

  const activePayment =
    getActiveReceivablePaymentTotal(
      receivableId
    );


  /*
     -------------------------------------------------------
     SALDO HASIL PERHITUNGAN
     -------------------------------------------------------
  */

  const calculatedPaid =
    Math.min(
      invoiceAmount,
      activePayment
    );


  const calculatedRemaining =
    Math.max(
      0,
      invoiceAmount -
      calculatedPaid
    );


  /*
     -------------------------------------------------------
     SALDO YANG TERSIMPAN
     -------------------------------------------------------
  */

  const storedPaid =
    Number(
      receivable.paid
    ) || 0;


  const storedRemaining =
    Number(
      receivable.remaining
    );


  /*
     Jika field remaining belum ada,
     dianggap belum terisi.
  */

  const hasStoredRemaining =
    Number.isFinite(
      storedRemaining
    );


  /*
     -------------------------------------------------------
     SELISIH
     -------------------------------------------------------
  */

  const paidDifference =
    Math.abs(
      calculatedPaid -
      storedPaid
    );


  const remainingDifference =
    hasStoredRemaining

      ? Math.abs(
          calculatedRemaining -
          storedRemaining
        )

      : calculatedRemaining;


  /*
     Toleransi Rp0,01
     untuk menghindari error pembulatan.
  */

  const tolerance =
    0.01;


  let status =
    "MATCH";


  let message =
    "Data piutang sesuai.";


  if (
    paidDifference >
    tolerance ||

    remainingDifference >
    tolerance
  ) {

    status =
      "ERROR";


    message =
      "Saldo piutang tidak sesuai dengan transaksi pembayaran.";

  }


  return {

    status,

    message,

    receivableId,

    customerId:
      receivable.customerId ||
      receivable.partyId ||
      "",

    customerName:
      receivable.customerName ||
      getCustomerNameById(
        receivable.customerId ||
        receivable.partyId
      ),

    invoiceNumber:
      receivable.invoiceNumber ||
      receivable.referenceNumber ||
      receivable.id,

    invoiceAmount,

    calculatedPaid,

    calculatedRemaining,

    storedPaid,

    storedRemaining:
      hasStoredRemaining
        ? storedRemaining
        : null,

    paidDifference,

    remainingDifference

  };

}


/* =========================================================
   RECONCILE ALL CUSTOMER RECEIVABLES
========================================================= */

function reconcileAllCustomerReceivables() {

  ensureReceivableStorage();

  ensureReceivablePaymentStorage();


  return db.receivables.map(
    receivable => {

      return reconcileCustomerReceivable(
        receivable.id
      );

    }
  );

}


/* =========================================================
   GET RECONCILIATION SUMMARY
========================================================= */

function getCustomerReceivableReconciliationSummary() {

  const results =
    reconcileAllCustomerReceivables();


  const total =
    results.length;


  const matched =
    results.filter(
      item =>
        item.status ===
        "MATCH"
    ).length;


  const errors =
    results.filter(
      item =>
        item.status ===
        "ERROR"
    ).length;


  return {

    total,

    matched,

    errors,

    isBalanced:
      errors === 0

  };

}


/* =========================================================
   AUTO REPAIR ONE RECEIVABLE
========================================================= */

function repairCustomerReceivable(
  receivableId
) {

  const receivable =
    getCustomerReceivableById(
      receivableId
    );


  if (!receivable) {

    showToast(
      "Piutang tidak ditemukan.",
      "error"
    );


    return {

      success: false

    };

  }


  /*
     Hitung ulang berdasarkan
     pembayaran ACTIVE saja.
  */

  const updated =
    recalculateCustomerReceivable(
      receivableId
    );


  if (!updated) {

    return {

      success: false

    };

  }


  /*
     Audit.
  */

  addAuditLog({

    action:
      "REPAIR_CUSTOMER_RECEIVABLE",

    reference:
      updated.invoiceNumber ||
      updated.id,

    module:
      "RECEIVABLE",

    description:
      "Saldo piutang customer dihitung ulang berdasarkan pembayaran aktif.",

    amount:
      Number(
        updated.remaining
      ) || 0

  });


  saveDB();


  showToast(
    "Saldo piutang berhasil direkonsiliasi.",
    "success"
  );


  return {

    success: true,

    receivable:
      updated

  };

}


/* =========================================================
   REPAIR ALL RECEIVABLES
========================================================= */

function repairAllCustomerReceivables() {

  ensureReceivableStorage();


  let repaired =
    0;


  db.receivables.forEach(
    receivable => {

      const beforePaid =
        Number(
          receivable.paid
        ) || 0;


      const beforeRemaining =
        Number(
          receivable.remaining
        ) || 0;


      const updated =
        recalculateCustomerReceivable(
          receivable.id
        );


      if (
        updated &&
        (
          beforePaid !==
          Number(
            updated.paid
          ) ||

          beforeRemaining !==
          Number(
            updated.remaining
          )
        )
      ) {

        repaired++;

      }

    }
  );


  if (
    repaired > 0
  ) {

    addAuditLog({

      action:
        "REPAIR_ALL_CUSTOMER_RECEIVABLE",

      reference:
        "SYSTEM",

      module:
        "RECEIVABLE",

      description:
        `Rekonsiliasi ${repaired} data piutang customer.`,

      amount:
        0

    });

  }


  saveDB();


  showToast(

    `${repaired} data piutang direkonsiliasi.`,

    "success"

  );


  refreshReceivableAfterTransaction();

  refreshCustomerReceivableDashboardSafe();


  return {

    success: true,

    repaired

  };

}


