/* =========================================================
   END BAGIAN 6I-15
========================================================= */
/* =========================================================
   FAEZA ERP V2
   BAGIAN 6I-16
   CUSTOMER RECEIVABLE AGING

   Aging:
   CURRENT
   1 - 30 DAYS
   31 - 60 DAYS
   61 - 90 DAYS
   > 90 DAYS

   Dasar:
   Due Date - Today
   Hanya saldo outstanding yang dihitung.
========================================================= */


/* =========================================================
   CALCULATE AGING DAYS
========================================================= */

function calculateReceivableAgingDays(
  dueDate,
  referenceDate = today()
) {

  if (!dueDate) {

    return 0;

  }


  const due =
    new Date(
      `${dueDate}T00:00:00`
    );


  const reference =
    new Date(
      `${referenceDate}T00:00:00`
    );


  if (
    Number.isNaN(
      due.getTime()
    ) ||
    Number.isNaN(
      reference.getTime()
    )
  ) {

    return 0;

  }


  const difference =
    reference.getTime() -
    due.getTime();


  return Math.floor(
    difference /
    (
      1000 *
      60 *
      60 *
      24
    )
  );

}


/* =========================================================
   GET AGING BUCKET
========================================================= */

function getReceivableAgingBucket(
  agingDays
) {

  const days =
    Number(
      agingDays
    ) || 0;


  /*
     Belum jatuh tempo
  */

  if (
    days <= 0
  ) {

    return {

      key:
        "CURRENT",

      label:
        "Current",

      days

    };

  }


  if (
    days <= 30
  ) {

    return {

      key:
        "1_30",

      label:
        "1–30 Hari",

      days

    };

  }


  if (
    days <= 60
  ) {

    return {

      key:
        "31_60",

      label:
        "31–60 Hari",

      days

    };

  }


  if (
    days <= 90
  ) {

    return {

      key:
        "61_90",

      label:
        "61–90 Hari",

      days

    };

  }


  return {

    key:
      "OVER_90",

    label:
      ">90 Hari",

    days

  };

}


/* =========================================================
   GET ONE RECEIVABLE AGING
========================================================= */

function getCustomerReceivableAging(
  receivable,
  referenceDate = today()
) {

  if (!receivable) {

    return null;

  }


  const remaining =
    getCustomerReceivableRemaining(
      receivable.id
    );


  /*
     Piutang lunas tidak masuk aging.
  */

  if (
    remaining <= 0
  ) {

    return {

      receivableId:
        receivable.id,

      customerId:
        receivable.customerId ||
        receivable.partyId ||
        "",

      customerName:
        receivable.customerName ||
        getCustomerNameById(
          receivable.customerId ||
          receivable.partyId
        ),

      invoiceNumber:
        receivable.invoiceNumber ||
        receivable.referenceNumber ||
        receivable.id,

      invoiceDate:
        receivable.date ||
        receivable.invoiceDate ||
        "",

      dueDate:
        receivable.dueDate ||
        "",

      amount:
        Number(
          receivable.amount
        ) || 0,

      paid:
        Number(
          receivable.amount
        ) || 0,

      remaining: 0,

      agingDays: 0,

      bucket: {

        key:
          "PAID",

        label:
          "Lunas"

      }

    };

  }


  const agingDays =
    calculateReceivableAgingDays(
      receivable.dueDate,
      referenceDate
    );


  const bucket =
    getReceivableAgingBucket(
      agingDays
    );


  return {

    receivableId:
      receivable.id,

    customerId:
      receivable.customerId ||
      receivable.partyId ||
      "",

    customerName:
      receivable.customerName ||
      getCustomerNameById(
        receivable.customerId ||
        receivable.partyId
      ),

    invoiceNumber:
      receivable.invoiceNumber ||
      receivable.referenceNumber ||
      receivable.id,

    invoiceDate:
      receivable.date ||
      receivable.invoiceDate ||
      "",

    dueDate:
      receivable.dueDate ||
      "",

    amount:
      Number(
        receivable.amount
      ) || 0,

    paid:
      Math.max(
        0,
        (
          Number(
            receivable.amount
          ) || 0
        ) -
        remaining
      ),

    remaining,

    agingDays,

    bucket

  };

}


/* =========================================================
   GET ALL OUTSTANDING AGING
========================================================= */

function getAllCustomerReceivableAging(
  referenceDate = today()
) {

  ensureReceivableStorage();

  ensureReceivablePaymentStorage();


  return db.receivables
    .map(
      receivable =>
        getCustomerReceivableAging(
          receivable,
          referenceDate
        )
    )
    .filter(
      item =>
        item &&
        item.remaining > 0
    );

}


/* =========================================================
   AGING SUMMARY
========================================================= */

function getCustomerReceivableAgingSummary(
  referenceDate = today()
) {

  const records =
    getAllCustomerReceivableAging(
      referenceDate
    );


  const summary = {

    total:
      0,

    current:
      0,

    days1to30:
      0,

    days31to60:
      0,

    days61to90:
      0,

    over90:
      0,

    invoiceCount:
      records.length

  };


  records.forEach(
    record => {

      const amount =
        Number(
          record.remaining
        ) || 0;


      summary.total +=
        amount;


      switch (
        record.bucket.key
      ) {

        case "CURRENT":

          summary.current +=
            amount;

          break;


        case "1_30":

          summary.days1to30 +=
            amount;

          break;


        case "31_60":

          summary.days31to60 +=
            amount;

          break;


        case "61_90":

          summary.days61to90 +=
            amount;

          break;


        case "OVER_90":

          summary.over90 +=
            amount;

          break;

      }

    }
  );


  return summary;

}


/* =========================================================
   AGING SUMMARY BY CUSTOMER
========================================================= */

function getCustomerReceivableAgingByCustomer(
  referenceDate = today()
) {

  const records =
    getAllCustomerReceivableAging(
      referenceDate
    );


  const map =
    {};


  records.forEach(
    record => {

      const key =
        String(
          record.customerId ||
          record.customerName ||
          "UNKNOWN"
        );


      if (
        !map[key]
      ) {

        map[key] = {

          customerId:
            record.customerId,

          customerName:
            record.customerName,

          current:
            0,

          days1to30:
            0,

          days31to60:
            0,

          days61to90:
            0,

          over90:
            0,

          total:
            0

        };

      }


      const amount =
        Number(
          record.remaining
        ) || 0;


      map[key].total +=
        amount;


      switch (
        record.bucket.key
      ) {

        case "CURRENT":

          map[key].current +=
            amount;

          break;


        case "1_30":

          map[key].days1to30 +=
            amount;

          break;


        case "31_60":

          map[key].days31to60 +=
            amount;

          break;


        case "61_90":

          map[key].days61to90 +=
            amount;

          break;


        case "OVER_90":

          map[key].over90 +=
            amount;

          break;

      }

    }
  );


  return Object.values(
    map
  )
  .sort(
    (
      a,
      b
    ) =>
      b.total -
      a.total
  );

}


