/* =========================================================
   FAEZA ERP V2
   BAGIAN 6I-17
   CUSTOMER RECEIVABLE COLLECTION PRIORITY

   PRIORITAS:
   P1 = KRITIS
   P2 = TINGGI
   P3 = SEDANG
   P4 = RENDAH
   P5 = CURRENT

   Dasar penilaian:
   - Umur piutang
   - Nominal outstanding
   - Status overdue
========================================================= */


/* =========================================================
   GET COLLECTION PRIORITY
========================================================= */

function getReceivableCollectionPriority(
  agingRecord
) {

  if (!agingRecord) {

    return {

      code:
        "P5",

      label:
        "Current",

      score:
        0

    };

  }


  const days =
    Number(
      agingRecord.agingDays
    ) || 0;


  const remaining =
    Number(
      agingRecord.remaining
    ) || 0;


  /*
     P1
     Lebih dari 90 hari
  */

  if (
    days > 90
  ) {

    return {

      code:
        "P1",

      label:
        "KRITIS",

      score:
        100

    };

  }


  /*
     P2
     61 - 90 hari
  */

  if (
    days > 60
  ) {

    return {

      code:
        "P2",

      label:
        "TINGGI",

      score:
        80

    };

  }


  /*
     P3
     31 - 60 hari
  */

  if (
    days > 30
  ) {

    return {

      code:
        "P3",

      label:
        "SEDANG",

      score:
        60

    };

  }


  /*
     P4
     1 - 30 hari
  */

  if (
    days > 0
  ) {

    return {

      code:
        "P4",

      label:
        "RENDAH",

      score:
        40

    };

  }


  /*
     Current
  */

  /*
     Piutang current bernominal
     sangat besar tetap diberi
     perhatian tambahan.
  */

  if (
    remaining >=
    10000000
  ) {

    return {

      code:
        "P4",

      label:
        "PERHATIAN",

      score:
        30

    };

  }


  return {

    code:
      "P5",

    label:
      "CURRENT",

    score:
      10

  };

}


/* =========================================================
   CALCULATE COLLECTION SCORE
========================================================= */

function calculateReceivableCollectionScore(
  agingRecord
) {

  if (!agingRecord) {

    return 0;

  }


  const priority =
    getReceivableCollectionPriority(
      agingRecord
    );


  const remaining =
    Number(
      agingRecord.remaining
    ) || 0;


  /*
     Faktor nominal.

     Maksimum tambahan 20 poin.
  */

  let amountScore =
    0;


  if (
    remaining >=
    50000000
  ) {

    amountScore =
      20;

  }

  else if (
    remaining >=
    20000000
  ) {

    amountScore =
      15;

  }

  else if (
    remaining >=
    10000000
  ) {

    amountScore =
      10;

  }

  else if (
    remaining >=
    5000000
  ) {

    amountScore =
      5;

  }


  return (

    priority.score +
    amountScore

  );

}


/* =========================================================
   GET COLLECTION PRIORITY RECORDS
========================================================= */

function getCustomerReceivableCollectionPriority(
  referenceDate = today()
) {

  const agingRecords =
    getAllCustomerReceivableAging(
      referenceDate
    );


  return agingRecords
    .map(
      record => {

        const priority =
          getReceivableCollectionPriority(
            record
          );


        const score =
          calculateReceivableCollectionScore(
            record
          );


        return {

          ...record,

          priorityCode:
            priority.code,

          priorityLabel:
            priority.label,

          collectionScore:
            score

        };

      }
    )
    .sort(
      (
        a,
        b
      ) => {

        /*
           Score tertinggi dahulu.
        */

        if (
          b.collectionScore !==
          a.collectionScore
        ) {

          return (

            b.collectionScore -
            a.collectionScore

          );

        }


        /*
           Jika score sama,
           nominal terbesar dahulu.
        */

        return (

          Number(
            b.remaining
          ) -

          Number(
            a.remaining
          )

        );

      }
    );

}


/* =========================================================
   PRIORITY BADGE
========================================================= */

function getReceivableCollectionPriorityBadge(
  code
) {

  switch (
    String(
      code
    ).toUpperCase()
  ) {

    case "P1":

      return `

        <span
          class="badge badge-danger"
        >

          P1 · KRITIS

        </span>

      `;


    case "P2":

      return `

        <span
          class="badge badge-warning"
        >

          P2 · TINGGI

        </span>

      `;


    case "P3":

      return `

        <span
          class="badge badge-warning"
        >

          P3 · SEDANG

        </span>

      `;


    case "P4":

      return `

        <span
          class="badge badge-info"
        >

          P4 · PERHATIAN

        </span>

      `;


    default:

      return `

        <span
          class="badge badge-success"
        >

          P5 · CURRENT

        </span>

      `;

  }

}


