/* =========================================================
   COLLECTION SUMMARY
========================================================= */

function getCustomerReceivableCollectionSummary() {

  const records =
    getCustomerReceivableCollectionPriority();


  const summary = {

    total:
      records.length,

    critical:
      0,

    high:
      0,

    medium:
      0,

    attention:
      0,

    current:
      0,

    totalOutstanding:
      0,

    criticalAmount:
      0,

    highAmount:
      0

  };


  records.forEach(
    record => {

      const amount =
        Number(
          record.remaining
        ) || 0;


      summary.totalOutstanding +=
        amount;


      switch (
        record.priorityCode
      ) {

        case "P1":

          summary.critical++;

          summary.criticalAmount +=
            amount;

          break;


        case "P2":

          summary.high++;

          summary.highAmount +=
            amount;

          break;


        case "P3":

          summary.medium++;

          break;


        case "P4":

          summary.attention++;

          break;


        default:

          summary.current++;

          break;

      }

    }
  );


  return summary;

}


/* =========================================================
   RENDER COLLECTION SUMMARY
========================================================= */

function renderCustomerReceivableCollectionSummary() {

  const summary =
    getCustomerReceivableCollectionSummary();


  const fields = {

    total:
      "collectionTotal",

    critical:
      "collectionCritical",

    high:
      "collectionHigh",

    medium:
      "collectionMedium",

    attention:
      "collectionAttention",

    current:
      "collectionCurrent",

    totalOutstanding:
      "collectionOutstanding",

    criticalAmount:
      "collectionCriticalAmount",

    highAmount:
      "collectionHighAmount"

  };


  Object.entries(
    fields
  )
  .forEach(
    (
      [
        key,
        elementId
      ]
    ) => {

      const element =
        document.getElementById(
          elementId
        );


      if (!element) {

        return;

      }


      if (
        key ===
        "totalOutstanding" ||

        key ===
        "criticalAmount" ||

        key ===
        "highAmount"
      ) {

        element.textContent =
          formatRupiah(
            summary[key]
          );

      }

      else {

        element.textContent =
          formatNumber(
            summary[key]
          );

      }

    }
  );

}


