/* =========================================================
   FAEZA ERP V2
   BAGIAN 6I-18
   CUSTOMER STATEMENT / KARTU PIUTANG DETAIL

   Menampilkan:
   - Invoice customer
   - Pembayaran aktif
   - Pembayaran VOID
   - Debit
   - Kredit
   - Saldo berjalan
   - Filter periode
   - Rekap customer
========================================================= */


/* =========================================================
   GET CUSTOMER STATEMENT
========================================================= */

function getCustomerReceivableStatement(
  customerId,
  options = {}
) {

  ensureReceivableStorage();
  ensureReceivablePaymentStorage();


  if (!customerId) {

    return [];

  }


  const startDate =
    options.startDate ||
    "";


  const endDate =
    options.endDate ||
    "";


  const includeVoid =
    options.includeVoid !== false;


  const events = [];


  /*
     -------------------------------------------------------
     INVOICE / PIUTANG
     -------------------------------------------------------
  */

  db.receivables
    .filter(
      receivable => {

        const id =
          receivable.customerId ||
          receivable.partyId ||
          "";


        return String(
          id
        ) === String(
          customerId
        );

      }
    )
    .forEach(
      receivable => {

        const date =
          receivable.date ||
          receivable.invoiceDate ||
          receivable.createdAt?.slice(
            0,
            10
          ) ||
          "";


        /*
           Filter tanggal.
        */

        if (
          startDate &&
          date <
          startDate
        ) {

          return;

        }


        if (
          endDate &&
          date >
          endDate
        ) {

          return;

        }


        const amount =
          Number(
            receivable.amount
          ) || 0;


        events.push({

          type:
            "INVOICE",

          date,

          id:
            receivable.id,

          reference:
            receivable.invoiceNumber ||
            receivable.referenceNumber ||
            receivable.id,

          description:
            "Invoice / Piutang",

          debit:
            amount,

          credit:
            0,

          amount,

          status:
            receivable.status ||
            "OPEN",

          receivableId:
            receivable.id,

          createdAt:
            receivable.createdAt ||
            ""

        });

      }
    );


  /*
     -------------------------------------------------------
     PEMBAYARAN
     -------------------------------------------------------
  */

  db.receivablePayments
    .filter(
      payment => {

        if (
          String(
            payment.customerId ||
            ""
          ) !==
          String(
            customerId
          )
        ) {

          return false;

        }


        normalizeReceivablePayment(
          payment
        );


        if (
          !includeVoid &&
          payment.status ===
          "VOID"
        ) {

          return false;

        }


        return true;

      }
    )
    .forEach(
      payment => {

        const date =
          payment.date ||
          payment.createdAt?.slice(
            0,
            10
          ) ||
          "";


        if (
          startDate &&
          date <
          startDate
        ) {

          return;

        }


        if (
          endDate &&
          date >
          endDate
        ) {

          return;

        }


        const isVoid =
          payment.status ===
          "VOID";


        events.push({

          type:
            isVoid
              ? "VOID_PAYMENT"
              : "PAYMENT",

          date,

          id:
            payment.id,

          reference:
            payment.paymentNumber ||
            payment.id,

          description:
            isVoid
              ? "VOID Pembayaran"
              : "Pembayaran Piutang",

          debit:
            0,

          credit:
            Number(
              payment.amount
            ) || 0,

          amount:
            Number(
              payment.amount
            ) || 0,

          status:
            payment.status,

          receivableId:
            payment.receivableId,

          paymentId:
            payment.id,

          method:
            payment.method ||
            "",

          referenceNumber:
            payment.reference ||
            "",

          voidReason:
            payment.voidReason ||
            "",

          createdAt:
            payment.createdAt ||
            ""

        });

      }
    );


  /*
     -------------------------------------------------------
     SORT
     -------------------------------------------------------

     Jika tanggal sama:
     Invoice lebih dulu,
     kemudian pembayaran.
  */

  events.sort(
    (
      a,
      b
    ) => {

      const dateCompare =
        String(
          a.date
        )
        .localeCompare(
          String(
            b.date
          )
        );


      if (
        dateCompare !== 0
      ) {

        return dateCompare;

      }


      const order = {

        INVOICE:
          1,

        PAYMENT:
          2,

        VOID_PAYMENT:
          3

      };


      return (

        (
          order[a.type] ||
          9
        ) -

        (
          order[b.type] ||
          9
        )

      );

    }
  );


  /*
     -------------------------------------------------------
     SALDO BERJALAN
     -------------------------------------------------------
  */

  let runningBalance =
    0;


  return events.map(
    event => {

      runningBalance +=
        Number(
          event.debit
        ) || 0;


      runningBalance -=
        Number(
          event.credit
        ) || 0;


      return {

        ...event,

        runningBalance

      };

    }
  );

}


/* =========================================================
   GET CUSTOMER STATEMENT SUMMARY
========================================================= */

function getCustomerReceivableStatementSummary(
  customerId,
  options = {}
) {

  const statement =
    getCustomerReceivableStatement(
      customerId,
      options
    );


  const summary = {

    invoiceCount:
      0,

    paymentCount:
      0,

    voidCount:
      0,

    totalDebit:
      0,

    totalCredit:
      0,

    balance:
      0

  };


  statement.forEach(
    item => {

      if (
        item.type ===
        "INVOICE"
      ) {

        summary.invoiceCount++;

        summary.totalDebit +=
          Number(
            item.debit
          ) || 0;

      }


      if (
        item.type ===
        "PAYMENT"
      ) {

        summary.paymentCount++;

        summary.totalCredit +=
          Number(
            item.credit
          ) || 0;

      }


      if (
        item.type ===
        "VOID_PAYMENT"
      ) {

        summary.voidCount++;

      }

    }
  );


  summary.balance =
    Math.max(
      0,
      summary.totalDebit -
      summary.totalCredit
    );


  return summary;

}


/* =========================================================
   RENDER CUSTOMER STATEMENT
========================================================= */

function renderCustomerReceivableStatement(
  customerId,
  options = {}
) {

  const tbody =
    document.getElementById(
      "customerReceivableStatementBody"
    );


  if (!tbody) {

    return;

  }


  if (!customerId) {

    tbody.innerHTML = `

      <tr>

        <td
          colspan="9"
          class="empty-state"
        >

          Pilih customer untuk melihat
          kartu piutang.

        </td>

      </tr>

    `;

    return;

  }


  const statement =
    getCustomerReceivableStatement(
      customerId,
      options
    );


  if (
    !statement.length
  ) {

    tbody.innerHTML = `

      <tr>

        <td
          colspan="9"
          class="empty-state"
        >

          Tidak ada transaksi pada periode ini.

        </td>

      </tr>

    `;

    return;

  }


  tbody.innerHTML =
    statement
      .map(
        (
          item,
          index
        ) => {

          const isInvoice =
            item.type ===
            "INVOICE";


          const isVoid =
            item.type ===
            "VOID_PAYMENT";


          return `

            <tr
              class="${
                isVoid
                  ? "payment-void-row"
                  : ""
              }"
            >

              <td>

                ${index + 1}

              </td>


              <td>

                ${escapeHTML(
                  item.date ||
                  "-"
                )}

              </td>


              <td>

                <strong>

                  ${escapeHTML(
                    item.reference ||
                    "-"
                  )}

                </strong>

              </td>


              <td>

                ${
                  isInvoice

                    ? `

                      <span
                        class="badge badge-warning"
                      >
                        INVOICE
                      </span>

                    `

                    : isVoid

                      ? `

                        <span
                          class="badge badge-danger"
                        >
                          VOID
                        </span>

                      `

                      : `

                        <span
                          class="badge badge-success"
                        >
                          PAYMENT
                        </span>

                      `

                }

              </td>


              <td>

                ${escapeHTML(
                  item.description ||
                  "-"
                )}

                ${
                  item.method

                    ? `<br><small>${escapeHTML(
                        item.method
                      )}</small>`

                    : ""
                }

              </td>


              <td class="money">

                ${
                  item.debit > 0

                    ? formatRupiah(
                        item.debit
                      )

                    : "-"
                }

              </td>


              <td class="money">

                ${
                  item.credit > 0

                    ? formatRupiah(
                        item.credit
                      )

                    : "-"
                }

              </td>


              <td class="money">

                <strong>

                  ${formatRupiah(
                    item.runningBalance
                  )}

                </strong>

              </td>


              <td>

                ${
                  isVoid

                    ? escapeHTML(
                        item.voidReason ||
                        "Dibatalkan"
                      )

                    : escapeHTML(
                        item.status ||
                        ""
                      )

                }

              </td>

            </tr>

          `;

        }
      )
      .join("");

}


