/* =========================================================
   OPEN CUSTOMER STATEMENT
========================================================= */

function openCustomerReceivableStatement(
  customerId
) {

  if (!customerId) {

    showToast(
      "Customer belum dipilih.",
      "warning"
    );

    return;

  }


  /*
     Simpan customer aktif.
  */

  window.activeReceivableStatementCustomerId =
    customerId;


  /*
     Isi filter tanggal.
  */

  const startDate =
    document.getElementById(
      "statementStartDate"
    )?.value || "";


  const endDate =
    document.getElementById(
      "statementEndDate"
    )?.value || "";


  const includeVoid =
    document.getElementById(
      "statementIncludeVoid"
    )?.checked !== false;


  const options = {

    startDate,

    endDate,

    includeVoid

  };


  renderCustomerReceivableStatement(
    customerId,
    options
  );


  renderCustomerReceivableStatementSummary(
    customerId,
    options
  );


  /*
     Buka section/modal jika tersedia.
  */

  const section =
    document.getElementById(
      "customerReceivableStatementSection"
    );


  if (
    section
  ) {

    section.scrollIntoView({
      behavior:
        "smooth",

      block:
        "start"

    });

  }

}


/* =========================================================
   APPLY STATEMENT FILTER
========================================================= */

function applyCustomerReceivableStatementFilter() {

  const customerId =
    window.activeReceivableStatementCustomerId ||
    document.getElementById(
      "statementCustomerFilter"
    )?.value ||
    "";


  const startDate =
    document.getElementById(
      "statementStartDate"
    )?.value || "";


  const endDate =
    document.getElementById(
      "statementEndDate"
    )?.value || "";


  const includeVoid =
    document.getElementById(
      "statementIncludeVoid"
    )?.checked !== false;


  if (
    startDate &&
    endDate &&
    startDate >
    endDate
  ) {

    showToast(
      "Tanggal mulai tidak boleh melebihi tanggal akhir.",
      "error"
    );

    return;

  }


  if (!customerId) {

    showToast(
      "Pilih customer terlebih dahulu.",
      "warning"
    );

    return;

  }


  const options = {

    startDate,

    endDate,

    includeVoid

  };


  renderCustomerReceivableStatement(
    customerId,
    options
  );


  renderCustomerReceivableStatementSummary(
    customerId,
    options
  );

}


