/* =========================================================
   POPULATE STATEMENT CUSTOMER FILTER
========================================================= */

function populateCustomerReceivableStatementFilter() {

  const select =
    document.getElementById(
      "statementCustomerFilter"
    );


  if (!select) {

    return;

  }


  const currentValue =
    select.value;


  const customers =
    Array.isArray(
      db.customers
    )
      ? db.customers
      : [];


  select.innerHTML = `

    <option value="">
      Pilih Customer
    </option>

  `;


  customers
    .slice()
    .sort(
      (
        a,
        b
      ) => {

        return String(
          a.name ||
          a.customerName ||
          ""
        )
        .localeCompare(
          String(
            b.name ||
            b.customerName ||
            ""
          )
        );

      }
    )
    .forEach(
      customer => {

        const option =
          document.createElement(
            "option"
          );


        option.value =
          customer.id;


        option.textContent =
          customer.name ||
          customer.customerName ||
          "Customer";


        select.appendChild(
          option
        );

      }
    );


  if (
    currentValue
  ) {

    select.value =
      currentValue;

  }

}


