/* =========================================================
   GET CUSTOMER STATEMENT PRINT DATA
========================================================= */

function getCustomerStatementPrintData(
  customerId,
  options = {}
) {

  if (!customerId) {

    return null;

  }


  const statement =
    getCustomerReceivableStatement(
      customerId,
      options
    );


  const summary =
    getCustomerReceivableStatementSummary(
      customerId,
      options
    );


  const customer =
    Array.isArray(
      db.customers
    )
      ? db.customers.find(
          item =>
            String(
              item.id
            ) ===
            String(
              customerId
            )
        )
      : null;


  return {

    customerId,

    customer,

    statement,

    summary,

    startDate:
      options.startDate ||
      "",

    endDate:
      options.endDate ||
      "",

    generatedAt:
      new Date().toISOString()

  };

}


/* =========================================================
   CUSTOMER PRINT NAME
========================================================= */

function getCustomerStatementPrintName(
  customer
) {

  if (!customer) {

    return "-";

  }


  return (
    customer.name ||
    customer.customerName ||
    customer.companyName ||
    "-"
  );

}


/* =========================================================
   CUSTOMER PRINT ADDRESS
========================================================= */

function getCustomerStatementPrintAddress(
  customer
) {

  if (!customer) {

    return "-";

  }


  return (
    customer.address ||
    customer.alamat ||
    "-"
  );

}


/* =========================================================
   CUSTOMER PRINT PHONE
========================================================= */

function getCustomerStatementPrintPhone(
  customer
) {

  if (!customer) {

    return "-";

  }


  return (
    customer.phone ||
    customer.phoneNumber ||
    customer.whatsapp ||
    customer.wa ||
    "-"
  );

}


/* =========================================================
   PRINT DATE RANGE
========================================================= */

function getCustomerStatementPrintPeriod(
  startDate,
  endDate
) {

  if (
    startDate &&
    endDate
  ) {

    return (
      formatPrintDate(
        startDate
      ) +
      " s/d " +
      formatPrintDate(
        endDate
      )
    );

  }


  if (
    startDate
  ) {

    return (
      "Mulai " +
      formatPrintDate(
        startDate
      )
    );

  }


  if (
    endDate
  ) {

    return (
      "Sampai " +
      formatPrintDate(
        endDate
      )
    );

  }


  return "Seluruh Periode";

}


