/* =========================================================
   PRINT CUSTOMER STATEMENT
========================================================= */

function printCustomerReceivableStatement(
  customerId
) {

  if (!customerId) {

    customerId =
      window.activeReceivableStatementCustomerId ||
      document.getElementById(
        "statementCustomerFilter"
      )?.value ||
      "";

  }


  if (!customerId) {

    showToast(
      "Pilih customer terlebih dahulu.",
      "warning"
    );

    return;

  }


  const startDate =
    document.getElementById(
      "statementStartDate"
    )?.value ||
    "";


  const endDate =
    document.getElementById(
      "statementEndDate"
    )?.value ||
    "";


  const includeVoid =
    document.getElementById(
      "statementIncludeVoid"
    )?.checked !== false;


  if (
    startDate &&
    endDate &&
    startDate >
    endDate
  ) {

    showToast(
      "Periode tanggal tidak valid.",
      "error"
    );

    return;

  }


  const data =
    getCustomerStatementPrintData(
      customerId,
      {

        startDate,

        endDate,

        includeVoid

      }
    );


  if (!data) {

    showToast(
      "Data customer tidak ditemukan.",
      "error"
    );

    return;

  }


  const html =
    generateCustomerStatementPrintHTML(
      data
    );


  if (!html) {

    showToast(
      "Gagal membuat laporan.",
      "error"
    );

    return;

  }


  const printWindow =
    window.open(
      "",
      "_blank",
      "width=1000,height=800"
    );


  if (!printWindow) {

    showToast(
      "Popup diblokir browser. Izinkan popup untuk Faeza ERP.",
      "warning"
    );

    return;

  }


  printWindow.document.open();

  printWindow.document.write(
    html
  );

  printWindow.document.close();

}


/* =========================================================
   PRINT CURRENT STATEMENT
========================================================= */

function printCurrentCustomerStatement() {

  const customerId =
    window.activeReceivableStatementCustomerId ||
    document.getElementById(
      "statementCustomerFilter"
    )?.value ||
    "";


  printCustomerReceivableStatement(
    customerId
  );

}


