/* =========================================================
   FAEZA ERP V2
   BAGIAN 6I-20
   EXPORT CUSTOMER STATEMENT
========================================================= */

function exportCustomerReceivableStatementCSV(
  customerId
) {

  if (!customerId) {

    customerId =
      window.activeReceivableStatementCustomerId ||
      document.getElementById(
        "statementCustomerFilter"
      )?.value ||
      "";

  }


  if (!customerId) {

    showToast(
      "Pilih customer terlebih dahulu.",
      "warning"
    );

    return;

  }


  const startDate =
    document.getElementById(
      "statementStartDate"
    )?.value ||
    "";


  const endDate =
    document.getElementById(
      "statementEndDate"
    )?.value ||
    "";


  const includeVoid =
    document.getElementById(
      "statementIncludeVoid"
    )?.checked !== false;


  if (
    startDate &&
    endDate &&
    startDate > endDate
  ) {

    showToast(
      "Periode tanggal tidak valid.",
      "error"
    );

    return;

  }


  const data =
    getCustomerStatementPrintData(
      customerId,
      {
        startDate,
        endDate,
        includeVoid
      }
    );


  if (!data) {

    showToast(
      "Data customer tidak ditemukan.",
      "error"
    );

    return;

  }


  const customerName =
    getCustomerStatementPrintName(
      data.customer
    );


  const rows = [];


  rows.push([
    "No",
    "Tanggal",
    "Referensi",
    "Jenis",
    "Keterangan",
    "Debit",
    "Kredit",
    "Saldo Berjalan",
    "Status"
  ]);


  data.statement.forEach(
    (
      item,
      index
    ) => {

      rows.push([

        index + 1,

        item.date || "",

        item.reference || "",

        item.type === "INVOICE"
          ? "Invoice"
          : item.type === "VOID_PAYMENT"
            ? "VOID Pembayaran"
            : "Pembayaran",

        item.description || "",

        Number(
          item.debit
        ) || 0,

        Number(
          item.credit
        ) || 0,

        Number(
          item.runningBalance
        ) || 0,

        item.status || ""

      ]);

    }
  );


  /*
     Rekap
  */

  rows.push([]);

  rows.push([
    "",
    "",
    "",
    "",
    "TOTAL INVOICE",
    data.summary.totalDebit,
    "",
    "",
    ""
  ]);


  rows.push([
    "",
    "",
    "",
    "",
    "TOTAL PEMBAYARAN",
    "",
    data.summary.totalCredit,
    "",
    ""
  ]);


  rows.push([
    "",
    "",
    "",
    "",
    "SALDO PIUTANG",
    "",
    "",
    data.summary.balance,
    ""
  ]);


  /*
     CSV escape
  */

  const csv =
    rows
      .map(
        row =>
          row
            .map(
              value => {

                const text =
                  String(
                    value ?? ""
                  );


                return `"${text
                  .replace(
                    /"/g,
                    '""'
                  )}"`;

              }
            )
            .join(",")
      )
      .join("\r\n");


  /*
     BOM supaya Excel membaca
     UTF-8 dengan benar.
  */

  const blob =
    new Blob(
      [
        "\uFEFF",
        csv
      ],
      {
        type:
          "text/csv;charset=utf-8;"
      }
    );


  const url =
    URL.createObjectURL(
      blob
    );


  const safeName =
    customerName
      .replace(
        /[^a-zA-Z0-9-_ ]/g,
        ""
      )
      .trim()
      .replace(
        /\s+/g,
        "-"
      );


  const filename =
    `Customer-Statement-${safeName || "Customer"}-${today()}.csv`;


  const link =
    document.createElement(
      "a"
    );


  link.href =
    url;


  link.download =
    filename;


  document.body.appendChild(
    link
  );


  link.click();


  link.remove();


  setTimeout(
    () => {

      URL.revokeObjectURL(
        url
      );

    },
    1000
  );


  addAuditLog({

    action:
      "EXPORT_CUSTOMER_STATEMENT",

    reference:
      customerId,

    module:
      "RECEIVABLE",

    description:
      `Export Customer Statement: ${customerName}`,

    amount:
      Number(
        data.summary.balance
      ) || 0

  });


  saveDB();


  showToast(
    "Customer Statement berhasil diexport.",
    "success"
  );


  return true;

}


/* =========================================================
   EXPORT CURRENT STATEMENT
========================================================= */

function exportCurrentCustomerStatement() {

  const customerId =
    window.activeReceivableStatementCustomerId ||
    document.getElementById(
      "statementCustomerFilter"
    )?.value ||
    "";


  return exportCustomerReceivableStatementCSV(
    customerId
  );

}


