/* =========================================================
   FAEZA ERP V2
   BAGIAN 6J-01
   SUPPLIER PAYABLE FOUNDATION
   HUTANG SUPPLIER
========================================================= */


/* =========================================================
   PAYABLE STORAGE
========================================================= */

function ensurePayableStorage() {

  if (
    !Array.isArray(
      db.payables
    )
  ) {

    db.payables = [];

  }


  if (
    !Array.isArray(
      db.payablePayments
    )
  ) {

    db.payablePayments = [];

  }

}


/* =========================================================
   GENERATE PAYABLE ID
========================================================= */

function generatePayableId() {

  return (
    "PAY-" +
    Date.now() +
    "-" +
    Math.random()
      .toString(36)
      .slice(2, 7)
      .toUpperCase()
  );

}


/* =========================================================
   GENERATE PAYABLE NUMBER
========================================================= */

function generatePayableNumber() {

  ensurePayableStorage();


  const year =
    new Date()
      .getFullYear();


  const prefix =
    `HUT-${year}-`;


  const numbers =
    db.payables
      .map(
        item => {

          const number =
            String(
              item.payableNumber ||
              ""
            );


          if (
            !number.startsWith(
              prefix
            )
          ) {

            return 0;

          }


          const value =
            Number(
              number.replace(
                prefix,
                ""
              )
            );


          return Number.isFinite(
            value
          )
            ? value
            : 0;

        }
      );


  const next =
    Math.max(
      0,
      ...numbers
    ) + 1;


  return (
    prefix +
    String(
      next
    ).padStart(
      5,
      "0"
    )
  );

}


/* =========================================================
   GET SUPPLIER BY ID
========================================================= */

function getSupplierById(
  supplierId
) {

  if (!supplierId) {

    return null;

  }


  const suppliers =
    Array.isArray(
      db.suppliers
    )
      ? db.suppliers
      : [];


  return (
    suppliers.find(
      supplier =>
        String(
          supplier.id
        ) ===
        String(
          supplierId
        )
    ) ||
    null
  );

}


/* =========================================================
   GET SUPPLIER NAME
========================================================= */

function getSupplierNameById(
  supplierId
) {

  const supplier =
    getSupplierById(
      supplierId
    );


  if (!supplier) {

    return "-";

  }


  return (
    supplier.name ||
    supplier.supplierName ||
    supplier.companyName ||
    "-"
  );

}


/* =========================================================
   GET PAYABLE BY ID
========================================================= */

function getPayableById(
  payableId
) {

  ensurePayableStorage();


  return (
    db.payables.find(
      item =>
        String(
          item.id
        ) ===
        String(
          payableId
        )
    ) ||
    null
  );

}


/* =========================================================
   GET PAYABLE BY PURCHASE ID
========================================================= */

function getPayableByPurchaseId(
  purchaseId
) {

  ensurePayableStorage();


  return (
    db.payables.find(
      item =>
        String(
          item.purchaseId
        ) ===
        String(
          purchaseId
        )
    ) ||
    null
  );

}


/* =========================================================
   GET SUPPLIER PAYABLE REMAINING
========================================================= */

function getSupplierPayableRemaining(
  payableId
) {

  ensurePayableStorage();


  const payable =
    getPayableById(
      payableId
    );


  if (!payable) {

    return 0;

  }


  const amount =
    Number(
      payable.amount
    ) || 0;


  const payments =
    db.payablePayments
      .filter(
        payment => {

          return (

            String(
              payment.payableId
            ) ===
            String(
              payableId
            ) &&

            String(
              payment.status ||
              "POSTED"
            ).toUpperCase() !==
            "VOID"

          );

        }
      );


  const paid =
    payments.reduce(
      (
        total,
        payment
      ) => {

        return (
          total +
          (
            Number(
              payment.amount
            ) || 0
          )
        );

      },
      0
    );


  return Math.max(
    0,
    amount - paid
  );

}


/* =========================================================
   GET SUPPLIER PAYABLE PAID
========================================================= */

function getSupplierPayablePaid(
  payableId
) {

  ensurePayableStorage();


  return db.payablePayments
    .filter(
      payment => {

        return (

          String(
            payment.payableId
          ) ===
          String(
            payableId
          ) &&

          String(
            payment.status ||
            "POSTED"
          ).toUpperCase() !==
          "VOID"

        );

      }
    )
    .reduce(
      (
        total,
        payment
      ) => {

        return (
          total +
          (
            Number(
              payment.amount
            ) || 0
          )
        );

      },
      0
    );

}


/* =========================================================
   CREATE SUPPLIER PAYABLE
========================================================= */

function createSupplierPayable(
  data = {}
) {

  ensurePayableStorage();


  const supplierId =
    data.supplierId ||
    "";


  if (!supplierId) {

    showToast(
      "Supplier wajib dipilih.",
      "warning"
    );


    return null;

  }


  const supplier =
    getSupplierById(
      supplierId
    );


  if (!supplier) {

    showToast(
      "Supplier tidak ditemukan.",
      "error"
    );


    return null;

  }


  const amount =
    Number(
      data.amount
    ) || 0;


  if (
    amount <= 0
  ) {

    showToast(
      "Nilai hutang harus lebih dari Rp0.",
      "warning"
    );


    return null;

  }


  const payable = {

    id:
      generatePayableId(),

    payableNumber:
      generatePayableNumber(),

    supplierId,

    supplierName:
      getSupplierNameById(
        supplierId
      ),

    purchaseId:
      data.purchaseId ||
      "",

    purchaseNumber:
      data.purchaseNumber ||
      "",

    invoiceNumber:
      data.invoiceNumber ||
      "",

    date:
      data.date ||
      today(),

    dueDate:
      data.dueDate ||
      "",

    amount,

    paid:
      0,

    remaining:
      amount,

    status:
      "OPEN",

    notes:
      data.notes ||
      "",

    createdAt:
      new Date().toISOString(),

    updatedAt:
      new Date().toISOString()

  };


  /*
     Hindari hutang ganda
     untuk pembelian yang sama.
  */

  if (
    payable.purchaseId
  ) {

    const existing =
      getPayableByPurchaseId(
        payable.purchaseId
      );


    if (existing) {

      showToast(
        "Pembelian ini sudah memiliki hutang supplier.",
        "warning"
      );


      return existing;

    }

  }


  db.payables.push(
    payable
  );


  addAuditLog({

    action:
      "CREATE_SUPPLIER_PAYABLE",

    reference:
      payable.payableNumber,

    module:
      "PAYABLE",

    description:
      `Hutang supplier dibuat untuk ${payable.supplierName}`,

    amount:
      payable.amount

  });


  saveDB();


  return payable;

}


/* =========================================================
   RECALCULATE SUPPLIER PAYABLE
========================================================= */

function recalculateSupplierPayable(
  payableId
) {

  const payable =
    getPayableById(
      payableId
    );


  if (!payable) {

    return null;

  }


  const amount =
    Number(
      payable.amount
    ) || 0;


  const paid =
    Math.min(
      amount,
      getSupplierPayablePaid(
        payableId
      )
    );


  const remaining =
    Math.max(
      0,
      amount - paid
    );


  payable.paid =
    paid;


  payable.remaining =
    remaining;


  if (
    remaining <= 0
  ) {

    payable.status =
      "PAID";

  }

  else if (
    paid > 0
  ) {

    payable.status =
      "PARTIAL";

  }

  else {

    payable.status =
      "OPEN";

  }


  payable.updatedAt =
    new Date().toISOString();


  return payable;

}


/* =========================================================
   RECALCULATE ALL SUPPLIER PAYABLES
========================================================= */

function recalculateAllSupplierPayables() {

  ensurePayableStorage();


  db.payables.forEach(
    payable => {

      recalculateSupplierPayable(
        payable.id
      );

    }
  );


  saveDB();

}


