/* =========================================================
   SUPPLIER PAYABLE PAYMENT SUMMARY
========================================================= */

function getSupplierPayablePaymentSummary() {

  ensurePayableStorage();


  const payments =
    db.payablePayments;


  const summary = {

    count:
      0,

    posted:
      0,

    void:
      0,

    totalPosted:
      0,

    totalVoid:
      0

  };


  payments.forEach(
    payment => {

      summary.count++;


      const amount =
        Number(
          payment.amount
        ) || 0;


      const status =
        String(
          payment.status ||
          "POSTED"
        ).toUpperCase();


      if (
        status ===
        "VOID"
      ) {

        summary.void++;

        summary.totalVoid +=
          amount;

      }

      else {

        summary.posted++;

        summary.totalPosted +=
          amount;

      }

    }
  );


  return summary;

}


