/* =========================================================
   OPEN PAYABLE PAYMENT
========================================================= */

function openSupplierPayablePayment(
  payableId
) {

  const payable =
    getPayableById(
      payableId
    );


  if (!payable) {

    showToast(
      "Hutang supplier tidak ditemukan.",
      "error"
    );


    return;

  }


  recalculateSupplierPayable(
    payable.id
  );


  if (
    Number(
      payable.remaining
    ) <= 0
  ) {

    showToast(
      "Hutang supplier sudah lunas.",
      "warning"
    );


    return;

  }


  const supplierInput =
    document.getElementById(
      "payablePaymentSupplier"
    );


  const payableInput =
    document.getElementById(
      "payablePaymentPayableId"
    );


  const amountInput =
    document.getElementById(
      "payablePaymentAmount"
    );


  const dateInput =
    document.getElementById(
      "payablePaymentDate"
    );


  if (
    supplierInput
  ) {

    supplierInput.value =
      payable.supplierName ||
      getSupplierNameById(
        payable.supplierId
      );

  }


  if (
    payableInput
  ) {

    payableInput.value =
      payable.id;

  }


  if (
    amountInput
  ) {

    amountInput.value =
      payable.remaining;

  }


  if (
    dateInput &&
    !dateInput.value
  ) {

    dateInput.value =
      today();

  }


  window.activeSupplierPayablePaymentId =
    payable.id;

}


