/* =========================================================
   GET PAYABLE LIST WITH CALCULATED BALANCE
========================================================= */

function getSupplierPayableList(
  filters = {}
) {

  ensurePayableStorage();


  const supplierId =
    filters.supplierId ||
    "";


  const status =
    String(
      filters.status ||
      "ALL"
    ).toUpperCase();


  const search =
    String(
      filters.search ||
      ""
    )
    .trim()
    .toLowerCase();


  const dateFrom =
    filters.dateFrom ||
    "";


  const dateTo =
    filters.dateTo ||
    "";


  const dueFrom =
    filters.dueFrom ||
    "";


  const dueTo =
    filters.dueTo ||
    "";


  return db.payables
    .map(
      payable => {

        recalculateSupplierPayable(
          payable.id
        );


        return payable;

      }
    )
    .filter(
      payable => {

        /*
           Supplier
        */

        if (
          supplierId &&
          String(
            payable.supplierId
          ) !==
          String(
            supplierId
          )
        ) {

          return false;

        }


        /*
           Status
        */

        if (
          status !== "ALL" &&
          String(
            payable.status ||
            ""
          ).toUpperCase() !==
          status
        ) {

          return false;

        }


        /*
           Search
        */

        if (
          search
        ) {

          const text =
            [

              payable.payableNumber,

              payable.supplierName,

              payable.purchaseNumber,

              payable.invoiceNumber

            ]
              .join(" ")
              .toLowerCase();


          if (
            !text.includes(
              search
            )
          ) {

            return false;

          }

        }


        /*
           Tanggal transaksi
        */

        if (
          dateFrom &&
          String(
            payable.date ||
            ""
          ) < dateFrom
        ) {

          return false;

        }


        if (
          dateTo &&
          String(
            payable.date ||
            ""
          ) > dateTo
        ) {

          return false;

        }


        /*
           Jatuh tempo
        */

        if (
          dueFrom &&
          String(
            payable.dueDate ||
            ""
          ) < dueFrom
        ) {

          return false;

        }


        if (
          dueTo &&
          String(
            payable.dueDate ||
            ""
          ) > dueTo
        ) {

          return false;

        }


        return true;

      }
    )
    .sort(
      (
        a,
        b
      ) => {

        return String(
          b.date ||
          ""
        )
        .localeCompare(
          String(
            a.date ||
            ""
          )
        );

      }
    );

}


/* =========================================================
   GET PAYABLE DAYS OVERDUE
========================================================= */

function getPayableDaysOverdue(
  payable
) {

  if (
    !payable ||
    !payable.dueDate
  ) {

    return 0;

  }


  if (
    Number(
      payable.remaining
    ) <= 0
  ) {

    return 0;

  }


  const todayDate =
    new Date(
      today()
    );


  const dueDate =
    new Date(
      payable.dueDate
    );


  const difference =
    todayDate.getTime() -
    dueDate.getTime();


  const days =
    Math.floor(
      difference /
      (
        1000 *
        60 *
        60 *
        24
      )
    );


  return Math.max(
    0,
    days
  );

}


/* =========================================================
   GET PAYABLE AGE BUCKET
========================================================= */

function getPayableAgeBucket(
  payable
) {

  const days =
    getPayableDaysOverdue(
      payable
    );


  if (
    Number(
      payable.remaining
    ) <= 0
  ) {

    return "PAID";

  }


  if (
    days <= 0
  ) {

    return "CURRENT";

  }


  if (
    days <= 30
  ) {

    return "1-30";

  }


  if (
    days <= 60
  ) {

    return "31-60";

  }


  if (
    days <= 90
  ) {

    return "61-90";

  }


  return ">90";

}


/* =========================================================
   GET PAYABLE STATUS CLASS
========================================================= */

function getSupplierPayableStatusClass(
  payable
) {

  if (
    Number(
      payable.remaining
    ) <= 0
  ) {

    return "payable-paid";

  }


  if (
    getPayableDaysOverdue(
      payable
    ) > 90
  ) {

    return "payable-critical";

  }


  if (
    getPayableDaysOverdue(
      payable
    ) > 0
  ) {

    return "payable-overdue";

  }


  if (
    payable.status ===
    "PARTIAL"
  ) {

    return "payable-partial";

  }


  return "payable-open";

}


/* =========================================================
   RENDER PAYABLE LIST
========================================================= */

function renderSupplierPayableListFiltered(
  filters = {}
) {

  const tbody =
    document.getElementById(
      "supplierPayableListBody"
    );


  if (!tbody) {

    return;

  }


  const payables =
    getSupplierPayableList(
      filters
    );


  if (
    !payables.length
  ) {

    tbody.innerHTML = `

      <tr>

        <td
          colspan="12"
          class="empty-state"
        >

          Tidak ada data hutang supplier
          sesuai filter.

        </td>

      </tr>

    `;

    updateSupplierPayableFilterSummary(
      []
    );

    return;

  }


  tbody.innerHTML =
    payables
      .map(
        (
          payable,
          index
        ) => {

          const overdue =
            getPayableDaysOverdue(
              payable
            );


          const bucket =
            getPayableAgeBucket(
              payable
            );


          const statusClass =
            getSupplierPayableStatusClass(
              payable
            );


          return `

            <tr
              class="${statusClass}"
            >

              <td>

                ${index + 1}

              </td>


              <td>

                <strong>

                  ${escapeHTML(
                    payable.payableNumber ||
                    "-"
                  )}

                </strong>

              </td>


              <td>

                ${escapeHTML(
                  payable.supplierName ||
                  getSupplierNameById(
                    payable.supplierId
                  )
                )}

              </td>


              <td>

                ${escapeHTML(
                  payable.purchaseNumber ||
                  "-"
                )}

              </td>


              <td>

                ${
                  payable.date
                    ? formatPrintDate(
                        payable.date
                      )
                    : "-"
                }

              </td>


              <td>

                ${
                  payable.dueDate
                    ? formatPrintDate(
                        payable.dueDate
                      )
                    : "-"
                }

              </td>


              <td class="money">

                ${formatRupiah(
                  payable.amount
                )}

              </td>


              <td class="money">

                ${formatRupiah(
                  payable.paid
                )}

              </td>


              <td class="money">

                <strong>

                  ${formatRupiah(
                    payable.remaining
                  )}

                </strong>

              </td>


              <td>

                ${
                  overdue > 0

                    ? `

                      <span
                        class="badge badge-danger"
                      >
                        ${overdue} hari
                      </span>

                    `

                    : `

                      <span
                        class="badge badge-success"
                      >
                        Lancar
                      </span>

                    `

                }

              </td>


              <td>

                <span
                  class="badge"
                >

                  ${bucket}

                </span>

              </td>


              <td>

                <div
                  class="table-actions"
                >

                  <button
                    type="button"
                    class="btn btn-sm"
                    onclick="
                      openSupplierPayableDetail(
                        '${escapeJS(
                          payable.id
                        )}'
                      )
                    "
                  >

                    Detail

                  </button>


                  ${
                    Number(
                      payable.remaining
                    ) > 0

                      ? `

                        <button
                          type="button"
                          class="btn btn-sm btn-primary"
                          onclick="
                            openSupplierPayablePayment(
                              '${escapeJS(
                                payable.id
                              )}'
                            )
                          "
                        >

                          Bayar

                        </button>

                      `

                      : ""

                  }

                </div>

              </td>

            </tr>

          `;

        }
      )
      .join("");


  updateSupplierPayableFilterSummary(
    payables
  );

}


/* =========================================================
   FILTER SUMMARY
========================================================= */

function updateSupplierPayableFilterSummary(
  payables
) {

  const list =
    Array.isArray(
      payables
    )
      ? payables
      : [];


  let total =
    0;


  let paid =
    0;


  let remaining =
    0;


  let overdue =
    0;


  list.forEach(
    payable => {

      total +=
        Number(
          payable.amount
        ) || 0;


      paid +=
        Number(
          payable.paid
        ) || 0;


      remaining +=
        Number(
          payable.remaining
        ) || 0;


      if (
        getPayableDaysOverdue(
          payable
        ) > 0
      ) {

        overdue++;

      }

    }
  );


  const count =
    document.getElementById(
      "payableFilterCount"
    );


  const totalElement =
    document.getElementById(
      "payableFilterTotal"
    );


  const paidElement =
    document.getElementById(
      "payableFilterPaid"
    );


  const remainingElement =
    document.getElementById(
      "payableFilterRemaining"
    );


  const overdueElement =
    document.getElementById(
      "payableFilterOverdue"
    );


  if (
    count
  ) {

    count.textContent =
      formatNumber(
        list.length
      );

  }


  if (
    totalElement
  ) {

    totalElement.textContent =
      formatRupiah(
        total
      );

  }


  if (
    paidElement
  ) {

    paidElement.textContent =
      formatRupiah(
        paid
      );

  }


  if (
    remainingElement
  ) {

    remainingElement.textContent =
      formatRupiah(
        remaining
      );

  }


  if (
    overdueElement
  ) {

    overdueElement.textContent =
      formatNumber(
        overdue
      );

  }

}


/* =========================================================
   FAEZA ERP V2
   BAGIAN 6J-03A
   APPLY SUPPLIER PAYABLE FILTER
========================================================= */

function applySupplierPayableFilter() {

  const supplierFilter =
    document.getElementById(
      "payableSupplierFilter"
    );

  const statusFilter =
    document.getElementById(
      "payableStatusFilter"
    );

  const searchFilter =
    document.getElementById(
      "payableSearchFilter"
    );

  const dateFromFilter =
    document.getElementById(
      "payableDateFrom"
    );

  const dateToFilter =
    document.getElementById(
      "payableDateTo"
    );

  const dueFromFilter =
    document.getElementById(
      "payableDueFrom"
    );

  const dueToFilter =
    document.getElementById(
      "payableDueTo"
    );


  const filters = {

    supplierId:
      supplierFilter?.value ||
      "",

    status:
      statusFilter?.value ||
      "ALL",

    search:
      searchFilter?.value ||
      "",

    dateFrom:
      dateFromFilter?.value ||
      "",

    dateTo:
      dateToFilter?.value ||
      "",

    dueFrom:
      dueFromFilter?.value ||
      "",

    dueTo:
      dueToFilter?.value ||
      ""

  };


  /* =====================================================
     VALIDASI PERIODE TRANSAKSI
  ===================================================== */

  if (

    filters.dateFrom &&

    filters.dateTo &&

    filters.dateFrom >
    filters.dateTo

  ) {

    showToast(
      "Tanggal mulai transaksi tidak boleh lebih besar dari tanggal akhir.",
      "warning"
    );

    return false;

  }


  /* =====================================================
     VALIDASI PERIODE JATUH TEMPO
  ===================================================== */

  if (

    filters.dueFrom &&

    filters.dueTo &&

    filters.dueFrom >
    filters.dueTo

  ) {

    showToast(
      "Tanggal jatuh tempo mulai tidak boleh lebih besar dari tanggal akhir.",
      "warning"
    );

    return false;

  }


  /* =====================================================
     RENDER HASIL FILTER
  ===================================================== */

  if (
    typeof renderSupplierPayableListFiltered ===
    "function"
  ) {

    renderSupplierPayableListFiltered(
      filters
    );

  }


  /* =====================================================
     SIMPAN FILTER AKTIF
  ===================================================== */

  window.activeSupplierPayableFilters =
    {
      ...filters
    };


  return true;

}


/* =========================================================
   AUTO APPLY FILTER
========================================================= */

function autoApplySupplierPayableFilter() {

  return applySupplierPayableFilter();

}


/* =========================================================
   FILTER DENGAN ENTER
========================================================= */

function handleSupplierPayableSearchKeydown(
  event
) {

  if (
    event &&
    event.key ===
    "Enter"
  ) {

    event.preventDefault();

    applySupplierPayableFilter();

  }

}


/* =========================================================
   END BAGIAN 6J-03A
========================================================= */

/* =========================================================
   FAEZA ERP V2
   BAGIAN 6J-03B
   CLEAR SUPPLIER PAYABLE FILTER
========================================================= */

function clearSupplierPayableFilter() {

  const filterIds = [

    "payableSupplierFilter",
    "payableStatusFilter",
    "payableSearchFilter",
    "payableDateFrom",
    "payableDateTo",
    "payableDueFrom",
    "payableDueTo"

  ];


  /* =====================================================
     KOSONGKAN SEMUA FILTER
  ===================================================== */

  filterIds.forEach(
    id => {

      const element =
        document.getElementById(
          id
        );


      if (!element) {

        return;

      }


      /*
         Status kembali ke ALL.
      */

      if (
        id ===
        "payableStatusFilter"
      ) {

        element.value =
          "ALL";

      }

      else {

        element.value =
          "";

      }

    }
  );


  /* =====================================================
     HAPUS FILTER AKTIF
  ===================================================== */

  window.activeSupplierPayableFilters =
    {};


  /* =====================================================
     RENDER SEMUA DATA
  ===================================================== */

  if (
    typeof renderSupplierPayableListFiltered ===
    "function"
  ) {

    renderSupplierPayableListFiltered(
      {}
    );

  }


  /* =====================================================
     FOCUS KEMBALI KE SEARCH
  ===================================================== */

  const search =
    document.getElementById(
      "payableSearchFilter"
    );


  if (
    search
  ) {

    /*
       Timeout kecil membantu
       browser Android menyelesaikan
       event klik terlebih dahulu.
    */

    setTimeout(
      () => {

        try {

          search.focus();

        }

        catch (
          error
        ) {

          /*
             Abaikan error focus
             pada browser tertentu.
          */

        }

      },
      50
    );

  }


  /* =====================================================
     NOTIFIKASI
  ===================================================== */

  if (
    typeof showToast ===
    "function"
  ) {

    showToast(
      "Filter hutang supplier berhasil dikosongkan.",
      "success"
    );

  }


  return true;

}


/* =========================================================
   RESET FILTER DENGAN KEYBOARD
========================================================= */

function resetSupplierPayableFilterWithEscape(
  event
) {

  if (!event) {

    return;

  }


  if (
    event.key ===
    "Escape"
  ) {

    event.preventDefault();

    clearSupplierPayableFilter();

  }

}


/* =========================================================
   PASANG EVENT SEARCH
========================================================= */

function bindSupplierPayableFilterEvents() {

  const search =
    document.getElementById(
      "payableSearchFilter"
    );


  if (
    search
  ) {

    /*
       Hindari listener ganda.
    */

    if (
      search.dataset.payableFilterBound !==
      "1"
    ) {

      search.addEventListener(
        "keydown",
        handleSupplierPayableSearchKeydown
      );


      search.addEventListener(
        "keydown",
        resetSupplierPayableFilterWithEscape
      );


      search.dataset.payableFilterBound =
        "1";

    }

  }

}


/* =========================================================
   INIT FILTER
========================================================= */

function initSupplierPayableFilter() {

  bindSupplierPayableFilterEvents();

  window.activeSupplierPayableFilters =
    window.activeSupplierPayableFilters ||
    {};

}


/* =========================================================
   END BAGIAN 6J-03B
========================================================= */


/* =========================================================
   FAEZA ERP V2
   BAGIAN 6J-03C
   POPULATE SUPPLIER PAYABLE FILTER
========================================================= */

function populateSupplierPayableFilter() {

  const select =
    document.getElementById(
      "payableSupplierFilter"
    );


  if (!select) {

    return false;

  }


  /*
     Simpan pilihan sebelumnya
     agar tidak hilang saat refresh.
  */

  const previousValue =
    select.value ||
    "";


  /*
     Ambil supplier dari database.
  */

  const suppliers =
    Array.isArray(
      db.suppliers
    )
      ? db.suppliers
      : [];


  /*
     Kosongkan dropdown.
  */

  select.innerHTML = "";


  /*
     Pilihan default.
  */

  const allOption =
    document.createElement(
      "option"
    );


  allOption.value =
    "";


  allOption.textContent =
    "Semua Supplier";


  select.appendChild(
    allOption
  );


  /*
     Urutkan berdasarkan nama.
  */

  const sortedSuppliers =
    suppliers
      .slice()
      .sort(
        (
          a,
          b
        ) => {

          const nameA =
            String(
              a.name ||
              a.supplierName ||
              a.companyName ||
              ""
            )
            .trim()
            .toLowerCase();


          const nameB =
            String(
              b.name ||
              b.supplierName ||
              b.companyName ||
              ""
            )
            .trim()
            .toLowerCase();


          return nameA.localeCompare(
            nameB
          );

        }
      );


  /*
     Masukkan supplier ke dropdown.
  */

  sortedSuppliers.forEach(
    supplier => {

      if (
        !supplier.id
      ) {

        return;

      }


      const option =
        document.createElement(
          "option"
        );


      option.value =
        supplier.id;


      option.textContent =
        supplier.name ||
        supplier.supplierName ||
        supplier.companyName ||
        "Supplier";


      select.appendChild(
        option
      );

    }
  );


  /*
     Kembalikan pilihan sebelumnya
     jika supplier tersebut masih ada.
  */

  if (
    previousValue
  ) {

    const exists =
      Array.from(
        select.options
      )
      .some(
        option =>
          String(
            option.value
          ) ===
          String(
            previousValue
          )
      );


    if (
      exists
    ) {

      select.value =
        previousValue;

    }

  }


  return true;

}


/* =========================================================
   REFRESH SUPPLIER FILTER
========================================================= */

function refreshSupplierPayableFilter() {

  const currentValue =
    document.getElementById(
      "payableSupplierFilter"
    )?.value ||
    "";


  populateSupplierPayableFilter();


  const select =
    document.getElementById(
      "payableSupplierFilter"
    );


  if (
    select &&
    currentValue
  ) {

    select.value =
      currentValue;

  }


  return true;

}


/* =========================================================
   SUPPLIER DATA CHANGED
========================================================= */

function onSupplierDataChangedForPayable() {

  refreshSupplierPayableFilter();


  /*
     Jangan mengubah filter lainnya.
  */

  if (
    typeof applySupplierPayableFilter ===
    "function"
  ) {

    applySupplierPayableFilter();

  }

}


/* =========================================================
   INIT SUPPLIER PAYABLE DROPDOWN
========================================================= */

function initSupplierPayableSupplierFilter() {

  populateSupplierPayableFilter();

}


