/* =========================================================
   FAEZA ERP V2
   BAGIAN 6J-03D
   GET SUPPLIER PAYABLE DETAIL
========================================================= */

function getSupplierPayableDetail(
  payableId
) {

  ensurePayableStorage();


  /*
     Validasi ID
  */

  if (!payableId) {

    return null;

  }


  /*
     Ambil data hutang
  */

  const payable =
    getPayableById(
      payableId
    );


  if (!payable) {

    return null;

  }


  /*
     Hitung ulang saldo terlebih dahulu
     agar detail selalu menggunakan
     angka terbaru.
  */

  recalculateSupplierPayable(
    payable.id
  );


  /*
     Ambil supplier
  */

  const supplier =
    getSupplierById(
      payable.supplierId
    );


  /*
     Ambil seluruh pembayaran,
     termasuk yang VOID.
  */

  const allPayments =
    db.payablePayments
      .filter(
        payment => {

          return (

            String(
              payment.payableId
            ) ===
            String(
              payable.id
            )

          );

        }
      )
      .sort(
        (
          a,
          b
        ) => {

          return String(
            b.date ||
            ""
          )
          .localeCompare(
            String(
              a.date ||
              ""
            )
          );

        }
      );


  /*
     Ambil pembayaran aktif.
     VOID tidak dihitung sebagai
     pembayaran hutang.
  */

  const activePayments =
    allPayments.filter(
      payment => {

        return (
          String(
            payment.status ||
            "POSTED"
          ).toUpperCase() !==
          "VOID"
        );

      }
    );


  /*
     Total pembayaran aktif.
  */

  const totalPaid =
    activePayments.reduce(
      (
        total,
        payment
      ) => {

        return (

          total +

          (
            Number(
              payment.amount
            ) || 0
          )

        );

      },
      0
    );


  /*
     Nilai hutang awal.
  */

  const totalAmount =
    Number(
      payable.amount
    ) || 0;


  /*
     Sisa hutang.
  */

  const remaining =
    Math.max(
      0,
      totalAmount -
      totalPaid
    );


  /*
     Hari keterlambatan.
  */

  const daysOverdue =
    getPayableDaysOverdue(
      payable
    );


  /*
     Aging bucket.
  */

  const ageBucket =
    getPayableAgeBucket(
      payable
    );


  /*
     Status aktual.
  */

  let status =
    "OPEN";


  if (
    remaining <= 0
  ) {

    status =
      "PAID";

  }

  else if (
    totalPaid > 0
  ) {

    status =
      "PARTIAL";

  }


  /*
     Sinkronkan object utama.
  */

  payable.paid =
    totalPaid;


  payable.remaining =
    remaining;


  payable.status =
    status;


  payable.updatedAt =
    new Date().toISOString();


  /*
     Kembalikan object detail lengkap.
  */

  return {

    payable,

    supplier,

    payments:
      activePayments,

    allPayments,

    totalAmount,

    totalPaid,

    remaining,

    status,

    daysOverdue,

    ageBucket,

    isPaid:
      remaining <= 0,

    isOverdue:
      remaining > 0 &&
      daysOverdue > 0

  };

}


/* =========================================================
   GET PAYABLE PAYMENT COUNT
========================================================= */

function getSupplierPayablePaymentCount(
  payableId
) {

  const detail =
    getSupplierPayableDetail(
      payableId
    );


  if (!detail) {

    return 0;

  }


  return detail.allPayments.length;

}


