/* =========================================================
   FAEZA ERP V2
   BAGIAN 6J-03E
   OPEN SUPPLIER PAYABLE DETAIL
========================================================= */

function openSupplierPayableDetail(
  payableId
) {

  if (!payableId) {

    showToast(
      "ID hutang supplier tidak ditemukan.",
      "error"
    );

    return false;

  }


  /*
     Ambil detail terbaru.
  */

  const detail =
    getSupplierPayableDetail(
      payableId
    );


  if (!detail) {

    showToast(
      "Data hutang supplier tidak ditemukan.",
      "error"
    );

    return false;

  }


  /*
     Simpan ID aktif.
  */

  window.activeSupplierPayableId =
    payableId;


  /*
     Cari modal.
  */

  const modal =
    document.getElementById(
      "supplierPayableDetailModal"
    );


  /*
     Jika modal belum tersedia,
     tampilkan ringkasan sederhana.
  */

  if (!modal) {

    showToast(
      `${detail.payable.payableNumber} | Sisa ${formatRupiah(detail.remaining)}`,
      "info"
    );

    return false;

  }


  /* =====================================================
     ISI INFORMASI UTAMA
  ===================================================== */

  setPayableDetailField(
    "supplier",
    detail.payable.supplierName ||
    getSupplierNameById(
      detail.payable.supplierId
    )
  );


  setPayableDetailField(
    "payableNumber",
    detail.payable.payableNumber ||
    "-"
  );


  setPayableDetailField(
    "purchaseNumber",
    detail.payable.purchaseNumber ||
    "-"
  );


  setPayableDetailField(
    "invoiceNumber",
    detail.payable.invoiceNumber ||
    "-"
  );


  setPayableDetailField(
    "date",
    detail.payable.date
      ? formatPrintDate(
          detail.payable.date
        )
      : "-"
  );


  setPayableDetailField(
    "dueDate",
    detail.payable.dueDate
      ? formatPrintDate(
          detail.payable.dueDate
        )
      : "-"
  );


  setPayableDetailField(
    "amount",
    formatRupiah(
      detail.totalAmount
    )
  );


  setPayableDetailField(
    "paid",
    formatRupiah(
      detail.totalPaid
    )
  );


  setPayableDetailField(
    "remaining",
    formatRupiah(
      detail.remaining
    )
  );


  setPayableDetailField(
    "status",
    detail.status
  );


  setPayableDetailField(
    "age",
    detail.ageBucket
  );


  setPayableDetailField(
    "overdue",
    detail.daysOverdue +
    " hari"
  );


  /* =====================================================
     ISI CATATAN
  ===================================================== */

  setPayableDetailField(
    "notes",
    detail.payable.notes ||
    "-"
  );


  /* =====================================================
     RENDER RIWAYAT PEMBAYARAN
  ===================================================== */

  renderSupplierPayableDetailPayments(
    detail.allPayments
  );


  /* =====================================================
     TOMBOL BAYAR
  ===================================================== */

  const payButton =
    document.getElementById(
      "supplierPayableDetailPayButton"
    );


  if (
    payButton
  ) {

    if (
      detail.remaining > 0
    ) {

      payButton.disabled =
        false;

      payButton.style.display =
        "";

      payButton.onclick =
        function () {

          openSupplierPayablePayment(
            detail.payable.id
          );

        };

    }

    else {

      payButton.disabled =
        true;

      payButton.style.display =
        "";

      payButton.textContent =
        "Sudah Lunas";

    }

  }


  /* =====================================================
     TAMPILKAN MODAL
  ===================================================== */

  modal.removeAttribute(
    "hidden"
  );


  modal.classList.add(
    "active"
  );


  /*
     Scroll ke bagian atas modal.
  */

  try {

    modal.scrollTop =
      0;

  }

  catch (
    error
  ) {

    /* Browser tertentu dapat mengabaikan. */

  }


  return true;

}


/* =========================================================
   SET DETAIL FIELD
========================================================= */

function setPayableDetailField(
  key,
  value
) {

  const element =
    document.querySelector(
      `[data-payable-detail="${key}"]`
    );


  if (!element) {

    return;

  }


  element.textContent =
    value === undefined ||
    value === null
      ? "-"
      : value;

}


/* =========================================================
   RENDER PAYMENT HISTORY
========================================================= */

function renderSupplierPayableDetailPayments(
  payments = []
) {

  const tbody =
    document.getElementById(
      "supplierPayableDetailPaymentBody"
    );


  if (!tbody) {

    return;

  }


  const list =
    Array.isArray(
      payments
    )
      ? payments
      : [];


  if (
    !list.length
  ) {

    tbody.innerHTML = `

      <tr>

        <td
          colspan="7"
          class="empty-state"
        >

          Belum ada pembayaran.

        </td>

      </tr>

    `;

    return;

  }


  tbody.innerHTML =
    list
      .map(
        (
          payment,
          index
        ) => {

          const status =
            String(
              payment.status ||
              "POSTED"
            ).toUpperCase();


          const isVoid =
            status ===
            "VOID";


          return `

            <tr
              class="${
                isVoid
                  ? "payment-void-row"
                  : ""
              }"
            >

              <td>

                ${index + 1}

              </td>


              <td>

                ${escapeHTML(
                  payment.paymentNumber ||
                  "-"
                )}

              </td>


              <td>

                ${
                  payment.date
                    ? formatPrintDate(
                        payment.date
                      )
                    : "-"
                }

              </td>


              <td class="money">

                ${formatRupiah(
                  payment.amount
                )}

              </td>


              <td>

                ${escapeHTML(
                  payment.method ||
                  "-"
                )}

              </td>


              <td>

                ${
                  isVoid

                    ? `

                      <span
                        class="badge badge-danger"
                      >
                        VOID
                      </span>

                    `

                    : `

                      <span
                        class="badge badge-success"
                      >
                        POSTED
                      </span>

                    `
                }

              </td>


              <td>

                ${
                  isVoid

                    ? escapeHTML(
                        payment.voidReason ||
                        "-"
                      )

                    : escapeHTML(
                        payment.reference ||
                        "-"
                      )
                }

              </td>

            </tr>

          `;

        }
      )
      .join("");

}


