/* =========================================================
   FAEZA ERP V2
   BAGIAN 6J-04A
   SUPPLIER PAYABLE AGING FOUNDATION
========================================================= */


/* =========================================================
   GET PAYABLE AGING DAYS
========================================================= */

function getSupplierPayableAgingDays(
  payable
) {

  if (!payable) {

    return 0;

  }


  /*
     Hutang lunas tidak masuk aging.
  */

  if (
    Number(
      payable.remaining
    ) <= 0
  ) {

    return 0;

  }


  /*
     Jika tidak ada jatuh tempo,
     gunakan tanggal transaksi.
  */

  const baseDate =
    payable.dueDate ||
    payable.date ||
    today();


  const due =
    new Date(
      baseDate
    );


  const now =
    new Date(
      today()
    );


  /*
     Normalisasi jam agar
     perhitungan konsisten.
  */

  due.setHours(
    0,
    0,
    0,
    0
  );


  now.setHours(
    0,
    0,
    0,
    0
  );


  const difference =
    now.getTime() -
    due.getTime();


  const days =
    Math.floor(
      difference /
      (
        1000 *
        60 *
        60 *
        24
      )
    );


  return Math.max(
    0,
    days
  );

}


/* =========================================================
   GET PAYABLE AGING BUCKET
========================================================= */

function getSupplierPayableAgingBucket(
  payable
) {

  if (!payable) {

    return "UNKNOWN";

  }


  if (
    Number(
      payable.remaining
    ) <= 0
  ) {

    return "PAID";

  }


  const days =
    getSupplierPayableAgingDays(
      payable
    );


  if (
    days <= 0
  ) {

    return "CURRENT";

  }


  if (
    days <= 30
  ) {

    return "1-30";

  }


  if (
    days <= 60
  ) {

    return "31-60";

  }


  if (
    days <= 90
  ) {

    return "61-90";

  }


  return ">90";

}


/* =========================================================
   GET AGING LABEL
========================================================= */

function getSupplierPayableAgingLabel(
  bucket
) {

  switch (
    String(
      bucket ||
      ""
    ).toUpperCase()
  ) {

    case "CURRENT":

      return "Belum Jatuh Tempo";


    case "1-30":

      return "1–30 Hari";


    case "31-60":

      return "31–60 Hari";


    case "61-90":

      return "61–90 Hari";


    case ">90":

      return ">90 Hari";


    case "PAID":

      return "Lunas";


    default:

      return "-";

  }

}


/* =========================================================
   GET AGING BUCKET OBJECT
========================================================= */

function createSupplierPayableAgingBucket() {

  return {

    CURRENT: {

      count: 0,

      amount: 0

    },

    "1-30": {

      count: 0,

      amount: 0

    },

    "31-60": {

      count: 0,

      amount: 0

    },

    "61-90": {

      count: 0,

      amount: 0

    },

    ">90": {

      count: 0,

      amount: 0

    },

    PAID: {

      count: 0,

      amount: 0

    }

  };

}


/* =========================================================
   CALCULATE SUPPLIER PAYABLE AGING
========================================================= */

function calculateSupplierPayableAging(
  filters = {}
) {

  ensurePayableStorage();


  const supplierId =
    filters.supplierId ||
    "";


  const dateFrom =
    filters.dateFrom ||
    "";


  const dateTo =
    filters.dateTo ||
    "";


  const aging =
    createSupplierPayableAgingBucket();


  let totalOutstanding =
    0;


  let totalCount =
    0;


  const payables =
    db.payables
      .map(
        payable => {

          recalculateSupplierPayable(
            payable.id
          );


          return payable;

        }
      );


  payables.forEach(
    payable => {

      /*
         Filter supplier.
      */

      if (
        supplierId &&
        String(
          payable.supplierId
        ) !==
        String(
          supplierId
        )
      ) {

        return;

      }


      /*
         Filter tanggal transaksi.
      */

      if (
        dateFrom &&
        String(
          payable.date ||
          ""
        ) < dateFrom
      ) {

        return;

      }


      if (
        dateTo &&
        String(
          payable.date ||
          ""
        ) > dateTo
      ) {

        return;

      }


      const bucket =
        getSupplierPayableAgingBucket(
          payable
        );


      if (
        !aging[bucket]
      ) {

        return;

      }


      const amount =
        Number(
          payable.remaining
        ) || 0;


      aging[bucket].count +=
        1;


      aging[bucket].amount +=
        amount;


      /*
         Outstanding hanya
         menghitung hutang yang
         belum lunas.
      */

      if (
        bucket !==
        "PAID"
      ) {

        totalOutstanding +=
          amount;

        totalCount++;

      }

    }
  );


  return {

    buckets:
      aging,

    totalOutstanding,

    totalCount

  };

}


/* =========================================================
   GET SUPPLIER PAYABLE AGING TOTAL
========================================================= */

function getSupplierPayableAgingTotal(
  filters = {}
) {

  const result =
    calculateSupplierPayableAging(
      filters
    );


  return {

    count:
      result.totalCount,

    amount:
      result.totalOutstanding

  };

}


