/* =========================================================
   SAFE SET ELEMENT TEXT
========================================================= */

function setElementText(
  id,
  value
) {

  const element =
    document.getElementById(
      id
    );


  if (!element) {

    return;

  }


  element.textContent =
    value === undefined ||
    value === null
      ? "-"
      : value;

}


/* =========================================================
   RENDER AGING TABLE
========================================================= */

function renderSupplierPayableAgingTable(
  filters = {}
) {

  const result =
    calculateSupplierPayableAging(
      filters
    );


  const tbody =
    document.getElementById(
      "supplierPayableAgingBody"
    );


  if (!tbody) {

    return result;

  }


  const rows = [

    {
      key: "CURRENT",

      label:
        "Belum Jatuh Tempo"

    },

    {
      key: "1-30",

      label:
        "1–30 Hari"

    },

    {
      key: "31-60",

      label:
        "31–60 Hari"

    },

    {
      key: "61-90",

      label:
        "61–90 Hari"

    },

    {
      key: ">90",

      label:
        ">90 Hari"

    }

  ];


  tbody.innerHTML =
    rows
      .map(
        row => {

          const bucket =
            result.buckets[
              row.key
            ];


          const amount =
            Number(
              bucket.amount
            ) || 0;


          const percentage =
            result.totalOutstanding >
            0

              ? (
                  amount /
                  result.totalOutstanding
                ) *
                100

              : 0;


          let severity =
            "normal";


          if (
            row.key ===
            "1-30"
          ) {

            severity =
              "warning";

          }


          if (
            row.key ===
            "31-60"
          ) {

            severity =
              "warning";

          }


          if (
            row.key ===
            "61-90"
          ) {

            severity =
              "danger";

          }


          if (
            row.key ===
            ">90"
          ) {

            severity =
              "critical";

          }


          return `

            <tr
              class="aging-${severity}"
            >

              <td>

                <strong>

                  ${row.label}

                </strong>

              </td>


              <td>

                ${formatNumber(
                  bucket.count
                )}

              </td>


              <td class="money">

                ${formatRupiah(
                  amount
                )}

              </td>


              <td>

                ${percentage.toFixed(
                  1
                )}%

              </td>

            </tr>

          `;

        }
      )
      .join("");


  return result;

}


/* =========================================================
   RENDER COMPLETE AGING
========================================================= */

function renderSupplierPayableAging(
  filters = {}
) {

  const result =
    renderSupplierPayableAgingSummary(
      filters
    );


  renderSupplierPayableAgingTable(
    filters
  );


  return result;

}


