/* =========================================================
   FAEZA ERP V2
   BAGIAN 6J-04C
   SUPPLIER PAYABLE AGING BY SUPPLIER
========================================================= */


/* =========================================================
   CALCULATE AGING PER SUPPLIER
========================================================= */

function calculateSupplierPayableAgingBySupplier(
  filters = {}
) {

  ensurePayableStorage();


  const supplierFilter =
    filters.supplierId ||
    "";


  const search =
    String(
      filters.search ||
      ""
    )
    .trim()
    .toLowerCase();


  const dateFrom =
    filters.dateFrom ||
    "";


  const dateTo =
    filters.dateTo ||
    "";


  const supplierMap =
    {};


  const payables =
    db.payables
      .map(
        payable => {

          recalculateSupplierPayable(
            payable.id
          );

          return payable;

        }
      );


  payables.forEach(
    payable => {

      /*
         Hanya hutang yang masih mempunyai
         saldo outstanding.
      */

      const remaining =
        Number(
          payable.remaining
        ) || 0;


      if (
        remaining <= 0
      ) {

        return;

      }


      /*
         Filter supplier.
      */

      if (
        supplierFilter &&
        String(
          payable.supplierId
        ) !==
        String(
          supplierFilter
        )
      ) {

        return;

      }


      /*
         Filter tanggal transaksi.
      */

      if (
        dateFrom &&
        String(
          payable.date ||
          ""
        ) < dateFrom
      ) {

        return;

      }


      if (
        dateTo &&
        String(
          payable.date ||
          ""
        ) > dateTo
      ) {

        return;

      }


      const supplierName =
        payable.supplierName ||
        getSupplierNameById(
          payable.supplierId
        ) ||
        "Supplier Tanpa Nama";


      /*
         Filter pencarian.
      */

      if (
        search &&
        !supplierName
          .toLowerCase()
          .includes(
            search
          )
      ) {

        return;

      }


      const supplierId =
        payable.supplierId ||
        "unknown";


      /*
         Buat supplier baru.
      */

      if (
        !supplierMap[
          supplierId
        ]
      ) {

        supplierMap[
          supplierId
        ] = {

          supplierId,

          supplierName,

          totalOutstanding:
            0,

          totalInvoices:
            0,

          current: {

            count: 0,

            amount: 0

          },

          "1-30": {

            count: 0,

            amount: 0

          },

          "31-60": {

            count: 0,

            amount: 0

          },

          "61-90": {

            count: 0,

            amount: 0

          },

          ">90": {

            count: 0,

            amount: 0

          },

          oldestDays:
            0,

          oldestDueDate:
            "",

          invoices: []

        };

      }


      const supplier =
        supplierMap[
          supplierId
        ];


      const bucket =
        getSupplierPayableAgingBucket(
          payable
        );


      /*
         Normalisasi bucket.
      */

      let agingBucket =
        String(
          bucket ||
          ""
        ).toUpperCase();


      if (
        agingBucket ===
        "CURRENT"
      ) {

        agingBucket =
          "current";

      }

      else if (
        agingBucket ===
        "1-30"
      ) {

        agingBucket =
          "1-30";

      }

      else if (
        agingBucket ===
        "31-60"
      ) {

        agingBucket =
          "31-60";

      }

      else if (
        agingBucket ===
        "61-90"
      ) {

        agingBucket =
          "61-90";

      }

      else if (
        agingBucket ===
        ">90"
      ) {

        agingBucket =
          ">90";

      }

      else {

        return;

      }


      /*
         Tambahkan nilai.
      */

      supplier[
        agingBucket
      ].count +=
        1;


      supplier[
        agingBucket
      ].amount +=
        remaining;


      supplier.totalOutstanding +=
        remaining;


      supplier.totalInvoices +=
        1;


      /*
         Hitung umur hutang.
      */

      const days =
        getSupplierPayableAgingDays(
          payable
        );


      if (
        days >
        supplier.oldestDays
      ) {

        supplier.oldestDays =
          days;


        supplier.oldestDueDate =
          payable.dueDate ||
          "";

      }


      /*
         Simpan detail invoice.
      */

      supplier.invoices.push({

        payableId:
          payable.id,

        payableNumber:
          payable.payableNumber ||
          "-",

        purchaseNumber:
          payable.purchaseNumber ||
          "-",

        invoiceNumber:
          payable.invoiceNumber ||
          "-",

        date:
          payable.date ||
          "",

        dueDate:
          payable.dueDate ||
          "",

        amount:
          Number(
            payable.amount
          ) || 0,

        paid:
          Number(
            payable.paid
          ) || 0,

        remaining,

        agingDays:
          days,

        agingBucket:
          agingBucket

      });

    }
  );


  /*
     Convert object menjadi array.
  */

  const result =
    Object.values(
      supplierMap
    );


  /*
     Urutkan berdasarkan
     outstanding terbesar.
  */

  result.sort(
    (
      a,
      b
    ) => {

      return (
        b.totalOutstanding -
        a.totalOutstanding
      );

    }
  );


  /*
     Urutkan invoice masing-masing supplier
     berdasarkan umur tertua.
  */

  result.forEach(
    supplier => {

      supplier.invoices.sort(
        (
          a,
          b
        ) => {

          return (
            b.agingDays -
            a.agingDays
          );

        }
      );

    }
  );


  return result;

}


/* =========================================================
   GET SUPPLIER WITH HIGHEST PAYABLE
========================================================= */

function getSupplierWithHighestPayable(
  filters = {}
) {

  const list =
    calculateSupplierPayableAgingBySupplier(
      filters
    );


  if (
    !list.length
  ) {

    return null;

  }


  return list[0];

}


/* =========================================================
   GET CRITICAL SUPPLIERS
========================================================= */

function getCriticalSupplierPayables(
  filters = {}
) {

  const list =
    calculateSupplierPayableAgingBySupplier(
      filters
    );


  return list.filter(
    supplier => {

      return (

        supplier[">90"].amount >
        0

        ||

        supplier["61-90"].amount >
        0

      );

    }
  );

}


/* =========================================================
   GET SUPPLIER PAYABLE AGING TOTAL
========================================================= */

function getSupplierPayableAgingBySupplierTotal(
  filters = {}
) {

  const list =
    calculateSupplierPayableAgingBySupplier(
      filters
    );


  return list.reduce(
    (
      total,
      supplier
    ) => {

      total.count +=
        supplier.totalInvoices;


      total.amount +=
        supplier.totalOutstanding;


      return total;

    },
    {

      count: 0,

      amount: 0

    }
  );

}


