/* =========================================================
   FAEZA ERP V2
   BAGIAN 6J-04D
   SUPPLIER PAYABLE AGING INVOICE DETAIL
========================================================= */


/* =========================================================
   GET AGING INVOICES BY SUPPLIER
========================================================= */

function getSupplierPayableAgingInvoices(
  supplierId,
  filters = {}
) {

  if (!supplierId) {

    return [];

  }


  const supplierList =
    calculateSupplierPayableAgingBySupplier({

      ...filters,

      supplierId

    });


  if (
    !supplierList.length
  ) {

    return [];

  }


  const supplier =
    supplierList[0];


  return Array.isArray(
    supplier.invoices
  )
    ? supplier.invoices
    : [];

}


/* =========================================================
   RENDER AGING INVOICE DETAIL
========================================================= */

function renderSupplierPayableAgingInvoices(
  supplierId,
  filters = {}
) {

  const tbody =
    document.getElementById(
      "supplierPayableAgingInvoiceBody"
    );


  if (!tbody) {

    return [];

  }


  const invoices =
    getSupplierPayableAgingInvoices(
      supplierId,
      filters
    );


  if (
    !invoices.length
  ) {

    tbody.innerHTML = `

      <tr>

        <td
          colspan="10"
          class="empty-state"
        >

          Tidak ada invoice outstanding
          untuk supplier ini.

        </td>

      </tr>

    `;

    return [];

  }


  tbody.innerHTML =
    invoices
      .map(
        (
          invoice,
          index
        ) => {

          const days =
            Number(
              invoice.agingDays
            ) || 0;


          let agingClass =
            "aging-current";


          if (
            days > 90
          ) {

            agingClass =
              "aging-critical";

          }

          else if (
            days > 60
          ) {

            agingClass =
              "aging-danger";

          }

          else if (
            days > 30
          ) {

            agingClass =
              "aging-warning";

          }


          return `

            <tr
              class="${agingClass}"
            >

              <td>

                ${index + 1}

              </td>


              <td>

                <strong>

                  ${escapeHTML(
                    invoice.payableNumber ||
                    "-"
                  )}

                </strong>

              </td>


              <td>

                ${escapeHTML(
                  invoice.invoiceNumber ||
                  "-"
                )}

              </td>


              <td>

                ${escapeHTML(
                  invoice.purchaseNumber ||
                  "-"
                )}

              </td>


              <td>

                ${
                  invoice.date
                    ? formatPrintDate(
                        invoice.date
                      )
                    : "-"
                }

              </td>


              <td>

                ${
                  invoice.dueDate
                    ? formatPrintDate(
                        invoice.dueDate
                      )
                    : "-"
                }

              </td>


              <td class="money">

                ${formatRupiah(
                  invoice.amount
                )}

              </td>


              <td class="money">

                ${formatRupiah(
                  invoice.paid
                )}

              </td>


              <td class="money">

                <strong>

                  ${formatRupiah(
                    invoice.remaining
                  )}

                </strong>

              </td>


              <td>

                <span
                  class="badge"
                >

                  ${
                    getSupplierPayableAgingLabel(
                      invoice.agingBucket
                    )
                  }

                </span>

              </td>


              <td>

                <span
                  class="badge"
                >

                  ${days} hari

                </span>

              </td>


              <td>

                <button
                  type="button"
                  class="btn btn-sm"
                  onclick="
                    openSupplierPayableDetail(
                      '${escapeJS(
                        invoice.payableId
                      )}'
                    )
                  "
                >

                  Detail

                </button>

              </td>

            </tr>

          `;

        }
      )
      .join("");


  return invoices;

}


/* =========================================================
   OPEN AGING SUPPLIER DETAIL
========================================================= */

function openSupplierPayableAgingSupplier(
  supplierId,
  filters = {}
) {

  if (!supplierId) {

    showToast(
      "Supplier belum dipilih.",
      "warning"
    );

    return false;

  }


  const supplier =
    getSupplierById(
      supplierId
    );


  const invoices =
    getSupplierPayableAgingInvoices(
      supplierId,
      filters
    );


  if (
    !supplier &&
    !invoices.length
  ) {

    showToast(
      "Data supplier tidak ditemukan.",
      "error"
    );

    return false;

  }


  window.activeSupplierPayableAgingSupplierId =
    supplierId;


  /*
     Isi informasi supplier.
  */

  setElementText(
    "payableAgingSupplierName",
    supplier?.name ||
    supplier?.supplierName ||
    "Supplier"
  );


  setElementText(
    "payableAgingSupplierInvoiceCount",
    formatNumber(
      invoices.length
    )
  );


  const totalOutstanding =
    invoices.reduce(
      (
        total,
        invoice
      ) => {

        return (
          total +
          (
            Number(
              invoice.remaining
            ) || 0
          )
        );

      },
      0
    );


  setElementText(
    "payableAgingSupplierOutstanding",
    formatRupiah(
      totalOutstanding
    )
  );


  /*
     Cari invoice tertua.
  */

  const oldest =
    invoices.length
      ? invoices.reduce(
          (
            current,
            invoice
          ) => {

            if (
              !current
            ) {

              return invoice;

            }


            return (
              Number(
                invoice.agingDays
              ) >
              Number(
                current.agingDays
              )
            )
              ? invoice
              : current;

          },
          null
        )
      : null;


  setElementText(
    "payableAgingSupplierOldest",
    oldest
      ? `${oldest.agingDays} hari`
      : "-"
  );


  /*
     Render invoice.
  */

  renderSupplierPayableAgingInvoices(
    supplierId,
    filters
  );


  /*
     Buka modal jika tersedia.
  */

  const modal =
    document.getElementById(
      "supplierPayableAgingDetailModal"
    );


  if (
    modal
  ) {

    modal.removeAttribute(
      "hidden"
    );


    modal.classList.add(
      "active"
    );

  }


  return true;

}


/* =========================================================
   CLOSE AGING SUPPLIER DETAIL
========================================================= */

function closeSupplierPayableAgingSupplier() {

  const modal =
    document.getElementById(
      "supplierPayableAgingDetailModal"
    );


  if (
    modal
  ) {

    modal.classList.remove(
      "active"
    );


    modal.setAttribute(
      "hidden",
      "hidden"
    );

  }


  window.activeSupplierPayableAgingSupplierId =
    "";


  return true;

}


