/* =========================================================
   RENDER PAYABLE REPORT TABLE
========================================================= */

function renderSupplierPayableReportTable(
  filters = {}
) {

  const tbody =
    document.getElementById(
      "supplierPayableReportBody"
    );


  const report =
    getSupplierPayableReportData(
      filters
    );


  if (!tbody) {

    return report;

  }


  if (
    !report.rows.length
  ) {

    tbody.innerHTML = `

      <tr>

        <td
          colspan="12"
          class="empty-state"
        >

          Tidak ada data hutang
          sesuai filter.

        </td>

      </tr>

    `;

    return report;

  }


  tbody.innerHTML =
    report.rows
      .map(
        (
          row,
          index
        ) => {

          let statusClass =
            "status-open";


          if (
            row.status ===
            "PARTIAL"
          ) {

            statusClass =
              "status-partial";

          }


          if (
            row.status ===
            "PAID"
          ) {

            statusClass =
              "status-paid";

          }


          let agingClass =
            "";


          if (
            row.remaining > 0
          ) {

            if (
              row.agingDays >
              90
            ) {

              agingClass =
                "aging-critical";

            }

            else if (
              row.agingDays >
              60
            ) {

              agingClass =
                "aging-danger";

            }

            else if (
              row.agingDays >
              30
            ) {

              agingClass =
                "aging-warning";

            }

          }


          return `

            <tr
              class="${agingClass}"
            >

              <td>

                ${index + 1}

              </td>


              <td>

                <strong>

                  ${escapeHTML(
                    row.payableNumber
                  )}

                </strong>

              </td>


              <td>

                ${escapeHTML(
                  row.supplierName
                )}

              </td>


              <td>

                ${escapeHTML(
                  row.purchaseNumber
                )}

              </td>


              <td>

                ${escapeHTML(
                  row.invoiceNumber
                )}

              </td>


              <td>

                ${
                  row.date
                    ? formatPrintDate(
                        row.date
                      )
                    : "-"
                }

              </td>


              <td>

                ${
                  row.dueDate
                    ? formatPrintDate(
                        row.dueDate
                      )
                    : "-"
                }

              </td>


              <td class="money">

                ${formatRupiah(
                  row.amount
                )}

              </td>


              <td class="money">

                ${formatRupiah(
                  row.paid
                )}

              </td>


              <td class="money">

                <strong>

                  ${formatRupiah(
                    row.remaining
                  )}

                </strong>

              </td>


              <td>

                <span
                  class="badge ${statusClass}"
                >

                  ${escapeHTML(
                    row.status
                  )}

                </span>

              </td>


              <td>

                ${
                  row.remaining > 0

                    ? `

                      <span
                        class="badge"
                      >

                        ${escapeHTML(
                          row.agingLabel
                        )}

                      </span>

                      <small>

                        ${
                          row.agingDays
                        } hari

                      </small>

                    `

                    : `

                      <span
                        class="badge status-paid"
                      >

                        Lunas

                      </span>

                    `
                }

              </td>


              <td>

                <button
                  type="button"
                  class="btn btn-sm"
                  onclick="
                    openSupplierPayableDetail(
                      '${escapeJS(
                        row.id
                      )}'
                    )
                  "
                >

                  Detail

                </button>

              </td>

            </tr>

          `;

        }
      )
      .join("");


  return report;

}


