/* =========================================================
   GET PAYABLE REPORT FILTERS FROM UI
========================================================= */

function getSupplierPayableReportFilters() {

  const supplier =
    document.getElementById(
      "supplierPayableReportSupplier"
    );


  const status =
    document.getElementById(
      "supplierPayableReportStatus"
    );


  const search =
    document.getElementById(
      "supplierPayableReportSearch"
    );


  const dateFrom =
    document.getElementById(
      "supplierPayableReportDateFrom"
    );


  const dateTo =
    document.getElementById(
      "supplierPayableReportDateTo"
    );


  const dueFrom =
    document.getElementById(
      "supplierPayableReportDueFrom"
    );


  const dueTo =
    document.getElementById(
      "supplierPayableReportDueTo"
    );


  return {

    supplierId:
      supplier?.value ||
      "",

    status:
      status?.value ||
      "ALL",

    search:
      search?.value ||
      "",

    dateFrom:
      dateFrom?.value ||
      "",

    dateTo:
      dateTo?.value ||
      "",

    dueFrom:
      dueFrom?.value ||
      "",

    dueTo:
      dueTo?.value ||
      ""

  };

}


/* =========================================================
   VALIDATE PAYABLE REPORT FILTER
========================================================= */

function validateSupplierPayableReportFilters(
  filters
) {

  if (!filters) {

    return true;

  }


  if (

    filters.dateFrom &&

    filters.dateTo &&

    filters.dateFrom >
    filters.dateTo

  ) {

    showToast(
      "Tanggal transaksi awal tidak boleh melebihi tanggal akhir.",
      "warning"
    );

    return false;

  }


  if (

    filters.dueFrom &&

    filters.dueTo &&

    filters.dueFrom >
    filters.dueTo

  ) {

    showToast(
      "Tanggal jatuh tempo awal tidak boleh melebihi tanggal akhir.",
      "warning"
    );

    return false;

  }


  return true;

}


/* =========================================================
   APPLY PAYABLE REPORT FILTER
========================================================= */

function applySupplierPayableReportFilter() {

  const filters =
    getSupplierPayableReportFilters();


  if (
    !validateSupplierPayableReportFilters(
      filters
    )
  ) {

    return false;

  }


  window.activeSupplierPayableReportFilters =
    {
      ...filters
    };


  renderSupplierPayableReport(
    filters
  );


  return true;

}


/* =========================================================
   CLEAR PAYABLE REPORT FILTER
========================================================= */

function clearSupplierPayableReportFilter() {

  const supplier =
    document.getElementById(
      "supplierPayableReportSupplier"
    );


  const status =
    document.getElementById(
      "supplierPayableReportStatus"
    );


  const search =
    document.getElementById(
      "supplierPayableReportSearch"
    );


  const dateFrom =
    document.getElementById(
      "supplierPayableReportDateFrom"
    );


  const dateTo =
    document.getElementById(
      "supplierPayableReportDateTo"
    );


  const dueFrom =
    document.getElementById(
      "supplierPayableReportDueFrom"
    );


  const dueTo =
    document.getElementById(
      "supplierPayableReportDueTo"
    );


  /*
     Reset supplier.
  */

  if (
    supplier
  ) {

    supplier.value =
      "";

  }


  /*
     Reset status.
  */

  if (
    status
  ) {

    status.value =
      "ALL";

  }


  /*
     Reset search.
  */

  if (
    search
  ) {

    search.value =
      "";

  }


  /*
     Reset tanggal transaksi.
  */

  if (
    dateFrom
  ) {

    dateFrom.value =
      "";

  }


  if (
    dateTo
  ) {

    dateTo.value =
      "";

  }


  /*
     Reset tanggal jatuh tempo.
  */

  if (
    dueFrom
  ) {

    dueFrom.value =
      "";

  }


  if (
    dueTo
  ) {

    dueTo.value =
      "";

  }


  /*
     Reset state filter.
  */

  window.activeSupplierPayableReportFilters =
    {};


  /*
     Render seluruh data.
  */

  renderSupplierPayableReport(
    {}
  );


  showToast(
    "Filter laporan hutang berhasil dikosongkan.",
    "success"
  );


  return true;

}


/* =========================================================
   SEARCH PAYABLE REPORT
========================================================= */

function searchSupplierPayableReport() {

  return applySupplierPayableReportFilter();

}


/* =========================================================
   RESET PAYABLE REPORT
========================================================= */

function resetSupplierPayableReport() {

  return clearSupplierPayableReportFilter();

}


