/* =========================================================
   ESCAPE CSV VALUE
========================================================= */

function escapeCSVValue(
  value
) {

  if (
    value === undefined ||
    value === null
  ) {

    return '""';

  }


  const text =
    String(
      value
    )
    .replace(
      /"/g,
      '""'
    );


  return `"${text}"`;

}


/* =========================================================
   BUILD PAYABLE CSV
========================================================= */

function buildSupplierPayableCSV(
  filters = {}
) {

  const report =
    getSupplierPayableReportData(
      filters
    );


  const rows =
    report.rows;


  const summary =
    report.summary;


  const csvRows = [];


  /*
     Header laporan.
  */

  csvRows.push(
    [

      "No",

      "No Hutang",

      "Supplier",

      "No Pembelian",

      "No Invoice",

      "Tanggal",

      "Jatuh Tempo",

      "Total Hutang",

      "Sudah Dibayar",

      "Sisa Hutang",

      "Status",

      "Aging",

      "Hari"

    ]
      .map(
        escapeCSVValue
      )
      .join(",")
  );


  /*
     Data hutang.
  */

  rows.forEach(
    (
      row,
      index
    ) => {

      csvRows.push(
        [

          index + 1,

          row.payableNumber,

          row.supplierName,

          row.purchaseNumber,

          row.invoiceNumber,

          row.date
            ? formatPrintDate(
                row.date
              )
            : "",

          row.dueDate
            ? formatPrintDate(
                row.dueDate
              )
            : "",

          row.amount,

          row.paid,

          row.remaining,

          row.status,

          row.agingLabel,

          row.agingDays

        ]
          .map(
            escapeCSVValue
          )
          .join(",")
      );

    }
  );


  /*
     Baris total.
  */

  csvRows.push(
    ""
  );


  csvRows.push(
    [

      "",

      "",

      "",

      "",

      "",

      "",

      "TOTAL",

      summary.amount,

      summary.paid,

      summary.remaining,

      "",

      "",

      ""

    ]
      .map(
        escapeCSVValue
      )
      .join(",")
  );


  /*
     BOM UTF-8 agar Excel membaca
     karakter Indonesia dengan benar.
  */

  return (
    "\uFEFF" +
    csvRows.join("\r\n")
  );

}


/* =========================================================
   DOWNLOAD CSV
========================================================= */

function downloadSupplierPayableCSV() {

  const filters =
    window.activeSupplierPayableReportFilters ||
    {};


  const csv =
    buildSupplierPayableCSV(
      filters
    );


  const blob =
    new Blob(
      [
        csv
      ],
      {
        type:
          "text/csv;charset=utf-8;"
      }
    );


  const url =
    URL.createObjectURL(
      blob
    );


  const link =
    document.createElement(
      "a"
    );


  const now =
    new Date();


  const datePart =
    now
      .toISOString()
      .slice(
        0,
        10
      );


  link.href =
    url;


  link.download =
    `laporan-hutang-supplier-${datePart}.csv`;


  document.body.appendChild(
    link
  );


  link.click();


  document.body.removeChild(
    link
  );


  setTimeout(
    function () {

      URL.revokeObjectURL(
        url
      );

    },
    1000
  );


  showToast(
    "Laporan hutang supplier berhasil diekspor.",
    "success"
  );


  return true;

}


/* =========================================================
   EXPORT CURRENT REPORT
========================================================= */

function exportCurrentSupplierPayableReport() {

  return downloadSupplierPayableCSV();

}


