/* =========================================================
   FAEZA ERP V2
   BAGIAN 6J-06A
   PURCHASE / STOCK-IN REPORT FOUNDATION
========================================================= */


/* =========================================================
   GET PURCHASE REPORT DATA
========================================================= */

function getPurchaseReportData(
  filters = {}
) {

  /*
     Pastikan storage pembelian tersedia.
  */

  ensurePurchaseStorage();


  const supplierId =
    filters.supplierId ||
    "";


  const status =
    String(
      filters.status ||
      "ALL"
    ).toUpperCase();


  const paymentStatus =
    String(
      filters.paymentStatus ||
      "ALL"
    ).toUpperCase();


  const search =
    String(
      filters.search ||
      ""
    )
      .trim()
      .toLowerCase();


  const dateFrom =
    filters.dateFrom ||
    "";


  const dateTo =
    filters.dateTo ||
    "";


  const rows = [];


  /*
     Ambil seluruh pembelian.
  */

  const purchases =
    Array.isArray(
      db.purchases
    )
      ? db.purchases
      : [];


  purchases.forEach(
    purchase => {

      if (!purchase) {

        return;

      }


      /*
         ID supplier.
      */

      const currentSupplierId =
        purchase.supplierId ||
        "";


      /*
         Nama supplier.
      */

      const supplierName =
        purchase.supplierName ||
        getSupplierNameById(
          currentSupplierId
        ) ||
        "-";


      /*
         Filter supplier.
      */

      if (
        supplierId &&
        String(
          currentSupplierId
        ) !==
        String(
          supplierId
        )
      ) {

        return;

      }


      /*
         Tanggal pembelian.
      */

      const purchaseDate =
        purchase.date ||
        purchase.purchaseDate ||
        purchase.createdAt ||
        "";


      /*
         Filter tanggal.
      */

      if (
        dateFrom &&
        String(
          purchaseDate
        ) < dateFrom
      ) {

        return;

      }


      if (
        dateTo &&
        String(
          purchaseDate
        ) > dateTo
      ) {

        return;

      }


      /*
         Nomor pembelian.
      */

      const purchaseNumber =
        purchase.purchaseNumber ||
        purchase.number ||
        purchase.code ||
        "-";


      /*
         Nomor invoice.
      */

      const invoiceNumber =
        purchase.invoiceNumber ||
        purchase.invoice ||
        "-";


      /*
         Items pembelian.
      */

      const items =
        Array.isArray(
          purchase.items
        )
          ? purchase.items
          : [];


      /*
         Hitung jumlah item.
      */

      const itemCount =
        items.reduce(
          (
            total,
            item
          ) => {

            return (

              total +

              (
                Number(
                  item.qty ||
                  item.quantity
                ) || 0
              )

            );

          },
          0
        );


      /*
         Hitung subtotal dari item
         bila total belum tersedia.
      */

      const calculatedTotal =
        items.reduce(
          (
            total,
            item
          ) => {

            const qty =
              Number(
                item.qty ||
                item.quantity
              ) || 0;


            const price =
              Number(
                item.price ||
                item.cost ||
                item.purchasePrice
              ) || 0;


            return (
              total +
              (
                qty *
                price
              )
            );

          },
          0
        );


      /*
         Total pembelian.
      */

      const total =
        Number(
          purchase.total
        ) ||

        Number(
          purchase.grandTotal
        ) ||

        calculatedTotal;


      /*
         Pembayaran pembelian.
      */

      const paid =
        Number(
          purchase.paid
        ) ||

        Number(
          purchase.amountPaid
        ) ||

        0;


      /*
         Sisa pembayaran.
      */

      const remaining =
        Math.max(
          0,
          total -
          paid
        );


      /*
         Status pembayaran.
      */

      let actualPaymentStatus =
        "UNPAID";


      if (
        total <= 0
      ) {

        actualPaymentStatus =
          "NO_VALUE";

      }

      else if (
        remaining <= 0
      ) {

        actualPaymentStatus =
          "PAID";

      }

      else if (
        paid > 0
      ) {

        actualPaymentStatus =
          "PARTIAL";

      }


      /*
         Status pembelian.
      */

      const actualStatus =
        String(
          purchase.status ||
          "POSTED"
        ).toUpperCase();


      /*
         Filter status pembelian.
      */

      if (
        status !== "ALL" &&
        actualStatus !== status
      ) {

        return;

      }


      /*
         Filter status pembayaran.
      */

      if (
        paymentStatus !== "ALL" &&
        actualPaymentStatus !==
        paymentStatus
      ) {

        return;

      }


      /*
         Search.
      */

      if (
        search
      ) {

        const searchText =
          [

            purchaseNumber,

            invoiceNumber,

            supplierName,

            purchase.notes ||
            "",

            purchase.reference ||
            ""

          ]
            .join(" ")
            .toLowerCase();


        if (
          !searchText.includes(
            search
          )
        ) {

          return;

        }

      }


      /*
         Cek stok masuk.
      */

      const stockInStatus =
        purchase.stockInStatus ||
        purchase.stockStatus ||
        (
          purchase.stockPosted === true
            ? "POSTED"
            : "PENDING"
        );


      /*
         Buat baris laporan.
      */

      rows.push({

        id:
          purchase.id,

        purchaseNumber,

        invoiceNumber,

        supplierId:
          currentSupplierId,

        supplierName,

        date:
          purchaseDate,

        itemCount,

        total,

        paid,

        remaining,

        status:
          actualStatus,

        paymentStatus:
          actualPaymentStatus,

        stockInStatus,

        notes:
          purchase.notes ||
          "",

        reference:
          purchase.reference ||
          "",

        items

      });

    }
  );


  /*
     Urutkan terbaru terlebih dahulu.
  */

  rows.sort(
    (
      a,
      b
    ) => {

      return String(
        b.date ||
        ""
      )
      .localeCompare(
        String(
          a.date ||
          ""
        )
      );

    }
  );


  /*
     Summary laporan.
  */

  const summary =
    rows.reduce(
      (
        result,
        row
      ) => {

        result.count +=
          1;


        result.itemCount +=
          row.itemCount;


        result.total +=
          row.total;


        result.paid +=
          row.paid;


        result.remaining +=
          row.remaining;


        if (
          row.paymentStatus ===
          "PAID"
        ) {

          result.paidCount +=
            1;

        }


        if (
          row.paymentStatus ===
          "PARTIAL"
        ) {

          result.partialCount +=
            1;

        }


        if (
          row.paymentStatus ===
          "UNPAID"
        ) {

          result.unpaidCount +=
            1;

        }


        if (
          row.stockInStatus ===
          "POSTED"
        ) {

          result.stockPostedCount +=
            1;

        }

        else {

          result.stockPendingCount +=
            1;

        }


        return result;

      },
      {

        count: 0,

        itemCount: 0,

        total: 0,

        paid: 0,

        remaining: 0,

        paidCount: 0,

        partialCount: 0,

        unpaidCount: 0,

        stockPostedCount: 0,

        stockPendingCount: 0

      }
    );


  return {

    rows,

    summary,

    filters: {

      supplierId,

      status,

      paymentStatus,

      search,

      dateFrom,

      dateTo

    }

  };

}


/* =========================================================
   GET PURCHASE REPORT SUMMARY
========================================================= */

function getPurchaseReportSummary(
  filters = {}
) {

  const report =
    getPurchaseReportData(
      filters
    );


  return report.summary;

}


/* =========================================================
   GET PURCHASE BY ID
========================================================= */

function getPurchaseReportRowById(
  purchaseId
) {

  if (
    !purchaseId
  ) {

    return null;

  }


  const report =
    getPurchaseReportData(
      {}
    );


  return (
    report.rows.find(
      row =>
        String(
          row.id
        ) ===
        String(
          purchaseId
        )
    ) ||
    null
  );

}


