/* =========================================================
   GET PURCHASE REPORT FILTERS
========================================================= */

function getPurchaseReportFilters() {

  const supplier =
    document.getElementById(
      "purchaseReportSupplier"
    );

  const status =
    document.getElementById(
      "purchaseReportStatus"
    );

  const paymentStatus =
    document.getElementById(
      "purchaseReportPaymentStatus"
    );

  const search =
    document.getElementById(
      "purchaseReportSearch"
    );

  const dateFrom =
    document.getElementById(
      "purchaseReportDateFrom"
    );

  const dateTo =
    document.getElementById(
      "purchaseReportDateTo"
    );


  return {

    supplierId:
      supplier?.value ||
      "",

    status:
      status?.value ||
      "ALL",

    paymentStatus:
      paymentStatus?.value ||
      "ALL",

    search:
      search?.value ||
      "",

    dateFrom:
      dateFrom?.value ||
      "",

    dateTo:
      dateTo?.value ||
      ""

  };

}


/* =========================================================
   VALIDATE PURCHASE REPORT FILTERS
========================================================= */

function validatePurchaseReportFilters(
  filters
) {

  if (!filters) {

    return true;

  }


  if (

    filters.dateFrom &&

    filters.dateTo &&

    filters.dateFrom >
    filters.dateTo

  ) {

    showToast(
      "Tanggal awal tidak boleh melebihi tanggal akhir.",
      "warning"
    );

    return false;

  }


  return true;

}


/* =========================================================
   APPLY PURCHASE REPORT FILTER
========================================================= */

function applyPurchaseReportFilter() {

  const filters =
    getPurchaseReportFilters();


  if (
    !validatePurchaseReportFilters(
      filters
    )
  ) {

    return false;

  }


  window.activePurchaseReportFilters =
    {
      ...filters
    };


  renderPurchaseReport(
    filters
  );


  return true;

}


/* =========================================================
   CLEAR PURCHASE REPORT FILTER
========================================================= */

function clearPurchaseReportFilter() {

  const supplier =
    document.getElementById(
      "purchaseReportSupplier"
    );


  const status =
    document.getElementById(
      "purchaseReportStatus"
    );


  const paymentStatus =
    document.getElementById(
      "purchaseReportPaymentStatus"
    );


  const search =
    document.getElementById(
      "purchaseReportSearch"
    );


  const dateFrom =
    document.getElementById(
      "purchaseReportDateFrom"
    );


  const dateTo =
    document.getElementById(
      "purchaseReportDateTo"
    );


  /*
     Supplier.
  */

  if (
    supplier
  ) {

    supplier.value =
      "";

  }


  /*
     Status pembelian.
  */

  if (
    status
  ) {

    status.value =
      "ALL";

  }


  /*
     Status pembayaran.
  */

  if (
    paymentStatus
  ) {

    paymentStatus.value =
      "ALL";

  }


  /*
     Search.
  */

  if (
    search
  ) {

    search.value =
      "";

  }


  /*
     Tanggal.
  */

  if (
    dateFrom
  ) {

    dateFrom.value =
      "";

  }


  if (
    dateTo
  ) {

    dateTo.value =
      "";

  }


  /*
     Reset state.
  */

  window.activePurchaseReportFilters =
    {};


  /*
     Render ulang semua pembelian.
  */

  renderPurchaseReport(
    {}
  );


  showToast(
    "Filter pembelian berhasil dikosongkan.",
    "success"
  );


  return true;

}


/* =========================================================
   SEARCH PURCHASE REPORT
========================================================= */

function searchPurchaseReport() {

  return applyPurchaseReportFilter();

}


/* =========================================================
   RESET PURCHASE REPORT
========================================================= */

function resetPurchaseReport() {

  return clearPurchaseReportFilter();

}


/* =========================================================
   APPLY QUICK DATE FILTER
========================================================= */

function applyPurchaseReportDatePreset(
  preset
) {

  const dateFrom =
    document.getElementById(
      "purchaseReportDateFrom"
    );


  const dateTo =
    document.getElementById(
      "purchaseReportDateTo"
    );


  if (
    !dateFrom ||
    !dateTo
  ) {

    return false;

  }


  const today =
    new Date();


  const start =
    new Date(
      today
    );


  switch (
    String(
      preset
    ).toUpperCase()
  ) {

    case "TODAY":

      break;


    case "7D":

      start.setDate(
        start.getDate() -
        6
      );

      break;


    case "30D":

      start.setDate(
        start.getDate() -
        29
      );

      break;


    case "MONTH":

      start.setDate(
        1
      );

      break;


    default:

      return false;

  }


  const formatDate =
    date => {

      const year =
        date.getFullYear();


      const month =
        String(
          date.getMonth() + 1
        )
        .padStart(
          2,
          "0"
        );


      const day =
        String(
          date.getDate()
        )
        .padStart(
          2,
          "0"
        );


      return (
        `${year}-${month}-${day}`
      );

    };


  dateFrom.value =
    formatDate(
      start
    );


  dateTo.value =
    formatDate(
      today
    );


  return applyPurchaseReportFilter();

}


