/* =========================================================
   FAEZA ERP V2
   BAGIAN 6J-06D
   PURCHASE REPORT DETAIL
========================================================= */


/* =========================================================
   GET PURCHASE DETAIL
========================================================= */

function getPurchaseReportDetail(
  purchaseId
) {

  if (
    !purchaseId
  ) {

    return null;

  }


  ensurePurchaseStorage();


  const purchase =
    db.purchases.find(
      item =>
        String(
          item.id
        ) ===
        String(
          purchaseId
        )
    );


  if (
    !purchase
  ) {

    return null;

  }


  const items =
    Array.isArray(
      purchase.items
    )
      ? purchase.items
      : [];


  const normalizedItems =
    items.map(
      (
        item,
        index
      ) => {

        const qty =
          Number(
            item.qty ||
            item.quantity
          ) || 0;


        const price =
          Number(
            item.price ||
            item.cost ||
            item.purchasePrice
          ) || 0;


        const subtotal =
          Number(
            item.subtotal
          ) ||
          (
            qty *
            price
          );


        return {

          index:
            index + 1,

          productId:
            item.productId ||
            item.id ||
            "",

          productName:
            item.productName ||
            item.name ||
            "-",

          sku:
            item.sku ||
            item.code ||
            "-",

          unit:
            item.unit ||
            "pcs",

          qty,

          price,

          subtotal

        };

      }
    );


  const calculatedTotal =
    normalizedItems.reduce(
      (
        total,
        item
      ) => {

        return (
          total +
          item.subtotal
        );

      },
      0
    );


  const total =
    Number(
      purchase.total
    ) ||

    Number(
      purchase.grandTotal
    ) ||

    calculatedTotal;


  const paid =
    Number(
      purchase.paid
    ) ||

    Number(
      purchase.amountPaid
    ) ||

    0;


  const remaining =
    Math.max(
      0,
      total -
      paid
    );


  const paymentStatus =
    remaining <= 0
      ? "PAID"
      : paid > 0
        ? "PARTIAL"
        : "UNPAID";


  const stockInStatus =
    purchase.stockInStatus ||
    purchase.stockStatus ||
    (
      purchase.stockPosted === true
        ? "POSTED"
        : "PENDING"
    );


  return {

    id:
      purchase.id,

    purchaseNumber:
      purchase.purchaseNumber ||
      purchase.number ||
      purchase.code ||
      "-",

    invoiceNumber:
      purchase.invoiceNumber ||
      purchase.invoice ||
      "-",

    supplierId:
      purchase.supplierId ||
      "",

    supplierName:
      purchase.supplierName ||
      getSupplierNameById(
        purchase.supplierId
      ) ||
      "-",

    date:
      purchase.date ||
      purchase.purchaseDate ||
      purchase.createdAt ||
      "",

    dueDate:
      purchase.dueDate ||
      "",

    status:
      String(
        purchase.status ||
        "POSTED"
      ).toUpperCase(),

    paymentStatus,

    stockInStatus,

    total,

    paid,

    remaining,

    items:
      normalizedItems,

    notes:
      purchase.notes ||
      "",

    reference:
      purchase.reference ||
      ""

  };

}


/* =========================================================
   RENDER PURCHASE DETAIL
========================================================= */

function renderPurchaseReportDetail(
  purchaseId
) {

  const detail =
    getPurchaseReportDetail(
      purchaseId
    );


  if (
    !detail
  ) {

    showToast(
      "Data pembelian tidak ditemukan.",
      "error"
    );

    return null;

  }


  /*
     Header detail.
  */

  setElementText(
    "purchaseDetailNumber",
    detail.purchaseNumber
  );


  setElementText(
    "purchaseDetailInvoice",
    detail.invoiceNumber
  );


  setElementText(
    "purchaseDetailSupplier",
    detail.supplierName
  );


  setElementText(
    "purchaseDetailDate",

    detail.date
      ? formatPrintDate(
          detail.date
        )
      : "-"
  );


  setElementText(
    "purchaseDetailDueDate",

    detail.dueDate
      ? formatPrintDate(
          detail.dueDate
        )
      : "-"
  );


  setElementText(
    "purchaseDetailTotal",
    formatRupiah(
      detail.total
    )
  );


  setElementText(
    "purchaseDetailPaid",
    formatRupiah(
      detail.paid
    )
  );


  setElementText(
    "purchaseDetailRemaining",
    formatRupiah(
      detail.remaining
    )
  );


  setElementText(
    "purchaseDetailNotes",
    detail.notes ||
    "-"
  );


  /*
     Status pembayaran.
  */

  const paymentStatus =
    document.getElementById(
      "purchaseDetailPaymentStatus"
    );


  if (
    paymentStatus
  ) {

    paymentStatus.innerHTML =
      getPurchasePaymentStatusBadge(
        detail.paymentStatus
      );

  }


  /*
     Status stok.
  */

  const stockStatus =
    document.getElementById(
      "purchaseDetailStockStatus"
    );


  if (
    stockStatus
  ) {

    stockStatus.innerHTML =
      getPurchaseStockInStatusBadge(
        detail.stockInStatus
      );

  }


  /*
     Render item.
  */

  const tbody =
    document.getElementById(
      "purchaseDetailItemBody"
    );


  if (
    tbody
  ) {

    if (
      !detail.items.length
    ) {

      tbody.innerHTML = `

        <tr>

          <td
            colspan="7"
            class="empty-state"
          >

            Tidak ada item
            pada pembelian ini.

          </td>

        </tr>

      `;

    }

    else {

      tbody.innerHTML =
        detail.items
          .map(
            item => {

              return `

                <tr>

                  <td>

                    ${item.index}

                  </td>


                  <td>

                    <strong>

                      ${escapeHTML(
                        item.productName
                      )}

                    </strong>

                  </td>


                  <td>

                    ${escapeHTML(
                      item.sku
                    )}

                  </td>


                  <td>

                    ${escapeHTML(
                      item.unit
                    )}

                  </td>


                  <td
                    class="text-right"
                  >

                    ${formatNumber(
                      item.qty
                    )}

                  </td>


                  <td
                    class="money"
                  >

                    ${formatRupiah(
                      item.price
                    )}

                  </td>


                  <td
                    class="money"
                  >

                    <strong>

                      ${formatRupiah(
                        item.subtotal
                      )}

                    </strong>

                  </td>

                </tr>

              `;

            }
          )
          .join("");

    }

  }


  /*
     Simpan transaksi aktif.
  */

  window.activePurchaseReportDetailId =
    purchaseId;


  /*
     Buka modal.
  */

  const modal =
    document.getElementById(
      "purchaseReportDetailModal"
    );


  if (
    modal
  ) {

    modal.removeAttribute(
      "hidden"
    );


    modal.classList.add(
      "active"
    );

  }


  return detail;

}


/* =========================================================
   OPEN PURCHASE REPORT DETAIL
========================================================= */

function openPurchaseReportDetail(
  purchaseId
) {

  return renderPurchaseReportDetail(
    purchaseId
  );

}


/* =========================================================
   CLOSE PURCHASE REPORT DETAIL
========================================================= */

function closePurchaseReportDetail() {

  const modal =
    document.getElementById(
      "purchaseReportDetailModal"
    );


  if (
    modal
  ) {

    modal.classList.remove(
      "active"
    );


    modal.setAttribute(
      "hidden",
      "hidden"
    );

  }


  window.activePurchaseReportDetailId =
    "";


  return true;

}


