/* =========================================================
   GET ALL STOCK MOVEMENTS
========================================================= */

function getStockMovementData(
  filters = {}
) {

  const productId =
    filters.productId ||
    "";


  const dateFrom =
    filters.dateFrom ||
    "";


  const dateTo =
    filters.dateTo ||
    "";


  const movementType =
    String(
      filters.movementType ||
      "ALL"
    ).toUpperCase();


  const search =
    String(
      filters.search ||
      ""
    )
      .trim()
      .toLowerCase();


  const movements = [];


  /*
     -------------------------------------------------------
     PURCHASE / STOCK IN
     -------------------------------------------------------
  */

  const purchases =
    Array.isArray(
      db.purchases
    )
      ? db.purchases
      : [];


  purchases.forEach(
    purchase => {

      if (
        !purchase
      ) {

        return;

      }


      const purchaseDate =
        purchase.date ||
        purchase.purchaseDate ||
        purchase.createdAt ||
        "";


      if (
        dateFrom &&
        String(
          purchaseDate
        ) < dateFrom
      ) {

        return;

      }


      if (
        dateTo &&
        String(
          purchaseDate
        ) > dateTo
      ) {

        return;

      }


      const items =
        Array.isArray(
          purchase.items
        )
          ? purchase.items
          : [];


      items.forEach(
        item => {

          const currentProductId =
            item.productId ||
            item.id ||
            "";


          if (
            productId &&
            String(
              currentProductId
            ) !==
            String(
              productId
            )
          ) {

            return;

          }


          const qty =
            Number(
              item.qty ||
              item.quantity
            ) || 0;


          if (
            qty <= 0
          ) {

            return;

          }


          const productName =
            item.productName ||
            item.name ||
            getProductNameById(
              currentProductId
            ) ||
            "-";


          const sku =
            item.sku ||
            item.code ||
            getProductSkuById(
              currentProductId
            ) ||
            "-";


          if (
            search
          ) {

            const text =
              [
                productName,
                sku,
                purchase.purchaseNumber,
                purchase.invoiceNumber,
                purchase.supplierName
              ]
                .join(" ")
                .toLowerCase();


            if (
              !text.includes(
                search
              )
            ) {

              return;

            }

          }


          if (
            movementType !==
            "ALL" &&
            movementType !==
            "IN"
          ) {

            return;

          }


          movements.push({

            id:
              `PURCHASE-${purchase.id}-${currentProductId}`,

            date:
              purchaseDate,

            productId:
              currentProductId,

            productName,

            sku,

            type:
              "IN",

            typeLabel:
              "STOK MASUK",

            qty,

            reference:
              purchase.purchaseNumber ||
              purchase.number ||
              "-",

            source:
              "PURCHASE",

            sourceId:
              purchase.id,

            supplierName:
              purchase.supplierName ||
              getSupplierNameById(
                purchase.supplierId
              ) ||
              "-",

            note:
              purchase.notes ||
              ""

          });

        }
      );

    }
  );


  /*
     -------------------------------------------------------
     SALES / STOCK OUT
     -------------------------------------------------------
  */

  const sales =
    Array.isArray(
      db.sales
    )
      ? db.sales
      : [];


  sales.forEach(
    sale => {

      if (
        !sale
      ) {

        return;

      }


      const saleDate =
        sale.date ||
        sale.saleDate ||
        sale.createdAt ||
        "";


      if (
        dateFrom &&
        String(
          saleDate
        ) < dateFrom
      ) {

        return;

      }


      if (
        dateTo &&
        String(
          saleDate
        ) > dateTo
      ) {

        return;

      }


      const items =
        Array.isArray(
          sale.items
        )
          ? sale.items
          : [];


      items.forEach(
        item => {

          const currentProductId =
            item.productId ||
            item.id ||
            "";


          if (
            productId &&
            String(
              currentProductId
            ) !==
            String(
              productId
            )
          ) {

            return;

          }


          const qty =
            Number(
              item.qty ||
              item.quantity
            ) || 0;


          if (
            qty <= 0
          ) {

            return;

          }


          const productName =
            item.productName ||
            item.name ||
            getProductNameById(
              currentProductId
            ) ||
            "-";


          const sku =
            item.sku ||
            item.code ||
            getProductSkuById(
              currentProductId
            ) ||
            "-";


          if (
            search
          ) {

            const text =
              [
                productName,
                sku,
                sale.invoiceNumber,
                sale.saleNumber
              ]
                .join(" ")
                .toLowerCase();


            if (
              !text.includes(
                search
              )
            ) {

              return;

            }

          }


          if (
            movementType !==
            "ALL" &&
            movementType !==
            "OUT"
          ) {

            return;

          }


          movements.push({

            id:
              `SALE-${sale.id}-${currentProductId}`,

            date:
              saleDate,

            productId:
              currentProductId,

            productName,

            sku,

            type:
              "OUT",

            typeLabel:
              "STOK KELUAR",

            qty,

            reference:
              sale.invoiceNumber ||
              sale.saleNumber ||
              "-",

            source:
              "SALE",

            sourceId:
              sale.id,

            supplierName:
              "",

            note:
              sale.notes ||
              ""

          });

        }
      );

    }
  );


  /*
     -------------------------------------------------------
     STOCK ADJUSTMENT
     -------------------------------------------------------
  */

  const adjustments =
    Array.isArray(
      db.stockAdjustments
    )
      ? db.stockAdjustments
      : [];


  adjustments.forEach(
    adjustment => {

      if (
        !adjustment
      ) {

        return;

      }


      const adjustmentDate =
        adjustment.date ||
        adjustment.createdAt ||
        "";


      if (
        dateFrom &&
        String(
          adjustmentDate
        ) < dateFrom
      ) {

        return;

      }


      if (
        dateTo &&
        String(
          adjustmentDate
        ) > dateTo
      ) {

        return;

      }


      const currentProductId =
        adjustment.productId ||
        "";


      if (
        productId &&
        String(
          currentProductId
        ) !==
        String(
          productId
        )
      ) {

        return;

      }


      const productName =
        adjustment.productName ||
        getProductNameById(
          currentProductId
        ) ||
        "-";


      const sku =
        adjustment.sku ||
        getProductSkuById(
          currentProductId
        ) ||
        "-";


      const qty =
        Number(
          adjustment.qty ||
          adjustment.quantity
        ) || 0;


      if (
        qty === 0
      ) {

        return;

      }


      const adjustmentType =
        qty > 0
          ? "IN"
          : "OUT";


      if (
        movementType !==
        "ALL" &&
        movementType !==
        adjustmentType
      ) {

        return;

      }


      if (
        search
      ) {

        const text =
          [
            productName,
            sku,
            adjustment.reference,
            adjustment.note
          ]
            .join(" ")
            .toLowerCase();


        if (
          !text.includes(
            search
          )
        ) {

          return;

        }

      }


      movements.push({

        id:
          `ADJUSTMENT-${adjustment.id}`,

        date:
          adjustmentDate,

        productId:
          currentProductId,

        productName,

        sku,

        type:
          adjustmentType,

        typeLabel:
          adjustmentType === "IN"
            ? "PENYESUAIAN +"
            : "PENYESUAIAN -",

        qty:
          Math.abs(
            qty
          ),

        reference:
          adjustment.reference ||
          "-",

        source:
          "ADJUSTMENT",

        sourceId:
          adjustment.id,

        supplierName:
          "",

        note:
          adjustment.note ||
          ""

      });

    }
  );


  /*
     -------------------------------------------------------
     SORT
     -------------------------------------------------------
  */

  movements.sort(
    (
      a,
      b
    ) => {

      return String(
        a.date ||
        ""
      )
      .localeCompare(
        String(
          b.date ||
          ""
        )
      );

    }
  );


  return movements;

}


/* =========================================================
   GET STOCK CARD
========================================================= */

function getStockCardData(
  productId,
  filters = {}
) {

  const movements =
    getStockMovementData(
      {
        ...filters,
        productId
      }
    );


  let runningStock =
    Number(
      getProductOpeningStockById(
        productId
      )
    ) || 0;


  const rows =
    movements.map(
      movement => {

        const stockBefore =
          runningStock;


        if (
          movement.type ===
          "IN"
        ) {

          runningStock +=
            movement.qty;

        }

        else {

          runningStock -=
            movement.qty;

        }


        return {

          ...movement,

          stockBefore,

          stockAfter:
            runningStock

        };

      }
    );


  return {

    productId,

    productName:
      getProductNameById(
        productId
      ) ||
      "-",

    openingStock:
      Number(
        getProductOpeningStockById(
          productId
        )
      ) || 0,

    rows,

    endingStock:
      runningStock

  };

}


