/* =========================================================
   STOCK MOVEMENT BADGE
========================================================= */

function getStockMovementBadge(
  type,
  label
) {

  const movementType =
    String(
      type ||
      ""
    ).toUpperCase();


  if (
    movementType ===
    "IN"
  ) {

    return `

      <span
        class="badge status-paid"
      >

        ${escapeHTML(
          label ||
          "STOK MASUK"
        )}

      </span>

    `;

  }


  return `

    <span
      class="badge status-danger"
    >

      ${escapeHTML(
        label ||
        "STOK KELUAR"
      )}

    </span>

  `;

}


/* =========================================================
   RENDER STOCK CARD SUMMARY
========================================================= */

function renderStockCardSummary(
  productId,
  filters = {}
) {

  const card =
    getStockCardData(
      productId,
      filters
    );


  let totalIn =
    0;


  let totalOut =
    0;


  card.rows.forEach(
    row => {

      if (
        row.type ===
        "IN"
      ) {

        totalIn +=
          row.qty;

      }

      else {

        totalOut +=
          row.qty;

      }

    }
  );


  const openingStock =
    card.openingStock;


  const endingStock =
    card.endingStock;


  setElementText(
    "stockCardProductName",
    card.productName
  );


  setElementText(
    "stockCardOpening",
    formatNumber(
      openingStock
    )
  );


  setElementText(
    "stockCardTotalIn",
    formatNumber(
      totalIn
    )
  );


  setElementText(
    "stockCardTotalOut",
    formatNumber(
      totalOut
    )
  );


  setElementText(
    "stockCardEnding",
    formatNumber(
      endingStock
    )
  );


  setElementText(
    "stockCardMovementCount",
    formatNumber(
      card.rows.length
    )
  );


  return {

    ...card,

    totalIn,

    totalOut

  };

}


/* =========================================================
   RENDER STOCK CARD TABLE
========================================================= */

function renderStockCardTable(
  productId,
  filters = {}
) {

  const tbody =
    document.getElementById(
      "stockCardBody"
    );


  const card =
    getStockCardData(
      productId,
      filters
    );


  if (
    !tbody
  ) {

    return card;

  }


  if (
    !card.rows.length
  ) {

    tbody.innerHTML = `

      <tr>

        <td
          colspan="10"
          class="empty-state"
        >

          Belum ada mutasi stok
          untuk produk ini.

        </td>

      </tr>

    `;


    return card;

  }


  tbody.innerHTML =
    card.rows
      .map(
        (
          row,
          index
        ) => {

          const qtyIn =
            row.type ===
            "IN"
              ? row.qty
              : 0;


          const qtyOut =
            row.type ===
            "OUT"
              ? row.qty
              : 0;


          return `

            <tr>

              <td>

                ${index + 1}

              </td>


              <td>

                ${
                  row.date
                    ? formatPrintDate(
                        row.date
                      )
                    : "-"
                }

              </td>


              <td>

                ${getStockMovementBadge(
                  row.type,
                  row.typeLabel
                )}

              </td>


              <td>

                ${escapeHTML(
                  row.reference
                )}

              </td>


              <td>

                ${escapeHTML(
                  row.productName
                )}

              </td>


              <td>

                ${escapeHTML(
                  row.sku
                )}

              </td>


              <td
                class="text-right"
              >

                ${
                  qtyIn > 0
                    ? `+${formatNumber(
                        qtyIn
                      )}`
                    : "-"
                }

              </td>


              <td
                class="text-right"
              >

                ${
                  qtyOut > 0
                    ? `-${formatNumber(
                        qtyOut
                      )}`
                    : "-"
                }

              </td>


              <td
                class="text-right"
              >

                <strong>

                  ${formatNumber(
                    row.stockAfter
                  )}

                </strong>

              </td>


              <td>

                ${escapeHTML(
                  row.note ||
                  "-"
                )}

              </td>

            </tr>

          `;

        }
      )
      .join("");


  return card;

}


/* =========================================================
   RENDER COMPLETE STOCK CARD
========================================================= */

function renderStockCard(
  productId,
  filters = {}
) {

  if (
    !productId
  ) {

    showToast(
      "Pilih produk terlebih dahulu.",
      "warning"
    );

    return null;

  }


  const card =
    renderStockCardSummary(
      productId,
      filters
    );


  renderStockCardTable(
    productId,
    filters
  );


  window.activeStockCardProductId =
    productId;


  window.activeStockCardFilters =
    {
      ...filters
    };


  return card;

}


/* =========================================================
   REFRESH STOCK CARD
========================================================= */

function refreshStockCard() {

  const productId =
    window.activeStockCardProductId ||
    "";


  const filters =
    window.activeStockCardFilters ||
    {};


  if (
    !productId
  ) {

    return null;

  }


  return renderStockCard(
    productId,
    filters
  );

}


