/* =========================================================
   PRINT STOCK CARD
========================================================= */

function printStockCard() {

  const productId =
    window.activeStockCardProductId ||
    "";


  const filters =
    window.activeStockCardFilters ||
    {};


  if (!productId) {

    showToast(
      "Pilih produk terlebih dahulu.",
      "warning"
    );

    return false;

  }


  const html =
    buildStockCardPrintHTML(
      productId,
      filters
    );


  if (!html) {

    showToast(
      "Data kartu stok tidak dapat dicetak.",
      "error"
    );

    return false;

  }


  const printWindow =
    window.open(
      "",
      "_blank",
      "width=1200,height=800"
    );


  if (!printWindow) {

    showToast(
      "Popup cetak diblokir browser.",
      "warning"
    );

    return false;

  }


  printWindow.document.open();

  printWindow.document.write(
    html
  );

  printWindow.document.close();


  return true;

}


