/* =========================================================
   FAEZA ERP V2
   BAGIAN 6J-07F
   EXPORT STOCK CARD TO CSV
========================================================= */


/* =========================================================
   BUILD STOCK CARD CSV
========================================================= */

function buildStockCardCSV(
  productId,
  filters = {}
) {

  if (!productId) {

    return "";

  }


  const card =
    getStockCardData(
      productId,
      filters
    );


  let totalIn = 0;

  let totalOut = 0;


  const csvRows = [];


  /*
     HEADER INFORMASI
  */

  csvRows.push(
    [
      "FAEZA STORE ERP"
    ]
      .map(
        escapeCSVValue
      )
      .join(",")
  );


  csvRows.push(
    [
      "KARTU STOK"
    ]
      .map(
        escapeCSVValue
      )
      .join(",")
  );


  csvRows.push(
    [
      "Produk",
      card.productName
    ]
      .map(
        escapeCSVValue
      )
      .join(",")
  );


  csvRows.push(
    [
      "SKU",
      getProductSkuById(
        productId
      ) || "-"
    ]
      .map(
        escapeCSVValue
      )
      .join(",")
  );


  csvRows.push("");


  /*
     HEADER TABEL
  */

  csvRows.push(
    [
      "No",
      "Tanggal",
      "Jenis Mutasi",
      "Referensi",
      "SKU",
      "Masuk",
      "Keluar",
      "Saldo Sebelum",
      "Saldo Sesudah",
      "Keterangan"
    ]
      .map(
        escapeCSVValue
      )
      .join(",")
  );


  /*
     DATA MUTASI
  */

  card.rows.forEach(
    (
      row,
      index
    ) => {

      const qtyIn =
        row.type === "IN"
          ? Number(
              row.qty
            ) || 0
          : 0;


      const qtyOut =
        row.type === "OUT"
          ? Number(
              row.qty
            ) || 0
          : 0;


      totalIn +=
        qtyIn;


      totalOut +=
        qtyOut;


      csvRows.push(
        [
          index + 1,

          row.date
            ? formatPrintDate(
                row.date
              )
            : "",

          row.typeLabel ||
            "",

          row.reference ||
            "",

          row.sku ||
            "",

          qtyIn,

          qtyOut,

          row.stockBefore,

          row.stockAfter,

          row.note ||
            ""

        ]
          .map(
            escapeCSVValue
          )
          .join(",")
      );

    }
  );


  /*
     RINGKASAN
  */

  csvRows.push("");


  csvRows.push(
    [
      "RINGKASAN",
      "",
      "",
      "",
      "",
      "",
      "",
      "",
      "",
      ""
    ]
      .map(
        escapeCSVValue
      )
      .join(",")
  );


  csvRows.push(
    [
      "Stok Awal",
      card.openingStock
    ]
      .map(
        escapeCSVValue
      )
      .join(",")
  );


  csvRows.push(
    [
      "Total Masuk",
      totalIn
    ]
      .map(
        escapeCSVValue
      )
      .join(",")
  );


  csvRows.push(
    [
      "Total Keluar",
      totalOut
    ]
      .map(
        escapeCSVValue
      )
      .join(",")
  );


  csvRows.push(
    [
      "Stok Akhir",
      card.endingStock
    ]
      .map(
        escapeCSVValue
      )
      .join(",")
  );


  /*
     BOM UTF-8
  */

  return (
    "\uFEFF" +
    csvRows.join(
      "\r\n"
    )
  );

}


/* =========================================================
   DOWNLOAD STOCK CARD CSV
========================================================= */

function downloadStockCardCSV() {

  const productId =
    window.activeStockCardProductId ||
    "";


  const filters =
    window.activeStockCardFilters ||
    {};


  if (!productId) {

    showToast(
      "Pilih produk terlebih dahulu.",
      "warning"
    );

    return false;

  }


  const csv =
    buildStockCardCSV(
      productId,
      filters
    );


  if (!csv) {

    showToast(
      "Data kartu stok tidak dapat diekspor.",
      "error"
    );

    return false;

  }


  const blob =
    new Blob(
      [
        csv
      ],
      {
        type:
          "text/csv;charset=utf-8;"
      }
    );


  const url =
    URL.createObjectURL(
      blob
    );


  const link =
    document.createElement(
      "a"
    );


  const now =
    new Date();


  const datePart =
    now
      .toISOString()
      .slice(
        0,
        10
      );


  const safeProductName =
    String(
      getProductNameById(
        productId
      ) ||
      "produk"
    )
      .replace(
        /[^a-zA-Z0-9-_ ]/g,
        ""
      )
      .trim()
      .replace(
        /\s+/g,
        "-"
      );


  link.href =
    url;


  link.download =
    `kartu-stok-${safeProductName}-${datePart}.csv`;


  document.body.appendChild(
    link
  );


  link.click();


  document.body.removeChild(
    link
  );


  setTimeout(
    function () {

      URL.revokeObjectURL(
        url
      );

    },
    1000
  );


  showToast(
    "Kartu stok berhasil diekspor.",
    "success"
  );


  return true;

}


/* =========================================================
   EXPORT CURRENT STOCK CARD
========================================================= */

function exportCurrentStockCard() {

  return downloadStockCardCSV();

}


