/* =========================================================
   FAEZA ERP V2
   BAGIAN 6J-08A
   SUPPLIER PAYABLE FOUNDATION
========================================================= */


/* =========================================================
   GET PURCHASE PAID AMOUNT
========================================================= */

function getPurchasePaidAmount(
  purchase
) {

  if (
    !purchase
  ) {

    return 0;

  }


  /*
     Nilai pembayaran langsung
     yang tersimpan di pembelian.
  */

  const directPaid =
    Number(
      purchase.paid
    ) ||

    Number(
      purchase.amountPaid
    ) ||

    Number(
      purchase.paymentAmount
    ) ||

    0;


  /*
     Jika ada tabel pembayaran supplier,
     jumlahkan pembayaran berdasarkan
     purchaseId.
  */

  const payments =
    Array.isArray(
      db.supplierPayments
    )
      ? db.supplierPayments
      : [];


  const purchaseId =
    purchase.id;


  const paymentTotal =
    payments
      .filter(
        payment =>
          String(
            payment.purchaseId ||
            ""
          ) ===
          String(
            purchaseId ||
            ""
          )
      )
      .reduce(
        (
          total,
          payment
        ) => {

          return (
            total +
            (
              Number(
                payment.amount
              ) ||
              Number(
                payment.paid
              ) ||
              0
            )
          );

        },
        0
      );


  /*
     Gunakan nilai terbesar agar
     pembayaran tidak dihitung dua kali
     bila purchase sudah menyimpan
     paid dan tabel payment juga ada.
  */

  return Math.max(
    directPaid,
    paymentTotal
  );

}


/* =========================================================
   GET PURCHASE TOTAL
========================================================= */

function getPurchaseTotalAmount(
  purchase
) {

  if (
    !purchase
  ) {

    return 0;

  }


  const directTotal =
    Number(
      purchase.total
    ) ||

    Number(
      purchase.grandTotal
    ) ||

    Number(
      purchase.amount
    ) ||

    0;


  if (
    directTotal > 0
  ) {

    return directTotal;

  }


  const items =
    Array.isArray(
      purchase.items
    )
      ? purchase.items
      : [];


  return items.reduce(
    (
      total,
      item
    ) => {

      const qty =
        Number(
          item.qty ||
          item.quantity
        ) || 0;


      const price =
        Number(
          item.price ||
          item.cost ||
          item.purchasePrice
        ) || 0;


      return (
        total +
        (
          qty *
          price
        )
      );

    },
    0
  );

}


/* =========================================================
   GET PAYABLE STATUS
========================================================= */

function getPayableStatus(
  total,
  paid
) {

  const grandTotal =
    Number(
      total
    ) || 0;


  const amountPaid =
    Number(
      paid
    ) || 0;


  const remaining =
    Math.max(
      0,
      grandTotal -
      amountPaid
    );


  if (
    grandTotal <= 0
  ) {

    return "NO_AMOUNT";

  }


  if (
    remaining <= 0
  ) {

    return "PAID";

  }


  if (
    amountPaid > 0
  ) {

    return "PARTIAL";

  }


  return "UNPAID";

}


/* =========================================================
   GET SUPPLIER PAYABLE DATA
========================================================= */

function getSupplierPayableData(
  filters = {}
) {

  const supplierId =
    filters.supplierId ||
    "";


  const status =
    String(
      filters.status ||
      "ALL"
    ).toUpperCase();


  const dateFrom =
    filters.dateFrom ||
    "";


  const dateTo =
    filters.dateTo ||
    "";


  const search =
    String(
      filters.search ||
      ""
    )
      .trim()
      .toLowerCase();


  const purchases =
    Array.isArray(
      db.purchases
    )
      ? db.purchases
      : [];


  const rows = [];


  purchases.forEach(
    purchase => {

      if (
        !purchase
      ) {

        return;

      }


      const purchaseSupplierId =
        purchase.supplierId ||
        "";


      /*
         Supplier filter.
      */

      if (
        supplierId &&
        String(
          purchaseSupplierId
        ) !==
        String(
          supplierId
        )
      ) {

        return;

      }


      const date =
        purchase.date ||
        purchase.purchaseDate ||
        purchase.createdAt ||
        "";


      /*
         Date filter.
      */

      if (
        dateFrom &&
        String(
          date
        ) < dateFrom
      ) {

        return;

      }


      if (
        dateTo &&
        String(
          date
        ) > dateTo
      ) {

        return;

      }


      const supplierName =
        purchase.supplierName ||
        getSupplierNameById(
          purchaseSupplierId
        ) ||
        "-";


      const purchaseNumber =
        purchase.purchaseNumber ||
        purchase.number ||
        purchase.code ||
        "-";


      const invoiceNumber =
        purchase.invoiceNumber ||
        purchase.invoice ||
        "-";


      /*
         Search.
      */

      if (
        search
      ) {

        const text =
          [
            purchaseNumber,
            invoiceNumber,
            supplierName
          ]
            .join(" ")
            .toLowerCase();


        if (
          !text.includes(
            search
          )
        ) {

          return;

        }

      }


      const total =
        getPurchaseTotalAmount(
          purchase
        );


      const paid =
        getPurchasePaidAmount(
          purchase
        );


      const remaining =
        Math.max(
          0,
          total -
          paid
        );


      const payableStatus =
        getPayableStatus(
          total,
          paid
        );


      /*
         Status filter.
      */

      if (
        status !==
        "ALL" &&
        status !==
        payableStatus
      ) {

        return;

      }


      rows.push({

        id:
          purchase.id,

        purchaseNumber,

        invoiceNumber,

        supplierId:
          purchaseSupplierId,

        supplierName,

        date,

        dueDate:
          purchase.dueDate ||
          "",

        total,

        paid,

        remaining,

        status:
          payableStatus,

        purchaseStatus:
          String(
            purchase.status ||
            "POSTED"
          ).toUpperCase(),

        notes:
          purchase.notes ||
          ""

      });

    }
  );


  /*
     Urutkan berdasarkan tanggal.
  */

  rows.sort(
    (
      a,
      b
    ) => {

      return String(
        b.date ||
        ""
      ).localeCompare(
        String(
          a.date ||
          ""
        )
      );

    }
  );


  /*
     Summary.
  */

  const summary =
    rows.reduce(
      (
        result,
        row
      ) => {

        result.count += 1;

        result.total +=
          row.total;

        result.paid +=
          row.paid;

        result.remaining +=
          row.remaining;


        if (
          row.status ===
          "UNPAID"
        ) {

          result.unpaid += 1;

        }


        if (
          row.status ===
          "PARTIAL"
        ) {

          result.partial += 1;

        }


        if (
          row.status ===
          "PAID"
        ) {

          result.paidCount += 1;

        }


        return result;

      },
      {

        count: 0,

        total: 0,

        paid: 0,

        remaining: 0,

        unpaid: 0,

        partial: 0,

        paidCount: 0

      }
    );


  return {

    rows,

    summary

  };

}


