/* =========================================================
   PAYABLE STATUS BADGE
========================================================= */

function getPayableStatusBadge(
  status
) {

  const value =
    String(
      status ||
      ""
    ).toUpperCase();


  if (
    value ===
    "PAID"
  ) {

    return `

      <span
        class="badge status-paid"
      >
        LUNAS
      </span>

    `;

  }


  if (
    value ===
    "PARTIAL"
  ) {

    return `

      <span
        class="badge status-warning"
      >
        SEBAGIAN
      </span>

    `;

  }


  if (
    value ===
    "UNPAID"
  ) {

    return `

      <span
        class="badge status-danger"
      >
        BELUM BAYAR
      </span>

    `;

  }


  return `

    <span
      class="badge"
    >
      -
    </span>

  `;

}


/* =========================================================
   CHECK OVERDUE
========================================================= */

function isPayableOverdue(
  row
) {

  if (
    !row ||
    !row.dueDate ||
    row.remaining <= 0
  ) {

    return false;

  }


  const today =
    new Date();


  const todayString =
    today
      .toISOString()
      .slice(
        0,
        10
      );


  return (
    String(
      row.dueDate
    ) <
    todayString
  );

}


/* =========================================================
   OVERDUE BADGE
========================================================= */

function getPayableDueBadge(
  row
) {

  if (
    !row ||
    !row.dueDate
  ) {

    return "-";

  }


  if (
    isPayableOverdue(
      row
    )
  ) {

    return `

      <span
        class="badge status-danger"
      >
        JATUH TEMPO
      </span>

    `;

  }


  return `

    <span
      class="badge"
    >
        ${formatPrintDate(
          row.dueDate
        )}
    </span>

  `;

}


