/* =========================================================
   GET PAYABLE FILTERS
========================================================= */

function getSupplierPayableFilters() {

  const supplier =
    document.getElementById(
      "payableSupplier"
    );


  const status =
    document.getElementById(
      "payableStatus"
    );


  const search =
    document.getElementById(
      "payableSearch"
    );


  const dateFrom =
    document.getElementById(
      "payableDateFrom"
    );


  const dateTo =
    document.getElementById(
      "payableDateTo"
    );


  const dueFrom =
    document.getElementById(
      "payableDueFrom"
    );


  const dueTo =
    document.getElementById(
      "payableDueTo"
    );


  return {

    supplierId:
      supplier?.value ||
      "",

    status:
      status?.value ||
      "ALL",

    search:
      search?.value ||
      "",

    dateFrom:
      dateFrom?.value ||
      "",

    dateTo:
      dateTo?.value ||
      "",

    dueFrom:
      dueFrom?.value ||
      "",

    dueTo:
      dueTo?.value ||
      ""

  };

}


/* =========================================================
   VALIDATE PAYABLE FILTER
========================================================= */

function validateSupplierPayableFilters(
  filters
) {

  if (
    !filters
  ) {

    return true;

  }


  if (

    filters.dateFrom &&

    filters.dateTo &&

    filters.dateFrom >
    filters.dateTo

  ) {

    showToast(
      "Tanggal transaksi tidak valid.",
      "warning"
    );

    return false;

  }


  if (

    filters.dueFrom &&

    filters.dueTo &&

    filters.dueFrom >
    filters.dueTo

  ) {

    showToast(
      "Tanggal jatuh tempo tidak valid.",
      "warning"
    );

    return false;

  }


  return true;

}


/* =========================================================
   APPLY PAYABLE FILTER
========================================================= */

function applySupplierPayableFilter() {

  const filters =
    getSupplierPayableFilters();


  if (
    !validateSupplierPayableFilters(
      filters
    )
  ) {

    return false;

  }


  /*
     Tambahan filter jatuh tempo
     dilakukan setelah data dasar
     diambil.
  */

  let report =
    getSupplierPayableData(
      filters
    );


  if (
    filters.dueFrom ||
    filters.dueTo
  ) {

    report.rows =
      report.rows.filter(
        row => {

          const dueDate =
            row.dueDate ||
            "";


          if (
            !dueDate
          ) {

            return false;

          }


          if (
            filters.dueFrom &&
            dueDate <
            filters.dueFrom
          ) {

            return false;

          }


          if (
            filters.dueTo &&
            dueDate >
            filters.dueTo
          ) {

            return false;

          }


          return true;

        }
      );


    /*
       Hitung ulang summary
       setelah filter jatuh tempo.
    */

    report.summary =
      report.rows.reduce(
        (
          result,
          row
        ) => {

          result.count += 1;

          result.total +=
            row.total;

          result.paid +=
            row.paid;

          result.remaining +=
            row.remaining;


          if (
            row.status ===
            "UNPAID"
          ) {

            result.unpaid += 1;

          }


          if (
            row.status ===
            "PARTIAL"
          ) {

            result.partial += 1;

          }


          if (
            row.status ===
            "PAID"
          ) {

            result.paidCount += 1;

          }


          return result;

        },
        {

          count: 0,

          total: 0,

          paid: 0,

          remaining: 0,

          unpaid: 0,

          partial: 0,

          paidCount: 0

        }
      );

  }


  window.activeSupplierPayableFilters =
    {
      ...filters
    };


  renderSupplierPayableSummaryFromReport(
    report
  );


  renderSupplierPayableTableFromReport(
    report
  );


  return report;

}


