/* =========================================================
   QUICK OVERDUE FILTER
========================================================= */

function filterOverdueSupplierPayable() {

  const filters =
    getSupplierPayableFilters();


  let report =
    getSupplierPayableData(
      filters
    );


  report.rows =
    report.rows.filter(
      row =>
        isPayableOverdue(
          row
        )
    );


  report.summary =
    report.rows.reduce(
      (
        result,
        row
      ) => {

        result.count += 1;

        result.total +=
          row.total;

        result.paid +=
          row.paid;

        result.remaining +=
          row.remaining;


        if (
          row.status ===
          "UNPAID"
        ) {

          result.unpaid += 1;

        }


        if (
          row.status ===
          "PARTIAL"
        ) {

          result.partial += 1;

        }


        if (
          row.status ===
          "PAID"
        ) {

          result.paidCount += 1;

        }


        return result;

      },
      {

        count: 0,

        total: 0,

        paid: 0,

        remaining: 0,

        unpaid: 0,

        partial: 0,

        paidCount: 0

      }
    );


  window.activeSupplierPayableFilters =
    {
      ...filters,
      overdueOnly:
        true
    };


  renderSupplierPayableSummaryFromReport(
    report
  );


  renderSupplierPayableTableFromReport(
    report
  );


  showToast(
    "Menampilkan hutang yang sudah jatuh tempo.",
    "success"
  );


  return report;

}


