/* =========================================================
   FIND PAYABLE BY PURCHASE ID
========================================================= */

function getSupplierPayableById(
  purchaseId
) {

  if (
    !purchaseId
  ) {

    return null;

  }


  const report =
    getSupplierPayableData(
      {}
    );


  return (
    report.rows.find(
      row =>
        String(
          row.id
        ) ===
        String(
          purchaseId
        )
    ) ||
    null
  );

}


/* =========================================================
   GET SUPPLIER PAYMENT HISTORY
========================================================= */

function getSupplierPaymentHistory(
  purchaseId
) {

  if (
    !purchaseId
  ) {

    return [];

  }


  const payments =
    Array.isArray(
      db.supplierPayments
    )
      ? db.supplierPayments
      : [];


  return payments
    .filter(
      payment =>
        String(
          payment.purchaseId ||
          ""
        ) ===
        String(
          purchaseId
        )
    )
    .sort(
      (
        a,
        b
      ) => {

        return String(
          b.date ||
          b.createdAt ||
          ""
        ).localeCompare(
          String(
            a.date ||
            a.createdAt ||
            ""
          )
        );

      }
    );

}


/* =========================================================
   PAYMENT METHOD LABEL
========================================================= */

function getPaymentMethodLabel(
  method
) {

  const value =
    String(
      method ||
      ""
    ).toUpperCase();


  const labels = {

    CASH:
      "Tunai",

    TRANSFER:
      "Transfer Bank",

    BANK:
      "Transfer Bank",

    QRIS:
      "QRIS",

    GIRO:
      "Giro",

    CREDIT:
      "Kredit",

    OTHER:
      "Lainnya"

  };


  return (
    labels[value] ||
    method ||
    "-"
  );

}


/* =========================================================
   RENDER PAYABLE PAYMENT HISTORY
========================================================= */

function renderSupplierPaymentHistory(
  purchaseId
) {

  const tbody =
    document.getElementById(
      "supplierPayablePaymentBody"
    );


  const payments =
    getSupplierPaymentHistory(
      purchaseId
    );


  if (
    !tbody
  ) {

    return payments;

  }


  if (
    !payments.length
  ) {

    tbody.innerHTML = `

      <tr>

        <td
          colspan="6"
          class="empty-state"
        >

          Belum ada pembayaran.

        </td>

      </tr>

    `;


    return payments;

  }


  tbody.innerHTML =
    payments
      .map(
        (
          payment,
          index
        ) => {

          return `

            <tr>

              <td>
                ${index + 1}
              </td>

              <td>

                ${
                  payment.date
                    ? formatPrintDate(
                        payment.date
                      )
                    : "-"
                }

              </td>

              <td>

                ${escapeHTML(
                  payment.reference ||
                  payment.paymentNumber ||
                  "-"
                )}

              </td>

              <td>

                ${escapeHTML(
                  getPaymentMethodLabel(
                    payment.method ||
                    payment.paymentMethod
                  )
                )}

              </td>

              <td
                class="money"
              >

                <strong>

                  ${formatRupiah(
                    Number(
                      payment.amount ||
                      payment.paid
                    ) || 0
                  )}

                </strong>

              </td>

              <td>

                ${escapeHTML(
                  payment.notes ||
                  payment.note ||
                  "-"
                )}

              </td>

            </tr>

          `;

        }
      )
      .join("");


  return payments;

}


/* =========================================================
   RENDER PAYABLE DETAIL
========================================================= */

function renderSupplierPayableDetail(
  purchaseId
) {

  const payable =
    getSupplierPayableById(
      purchaseId
    );


  if (
    !payable
  ) {

    showToast(
      "Data hutang supplier tidak ditemukan.",
      "error"
    );

    return null;

  }


  const purchase =
    Array.isArray(
      db.purchases
    )
      ? db.purchases.find(
          item =>
            String(
              item.id
            ) ===
            String(
              purchaseId
            )
        )
      : null;


  /*
     Data utama.
  */

  setElementText(
    "payableDetailSupplier",
    payable.supplierName
  );


  setElementText(
    "payableDetailPurchaseNumber",
    payable.purchaseNumber
  );


  setElementText(
    "payableDetailInvoice",
    payable.invoiceNumber
  );


  setElementText(
    "payableDetailDate",

    payable.date
      ? formatPrintDate(
          payable.date
        )
      : "-"
  );


  setElementText(
    "payableDetailDueDate",

    payable.dueDate
      ? formatPrintDate(
          payable.dueDate
        )
      : "-"
  );


  setElementText(
    "payableDetailTotal",
    formatRupiah(
      payable.total
    )
  );


  setElementText(
    "payableDetailPaid",
    formatRupiah(
      payable.paid
    )
  );


  setElementText(
    "payableDetailRemaining",
    formatRupiah(
      payable.remaining
    )
  );


  setElementText(
    "payableDetailStatus",
    payable.status ===
      "PAID"
      ? "LUNAS"
      : payable.status ===
        "PARTIAL"
        ? "SEBAGIAN"
        : "BELUM BAYAR"
  );


  /*
     Catatan pembelian.
  */

  setElementText(
    "payableDetailNotes",
    purchase?.notes ||
    purchase?.note ||
    payable.notes ||
    "-"
  );


  /*
     Status jatuh tempo.
  */

  setElementText(
    "payableDetailDueStatus",

    isPayableOverdue(
      payable
    )
      ? "JATUH TEMPO"
      : payable.remaining <= 0
        ? "LUNAS"
        : "BELUM JATUH TEMPO"
  );


  /*
     Riwayat pembayaran.
  */

  renderSupplierPaymentHistory(
    purchaseId
  );


  /*
     Simpan ID aktif.
  */

  window.activeSupplierPayableId =
    purchaseId;


  /*
     Buka modal.
  */

  const modal =
    document.getElementById(
      "supplierPayableDetailModal"
    );


  if (
    modal
  ) {

    modal.removeAttribute(
      "hidden"
    );


    modal.classList.add(
      "active"
    );

  }


  return {

    payable,

    purchase,

    payments:
      getSupplierPaymentHistory(
        purchaseId
      )

  };

}


