/* =========================================================
   ENSURE SUPPLIER PAYMENT STORAGE
========================================================= */

function ensureSupplierPaymentStorage() {

  if (
    !Array.isArray(
      db.supplierPayments
    )
  ) {

    db.supplierPayments = [];

  }


  return db.supplierPayments;

}


/* =========================================================
   GET PAYMENT FORM VALUES
========================================================= */

function getSupplierPaymentFormValues() {

  const date =
    document.getElementById(
      "supplierPaymentDate"
    );


  const amount =
    document.getElementById(
      "supplierPaymentAmount"
    );


  const method =
    document.getElementById(
      "supplierPaymentMethod"
    );


  const reference =
    document.getElementById(
      "supplierPaymentReference"
    );


  const notes =
    document.getElementById(
      "supplierPaymentNotes"
    );


  return {

    date:
      date?.value ||
      new Date()
        .toISOString()
        .slice(
          0,
          10
        ),

    amount:
      Number(
        String(
          amount?.value ||
          "0"
        ).replace(
          /[^\d.-]/g,
          ""
        )
      ) || 0,

    method:
      method?.value ||
      "CASH",

    reference:
      reference?.value?.trim() ||
      "",

    notes:
      notes?.value?.trim() ||
      ""

  };

}


/* =========================================================
   VALIDATE SUPPLIER PAYMENT
========================================================= */

function validateSupplierPayment(
  payable,
  payment
) {

  if (
    !payable
  ) {

    showToast(
      "Data hutang tidak ditemukan.",
      "error"
    );

    return false;

  }


  if (
    payable.remaining <= 0
  ) {

    showToast(
      "Hutang ini sudah lunas.",
      "warning"
    );

    return false;

  }


  if (
    !payment.amount ||
    payment.amount <= 0
  ) {

    showToast(
      "Masukkan jumlah pembayaran.",
      "warning"
    );

    return false;

  }


  if (
    payment.amount >
    payable.remaining
  ) {

    showToast(
      "Pembayaran melebihi sisa hutang.",
      "warning"
    );

    return false;

  }


  if (
    !payment.date
  ) {

    showToast(
      "Tanggal pembayaran wajib diisi.",
      "warning"
    );

    return false;

  }


  return true;

}


/* =========================================================
   CREATE SUPPLIER PAYMENT NUMBER
========================================================= */

function createSupplierPaymentNumber() {

  const payments =
    ensureSupplierPaymentStorage();


  const year =
    new Date()
      .getFullYear();


  const number =
    payments.length + 1;


  return (

    "PAY-" +

    year +

    "-" +

    String(
      number
    ).padStart(
      5,
      "0"
    )

  );

}


/* =========================================================
   SAVE SUPPLIER PAYMENT
========================================================= */

function saveSupplierPayment() {

  const purchaseId =
    window.activeSupplierPayableId ||
    "";


  if (
    !purchaseId
  ) {

    showToast(
      "Pilih hutang supplier terlebih dahulu.",
      "warning"
    );

    return false;

  }


  const payable =
    getSupplierPayableById(
      purchaseId
    );


  if (
    !payable
  ) {

    showToast(
      "Data hutang tidak ditemukan.",
      "error"
    );

    return false;

  }


  const payment =
    getSupplierPaymentFormValues();


  if (
    !validateSupplierPayment(
      payable,
      payment
    )
  ) {

    return false;

  }


  const payments =
    ensureSupplierPaymentStorage();


  const paymentRecord = {

    id:
      "SP-" +
      Date.now() +
      "-" +
      Math.random()
        .toString(36)
        .slice(
          2,
          7
        ),

    paymentNumber:
      createSupplierPaymentNumber(),

    purchaseId:
      purchaseId,

    supplierId:
      payable.supplierId,

    supplierName:
      payable.supplierName,

    date:
      payment.date,

    amount:
      payment.amount,

    paid:
      payment.amount,

    method:
      payment.method,

    paymentMethod:
      payment.method,

    reference:
      payment.reference,

    notes:
      payment.notes,

    createdAt:
      new Date()
        .toISOString()

  };


  payments.push(
    paymentRecord
  );


  /*
     Jika transaksi pembelian
     memiliki field paid,
     sinkronkan nilainya.
  */

  const purchase =
    Array.isArray(
      db.purchases
    )
      ? db.purchases.find(
          item =>
            String(
              item.id
            ) ===
            String(
              purchaseId
            )
        )
      : null;


  if (
    purchase
  ) {

    const currentPaid =
      Number(
        purchase.paid
      ) || 0;


    purchase.paid =
      currentPaid +
      payment.amount;


    purchase.amountPaid =
      purchase.paid;


    const total =
      getPurchaseTotalAmount(
        purchase
      );


    purchase.remaining =
      Math.max(
        0,
        total -
        purchase.paid
      );


    if (
      purchase.remaining <= 0
    ) {

      purchase.paymentStatus =
        "PAID";

    }

    else if (
      purchase.paid > 0
    ) {

      purchase.paymentStatus =
        "PARTIAL";

    }

    else {

      purchase.paymentStatus =
        "UNPAID";

    }

  }


  /*
     Simpan database.
  */

  if (
    typeof saveDB ===
    "function"
  ) {

    saveDB();

  }

  else if (
    typeof saveDatabase ===
    "function"
  ) {

    saveDatabase();

  }

  else {

    try {

      localStorage.setItem(
        "faezaERP",
        JSON.stringify(
          db
        )
      );

    }

    catch (
      error
    ) {

      console.warn(
        "Gagal menyimpan database:",
        error
      );

    }

  }


  /*
     Bersihkan form.
  */

  clearSupplierPaymentForm();


  /*
     Refresh detail.
  */

  renderSupplierPayableDetail(
    purchaseId
  );


  /*
     Refresh laporan.
  */

  renderSupplierPayableReport(
    window.activeSupplierPayableFilters ||
    {}
  );


  showToast(
    "Pembayaran hutang berhasil disimpan.",
    "success"
  );


  return paymentRecord;

}


/* =========================================================
   CLEAR PAYMENT FORM
========================================================= */

function clearSupplierPaymentForm() {

  const date =
    document.getElementById(
      "supplierPaymentDate"
    );


  const amount =
    document.getElementById(
      "supplierPaymentAmount"
    );


  const method =
    document.getElementById(
      "supplierPaymentMethod"
    );


  const reference =
    document.getElementById(
      "supplierPaymentReference"
    );


  const notes =
    document.getElementById(
      "supplierPaymentNotes"
    );


  if (
    date
  ) {

    date.value =
      new Date()
        .toISOString()
        .slice(
          0,
          10
        );

  }


  if (
    amount
  ) {

    amount.value =
      "";

  }


  if (
    method
  ) {

    method.value =
      "CASH";

  }


  if (
    reference
  ) {

    reference.value =
      "";

  }


  if (
    notes
  ) {

    notes.value =
      "";

  }


  return true;

}


/* =========================================================
   OPEN SUPPLIER PAYMENT FORM
========================================================= */

function openSupplierPaymentForm(
  purchaseId
) {

  const payable =
    getSupplierPayableById(
      purchaseId
    );


  if (
    !payable
  ) {

    showToast(
      "Data hutang tidak ditemukan.",
      "error"
    );

    return false;

  }


  if (
    payable.remaining <= 0
  ) {

    showToast(
      "Hutang ini sudah lunas.",
      "warning"
    );

    return false;

  }


  window.activeSupplierPayableId =
    purchaseId;


  setElementText(
    "supplierPaymentSupplier",
    payable.supplierName
  );


  setElementText(
    "supplierPaymentPurchase",
    payable.purchaseNumber
  );


  setElementText(
    "supplierPaymentInvoice",
    payable.invoiceNumber
  );


  setElementText(
    "supplierPaymentOutstanding",
    formatRupiah(
      payable.remaining
    )
  );


  const date =
    document.getElementById(
      "supplierPaymentDate"
    );


  if (
    date &&
    !date.value
  ) {

    date.value =
      new Date()
        .toISOString()
        .slice(
          0,
          10
        );

  }


  const modal =
    document.getElementById(
      "supplierPaymentModal"
    );


  if (
    modal
  ) {

    modal.removeAttribute(
      "hidden"
    );


    modal.classList.add(
      "active"
    );

  }


  return true;

}


/* =========================================================
   CLOSE SUPPLIER PAYMENT FORM
========================================================= */

function closeSupplierPaymentForm() {

  const modal =
    document.getElementById(
      "supplierPaymentModal"
    );


  if (
    modal
  ) {

    modal.classList.remove(
      "active"
    );


    modal.setAttribute(
      "hidden",
      "hidden"
    );

  }


  return true;

}


/* =========================================================
   PAY CURRENT PAYABLE
========================================================= */

function payCurrentSupplierPayable() {

  const purchaseId =
    window.activeSupplierPayableId ||
    "";


  if (
    !purchaseId
  ) {

    showToast(
      "Tidak ada hutang yang dipilih.",
      "warning"
    );

    return false;

  }


  return openSupplierPaymentForm(
    purchaseId
  );

}


