/* =========================================================
   FAEZA ERP V2
   BAGIAN 6J-08G
   EXPORT SUPPLIER PAYABLE TO CSV
========================================================= */


/* =========================================================
   ESCAPE CSV VALUE
========================================================= */

function escapePayableCSVValue(
  value
) {

  if (
    value === null ||
    value === undefined
  ) {

    return '""';

  }


  return (
    '"' +
    String(
      value
    )
      .replace(
        /"/g,
        '""'
      ) +
    '"'
  );

}


/* =========================================================
   GET FILTERED PAYABLE REPORT
========================================================= */

function getFilteredSupplierPayableReport(
  filters = {}
) {

  const report =
    getSupplierPayableData(
      filters
    );


  let rows =
    report.rows ||
    [];


  /*
     Filter tanggal jatuh tempo.
  */

  if (
    filters.dueFrom ||
    filters.dueTo
  ) {

    rows =
      rows.filter(
        row => {

          const dueDate =
            row.dueDate ||
            "";


          if (
            !dueDate
          ) {

            return false;

          }


          if (
            filters.dueFrom &&
            dueDate <
            filters.dueFrom
          ) {

            return false;

          }


          if (
            filters.dueTo &&
            dueDate >
            filters.dueTo
          ) {

            return false;

          }


          return true;

        }
      );

  }


  /*
     Hanya hutang jatuh tempo.
  */

  if (
    filters.overdueOnly
  ) {

    rows =
      rows.filter(
        row =>
          isPayableOverdue(
            row
          )
      );

  }


  /*
     Hitung ulang summary.
  */

  const summary =
    rows.reduce(
      (
        result,
        row
      ) => {

        result.count += 1;

        result.total +=
          Number(
            row.total
          ) || 0;

        result.paid +=
          Number(
            row.paid
          ) || 0;

        result.remaining +=
          Number(
            row.remaining
          ) || 0;


        if (
          row.status ===
          "UNPAID"
        ) {

          result.unpaid += 1;

        }


        if (
          row.status ===
          "PARTIAL"
        ) {

          result.partial += 1;

        }


        if (
          row.status ===
          "PAID"
        ) {

          result.paidCount += 1;

        }


        return result;

      },
      {

        count: 0,

        total: 0,

        paid: 0,

        remaining: 0,

        unpaid: 0,

        partial: 0,

        paidCount: 0

      }
    );


  return {

    rows,

    summary

  };

}


/* =========================================================
   BUILD PAYABLE CSV
========================================================= */

function buildSupplierPayableCSV(
  filters = {}
) {

  const report =
    getFilteredSupplierPayableReport(
      filters
    );


  const rows =
    report.rows;


  const csvRows = [];


  /*
     TITLE
  */

  csvRows.push(
    [
      "FAEZA STORE ERP"
    ]
      .map(
        escapePayableCSVValue
      )
      .join(",")
  );


  csvRows.push(
    [
      "LAPORAN HUTANG SUPPLIER"
    ]
      .map(
        escapePayableCSVValue
      )
      .join(",")
  );


  csvRows.push("");


  /*
     HEADER
  */

  csvRows.push(
    [
      "No",
      "Tanggal",
      "Supplier",
      "No Pembelian",
      "Invoice",
      "Total Pembelian",
      "Dibayar",
      "Sisa Hutang",
      "Jatuh Tempo",
      "Status"
    ]
      .map(
        escapePayableCSVValue
      )
      .join(",")
  );


  /*
     DATA
  */

  rows.forEach(
    (
      row,
      index
    ) => {

      csvRows.push(
        [

          index + 1,

          row.date
            ? formatPrintDate(
                row.date
              )
            : "",

          row.supplierName ||
            "",

          row.purchaseNumber ||
            "",

          row.invoiceNumber ||
            "",

          Number(
            row.total
          ) || 0,

          Number(
            row.paid
          ) || 0,

          Number(
            row.remaining
          ) || 0,

          row.dueDate
            ? formatPrintDate(
                row.dueDate
              )
            : "",

          getPrintablePayableStatus(
            row
          )

        ]
          .map(
            escapePayableCSVValue
          )
          .join(",")
      );

    }
  );


  /*
     SUMMARY
  */

  csvRows.push("");


  csvRows.push(
    [
      "RINGKASAN"
    ]
      .map(
        escapePayableCSVValue
      )
      .join(",")
  );


  csvRows.push(
    [
      "Jumlah Transaksi",
      report.summary.count
    ]
      .map(
        escapePayableCSVValue
      )
      .join(",")
  );


  csvRows.push(
    [
      "Total Pembelian",
      report.summary.total
    ]
      .map(
        escapePayableCSVValue
      )
      .join(",")
  );


  csvRows.push(
    [
      "Total Dibayar",
      report.summary.paid
    ]
      .map(
        escapePayableCSVValue
      )
      .join(",")
  );


  csvRows.push(
    [
      "Total Sisa Hutang",
      report.summary.remaining
    ]
      .map(
        escapePayableCSVValue
      )
      .join(",")
  );


  csvRows.push(
    [
      "Belum Bayar",
      report.summary.unpaid
    ]
      .map(
        escapePayableCSVValue
      )
      .join(",")
  );


  csvRows.push(
    [
      "Sebagian",
      report.summary.partial
    ]
      .map(
        escapePayableCSVValue
      )
      .join(",")
  );


  csvRows.push(
    [
      "Lunas",
      report.summary.paidCount
    ]
      .map(
        escapePayableCSVValue
      )
      .join(",")
  );


  /*
     UTF-8 BOM
     agar Excel membaca bahasa
     Indonesia dengan benar.
  */

  return (
    "\uFEFF" +
    csvRows.join(
      "\r\n"
    )
  );

}


/* =========================================================
   DOWNLOAD PAYABLE CSV
========================================================= */

function downloadSupplierPayableCSV() {

  const filters =
    window.activeSupplierPayableFilters ||
    {};


  const csv =
    buildSupplierPayableCSV(
      filters
    );


  if (
    !csv
  ) {

    showToast(
      "Data hutang tidak dapat diekspor.",
      "error"
    );

    return false;

  }


  const blob =
    new Blob(
      [
        csv
      ],
      {
        type:
          "text/csv;charset=utf-8;"
      }
    );


  const url =
    URL.createObjectURL(
      blob
    );


  const link =
    document.createElement(
      "a"
    );


  const date =
    new Date()
      .toISOString()
      .slice(
        0,
        10
      );


  link.href =
    url;


  link.download =
    `laporan-hutang-supplier-${date}.csv`;


  document.body.appendChild(
    link
  );


  link.click();


  document.body.removeChild(
    link
  );


  setTimeout(
    function () {

      URL.revokeObjectURL(
        url
      );

    },
    1000
  );


  showToast(
    "Laporan hutang supplier berhasil diekspor.",
    "success"
  );


  return true;

}


/* =========================================================
   EXPORT CURRENT PAYABLE REPORT
========================================================= */

function exportCurrentSupplierPayable() {

  return downloadSupplierPayableCSV();

}


