/* =========================================================
   FAEZA ERP V2
   BAGIAN 6J-09A
   CUSTOMER RECEIVABLE FOUNDATION
========================================================= */


/* =========================================================
   ENSURE CUSTOMER PAYMENT STORAGE
========================================================= */

function ensureCustomerPaymentStorage() {

  if (
    !Array.isArray(
      db.customerPayments
    )
  ) {

    db.customerPayments = [];

  }


  return db.customerPayments;

}


/* =========================================================
   GET SALE TOTAL
========================================================= */

function getSaleTotalAmount(
  sale
) {

  if (
    !sale
  ) {

    return 0;

  }


  const directTotal =
    Number(
      sale.total
    ) ||

    Number(
      sale.grandTotal
    ) ||

    Number(
      sale.amount
    ) ||

    Number(
      sale.totalAmount
    ) ||

    0;


  if (
    directTotal > 0
  ) {

    return directTotal;

  }


  const items =
    Array.isArray(
      sale.items
    )
      ? sale.items
      : [];


  return items.reduce(
    (
      total,
      item
    ) => {

      const qty =
        Number(
          item.qty ||
          item.quantity
        ) || 0;


      const price =
        Number(
          item.price ||
          item.sellingPrice ||
          item.salePrice
        ) || 0;


      return (
        total +
        (
          qty *
          price
        )
      );

    },
    0
  );

}


/* =========================================================
   GET SALE PAID AMOUNT
========================================================= */

function getSalePaidAmount(
  sale
) {

  if (
    !sale
  ) {

    return 0;

  }


  const directPaid =
    Number(
      sale.paid
    ) ||

    Number(
      sale.amountPaid
    ) ||

    Number(
      sale.paymentAmount
    ) ||

    0;


  const payments =
    ensureCustomerPaymentStorage();


  const paymentTotal =
    payments
      .filter(
        payment =>
          String(
            payment.saleId ||
            ""
          ) ===
          String(
            sale.id ||
            ""
          )
      )
      .reduce(
        (
          total,
          payment
        ) => {

          return (
            total +
            (
              Number(
                payment.amount
              ) ||
              Number(
                payment.paid
              ) ||
              0
            )
          );

        },
        0
      );


  return Math.max(
    directPaid,
    paymentTotal
  );

}


/* =========================================================
   GET RECEIVABLE STATUS
========================================================= */

function getReceivableStatus(
  total,
  paid
) {

  const grandTotal =
    Number(
      total
    ) || 0;


  const amountPaid =
    Number(
      paid
    ) || 0;


  const remaining =
    Math.max(
      0,
      grandTotal -
      amountPaid
    );


  if (
    grandTotal <= 0
  ) {

    return "NO_AMOUNT";

  }


  if (
    remaining <= 0
  ) {

    return "PAID";

  }


  if (
    amountPaid > 0
  ) {

    return "PARTIAL";

  }


  return "UNPAID";

}


/* =========================================================
   GET CUSTOMER NAME
========================================================= */

function getCustomerNameSafe(
  customerId,
  sale
) {

  if (
    sale?.customerName
  ) {

    return sale.customerName;

  }


  if (
    sale?.customer
  ) {

    if (
      typeof sale.customer ===
      "string"
    ) {

      return sale.customer;

    }

    if (
      sale.customer.name
    ) {

      return sale.customer.name;

    }

  }


  if (
    typeof getCustomerNameById ===
    "function"
  ) {

    return (
      getCustomerNameById(
        customerId
      ) ||
      "-"
    );

  }


  const customers =
    Array.isArray(
      db.customers
    )
      ? db.customers
      : [];


  const customer =
    customers.find(
      item =>
        String(
          item.id
        ) ===
        String(
          customerId
        )
    );


  return (
    customer?.name ||
    customer?.customerName ||
    "-"
  );

}


/* =========================================================
   GET CUSTOMER RECEIVABLE DATA
========================================================= */

function getCustomerReceivableData(
  filters = {}
) {

  const customerId =
    filters.customerId ||
    "";


  const status =
    String(
      filters.status ||
      "ALL"
    ).toUpperCase();


  const dateFrom =
    filters.dateFrom ||
    "";


  const dateTo =
    filters.dateTo ||
    "";


  const search =
    String(
      filters.search ||
      ""
    )
      .trim()
      .toLowerCase();


  /*
     Support beberapa nama
     storage transaksi penjualan.
  */

  const sales =
    Array.isArray(
      db.sales
    )
      ? db.sales
      : Array.isArray(
          db.transactions
        )
        ? db.transactions
        : [];


  const rows = [];


  sales.forEach(
    sale => {

      if (
        !sale
      ) {

        return;

      }


      /*
         Hanya transaksi yang
         memang berhubungan dengan
         piutang/customer kredit.
      */

      const paymentStatus =
        String(
          sale.paymentStatus ||
          sale.paymentType ||
          sale.paymentMethod ||
          ""
        ).toUpperCase();


      const isCredit =
        sale.isCredit === true ||
        sale.credit === true ||
        paymentStatus ===
          "CREDIT" ||
        paymentStatus ===
          "KREDIT" ||
        paymentStatus ===
          "PIUTANG" ||
        Number(
          sale.creditAmount
        ) > 0 ||
        Number(
          sale.remaining
        ) > 0;


      /*
         Jika tidak ada identitas
         customer dan bukan kredit,
         jangan masukkan.
      */

      const saleCustomerId =
        sale.customerId ||
        sale.customer_id ||
        "";


      const customerName =
        getCustomerNameSafe(
          saleCustomerId,
          sale
        );


      if (
        !isCredit &&
        !saleCustomerId &&
        (
          !sale.customerName
        )
      ) {

        return;

      }


      /*
         Filter customer.
      */

      if (
        customerId &&
        String(
          saleCustomerId
        ) !==
        String(
          customerId
        )
      ) {

        return;

      }


      const date =
        sale.date ||
        sale.saleDate ||
        sale.createdAt ||
        "";


      /*
         Filter tanggal.
      */

      if (
        dateFrom &&
        String(
          date
        ) < dateFrom
      ) {

        return;

      }


      if (
        dateTo &&
        String(
          date
        ) > dateTo
      ) {

        return;

      }


      const saleNumber =
        sale.saleNumber ||
        sale.invoiceNumber ||
        sale.number ||
        sale.code ||
        sale.id ||
        "-";


      const invoiceNumber =
        sale.invoiceNumber ||
        sale.invoice ||
        saleNumber ||
        "-";


      /*
         Search.
      */

      if (
        search
      ) {

        const searchable =
          [
            saleNumber,
            invoiceNumber,
            customerName
          ]
            .join(" ")
            .toLowerCase();


        if (
          !searchable.includes(
            search
          )
        ) {

          return;

        }

      }


      const total =
        getSaleTotalAmount(
          sale
        );


      const paid =
        getSalePaidAmount(
          sale
        );


      const remaining =
        Math.max(
          0,
          total -
          paid
        );


      const receivableStatus =
        getReceivableStatus(
          total,
          paid
        );


      /*
         Status filter.
      */

      if (
        status !==
        "ALL" &&
        status !==
        receivableStatus
      ) {

        return;

      }


      rows.push({

        id:
          sale.id,

        saleNumber,

        invoiceNumber,

        customerId:
          saleCustomerId,

        customerName,

        date,

        dueDate:
          sale.dueDate ||
          sale.paymentDueDate ||
          "",

        total,

        paid,

        remaining,

        status:
          receivableStatus,

        paymentStatus:
          sale.paymentStatus ||
          "",

        notes:
          sale.notes ||
          sale.note ||
          ""

      });

    }
  );


  /*
     Urutkan terbaru dahulu.
  */

  rows.sort(
    (
      a,
      b
    ) => {

      return String(
        b.date ||
        ""
      ).localeCompare(
        String(
          a.date ||
          ""
        )
      );

    }
  );


  /*
     Summary.
  */

  const summary =
    rows.reduce(
      (
        result,
        row
      ) => {

        result.count += 1;

        result.total +=
          Number(
            row.total
          ) || 0;

        result.paid +=
          Number(
            row.paid
          ) || 0;

        result.remaining +=
          Number(
            row.remaining
          ) || 0;


        if (
          row.status ===
          "UNPAID"
        ) {

          result.unpaid += 1;

        }


        if (
          row.status ===
          "PARTIAL"
        ) {

          result.partial += 1;

        }


        if (
          row.status ===
          "PAID"
        ) {

          result.paidCount += 1;

        }


        return result;

      },
      {

        count: 0,

        total: 0,

        paid: 0,

        remaining: 0,

        unpaid: 0,

        partial: 0,

        paidCount: 0

      }
    );


  return {

    rows,

    summary

  };

}


