/* =========================================================
   QUICK OVERDUE RECEIVABLE
========================================================= */

function filterOverdueCustomerReceivable() {

  const filters =
    getCustomerReceivableFilters();


  let report =
    getCustomerReceivableData(
      filters
    );


  report.rows =
    report.rows.filter(
      row =>
        isReceivableOverdue(
          row
        )
    );


  report.summary =
    rebuildCustomerReceivableSummary(
      report.rows
    );


  window.activeCustomerReceivableFilters =
    {
      ...filters,
      overdueOnly:
        true
    };


  renderCustomerReceivableSummaryFromReport(
    report
  );


  renderCustomerReceivableTableFromReport(
    report
  );


  showToast(
    "Menampilkan piutang yang sudah jatuh tempo.",
    "success"
  );


  return report;

}


