/* =========================================================
   GET RECEIVABLE BY SALE ID
========================================================= */

function getCustomerReceivableById(
  saleId
) {

  const report =
    getCustomerReceivableData(
      {}
    );


  return (
    report.rows.find(
      row =>
        String(
          row.id
        ) ===
        String(
          saleId
        )
    ) ||
    null
  );

}


/* =========================================================
   GET CUSTOMER PAYMENTS BY SALE
========================================================= */

function getCustomerPaymentsBySaleId(
  saleId
) {

  const payments =
    ensureCustomerPaymentStorage();


  return payments
    .filter(
      payment =>
        String(
          payment.saleId ||
          ""
        ) ===
        String(
          saleId
        )
    )
    .sort(
      (
        a,
        b
      ) => {

        return String(
          b.date ||
          b.createdAt ||
          ""
        ).localeCompare(
          String(
            a.date ||
            a.createdAt ||
            ""
          )
        );

      }
    );

}


/* =========================================================
   GET CUSTOMER RECEIVABLE DETAIL
========================================================= */

function getCustomerReceivableDetailData(
  saleId
) {

  const receivable =
    getCustomerReceivableById(
      saleId
    );


  if (
    !receivable
  ) {

    return null;

  }


  const payments =
    getCustomerPaymentsBySaleId(
      saleId
    );


  const paymentTotal =
    payments.reduce(
      (
        total,
        payment
      ) => {

        return (
          total +
          (
            Number(
              payment.amount
            ) ||
            Number(
              payment.paid
            ) ||
            0
          )
        );

      },
      0
    );


  return {

    ...receivable,

    payments,

    paymentTotal

  };

}


