/* =========================================================
   GET CUSTOMER PAYMENT FORM VALUES
========================================================= */

function getCustomerReceivablePaymentFormValues() {

  const date =
    document.getElementById(
      "customerPaymentDate"
    );


  const amount =
    document.getElementById(
      "customerPaymentAmount"
    );


  const method =
    document.getElementById(
      "customerPaymentMethod"
    );


  const reference =
    document.getElementById(
      "customerPaymentReference"
    );


  const notes =
    document.getElementById(
      "customerPaymentNotes"
    );


  return {

    date:
      date?.value ||
      new Date()
        .toISOString()
        .slice(
          0,
          10
        ),

    amount:
      Number(
        String(
          amount?.value ||
          "0"
        ).replace(
          /[^\d.-]/g,
          ""
        )
      ) || 0,

    method:
      method?.value ||
      "CASH",

    reference:
      reference?.value?.trim() ||
      "",

    notes:
      notes?.value?.trim() ||
      ""

  };

}


/* =========================================================
   CREATE CUSTOMER PAYMENT NUMBER
========================================================= */

function createCustomerPaymentNumber() {

  const payments =
    ensureCustomerPaymentStorage();


  const year =
    new Date()
      .getFullYear();


  return (

    "RCP-" +

    year +

    "-" +

    String(
      payments.length + 1
    ).padStart(
      5,
      "0"
    )

  );

}


/* =========================================================
   VALIDATE CUSTOMER PAYMENT
========================================================= */

function validateCustomerReceivablePayment(
  receivable,
  payment
) {

  if (
    !receivable
  ) {

    showToast(
      "Data piutang tidak ditemukan.",
      "error"
    );

    return false;

  }


  if (
    receivable.remaining <= 0
  ) {

    showToast(
      "Piutang ini sudah lunas.",
      "warning"
    );

    return false;

  }


  if (
    !payment.amount ||
    payment.amount <= 0
  ) {

    showToast(
      "Masukkan jumlah pembayaran.",
      "warning"
    );

    return false;

  }


  if (
    payment.amount >
    receivable.remaining
  ) {

    showToast(
      "Pembayaran melebihi sisa piutang.",
      "warning"
    );

    return false;

  }


  if (
    !payment.date
  ) {

    showToast(
      "Tanggal pembayaran wajib diisi.",
      "warning"
    );

    return false;

  }


  return true;

}


/* =========================================================
   OPEN CUSTOMER RECEIVABLE PAYMENT
========================================================= */

function openCustomerReceivablePaymentForm(
  saleId
) {

  const receivable =
    getCustomerReceivableById(
      saleId
    );


  if (
    !receivable
  ) {

    showToast(
      "Data piutang tidak ditemukan.",
      "error"
    );

    return false;

  }


  if (
    receivable.remaining <= 0
  ) {

    showToast(
      "Piutang ini sudah lunas.",
      "warning"
    );

    return false;

  }


  window.activeCustomerReceivableId =
    saleId;


  setElementText(
    "customerPaymentCustomer",
    receivable.customerName
  );


  setElementText(
    "customerPaymentSale",
    receivable.saleNumber
  );


  setElementText(
    "customerPaymentInvoice",
    receivable.invoiceNumber
  );


  setElementText(
    "customerPaymentOutstanding",
    formatRupiah(
      receivable.remaining
    )
  );


  const date =
    document.getElementById(
      "customerPaymentDate"
    );


  if (
    date
  ) {

    date.value =
      new Date()
        .toISOString()
        .slice(
          0,
          10
        );

  }


  const amount =
    document.getElementById(
      "customerPaymentAmount"
    );


  if (
    amount
  ) {

    amount.value =
      "";

    amount.max =
      receivable.remaining;

  }


  const modal =
    document.getElementById(
      "customerReceivablePaymentModal"
    );


  if (
    modal
  ) {

    modal.removeAttribute(
      "hidden"
    );


    modal.classList.add(
      "active"
    );

  }


  return true;

}


/* =========================================================
   SAVE CUSTOMER RECEIVABLE PAYMENT
========================================================= */

function saveCustomerReceivablePayment() {

  const saleId =
    window.activeCustomerReceivableId ||
    "";


  if (
    !saleId
  ) {

    showToast(
      "Pilih piutang terlebih dahulu.",
      "warning"
    );

    return false;

  }


  const receivable =
    getCustomerReceivableById(
      saleId
    );


  if (
    !receivable
  ) {

    showToast(
      "Data piutang tidak ditemukan.",
      "error"
    );

    return false;

  }


  const payment =
    getCustomerReceivablePaymentFormValues();


  if (
    !validateCustomerReceivablePayment(
      receivable,
      payment
    )
  ) {

    return false;

  }


  const payments =
    ensureCustomerPaymentStorage();


  const paymentRecord = {

    id:
      "RCP-" +
      Date.now() +
      "-" +
      Math.random()
        .toString(36)
        .slice(
          2,
          7
        ),

    paymentNumber:
      createCustomerPaymentNumber(),

    saleId:
      saleId,

    customerId:
      receivable.customerId,

    customerName:
      receivable.customerName,

    date:
      payment.date,

    amount:
      payment.amount,

    paid:
      payment.amount,

    method:
      payment.method,

    paymentMethod:
      payment.method,

    reference:
      payment.reference,

    notes:
      payment.notes,

    createdAt:
      new Date()
        .toISOString()

  };


  payments.push(
    paymentRecord
  );


  /*
     Sinkronkan transaksi penjualan.
  */

  const sales =
    Array.isArray(
      db.sales
    )
      ? db.sales
      : [];


  const sale =
    sales.find(
      item =>
        String(
          item.id
        ) ===
        String(
          saleId
        )
    );


  if (
    sale
  ) {

    const currentPaid =
      Number(
        sale.paid
      ) ||
      Number(
        sale.amountPaid
      ) ||
      0;


    sale.paid =
      currentPaid +
      payment.amount;


    sale.amountPaid =
      sale.paid;


    const total =
      getSaleTotalAmount(
        sale
      );


    sale.remaining =
      Math.max(
        0,
        total -
        sale.paid
      );


    if (
      sale.remaining <= 0
    ) {

      sale.paymentStatus =
        "PAID";

    }

    else if (
      sale.paid > 0
    ) {

      sale.paymentStatus =
        "PARTIAL";

    }

    else {

      sale.paymentStatus =
        "UNPAID";

    }

  }


  /*
     Simpan database.
  */

  if (
    typeof saveDB ===
    "function"
  ) {

    saveDB();

  }

  else if (
    typeof saveDatabase ===
    "function"
  ) {

    saveDatabase();

  }

  else {

    try {

      localStorage.setItem(
        "faezaERP",
        JSON.stringify(
          db
        )
      );

    }

    catch (
      error
    ) {

      console.warn(
        "Gagal menyimpan database:",
        error
      );

    }

  }


  /*
     Tutup form.
  */

  closeCustomerReceivablePaymentForm();


  /*
     Refresh detail dan laporan.
  */

  renderCustomerReceivableReport(
    window.activeCustomerReceivableFilters ||
    {}
  );


  renderCustomerReceivableDetail(
    saleId
  );


  showToast(
    "Pembayaran customer berhasil disimpan.",
    "success"
  );


  return paymentRecord;

}


/* =========================================================
   CLOSE PAYMENT FORM
========================================================= */

function closeCustomerReceivablePaymentForm() {

  const modal =
    document.getElementById(
      "customerReceivablePaymentModal"
    );


  if (
    modal
  ) {

    modal.classList.remove(
      "active"
    );


    modal.setAttribute(
      "hidden",
      "hidden"
    );

  }


  clearCustomerReceivablePaymentForm();


  return true;

}


