/* =========================================================
   PRINTABLE RECEIVABLE STATUS
========================================================= */

function getPrintableReceivableStatus(
  row
) {

  if (
    isReceivableOverdue(
      row
    )
  ) {

    return "JATUH TEMPO";

  }


  if (
    row.status ===
    "PAID"
  ) {

    return "LUNAS";

  }


  if (
    row.status ===
    "PARTIAL"
  ) {

    return "SEBAGIAN";

  }


  return "BELUM BAYAR";

}


