/* =========================================================
   FAEZA ERP V2
   BAGIAN 6J-09G
   EXPORT CUSTOMER RECEIVABLE TO CSV
========================================================= */


/* =========================================================
   ESCAPE CSV VALUE
========================================================= */

function escapeReceivableCSVValue(
  value
) {

  if (
    value === null ||
    value === undefined
  ) {

    return '""';

  }


  return (
    '"' +
    String(
      value
    )
      .replace(
        /"/g,
        '""'
      ) +
    '"'
  );

}


/* =========================================================
   GET FILTERED RECEIVABLE REPORT
========================================================= */

function getFilteredCustomerReceivableReport(
  filters = {}
) {

  const report =
    getCustomerReceivableData(
      filters
    );


  let rows =
    report.rows ||
    [];


  /*
     Filter tanggal jatuh tempo.
  */

  if (
    filters.dueFrom ||
    filters.dueTo
  ) {

    rows =
      rows.filter(
        row => {

          const dueDate =
            row.dueDate ||
            "";


          if (
            !dueDate
          ) {

            return false;

          }


          if (
            filters.dueFrom &&
            dueDate <
            filters.dueFrom
          ) {

            return false;

          }


          if (
            filters.dueTo &&
            dueDate >
            filters.dueTo
          ) {

            return false;

          }


          return true;

        }
      );

  }


  /*
     Hanya piutang jatuh tempo.
  */

  if (
    filters.overdueOnly
  ) {

    rows =
      rows.filter(
        row =>
          isReceivableOverdue(
            row
          )
      );

  }


  const summary =
    rebuildCustomerReceivableSummary(
      rows
    );


  return {

    rows,

    summary

  };

}


/* =========================================================
   BUILD RECEIVABLE CSV
========================================================= */

function buildCustomerReceivableCSV(
  filters = {}
) {

  const report =
    getFilteredCustomerReceivableReport(
      filters
    );


  const rows =
    report.rows;


  const csvRows = [];


  /*
     HEADER APLIKASI
  */

  csvRows.push(
    [
      "FAEZA STORE ERP"
    ]
      .map(
        escapeReceivableCSVValue
      )
      .join(",")
  );


  csvRows.push(
    [
      "LAPORAN PIUTANG CUSTOMER"
    ]
      .map(
        escapeReceivableCSVValue
      )
      .join(",")
  );


  csvRows.push("");


  /*
     HEADER DATA
  */

  csvRows.push(
    [
      "No",
      "Tanggal",
      "Customer",
      "No Penjualan",
      "Invoice",
      "Total Penjualan",
      "Dibayar",
      "Sisa Piutang",
      "Jatuh Tempo",
      "Status"
    ]
      .map(
        escapeReceivableCSVValue
      )
      .join(",")
  );


  /*
     DATA
  */

  rows.forEach(
    (
      row,
      index
    ) => {

      csvRows.push(
        [

          index + 1,

          row.date
            ? formatPrintDate(
                row.date
              )
            : "",

          row.customerName ||
            "",

          row.saleNumber ||
            "",

          row.invoiceNumber ||
            "",

          Number(
            row.total
          ) || 0,

          Number(
            row.paid
          ) || 0,

          Number(
            row.remaining
          ) || 0,

          row.dueDate
            ? formatPrintDate(
                row.dueDate
              )
            : "",

          getPrintableReceivableStatus(
            row
          )

        ]
          .map(
            escapeReceivableCSVValue
          )
          .join(",")
      );

    }
  );


  /*
     RINGKASAN
  */

  csvRows.push("");


  csvRows.push(
    [
      "RINGKASAN"
    ]
      .map(
        escapeReceivableCSVValue
      )
      .join(",")
  );


  csvRows.push(
    [
      "Jumlah Transaksi",
      report.summary.count
    ]
      .map(
        escapeReceivableCSVValue
      )
      .join(",")
  );


  csvRows.push(
    [
      "Total Penjualan",
      report.summary.total
    ]
      .map(
        escapeReceivableCSVValue
      )
      .join(",")
  );


  csvRows.push(
    [
      "Total Dibayar",
      report.summary.paid
    ]
      .map(
        escapeReceivableCSVValue
      )
      .join(",")
  );


  csvRows.push(
    [
      "Total Sisa Piutang",
      report.summary.remaining
    ]
      .map(
        escapeReceivableCSVValue
      )
      .join(",")
  );


  csvRows.push(
    [
      "Belum Bayar",
      report.summary.unpaid
    ]
      .map(
        escapeReceivableCSVValue
      )
      .join(",")
  );


  csvRows.push(
    [
      "Sebagian",
      report.summary.partial
    ]
      .map(
        escapeReceivableCSVValue
      )
      .join(",")
  );


  csvRows.push(
    [
      "Lunas",
      report.summary.paidCount
    ]
      .map(
        escapeReceivableCSVValue
      )
      .join(",")
  );


  /*
     BOM UTF-8
     Agar Excel membaca
     karakter Indonesia dengan benar.
  */

  return (
    "\uFEFF" +
    csvRows.join(
      "\r\n"
    )
  );

}


/* =========================================================
   DOWNLOAD CUSTOMER RECEIVABLE CSV
========================================================= */

function downloadCustomerReceivableCSV() {

  const filters =
    window.activeCustomerReceivableFilters ||
    {};


  const csv =
    buildCustomerReceivableCSV(
      filters
    );


  if (
    !csv
  ) {

    showToast(
      "Data piutang tidak dapat diekspor.",
      "error"
    );

    return false;

  }


  const blob =
    new Blob(
      [
        csv
      ],
      {
        type:
          "text/csv;charset=utf-8;"
      }
    );


  const url =
    URL.createObjectURL(
      blob
    );


  const link =
    document.createElement(
      "a"
    );


  const date =
    new Date()
      .toISOString()
      .slice(
        0,
        10
      );


  link.href =
    url;


  link.download =
    `laporan-piutang-customer-${date}.csv`;


  document.body.appendChild(
    link
  );


  link.click();


  document.body.removeChild(
    link
  );


  setTimeout(
    function () {

      URL.revokeObjectURL(
        url
      );

    },
    1000
  );


  showToast(
    "Laporan piutang customer berhasil diekspor.",
    "success"
  );


  return true;

}


/* =========================================================
   EXPORT CURRENT RECEIVABLE
========================================================= */

function exportCurrentCustomerReceivable() {

  return downloadCustomerReceivableCSV();

}


