/* =========================================================
   SAFE NUMBER
========================================================= */

function financialNumber(value) {

  const number =
    Number(value);

  return Number.isFinite(
    number
  )
    ? number
    : 0;

}


/* =========================================================
   GET DATABASE ARRAY
========================================================= */

function financialArray(
  key
) {

  if (
    typeof db ===
      "undefined" ||
    !db
  ) {

    return [];

  }


  return Array.isArray(
    db[key]
  )
    ? db[key]
    : [];

}


/* =========================================================
   GET SALE TOTAL
========================================================= */

function getFinancialSaleTotal(
  sale
) {

  if (
    !sale
  ) {

    return 0;

  }


  if (
    typeof getSaleTotalAmount ===
    "function"
  ) {

    return financialNumber(
      getSaleTotalAmount(
        sale
      )
    );

  }


  return financialNumber(
    sale.total ??
    sale.grandTotal ??
    sale.amount ??
    sale.totalAmount
  );

}


/* =========================================================
   GET SALE PAYMENT
========================================================= */

function getFinancialSalePaid(
  sale
) {

  if (
    !sale
  ) {

    return 0;

  }


  return financialNumber(
    sale.paid ??
    sale.amountPaid ??
    sale.payment ??
    sale.paidAmount
  );

}


/* =========================================================
   GET SALES SUMMARY
========================================================= */

function getFinancialSalesSummary() {

  const sales =
    financialArray(
      "sales"
    );


  return sales.reduce(
    (
      result,
      sale
    ) => {

      const total =
        getFinancialSaleTotal(
          sale
        );


      const paid =
        getFinancialSalePaid(
          sale
        );


      result.transaction += 1;

      result.sales +=
        total;

      result.cash +=
        Math.min(
          paid,
          total
        );


      if (
        String(
          sale.paymentStatus ||
          ""
        ).toUpperCase() ===
        "PAID"
      ) {

        result.paidTransaction +=
          1;

      }


      return result;

    },
    {

      transaction: 0,

      sales: 0,

      cash: 0,

      paidTransaction: 0

    }
  );

}


/* =========================================================
   GET CUSTOMER RECEIVABLE SUMMARY
========================================================= */

function getFinancialReceivableSummary() {

  if (
    typeof getCustomerReceivableData ===
    "function"
  ) {

    const report =
      getCustomerReceivableData(
        {}
      );


    return {

      transaction:
        financialNumber(
          report?.summary?.count
        ),

      total:
        financialNumber(
          report?.summary?.total
        ),

      paid:
        financialNumber(
          report?.summary?.paid
        ),

      outstanding:
        financialNumber(
          report?.summary?.remaining
        ),

      unpaid:
        financialNumber(
          report?.summary?.unpaid
        ),

      partial:
        financialNumber(
          report?.summary?.partial
        ),

      paidCount:
        financialNumber(
          report?.summary?.paidCount
        )

    };

  }


  return {

    transaction: 0,

    total: 0,

    paid: 0,

    outstanding: 0,

    unpaid: 0,

    partial: 0,

    paidCount: 0

  };

}


/* =========================================================
   GET CUSTOMER PAYMENT TOTAL
========================================================= */

function getFinancialCustomerPaymentTotal() {

  if (
    typeof ensureCustomerPaymentStorage !==
    "function"
  ) {

    return 0;

  }


  const payments =
    ensureCustomerPaymentStorage();


  return payments.reduce(
    (
      total,
      payment
    ) => {

      return (
        total +
        financialNumber(
          payment.amount ??
          payment.paid
        )
      );

    },
    0
  );

}


/* =========================================================
   GET SUPPLIER PAYMENTS
========================================================= */

function getFinancialSupplierPaymentTotal() {

  /*
     Menyesuaikan beberapa kemungkinan
     nama storage agar dashboard
     tetap kompatibel dengan modul lama.
  */

  const collections = [

    "supplierPayments",

    "purchasePayments",

    "payablePayments",

    "supplierPayment"

  ];


  for (
    const key of collections
  ) {

    const list =
      financialArray(
        key
      );


    if (
      list.length
    ) {

      return list.reduce(
        (
          total,
          payment
        ) => {

          return (
            total +
            financialNumber(
              payment.amount ??
              payment.paid
            )
          );

        },
        0
      );

    }

  }


  return 0;

}


/* =========================================================
   GET PAYABLE SUMMARY
========================================================= */

function getFinancialPayableSummary() {

  /*
     Gunakan modul hutang supplier
     jika tersedia.
  */

  if (
    typeof getSupplierPayableData ===
    "function"
  ) {

    const report =
      getSupplierPayableData(
        {}
      );


    return {

      transaction:
        financialNumber(
          report?.summary?.count
        ),

      total:
        financialNumber(
          report?.summary?.total
        ),

      paid:
        financialNumber(
          report?.summary?.paid
        ),

      outstanding:
        financialNumber(
          report?.summary?.remaining
        ),

      unpaid:
        financialNumber(
          report?.summary?.unpaid
        ),

      partial:
        financialNumber(
          report?.summary?.partial
        ),

      paidCount:
        financialNumber(
          report?.summary?.paidCount
        )

    };

  }


  return {

    transaction: 0,

    total: 0,

    paid: 0,

    outstanding: 0,

    unpaid: 0,

    partial: 0,

    paidCount: 0

  };

}


/* =========================================================
   GET PURCHASE TOTAL
========================================================= */

function getFinancialPurchaseSummary() {

  const purchases =
    financialArray(
      "purchases"
    );


  return purchases.reduce(
    (
      result,
      purchase
    ) => {

      const total =
        financialNumber(
          purchase.total ??
          purchase.grandTotal ??
          purchase.amount ??
          purchase.totalAmount
        );


      result.transaction +=
        1;

      result.purchase +=
        total;


      return result;

    },
    {

      transaction: 0,

      purchase: 0

    }
  );

}


/* =========================================================
   GET STOCK VALUE
========================================================= */

function getFinancialStockValue() {

  const products =
    financialArray(
      "products"
    );


  return products.reduce(
    (
      total,
      product
    ) => {

      const stock =
        financialNumber(
          product.stock ??
          product.qty ??
          product.quantity
        );


      const cost =
        financialNumber(
          product.costPrice ??
          product.purchasePrice ??
          product.buyPrice ??
          product.hpp
        );


      return (
        total +
        (
          stock *
          cost
        )
      );

    },
    0
  );

}


/* =========================================================
   BUILD FINANCIAL DASHBOARD DATA
========================================================= */

function getFinancialDashboardData() {

  const sales =
    getFinancialSalesSummary();


  const purchases =
    getFinancialPurchaseSummary();


  const receivable =
    getFinancialReceivableSummary();


  const payable =
    getFinancialPayableSummary();


  const customerPayments =
    getFinancialCustomerPaymentTotal();


  const supplierPayments =
    getFinancialSupplierPaymentTotal();


  const stockValue =
    getFinancialStockValue();


  const netCashMovement =
    customerPayments -
    supplierPayments;


  return {

    sales,

    purchases,

    receivable,

    payable,

    customerPayments,

    supplierPayments,

    stockValue,

    netCashMovement

  };

}


/* =========================================================
   RENDER FINANCIAL DASHBOARD
========================================================= */

function renderFinancialDashboard() {

  const data =
    getFinancialDashboardData();


  /*
     PENJUALAN
  */

  setElementText(
    "financialSalesTotal",
    formatRupiah(
      data.sales.sales
    )
  );


  setElementText(
    "financialSalesTransaction",
    formatNumber(
      data.sales.transaction
    )
  );


  /*
     PEMBELIAN
  */

  setElementText(
    "financialPurchaseTotal",
    formatRupiah(
      data.purchases.purchase
    )
  );


  setElementText(
    "financialPurchaseTransaction",
    formatNumber(
      data.purchases.transaction
    )
  );


  /*
     PIUTANG
  */

  setElementText(
    "financialReceivable",
    formatRupiah(
      data.receivable.outstanding
    )
  );


  setElementText(
    "financialReceivableCount",
    formatNumber(
      data.receivable.transaction
    )
  );


  /*
     HUTANG
  */

  setElementText(
    "financialPayable",
    formatRupiah(
      data.payable.outstanding
    )
  );


  setElementText(
    "financialPayableCount",
    formatNumber(
      data.payable.transaction
    )
  );


  /*
     PEMBAYARAN CUSTOMER
  */

  setElementText(
    "financialCustomerPayment",
    formatRupiah(
      data.customerPayments
    )
  );


  /*
     PEMBAYARAN SUPPLIER
  */

  setElementText(
    "financialSupplierPayment",
    formatRupiah(
      data.supplierPayments
    )
  );


  /*
     NILAI STOK
  */

  setElementText(
    "financialStockValue",
    formatRupiah(
      data.stockValue
    )
  );


  /*
     PERGERAKAN KAS
  */

  setElementText(
    "financialNetCash",
    formatRupiah(
      data.netCashMovement
    )
  );


  window.currentFinancialDashboardData =
    data;


  return data;

}


/* =========================================================
   REFRESH FINANCIAL DASHBOARD
========================================================= */

function refreshFinancialDashboard() {

  return renderFinancialDashboard();

}


