/* =========================================================
   FAEZA ERP V2
   6J-10B
   QUICK SUMMARY ENGINE
========================================================= */

function renderFinancialQuickSummary(
  data
) {

  if (
    !data
  ) {

    data =
      getFinancialDashboardData();

  }


  /*
     PIUTANG
  */

  setElementText(
    "financialSummaryReceivable",
    formatRupiah(
      data.receivable?.outstanding ||
      0
    )
  );


  /*
     HUTANG
  */

  setElementText(
    "financialSummaryPayable",
    formatRupiah(
      data.payable?.outstanding ||
      0
    )
  );


  /*
     KAS BERSIH
  */

  const netCash =
    Number(
      data.netCashMovement
    ) || 0;


  setElementText(
    "financialSummaryCash",
    formatRupiah(
      netCash
    )
  );


  /*
     STATUS KEUANGAN
  */

  let status =
    "Stabil";


  if (
    data.receivable?.outstanding >
    data.payable?.outstanding
  ) {

    status =
      "Piutang lebih besar dari hutang";

  }


  if (
    data.payable?.outstanding >
    data.receivable?.outstanding
  ) {

    status =
      "Hutang perlu diperhatikan";

  }


  if (
    netCash < 0
  ) {

    status =
      "Arus kas perlu diperhatikan";

  }


  if (
    data.receivable?.outstanding ===
      0 &&
    data.payable?.outstanding ===
      0
  ) {

    status =
      "Keuangan stabil";

  }


  setElementText(
    "financialHealthStatus",
    status
  );


  return {

    status,

    receivable:
      data.receivable?.outstanding ||
      0,

    payable:
      data.payable?.outstanding ||
      0,

    netCash

  };

}


/* =========================================================
   REFRESH QUICK SUMMARY
========================================================= */

function refreshFinancialQuickSummary() {

  const data =
    getFinancialDashboardData();


  return renderFinancialQuickSummary(
    data
  );

}


